/* ============================================================
   APP — events, modal system, init
   ============================================================ */

/* ── Init ────────────────────────────────────────────── */

document.addEventListener('DOMContentLoaded', async () => {
  // Load locale before first render so t() is ready
  if (typeof loadLocale === 'function') {
    await loadLocale();
  }
  // Shippy's bubbles: a burst of three every few seconds, with jitter so no
  // two are alike. They only show while the guide is collapsed, since that is
  // when the lane above the fab exists — the loop no-ops otherwise.
  if (typeof bubbleLoop === 'function') bubbleLoop();
  initSubnavDebugToggle();
  initWebPagePreviewToggle();
  initCalendarKeys();
  // Boot straight into the app (title bar persists) with the splash view showing.
  bootApp();
});

/* DEBUG — Ctrl+D swaps the band above the content between the row of sub-tab
   pills and a single line naming the section you're in.

   Session-only: it always boots OFF (pills visible) and is NOT persisted, so an
   accidental Ctrl+D can't hide the sub-tabs across reloads — a refresh always
   restores them. (Previously persisted to localStorage, which stuck the band in
   title-only mode and hid the Marketing/Details sub-tabs until pressed again.)

   Temporary: when the experiment is settled, delete this function, its call
   above, and state.subnavTitleOnly. */
function initSubnavDebugToggle() {
  state.subnavTitleOnly = false;
  // Clear any value a previous (persisting) build left behind.
  try { localStorage.removeItem('sm.subnavTitleOnly'); } catch (_) {}
  document.addEventListener('keydown', e => {
    if (!e.ctrlKey || e.metaKey || e.altKey) return;
    if ((e.key || '').toLowerCase() !== 'd') return;
    // Never steal the key from a field the user is typing in.
    const el = document.activeElement;
    const tag = el && el.tagName;
    if (tag === 'INPUT' || tag === 'TEXTAREA' || (el && el.isContentEditable)) return;
    e.preventDefault();
    state.subnavTitleOnly = !state.subnavTitleOnly;
    if (typeof renderAppSubnav === 'function') renderAppSubnav();
  });
}

/* The content scroller (.main) reserves a scrollbar gutter on its right; the
   fixed top bar doesn't. Measure that width and pad the top bar to match, so the
   header columns line up exactly with the content columns below. */
function measureScrollbar() {
  const m = document.querySelector('.main');
  const sbw = m ? Math.max(0, m.offsetWidth - m.clientWidth) : 0;
  document.documentElement.style.setProperty('--sbw', sbw + 'px');
}

/* Boot into main-app with the persistent title bar and the splash view active. */
function bootApp() {
  document.getElementById('splash-section')?.classList.add('hidden');
  document.getElementById('onboarding-overlay')?.classList.add('hidden');
  document.getElementById('main-app').classList.remove('hidden');
  document.body.classList.add('signed-in');
  document.body.classList.remove('is-splash');
  if (!state.onboardingComplete && (!state.projects || state.projects.length === 0)) {
    try { completeOnboarding(); } catch (e) { /* keep going */ }
  }
  try { seedOnboardingToIOS(); seedOnboardingToIOS('macos'); seedOnboardingToAndroid(); } catch (e) {}
  // (Top-bar hover sub-menus removed — sub-tabs now live under the title bar.)
  showSplashView();
  measureScrollbar();
  requestAnimationFrame(measureScrollbar);   // again after first layout settles
  // (No token to warm anymore — the picklist search goes through our own
  // backend now, not direct IGDB/Twitch. See IGDB_SEARCH_ENDPOINT, claude.js.)
}
window.addEventListener('resize', () => { try { measureScrollbar(); } catch (e) {} });

/* Show the splash as an in-app view (no active tab, guide hidden, full width). */
function showSplashView() {
  document.getElementById('main-app').classList.remove('hidden');
  document.getElementById('splash-section')?.classList.add('hidden');
  document.body.classList.remove('is-splash');
  document.body.classList.add('signed-in', 'viewing-splash');
  state.activeView = 'splash';
  for (const id of Object.values(VIEW_IDS)) document.getElementById(id)?.classList.add('hidden');
  for (const id of Object.values(VIEW_NAV)) {
    const b = document.getElementById(id);
    if (b) { b.classList.remove('is-active'); b.setAttribute('aria-selected', 'false'); }
  }
  state.navExpanded = false;
  document.getElementById('splashview')?.classList.remove('hidden');
  renderProjectBar();
  if (typeof renderSubnav === 'function') renderSubnav();
  renderSplashView();
  window.scrollTo(0, 0);
}

/* ── Splash screen ───────────────────────────────────── */

function showSplash() {
  document.getElementById('splash-section').classList.remove('hidden');
  document.getElementById('onboarding-overlay').classList.add('hidden');
  document.getElementById('main-app').classList.add('hidden');
  document.body.classList.add('is-splash');
  document.body.classList.remove('signed-in');
  if (window.__splashFitZoom) window.__splashFitZoom();
  renderLangMenu();
}

function hideSplash() {
  document.getElementById('splash-section').classList.add('hidden');
  document.body.classList.remove('is-splash');
}

/** "Get Started" button — always goes to onboarding for new users */
function startFromSplash() {
  hideSplash();
  showOnboarding();
}

/** "Sign In" button — returning users jump straight to their dashboard */
function signInFromSplash() {
  hideSplash();
  if (state.onboardingComplete) {
    showMainApp();
  } else {
    showOnboarding();
  }
}

function showMainApp(view = 'dashboard') {
  document.getElementById('onboarding-overlay').classList.add('hidden');
  document.getElementById('main-app').classList.remove('hidden');
  document.body.classList.add('signed-in');
  seedOnboardingToIOS();
  seedOnboardingToIOS('macos');
  seedOnboardingToAndroid();
  // No "Continue" button anymore — make sure the first project exists up front.
  if (!state.onboardingComplete && (!state.projects || state.projects.length === 0)) {
    try { completeOnboarding(); } catch (e) { /* keep going */ }
  }
  setView(view);
}

/* ── Top-level tab switch: Add Game Details · Submit to Platforms · Spread the Word ── */
const VIEW_IDS = { details: 'details', dashboard: 'dashboard', broadcast: 'broadcast', performance: 'performance', calendar: 'calendarview' };
const VIEW_NAV = { details: 'nav-details', dashboard: 'nav-dashboard', broadcast: 'nav-broadcast', performance: 'nav-performance', calendar: 'nav-calendar' };
/* A FIXED OVERLAY HAS TO BE TOLD WHEN YOU LEAVE (v7.10). Jaco: *"en
   descripción, si cambio a otra tab mientras está cargando la animación verde,
   deberías ocultarlo para que no se vea como un overlay en la siguiente tab."*

   `_masCommitGlimmer` draws its sweep as a `position: fixed` box pinned to the
   field's rect — deliberately tied to nothing, which is the property that made
   it work at all (see its own note: a confirmation that waits on a render is
   not a confirmation). The cost of being tied to nothing is that it does not
   know the field has gone: it already ends on scroll, resize and typing, and a
   tab change is none of those, so 900ms of green letters were left floating
   over whatever came next.

   Both doors, and for the reason `setView` states about the step modal: every
   route into a view goes through it, and every route between Game Details'
   sub-tabs goes through `gdSetSection`, so these are the two places that
   cannot be forgotten by whatever adds the next way of navigating. */
function setView(view) {
  if (!VIEW_IDS[view]) view = 'dashboard';
  _masGlimmerCancelAll();
  /* LEAVING THE TAB LEAVES WHAT WAS OPEN ON IT.

     A step modal belongs to the tab it was opened from — it is editing that
     platform's submission — but it is drawn OVER everything, so switching
     tabs underneath left it floating above a page it has nothing to do with,
     with a close button that returns you to a tab you already left.

     Here rather than in the tab buttons: every route into a view goes through
     setView, so this is the one place that cannot be forgotten by whatever
     adds the next way of navigating. Guarded on an actual change of view, so
     clicking the tab you are already on — which the nav uses to toggle its
     drawer — does not shut the modal you are working in. */
  if (state.activeView !== view && state.stepModal && typeof closeStepModal === 'function') {
    closeStepModal();
  }

  if (state.activeView !== view) scrollContentToTop();

  /* BUILD STATE, ENSURED HERE, and the location is the point.
     This began life at project creation and then also in activatePlatform(),
     and it still missed: a platform can become active without going through
     either (the onboarding tiles are a third path), so its card opened with
     state.platformBuilds undefined. Rather than chase a fourth entry point,
     this is the same argument the comment above makes about closeStepModal:
     every route into a view goes through setView, so it cannot be forgotten by
     whatever adds the next way of activating a platform.
     It only fills in missing objects, so it is idempotent and never touches a
     binary you actually dropped in. */
  if (typeof ensureBuildState === 'function') {
    const proj = state.projects.find(p => p.id === state.activeProjectId);
    if (proj) ensureBuildState(proj);
  }
  state.activeView = view;
  document.getElementById('splashview')?.classList.add('hidden');   // leave the splash
  document.body.classList.remove('viewing-splash');
  for (const [v, id] of Object.entries(VIEW_IDS)) {
    const el = document.getElementById(id);
    if (el) el.classList.toggle('hidden', v !== view);
  }
  for (const [v, id] of Object.entries(VIEW_NAV)) {
    const btn = document.getElementById(id);
    if (btn) { const on = v === view; btn.classList.toggle('is-active', on); btn.setAttribute('aria-selected', String(on)); }
  }
  // With a tab selected, the other chips' icon squares drop to 5%.
  document.getElementById('bar-nav')?.classList.add('has-sel');
  paintBarGlow();
  if (view === 'details') renderDetails();
  else if (view === 'broadcast') renderBroadcast();
  else if (view === 'performance') renderPerformance();
  else if (view === 'calendar') renderCalendar();
  else renderDashboard();
  renderGuide();       // right pane = this tab's banner + task checklist
  if (typeof renderSubnav === 'function') renderSubnav();   // top-nav sub-tab drawer
  window.scrollTo(0, 0);
}

/* Netflix-style main-tab click: switch tabs (and open the sub-tab drawer), or
   toggle the drawer if you click the tab you're already on. */
function navTabClick(view) {
  setView(view);   // hover handles the dropdown; a click just navigates
}

/* Hover opens the sub-menu for that tab (tabs without sub-tabs close it). */
function navHoverTab(view) {
  const has = (typeof _navSubtabs === 'function') && !!_navSubtabs(view);
  if (has) {
    if (state.navOpenView === view && state.navExpanded) return;   // already open
    state.navOpenView = view;
    state.navExpanded = true;
    renderSubnav();
  } else if (state.navExpanded) {
    state.navExpanded = false;
    renderSubnav();
  }
}

/* Leaving the whole nav (incl. the dropdown, which is a child) closes it. */
function navLeaveNav() {
  if (!state.navExpanded) return;
  state.navExpanded = false;
  renderSubnav();
}

/* Wire hover once — delegated on the nav so the static buttons don't each need a handler. */
function wireNavHover() {
  const bn = document.getElementById('bar-nav');
  if (!bn || bn._hoverWired) return;
  bn._hoverWired = true;
  const ID2VIEW = { 'nav-details': 'details', 'nav-dashboard': 'dashboard', 'nav-broadcast': 'broadcast', 'nav-performance': 'performance' };
  bn.addEventListener('mouseover', (e) => {
    const btn = e.target.closest && e.target.closest('.bar-nav-btn');
    if (btn && ID2VIEW[btn.id]) navHoverTab(ID2VIEW[btn.id]);
  });
  bn.addEventListener('mouseleave', navLeaveNav);
}

/* Close the sub-tab drawer (used by the dim overlay). */
function closeNav() { state.navExpanded = false; renderSubnav(); }

/* Pick a sub-tab from the dropdown. Since menus open on hover, the open menu may
   belong to a tab you're NOT on — so switch to that tab first, then open the
   chosen section, then close the dropdown. */
function navSubClick(fn, id) {
  state.navExpanded = false;
  const view = state.navOpenView;
  if (view && state.activeView !== view) setView(view);   // jump to that tab first
  if (typeof window[fn] === 'function') window[fn](id);    // then open the section
  else renderSubnav();
}

/* Removed in the v3.92 guide rebuild (handoff §4): the guide is a fixed inset
   card with margin-top:0 now — no JS banner alignment. No-op for safety. */
function alignSidePanes() {}

/* Diffuse light behind the chip that carries news — the prototype's
   paintGlow(). "Spread the Word" is the only flagged chip, and the glow goes
   out once you're actually on it, matching the prototype's rule that a news
   flag only shows while the tab is unvisited. */
/* Removed in the v3.88 top-bar rebuild (handoff §1): the news glow is gone.
   Kept as a no-op so existing callers stay harmless. If "this tab has news"
   needs a signal again, use a 6px purple dot on the tab, not a glow. */
function paintBarGlow() {}

// The pill is fluid below 1200px, so the glow has to follow it.
window.addEventListener('resize', paintBarGlow);

/* Size the nav type so "MY LITTLE GAME" measures exactly 134px, whatever
   metrics the font that actually loads turns out to have. This is the
   prototype's calibrate(), ported verbatim.

   It matters more than it looks: the 14.08px in the prototype's :root is a
   pre-calibration placeholder that this function immediately overwrites, so
   copying that literal into CSS and stopping there left the nav noticeably
   smaller than the prototype renders. The measurement has to happen at
   runtime, after the webfont lands. */
/* Removed in the v3.88 top-bar rebuild (handoff §1): tab type is a fixed 10px
   literal now, so the webfont-measuring pass is dead. No-op for safety. */
function calibrateNavFs() {}

// Calibrate, then again once the webfont has actually loaded — and re-place the
// glow after, since the chips change width when the type is resized.
calibrateNavFs();
if (document.fonts?.ready) {
  document.fonts.ready.then(() => { calibrateNavFs(); paintBarGlow(); });
}

/* ── Performance dashboard handlers ───────────────────── */
function perfSetPeriod(id) { state.performance.period = id; renderPerformance(); }
/* §6 — Analysis section folders + Submission platform folders */
function perfSetSection(id) { state.performance.section = id; renderPerformance(); renderSubnav(); }
/* Submission: the "Add platform" dropdown hanging off the sub-nav pill.

   IT TOUCHES THE DOM, IT DOES NOT RENDER — and that is a requirement rather
   than an optimisation. Opening a menu is not a state change about the
   submission; rendering here would rebuild the pane underneath it, which on
   this tab means throwing away an expanded step and its scroll for the sake of
   showing a list of four platforms. Same rule as gcalWaitHover and
   _sppFocusHere. The MARKUP is already in the document (buildSubnavAddPlatform
   emits the menu in both states), so a class is the whole of it.

   `state.submission.addOpen` is still written, for the reason
   _locsToggleSettingsMenu writes its flag: nothing renders on open or close,
   but something else might render WHILE it is open (activatePlatform does),
   and a menu whose only record is a DOM class would vanish on that repaint —
   or, worse, be re-emitted open after it had been dismissed.

   THIS IS ALSO WHAT USED TO BLANK THE PAGE. The old picker replaced the pane,
   so this function cleared the tab, the settings face and every open step so
   that closing it again "does not spring the old pane back open with a
   half-read step inside it". A dropdown takes nothing away, so there is
   nothing to put back and none of those three lines has a job any more.

   The event is required: closeAllDropdowns is bound to document click (see the
   listener at the bottom of this file), so without stopping propagation the
   press that opens this menu would immediately close it again. Same shape as
   toggleSwSelect. */
/* ── THE PILL'S RIGHT MARGIN IS SOLVED, NOT TYPED ────────────────────────────
   `.subnav-add-wrap` has to put the pill's border box on the CONTENT panel's
   right edge, and the sub-nav row's own box reaches past it — the row is
   `.app-split`'s width, which spans all three columns. The distance between
   the two is whatever the guide column is currently taking.

   IT SHIPPED AS `calc(var(--guide-w) + var(--split-gap))` AND THAT IS WRONG IN
   TWO REAL STATES, both measured: below 1100px `.app-split` wraps and the
   guide drops UNDER the content, so the lane is 0 and the pill sat 306px
   inside the panel; and `.app-guide.is-collapsed` is 52px, which would have
   left it 238 out. Three arrangements, and a constant can only be right in one
   of them. The CSS could enumerate all three — a media query plus a
   `body:has(#app-guide.is-collapsed)` — and that restates the 1100 breakpoint
   and the 52 in a second place, which is how two copies of a number start to
   disagree. This asks the layout instead, the way _sizeLangSearchList asks
   Basic Info for its height rather than carrying a 463.

   BOTH READINGS ARE CONTENT-BOX TO CONTENT-BOX, so nothing here knows about
   --content-inset, the split's gap or the guide's width: the row's padding box
   against the panel's, and the difference is the answer by definition. Add a
   fourth column tomorrow and this still lands.

   The CSS keeps the three-column sum as its FALLBACK rather than 0, so the
   first paint of a cold load is already correct in the ordinary case and the
   solve only ever confirms it. */
let _subnavAddGapLast = null;
let _subnavAddArmed = false;
function _subnavAddSolve() {
  const row   = document.getElementById('app-subnav');
  const panel = document.getElementById('dashboard');
  if (!row || !panel || !document.getElementById('subnav-add-wrap')) return;
  const pr = panel.getBoundingClientRect();
  if (!pr.width) return;   // the panel is hidden — nothing to align to
  const rowRight   = row.getBoundingClientRect().right - parseFloat(getComputedStyle(row).paddingRight);
  const panelRight = pr.right - parseFloat(getComputedStyle(panel).paddingRight);
  const gap = Math.max(0, rowRight - panelRight);
  if (_subnavAddGapLast !== null && Math.abs(gap - _subnavAddGapLast) < 0.5) return;
  _subnavAddGapLast = gap;
  document.documentElement.style.setProperty('--subnav-add-gap', gap.toFixed(2) + 'px');
}
/* Armed ONCE on `#dashboard` itself, which is static markup and is the one box
   that moves in every case at issue: a window resize, the guide collapsing, the
   1100px wrap — and, the case a solve-on-render alone gets wrong, the view
   being SHOWN. Arriving at Submission renders the sub-nav row before the panel
   has a box (`.hidden` until the view switch lands), so the solve correctly
   bails and there is nothing left to re-run it; measured, the pill sat 306px
   inside the panel until the next unrelated repaint. The observer fires on the
   0 → N transition and closes that by itself.

   Observing what you measure would normally risk a loop. It cannot here: what
   this writes is a margin on an item inside the sub-nav row, and nothing in
   that row can change the content panel's width. */
function _subnavAddArm() {
  if (_subnavAddArmed || typeof ResizeObserver !== 'function') return;
  const panel = document.getElementById('dashboard');
  if (!panel) return;
  _subnavAddArmed = true;
  new ResizeObserver(() => _subnavAddSolve()).observe(panel);
}

function toggleAddPlatform(event) {
  if (event) event.stopPropagation();
  const wasOpen = !!(state.submission && state.submission.addOpen);
  closeAllDropdowns();
  if (!wasOpen) {
    state.submission.addOpen = true;
    document.getElementById('subnav-add-wrap')?.classList.add('is-open');
    document.getElementById('subnav-add-btn')?.setAttribute('aria-expanded', 'true');
  }
}

/* ═══ THE SUBMISSION PANE (v6.29) ════════════════════════════════════════════
   The steps stopped opening a modal and started expanding where they are.
   openStepModal and the whole .submit-modal shell are still here and still
   work — the Product Page Preview's sub-sections deliberately still use them
   (see openStorePreviewSection below) — but nothing in the pane reaches them.
   ═════════════════════════════════════════════════════════════════════════ */

function selectPlatformTab(pid) {
  if (!state.activePlatforms.has(pid)) return;
  /* SET, not toggle — see setGuideFace. The `&& !addOpen` this carried was for
     the picker that blanked the pane: pressing the tab you were already on had
     to be able to bring it back. A dropdown never took it away, and the press
     closes the menu on its own through closeAllDropdowns, so re-rendering here
     would be a scroll-to-top for a tab you never left. */
  if (state.submission.tab === pid) return;
  state.submission.tab = pid;
  state.stepModal = null;
  /* Settings belong to the platform you were on. Moving to another tab and
     finding its steps replaced by an account face you opened somewhere else
     is the pane remembering a detour you had already left. */
  state.submission.settings = null;
  scrollContentToTop();
  renderDashboard();
}

/* ONE SECTION OPEN AT A TIME, and the opened header travels to the top.

   Both halves matter and the second is why the first is bearable. A step body
   is routinely taller than the viewport (Content Rating is 22 questions), so
   leaving several open would put the row you pressed anywhere on a page metres
   long. Collapsing the last one and bringing the new header to the top of the
   scrollport means the thing you just asked for is always in the same place.

   Pressing the OPEN section closes it. There is no separate close control and
   there is no footer button: every answer handler already writes straight to
   state as it is made, so a section has nothing left to "save" by the time you
   fold it. What collapsing does record is stepSaveAttempted — the flag that
   lets a risk dot appear on a row you have actually visited — which is the one
   piece of bookkeeping closeStepModal was doing that had to come with it. */
async function toggleStepSection(pid, stepId) {
  // Honour the layout flag even when something calls this directly (the submit
  // gate opens Upload Build this way), so there is one behaviour per mode.
  if (state.submission?.layout === 'modal') return openStepModal(pid, stepId);
  if (!state.submission.openStep) state.submission.openStep = {};
  const wasOpen = state.submission.openStep[pid] === stepId;

  // Closing (either by pressing this row again, or by opening another one)
  // counts as having visited whatever was open.
  const prev = state.submission.openStep[pid];
  if (prev) {
    if (!state.stepSaveAttempted) state.stepSaveAttempted = new Set();
    state.stepSaveAttempted.add(`${pid}-${prev}`);
  }

  if (wasOpen) {
    state.submission.openStep[pid] = null;
    state.stepModal = null;
    _renderSubPane(pid);
    return;
  }

  state.submission.openStep[pid] = stepId;
  // Expanding the row in the inline pane is the same visit the modal records
  // at the top of openStepModal — see STEP_REQUIRES_VISIT (state.js). Distinct
  // from stepSaveAttempted above, which means "closed at least once" and only
  // drives risk dots; this fires on OPEN, so a step opened and left open still
  // counts as looked at.
  markStepSectionSeen(pid, stepId);

  /* `state.stepModal` IS "WHICH STEP AM I IN", NOT "IS A MODAL OPEN" — and the
     pane has to keep it current even though it opens no modal.

     Twenty-one handlers across app.js and render.js resolve the platform they
     are writing to as `state.stepModal?.platformId || 'ios'`. That was true
     enough while a step could only be reached through the modal. With the pane
     leaving it null, every one of them silently fell back to 'ios' — so
     answering a question on Mac App Store wrote into the App Store's answers —
     and togglePrivacyPreset, the one with no fallback, got `undefined` and did
     nothing at all, which is why Data Collection could not be finished from a
     preset while the Data Types table still worked by hand.

     Setting it here is the same move as the pane keeping the card's
     `active-card-<pid>` id: one assignment at the boundary, instead of
     rewriting twenty-one call sites to ask a new question. Cleared on collapse
     so nothing reads a step that is no longer open. */
  state.stepModal = { platformId: pid, stepId, inferenceStatus: null };

  /* Everything openStepModal does on the way in, minus the overlay. These are
     one-time seeds and "seen" gates, not chrome: skipping them would leave
     Mac's listing unseeded and would stop Localizations and Product Page
     Preview ever counting as visited, which is half of what makes them
     complete (isIOSSectionComplete / isMacSectionComplete, state.js). */
  if (stepId === 'storePreview' || stepId === 'storePreviewPrototype') {
    if (!state.storePreviewFlipTarget) state.storePreviewFlipTarget = {};
    state.storePreviewFlipTarget[pid] = null;
    if (!state.storePreviewFocus) state.storePreviewFocus = { ios: null, macos: null };
    state.storePreviewFocus[pid] = null;
  }
  if (pid === 'android') seedOnboardingToAndroid();
  if (pid === 'ios' || pid === 'macos' || pid === 'macos_full') {
    seedOnboardingToIOS(pid);
    if (pid === 'macos')      seedMacAppStoreListing();
    if (pid === 'macos_full') seedMacFullAppStoreListing();
  }
  _markStepVisited(pid, stepId);

  const step = PLATFORMS[pid].steps.find(s => s.id === stepId);
  if (!state.submission.infer) state.submission.infer = {};
  state.submission.infer[pid] = { step: stepId, status: null, error: null };

  if (step?.hasInference && CLAUDE_API_KEY) {
    state.submission.infer[pid].status = 'loading';
    _renderSubPane(pid, true);
    try {
      /* NO `delete` HERE. runInference caches on the prompt's own signature
         (claude.js) and returns instantly when the input has not changed, which
         is exactly what "collapsing and reopening must not re-infer" needs.
         Clearing the key first — which this did, on a comment about re-running
         to pick up the latest knowledge — defeated that guard every single
         time. The signature already answers "has anything changed"; an explicit
         Retry (_retryInference) is the one path that still forces a re-run. */
      await runInference(pid, stepId);
      state.submission.infer[pid].status = 'done';
      _postInferenceSetup(stepId);
    } catch (err) {
      state.submission.infer[pid].status = 'error';
      state.submission.infer[pid].error  = err.message === 'NO_KEY' ? 'No API key set.' : err.message;
    }
    _renderSubPane(pid);
    return;
  }

  _renderSubPane(pid, true);
  if (stepId === 'improveSubmission') _autoRunImproveSubmission(pid);
}

/* THE ESCAPE HATCH FROM THE INLINE PANE.

     smSubmitLayout('modal')   steps open the step modal (the DEFAULT, v6.47)
     smSubmitLayout('inline')  steps expand in Mark's pane
     smSubmitLayout()          reports which is active

   Console-only, like smCardState and smReviewVariant, and for the reason the
   dev bar was deleted under: a switch on screen is how a comparison control
   quietly becomes part of the app. Nothing about the modal path was removed to
   build the pane — openStepModal, the .submit-modal shell and every step body
   builder are the same functions both surfaces call — so this really does
   revert the interaction rather than re-implementing it. It also collapses any
   open section on the way, or the pane would keep drawing a body no row can
   close. */
function smSubmitLayout(mode) {
  /* The fallback is 'modal' as of v6.47, matching the literal in state.js. It
     is unreachable while that literal exists — this is the reporting arm and
     the field is always set — but a fallback that names the OTHER arm is a
     second statement of the default, and two of those is how they drift. */
  if (mode !== 'modal' && mode !== 'inline') return state.submission.layout || 'modal';
  state.submission.layout = mode;
  state.submission.openStep = {};
  state.stepModal = null;
  renderDashboard();
  return 'submission layout: ' + mode;
}

/* ── THE STEP BODY SAYS WHEN THERE IS MORE ─────────────────────────────────
   A capped, scrolling box with no edge treatment is indistinguishable from a
   box that simply ends — Content Rating's twenty-two questions were being read
   as however many happened to fit, and the eleven below the fold were not
   "hidden", they were invisible. The cap is right (it is what keeps the steps
   below an open section on screen); what was missing is the box admitting to
   it.

   Two marks for one fact, deliberately, because they answer two different
   questions: the FADE says the content continues (the last row dissolving is
   the oldest signal there is), and the ARROW says you can do something about
   it. A fade alone reads as a styling flourish at this size; an arrow alone
   over a hard cut reads as a button someone dropped on the edge.

   STATED POSITIVELY — the class is `is-scrollable-down`, so the resting state
   at the end of the scroll needs no class at all. That is `_smModalFades`'s own
   correction: a mark that has to be REMOVED at the boundary flashes for one
   frame on every fresh render before the code catches up. */
function _subScrollCue() {
  const body = document.getElementById('sub-step-body');
  if (!body) return;

  const update = () => {
    /* A TALLER CONTENT IS NOT A SCROLLER. Upload Build's body is
       `.sub-step-body--free` — no cap, `overflow: visible`, because it holds a
       dropdown that has to escape. Its content can exceed its own box without
       being scrollable, and a cue there would point at a scroll that cannot
       happen. Ask the overflow first, then the heights — the same order, and
       the same trap, `_smModalFades` already pays for. */
    const ov = getComputedStyle(body).overflowY;
    const scrollable = (ov === 'auto' || ov === 'scroll') &&
                       body.scrollHeight > body.clientHeight + 2;
    const more = scrollable &&
                 body.scrollTop + body.clientHeight < body.scrollHeight - 2;
    body.classList.toggle('is-scrollable-down', more);
  };

  body.addEventListener('scroll', update, { passive: true });
  update();
}

/* Pressing it travels one screenful, through the app's one scroll animation
   (`_smScrollTo`) rather than `scrollBy({behavior:'smooth'})` — see "The travel
   is ours, not the browser's" for why a per-engine smooth implementation is the
   thing this codebase avoids.

   0.85 of a screen, not a whole one: a full page turn leaves nothing in common
   between the two views, so you cannot tell whether you moved or the content
   was replaced. The overlap is what makes it read as travel. */
function _subScrollCueClick(event) {
  event.stopPropagation();
  const body = document.getElementById('sub-step-body');
  if (!body) return;
  const max = Math.max(0, body.scrollHeight - body.clientHeight);
  _smScrollTo(body, Math.min(max, body.scrollTop + body.clientHeight * 0.85));
}

function _retryInferenceInline(pid, stepId) {
  if (!state.submission.openStep) state.submission.openStep = {};
  state.submission.openStep[pid] = null;   // force toggleStepSection to re-open
  toggleStepSection(pid, stepId);
}

/* Repaint the pane and, on the render that OPENS a section, bring its header to
   the top of the scrollport.

   The scroll is deliberately not `scrollIntoView`: the app scrolls inside
   `main.main`, and scrollIntoView on a nested scroller also nudges every
   ancestor, which on this layout drags the sticky guide column. Measuring the
   row against the scroller and setting scrollTop moves exactly one thing.
   16px of air above it so the header is not welded to the scrollport's edge. */
/* THE PAGE DOES NOT MOVE WHEN A SECTION OPENS.

   It used to bring the opened header to the top of the scrollport, on the
   argument that a long body could otherwise leave the row you pressed anywhere
   on the page. That argument is already answered by `--sub-body-max`: the box
   caps itself and scrolls internally, so nothing below an open section gets
   pushed off screen and there is nothing to chase. What the scroll added on top
   of that was a surface moving under the pointer immediately after a click —
   and because it ran against a list whose height was changing in the same
   frame, it landed short and read as a twitch rather than as travel.

   Kept as a parameter that now does nothing rather than removed from the four
   call sites: the argument above is worth being able to reverse in one place if
   a long step ever does outgrow the cap. */
function _renderSubPane(pid, _scrollToOpen) {
  renderDashboard();
}

/* Repaint ONLY the open step's body, in place.

   This is what every answer handler in the app reaches through
   reRenderStepModal while the pane is the surface on screen. It returns false
   when there is nothing of its kind to repaint, so that function can fall
   through to the modal path unchanged.

   Three things are restored by hand because innerHTML throws them away, and all
   three were real bugs: the box's own scrollTop (answering question 30 snapped
   you to question 1), and the two nested scrollers the modal already had to
   learn about — the Data Types matrix and the Mac preview's page column. */
function _repaintSubStepBody() {
  const pid    = submissionTab();
  const stepId = pid && state.submission?.openStep?.[pid];
  const bodyEl = document.getElementById('sub-step-body');
  if (!pid || !stepId || !bodyEl) return false;

  const bodyT = bodyEl.scrollTop;
  // Same pair as reRenderStepModal's — see the long note there. `.pvt-scroll`
  // is the accordion's, `.prv-matrix-wrap` is Google Play's and Steam's until
  // those two are ported; they never co-exist.
  const pm    = bodyEl.querySelector('.pvt-scroll, .prv-matrix-wrap');
  const pmT   = pm ? pm.scrollTop : null;
  const mm    = bodyEl.querySelector('.mac-spp-main');
  const mmT   = mm ? mm.scrollTop : null;

  bodyEl.innerHTML = _subStepBodyInner(pid, stepId);

  bodyEl.scrollTop = bodyT;
  if (pmT !== null) { const n = bodyEl.querySelector('.pvt-scroll, .prv-matrix-wrap'); if (n) n.scrollTop = pmT; }
  if (mmT !== null) { const n = bodyEl.querySelector('.mac-spp-main');    if (n) n.scrollTop = mmT; }

  _syncSubRowAndDashes(pid, stepId);
  // The listener died with the old innerHTML; the cue has to be re-armed for
  // the same reason _smModalFades is re-armed after every modal render.
  _subScrollCue();

  // Same reason as renderStepModal's own tail — see the note there. This is the
  // inline pane's paint, and the seen-flags are written while its HTML is built.
  if (typeof refreshGuideCompletion === 'function') refreshGuideCompletion();
  return true;
}

/* The two things OUTSIDE the body that an answer can still change: the row's
   own disc (a step can complete on the pill you just pressed) and the tab's
   progress dashes. Painted directly rather than by re-rendering, because
   re-rendering the strip is exactly the flash this split exists to remove.
   The disc goes through _paintStepRow, per CLAUDE.md — the two class systems
   are inverted and setting is-done/is-complete by hand is how they drift. */
function _syncSubRowAndDashes(pid, stepId) {
  if (typeof _paneComplete === 'function' && typeof _paintStepRow === 'function') {
    _paintStepRow(pid, stepId, _paneComplete(pid, stepId));
  }

  const countEl = document.querySelector(`#${pid}-step-card-${stepId} .sub-row-count`);
  const n = (typeof _stepUnansweredCount === 'function') ? _stepUnansweredCount(pid, stepId) : null;
  if (countEl) {
    if (n > 0) countEl.textContent = `${n} unanswered`;
    else countEl.remove();
  }

  const dashes = document.querySelectorAll(`#sub-tab-${pid} .sub-dash`);
  if (dashes.length) {
    const steps = _paneSteps(pid);
    const done  = steps.filter(s => _paneComplete(pid, s.id)).length
                + ((state.platformFlipped?.[pid] || state.platformStepStatus?.[pid]?.['submit'] === 'complete') ? 1 : 0);
    dashes.forEach((d, i) => d.classList.toggle('is-done', i < done));
  }

  const card = document.getElementById('active-card-' + pid);
  if (card) {
    const counts = platformStepCount(pid);
    card.classList.toggle('submit-ready', !!counts.allRequired);
    const submitRow = document.getElementById(`${pid}-step-card-submit`);
    if (submitRow) submitRow.classList.toggle('submit-step-locked', !counts.allRequired);
  }
}

/* THE TAB'S GEAR OPENS THE CONNECT MODAL, it does not turn anything over.
   On a card the gear flipped to the account face, which is a face of that
   card; a tab has no reverse. The account face's own two bodies are reused
   verbatim — settings when the platform is connected, the three-stage connect
   flow when it is not — so there is no third description of "your account on
   this store" to keep in sync. */
/* THE GEAR SWAPS THE PANE, it does not open a modal.

   It was a modal for one version and the box was wrong. A modal is the shape
   for something you do INSTEAD of the page under it; connecting a store is part
   of the submission and is read against the steps it unblocks — Submit is
   locked until it is done, and gate 1 of submitStepClick points at this very
   button. Putting it in the pane keeps it on the same surface as the thing it
   is a prerequisite for, and the back arrow says the steps have not gone
   anywhere.

   The portal SIGN-IN stays a modal, and that distinction is the point rather
   than an inconsistency: openAscLogin draws a browser window with a URL bar and
   somebody else's site inside it (buildAscLoginModal). A separate window is
   exactly what it is depicting, and depicting it inside the pane would have
   Shipmate appearing to host appstoreconnect.apple.com. */
function platformGearFromTab(pid) {
  if (!state.activePlatforms.has(pid)) return;
  state.submission.tab      = pid;
  state.submission.settings = pid;
  state.stepModal = null;
  /* Collapse whatever step was open. It is not on screen any more, and coming
     back to a section you cannot see re-expanded is the pane deciding for you
     where you had got to. */
  if (state.submission.openStep) state.submission.openStep[pid] = null;
  scrollContentToTop();
  renderDashboard();
}

function closePlatformSettings() {
  const pid = state.submission?.settings;
  state.submission.settings = null;
  if (pid) _setPlatformFace(pid, 'steps');
  scrollContentToTop();
  renderDashboard();
}
function perfOpen(portal) { bcToast(`${portal} — connect the account to pull live figures. (Mock data shown for now.)`); }
function perfJump(id) { const el = document.getElementById(id); if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' }); }

/* ── Marketing subsections ────────────────────────────── */
/* ── BACK TO THE TOP WHEN THE CONTENT CHANGES ─────────────────────────────
   Switching tab or sub-tab, or flipping a card to an edit panel, replaces what
   is on screen but not where you are looking: the scroller kept its offset, so
   a new panel opened halfway down itself, and coming back from a 1500px-tall
   page left you in the middle of a form you had just arrived at.

   .main is the app's scroller and #step-modal-body is the modal's — measured,
   not guessed: they are the only two elements in the document whose overflow-y
   scrolls. The window is reset too, harmlessly, so a future layout that
   scrolls the document itself does not quietly reintroduce this.

   INSTANT, not smooth. This is a navigation, not a gesture — animating 1500px
   makes arriving somewhere feel like waiting for it. */
function scrollContentToTop() {
  document.querySelectorAll('main.main, #step-modal-body').forEach(n => { n.scrollTop = 0; });
  try { window.scrollTo(0, 0); } catch (_) {}
}

function mktSetSection(id) {
  state.marketing.section = id;
  scrollContentToTop();
  renderBroadcast();
  renderSubnav();
  if (typeof renderGuide === 'function') renderGuide();
}

/* ── Game Details sub-tabs (Game Details / Distribution / Localization / Content / Assets) ── */
/* VISITING COMPLETES IT, AND THERE ARE TWO DOORS (v7.12). Jaco: *"un bug que
   veo a veces en el checklist de shippy con el List Localizations: es como que
   a veces no se marca aunque marque las locs."*

   `state.localizationSeen` was written in exactly one place — `gdSetSection`,
   the sub-tab rail — while `chkGo`, the checklist's OWN navigation, sets
   `state.details.section` directly and then calls `setView`. So pressing
   "Select target languages" in Shippy's list landed you on the Localization
   pane with the flag still false, and since that flag was the row's whole
   done-state, adding languages from there never ticked it. Reaching the same
   pane from the rail ticked it instantly — before you had chosen anything —
   which is where the "a veces" comes from: same pane, two routes, two answers.

   One rule, both doors. A third way of getting there calls this too rather
   than repeating the condition, which is the inventory this file keeps being
   bitten by. */
function _gdMarkSectionSeen(id) {
  if (id === 'localization') state.localizationSeen = true;
}

function gdSetSection(id) {
  _masGlimmerCancelAll();   // see the note at setView
  state.details.section = id;
  scrollContentToTop();
  _gdMarkSectionSeen(id);
  renderDetails(); renderSubnav();
  if (typeof renderGuide === 'function') renderGuide();
}

/* Content Questions: switch the platform whose content-rating questionnaire is shown. */
function gdSetContentPlatform(pid) { state.details.contentPlatform = pid; renderDetails(); }

/* Shippy Guide horizontal collapse toggle (full card ↔ mini progress rail). */
/* `toggleGuide` is gone with the collapse chevron that was its only caller —
   see the note in renderGuide (render.js). */

/* Drive the inline "analyzing → questionnaire" flow for the selected platform.
   First view of a platform shows a loading screen; after a short beat we snapshot
   which answers inference filled (enabling the Unanswered/All filter) and reveal
   the questionnaire, defaulting to the unanswered questions. */
async function _kickContentQ() {
  const pid = state.details.contentPlatform;
  if (!pid) return;
  if (!state.contentQ.status) state.contentQ.status = {};
  if ((state.contentQ.status[pid] || 'idle') !== 'idle') return;  // already loading/ready
  state.contentQ.status[pid] = 'loading';
  // Run the REAL AI inference (unified across active platforms). Cached by
  // 'unified:questionnaire', so switching platforms reuses the same result.
  try {
    if (typeof runInference === 'function') await runInference(pid, 'questionnaire');
  } catch (err) {
    console.warn('[ContentQ] inference failed:', err && err.message);
  }
  // Snapshot which answers inference filled, then default to "Unanswered".
  try { takeFilterSnapshot(pid); } catch (e) {}
  if (pid === 'ios')          state.iosContentRatingExpanded     = false;
  else if (pid === 'android') state.androidContentRatingExpanded = false;
  else if (pid === 'steam')   state.steamContentRatingExpanded   = false;
  state.contentQ.status[pid] = 'ready';
  if (state.activeView === 'details' && state.details.section === 'content') renderDetails();
}
function mktToast(what) { bcToast(`${what} — coming soon in the Marketing hub.`); }
function mktReachOut(name) { bcToast(`Drafted a tailored outreach message to ${name} — connect email to send.`); }

/* ── Calendar / Checklist (Marketing → Calendar) ───────
   Every handler ends the same way: repaint the grid and the guide column, since
   the two are the same model seen twice and must never disagree. */
function _calRerender() {
  renderCalendar();
  if (typeof renderGuide === 'function') renderGuide();
  _calFitPop();
}

/* _calPopPos places the popover from an estimate of its height (POP_H), because
   it doesn't exist yet at that point. Once it's painted, measure the real thing
   and nudge it back inside the viewport if it overhangs — a read view with a
   long title and a note is a good deal taller than the editor.
   The correction is written straight to the node's style as well as to the
   draft: re-rendering here would take focus out of whatever field you're in. */
function _calFitPop() {
  requestAnimationFrame(() => {
    const pop = document.querySelector('.mcal-pop');
    const d = state.calendar.draft;
    if (!pop || !d) return;
    const r = pop.getBoundingClientRect();
    let dx = 0, dy = 0;
    if (r.bottom > window.innerHeight - 8) dy = window.innerHeight - 8 - r.bottom;
    if (r.top + dy < TOP_SAFE)             dy = TOP_SAFE - r.top;
    if (r.right > window.innerWidth - 8)   dx = window.innerWidth - 8 - r.right;
    if (r.left + dx < 8)                   dx = 8 - r.left;
    if (!dx && !dy) return;
    d.x += dx; d.y += dy;
    pop.style.left = d.x + 'px';
    pop.style.top  = d.y + 'px';
  });
}
/* The guide's two faces. Only the guide re-renders — the month it shows comes
   from `state.calendar`, which nothing here touches. */
/* A SEGMENTED CONTROL CANNOT TOGGLE. The two faces used to hang off one icon
   button that flipped `guideCal`, and a flip is the right verb for one button
   with two states. It is the wrong one the moment there are two halves: press
   the half that is already lit and a toggle turns it OFF, which from a
   segmented control reads as the control breaking — you asked for Checklist
   while on Checklist and landed on Month. So the halves SET rather than flip,
   and pressing the live one is a no-op that never reaches a render.
   `toggleGuideCal` stays because `_doFinalSubmit` and the keyboard path still
   mean "flip"; it is now a thin wrapper over the same setter, so the
   month-offset rule below lives in exactly one place. */
function setGuideFace(which) {
  const wantCal = which === 'cal';
  if (!!state.guideCal === wantCal) return;   // already there — nothing changed
  _applyGuideFace(wantCal);
}

function toggleGuideCal() {
  _applyGuideFace(!state.guideCal);
}

function _applyGuideFace(toCal) {
  state.guideCal = toCal;
  /* OPENING IT LANDS ON NOW. `calendar.monthOffset` starts at 1, because the
     Calendar TAB is a planning surface and opens on next month — but this face
     is a glance, and a glance that opens on a month with no "today" in it is
     the one thing it must not do. Only on the way IN, so paging from here and
     going back to the checklist keeps your place. It does move the Calendar
     tab's month with it; they are one calendar, and that is the trade. */
  if (state.guideCal) state.calendar.monthOffset = 0;
  renderGuide();
}

/* A day opens the panel underneath the grid rather than navigating: pressing
   the same day again closes it, so the gesture is its own undo. Only the guide
   re-renders — nothing about the calendar's own state changes here. */
function guideCalOpen(iso) {
  state.guideCalDay = (state.guideCalDay === iso) ? null : iso;
  /* Opening a DAY clears the focused submission. The two are different
     questions — "what is on the 17th" and "where is the App Store build" — and
     a focus that survived would leave the panel answering the second one under
     a header naming the first. */
  state.guideCalWait = null;
  renderGuide();
  /* Put the caret where the next keystroke is most likely meant to go. Not on
     a close: focusing an input that just stopped existing throws. */
  if (state.guideCalDay) {
    requestAnimationFrame(() => document.getElementById('gcal-add-input')?.focus());
  }
}

/* PRESSING A STRIP OPENS THE DAY AND FOCUSES THE SUBMISSION — both, in one
   press, because a strip is a fact about a day AND about a build, and arriving
   with only half of that on screen is why a strip that merely opened the day
   would be a second, thinner copy of the cell above it.

   Pressing the same submission on the same day lets go of it, the way pressing
   the same day again folds the panel: the gesture is its own undo. It lets go
   of the FOCUS and keeps the day open — the panel you are reading does not
   vanish, it goes back to describing the date. Pressing another lane, or the
   same lane on another day, moves the focus rather than toggling it. */
function guideCalWaitOpen(pid, iso) {
  const same = state.guideCalWait === pid && state.guideCalDay === iso;
  state.guideCalDay  = iso;
  state.guideCalWait = same ? null : pid;
  renderGuide();
}

/* ── HOVERING A LEDE ROW LIGHTS THAT WAIT'S OWN DAYS ─────────────────────────
   The band is a UNION and cannot say whose days are whose (see `_guideCalLede`
   and the span/due split in `buildGuideMiniCal`). The list above it names the
   store; this is what joins the two, for exactly as long as you point at a row.

   **IT TOUCHES THE DOM, IT DOES NOT RENDER.** A hover is not a state change —
   nothing about the submission, the month or the picked day is different
   because a pointer moved — and `renderGuide()` rebuilds this column with
   innerHTML, which would throw away the add row's half-typed title and its
   caret on every pass of the mouse. It is also the fastest possible way to make
   a hover feel broken. So: two class names, added and removed.

   **FOCUS IS THE ABSENCE OF DIMMING**, the rule the stripe presentation already
   settled. Every band day is the wait's yellow because colour is the STATE on
   this grid, so the pointed-at run cannot take a hue of its own and a ring on
   it would be two marks on one stroke. The others step back to .35 instead —
   this app's own value for "still true, just not what you asked for".

   Nothing to mark means nothing is marked: with one wait on the month, the
   whole band IS that wait, so `is-wait-lit` lands on every banded day and no
   day is dimmed. The class still goes on, because the alternative is a special
   case that only differs when it cannot be seen. */
function gcalWaitHover(pid) {
  const grid = document.querySelector('.gcal-grid');
  if (!grid) return;

  grid.classList.remove('is-wait-focus');
  grid.querySelectorAll('.is-wait-lit').forEach(c =>
    c.classList.remove('is-wait-lit', 'is-wait-lit-start', 'is-wait-lit-end'));
  if (!pid) return;

  /* Recomputed rather than cached: `_calWaits` is the same source the band, the
     day panel and the list itself read, so a hover cannot point at a range none
     of them agrees with. */
  const w = (typeof _calWaits === 'function' ? _calWaits() : []).find(x => x.pid === pid);
  if (!w) return;

  const lit = new Set();
  for (let d = new Date(w.from); d <= w.to; d = _calDay(d, 1)) lit.add(_calISO(d));

  /* THE LIT PIECE GETS ITS OWN CAPS, and this is the band's own `span-start` /
     `span-end` rule applied one layer in. The union's caps are drawn where the
     WHOLE band begins and ends; the bright segment inside it begins and ends
     somewhere else entirely, and left square it reads as a stroke someone cut
     with scissors rather than as a run of days.

     A ROW EDGE counts as both, for the band's reason and not by analogy: this
     highlight cannot flow from Saturday to Sunday either, so a wait crossing a
     week is two capsules, each capped at the line break. `i % 7` is what says
     so — arithmetic on the grid, never on the dates.

     The cells come back in grid order, so the index IS the position in the
     week; the weekday header is not a `.gcal-day` and cannot shift it. */
  const cells = [...grid.querySelectorAll('.gcal-day[data-iso]')];
  cells.forEach((c, i) => {
    if (!lit.has(c.dataset.iso)) return;
    c.classList.add('is-wait-lit');
    const prevLit = i % 7 !== 0 && cells[i - 1] && lit.has(cells[i - 1].dataset.iso);
    const nextLit = i % 7 !== 6 && cells[i + 1] && lit.has(cells[i + 1].dataset.iso);
    if (!prevLit) c.classList.add('is-wait-lit-start');
    if (!nextLit) c.classList.add('is-wait-lit-end');
  });
  grid.classList.add('is-wait-focus');
}

/* THE DOOR FOR THE COMPARISON, and it is a console function for the reason the
   dev bar was deleted: this is a decision aid with an expiry date, not a
   feature, and a visible switch is how the first quietly becomes the second.
   `smWaitStyle()` with no argument flips to the other presentation, so
   comparing them is one press of Enter; `?wait=stripe` (state.js) is the same
   choice through a reload. Both write the same `sm.wait` key, so the console
   and the URL cannot disagree. */
function smWaitStyle(v) {
  const next = (v === 'band' || v === 'stripe')
    ? v
    : (state.calWaitStyle === 'stripe' ? 'band' : 'stripe');
  state.calWaitStyle = next;
  state.guideCalWait = null;          // the band has no lane to focus
  try { localStorage.setItem('sm.wait', next); } catch (_) {}
  renderGuide();
  return next;
}

/* Adds to the SAME list `calDraftSave` writes (state.calendar.custom), with the
   same record shape — a title, on this date, no repeat. Kind, note and repeat
   are what the big calendar's popover is for; asking for them in a 254px
   column would make the quick thing the slow one. */
function guideCalAdd(iso) {
  const el = document.getElementById('gcal-add-input');
  const label = (el?.value || '').trim();
  if (!label) { el?.focus(); return; }
  const kind = CAL_KIND[state.guideCalKind] ? state.guideCalKind : 'marketing';
  const list = state.calendar.custom || (state.calendar.custom = []);
  list.push({ id: 'custom-' + Date.now(), kind, label, note: '', dateISO: iso, repeat: 'none' });
  /* Emptied BEFORE the repaint, because `_gcalRerender` carries the field's
     current value across on purpose — this is the one caller that wants it
     gone. The caret stays in the field either way, so the next one can be
     typed straight after. */
  if (el) el.value = '';
  _gcalRerender();
  requestAnimationFrame(() => document.getElementById('gcal-add-input')?.focus());
}

/* ── EDITING FROM THE PANEL ──────────────────────────────────────────────────
   Two kinds of item live in this list and they are changed in two different
   places, which is the whole reason these are functions rather than one line
   each: an item you added is a record in `calendar.custom` and is edited in
   place, while a built-in (the recurring and one-off items in CAL_RECURRING /
   CAL_ONEOFF) is a constant — it is changed by writing an OVERRIDE keyed on
   the occurrence, and removed by writing to `calendar.hidden`. Both of those
   maps already exist and `calDraftSave` / `calDraftDelete` write the same two;
   this just reaches them without the popover. */
function _gcalCustomRec(it) {
  return (state.calendar.custom || []).find(c => c.id === it.id) || null;
}

function guideCalCycleKind(key) {
  const it = _calFindByKey(key);
  if (!it) return;
  const kinds = Object.keys(CAL_KIND);
  const next  = kinds[(kinds.indexOf(it.kind) + 1) % kinds.length];
  const rec   = _gcalCustomRec(it);
  if (rec) {
    rec.kind = next;
  } else {
    /* An override replaces the whole displayed record, so every field it does
       not carry would come back empty. Spread what the occurrence is showing
       now and change the one thing. */
    (state.calendar.overrides || (state.calendar.overrides = {}))[key] = {
      kind: next, label: it.label, note: it.note || '',
      dateISO: it.date ? _calISO(it.date) : '', repeat: it.repeat || 'none',
    };
  }
  _gcalRerender();
}

function guideCalRemove(key) {
  const it = _calFindByKey(key);
  if (!it) return;
  /* **A DERIVED ITEM CANNOT BE HIDDEN** (v6.60) — see `_calIsDerived`
     (render.js) for the argument. The day panel stopped drawing an × on these,
     so nothing in the UI reaches this line; the guard is here anyway because
     the WRITER is the only place that covers every future caller, and hiding
     `decide-steam` would leave the band, the lede and the card all still saying
     the submission is out while the day it lands on claimed to be empty. */
  if (typeof _calIsDerived === 'function' && _calIsDerived(it)) return;
  const rec = _gcalCustomRec(it);
  if (rec) {
    state.calendar.custom = state.calendar.custom.filter(c => c.id !== rec.id);
  } else {
    (state.calendar.hidden || (state.calendar.hidden = {}))[key] = true;
  }
  _gcalRerender();
}

/* The colour of the thing you are about to type. Kept on `state` rather than
   read off the DOM so it survives the re-render that showing it requires. */
function guideCalNextKind() {
  const kinds = Object.keys(CAL_KIND);
  const cur   = CAL_KIND[state.guideCalKind] ? state.guideCalKind : 'marketing';
  state.guideCalKind = kinds[(kinds.indexOf(cur) + 1) % kinds.length];
  _gcalRerender();
}

/* One repaint for all of the above, and it does the two things a repaint here
   always has to: carry the half-typed title across (innerHTML throws the input
   away) and put the caret back where it was. */
function _gcalRerender() {
  const el    = document.getElementById('gcal-add-input');
  const text  = el ? el.value : '';
  const had   = document.activeElement === el;
  renderGuide();
  requestAnimationFrame(() => {
    const next = document.getElementById('gcal-add-input');
    if (!next) return;
    next.value = text;
    if (had || text) { next.focus(); next.setSelectionRange(text.length, text.length); }
  });
}

function calShiftMonth(n) {
  state.calendar.monthOffset += n;
  state.calendar.selectedWeek = null;   // a week of the old month means nothing here
  _calRerender();
}
function calToday() {
  state.calendar.monthOffset = 0;
  state.calendar.selectedWeek = null;
  _calRerender();
}
function calSetView(v) { state.calendar.view = v; _calRerender(); }

/* "+ New event" opens the composer on today when today is in the month you're
   looking at, and on the 1st otherwise — dropping a new item into a month you
   can't see would be worse than picking a visible day for it. */
function calNewToday(ev) {
  const today = _calToday();
  const first = _calMonth();
  const inView = today.getFullYear() === first.getFullYear() && today.getMonth() === first.getMonth();
  calNewItem(_calISO(inView ? today : first), ev);
}

/* Typing rebuilds the grid, which rebuilds the field — so the caret is put back
   where it was afterwards, or every keystroke would drop focus. */
function calSearch(v) {
  state.calendar.query = v;
  const el = document.getElementById('mcal-search');
  const pos = el ? el.selectionStart : null;
  _calRerender();
  requestAnimationFrame(() => {
    const next = document.getElementById('mcal-search');
    if (!next) return;
    next.focus();
    if (pos != null) { try { next.setSelectionRange(pos, pos); } catch (_) {} }
  });
}
/* Clicking the selected week again clears it — the gutter is a toggle, so there
   is always a way back to the whole month without hunting for a control. */
function calSelectWeek(iso) {
  state.calendar.selectedWeek = state.calendar.selectedWeek === iso ? null : iso;
  _calRerender();
}
/* Double-clicking a day opens the composer popover anchored to that cell. The
   position is worked out once, here, and kept on the draft — recomputing it on
   every re-render would make the popover jump while you type in it.
   POP_W has to match .mcal-pop's width in the stylesheet; it's needed in JS to
   keep the popover from hanging off the right edge of the grid. */
const POP_W = 268;
const POP_H = 296;   // approximate; only used to keep the popover inside the grid

/* Where the popover goes, given whatever was clicked inside a day cell. Beside
   the day, never on top of it — the date it belongs to has to stay readable.
   Right by default; if that would run off the grid it flips to the left of the
   cell rather than being squashed against the edge. Vertically it's kept inside
   the grid so the last rows don't open off-screen.
   Worked out once, when the popover opens, and kept on the draft: recomputing
   it on every re-render would make it jump around while you type. */
const TOP_SAFE = 72;   // clears the fixed header
function _calPopPos(ev, iso) {
  /* Viewport coordinates, because the popover is position:fixed. It has to be:
     it opens from the grid AND from the checklist, and those live in different
     columns — anchoring inside the calendar's own box left an undated item,
     which has no cell, stranded in the corner.

     The day is found in the live DOM by its date rather than taken from the
     event. A double-click fires two single clicks first, each of which
     re-renders the grid (they toggle the week selection), so by the time
     ondblclick runs its node is detached — and a detached node measures as all
     zeros. The event is the fallback, and covers the checklist rows. */
  let anchor = iso ? document.querySelector(`.mcal-day[data-iso="${iso}"]`) : null;
  if (!anchor && ev && ev.currentTarget) {
    anchor = ev.currentTarget.closest('.mcal-day, .mcal-task') || ev.currentTarget;
  }
  if (!anchor || !anchor.getBoundingClientRect) return { x: 24, y: TOP_SAFE };
  const r = anchor.getBoundingClientRect();
  // Beside it, flipping to the other side rather than hanging off the screen.
  let x = r.right + 10;
  if (x + POP_W > window.innerWidth - 8) x = r.left - POP_W - 10;
  return {
    x: Math.max(8, Math.min(x, window.innerWidth - POP_W - 8)),
    y: Math.max(TOP_SAFE, Math.min(r.top, window.innerHeight - POP_H - 8)),
  };
}
function calNewItem(iso, ev) {
  /* Called from two places — a double-click on the cell and the hover "+"
     inside it — so resolve up to the cell either way; the popover anchors to
     the day, not to whatever was clicked. */
  state.calendar.draft = { mode: 'new', date: iso, kind: 'marketing', text: '', note: '', repeat: 'none', ..._calPopPos(ev, iso) };
  _calRerender();
  requestAnimationFrame(() => {
    const el = document.getElementById('mcal-pop-title');
    if (el) { el.focus(); el.select(); }
    const note = document.getElementById('mcal-pop-note');
    if (note) calAutoGrow(note);
  });
}

/* Clicking an item on the grid opens the same popover on it. Ticking moved to
   the checklist and to this popover's own button — a chip that both opened
   details and toggled done on the same click couldn't do either predictably. */
function calOpenItem(key, ev) {
  const it = _calFindByKey(key);
  if (!it) return;
  const iso = it.date ? _calISO(it.date) : '';
  /* Opening an item takes the checklist to its week, so the panel on the right
     is showing the days the thing you just clicked lives among — rather than
     whichever week you happened to have selected before. Undated items leave
     the selection alone: they belong to no week. */
  if (it.date) state.calendar.selectedWeek = _calISO(_calDay(it.date, -it.date.getDay()));
  state.calendar.draft = {
    mode: 'detail',
    key, itemId: it.id,
    custom: String(it.id).startsWith('custom-'),
    date: iso,
    kind: it.kind, text: it.label, note: it.note || '', repeat: it.repeat || 'none',
    go: it.go || null,
    ..._calPopPos(ev, iso),
  };
  _calRerender();
  requestAnimationFrame(() => {
    const note = document.getElementById('mcal-pop-note');
    if (note) calAutoGrow(note);
  });
}

/* Every field is read back into state before any re-render, so switching the
   colour or the repeat doesn't wipe what's already been typed. */
function _calReadDraft() {
  const d = state.calendar.draft;
  if (!d) return null;
  const val = id => (document.getElementById(id) || {}).value;
  d.text = val('mcal-pop-title') ?? d.text;
  d.note = val('mcal-pop-note')  ?? d.note;
  d.date = val('mcal-pop-date')  || d.date;
  return d;
}
function _calRefocus() {
  requestAnimationFrame(() => {
    document.getElementById('mcal-pop-title')?.focus();
    const note = document.getElementById('mcal-pop-note');
    if (note) calAutoGrow(note);
  });
}
/* The note grows with what's written in it, up to a ceiling — past that it
   scrolls, so the popover can't grow taller than the grid it sits in. */
function calAutoGrow(el) {
  el.style.height = 'auto';
  el.style.height = Math.min(el.scrollHeight, 132) + 'px';
}
/* Enter belongs to the note itself; ⌘/Ctrl+Enter is how you save from inside it. */
function calNoteKey(e) {
  if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) { e.preventDefault(); calDraftSave(); }
}

/* Escape closes the popover whatever is open and wherever the focus is —
   reading an item, editing one, or typing in the note. One document-level
   listener rather than one per field, because the read view has no fields. */
function initCalendarKeys() {
  document.addEventListener('keydown', e => {
    if (e.key !== 'Escape') return;
    if (!state.calendar || !state.calendar.draft) return;
    e.preventDefault();
    e.stopPropagation();
    calDraftCancel();
  }, true);   // capture: get it before any field's own Escape handling
}
function calDraftKind(kind)     { const d = _calReadDraft(); if (!d) return; d.kind = kind;     _calRerender(); _calRefocus(); }
function calDraftRepeat(repeat) { const d = _calReadDraft(); if (!d) return; d.repeat = repeat; _calRerender(); _calRefocus(); }

/* Escape is handled once, globally, by initCalendarKeys — the read view has no
   field to hang a key handler on, so it can't live on the inputs. */
function calDraftKey(e) {
  if (e.key === 'Enter') calDraftSave();
}
/* Saving takes one of three routes, depending on what's being edited:
     a new item          → appended to state.calendar.custom
     one you created     → that record is updated in place
     a generated one     → an override under its key, since the item itself is
                           rebuilt from a rule or from the launch date and has
                           nothing to write back to. */
function calDraftSave() {
  const d = _calReadDraft();
  if (!d) return;
  const label = (d.text || '').trim();
  if (!label) { document.getElementById('mcal-pop-title')?.focus(); return; }
  const fields = {
    kind: d.kind, label,
    note: (d.note || '').trim() || (d.repeat === 'weekly' ? 'Repeats weekly' : ''),
    dateISO: d.date, repeat: d.repeat,
  };
  const list = state.calendar.custom || (state.calendar.custom = []);
  if (d.mode !== 'edit') {
    list.push({ id: 'custom-' + Date.now(), ...fields });
  } else if (d.custom) {
    const rec = list.find(c => c.id === d.itemId);
    if (rec) Object.assign(rec, fields);
  } else {
    (state.calendar.overrides || (state.calendar.overrides = {}))[d.key] = fields;
  }
  state.calendar.draft = null;
  _calRerender();
}
/* Deleting a generated item can't remove it at source either — it's hidden by
   key instead, and the rule that made it carries on producing the others. */
function calDraftDelete() {
  const d = state.calendar.draft;
  if (!d || d.mode !== 'edit') return;
  /* The same guard the guide's panel got in v6.60, on the OTHER surface that can
     write `calendar.hidden` — the Calendar tab's popover. One rule, two doors:
     a fact read off `platformFlipped` or `formData.releaseDate` is not a record
     this calendar owns, so it cannot be deleted from either of them. The
     popover's delete button is still drawn here (it is generic markup with no
     item in hand at parse time); that is the remaining half of this fix and it
     belongs with whoever next opens that builder. */
  if (typeof _calIsDerived === 'function') {
    const it = typeof _calFindByKey === 'function' ? _calFindByKey(d.key) : null;
    if (_calIsDerived(it)) { state.calendar.draft = null; _calRerender(); return; }
  }
  if (d.custom) {
    state.calendar.custom = (state.calendar.custom || []).filter(c => c.id !== d.itemId);
  } else {
    (state.calendar.hidden || (state.calendar.hidden = {}))[d.key] = true;
  }
  state.calendar.draft = null;
  _calRerender();
}

/* ── Dragging an undated item onto a day ───────────────
   Scheduling something is the one gesture the two halves share, so it's a drag
   from the checklist to the grid rather than a form. Only the "no date yet"
   rows are draggable; the dated ones already have their place.
   The dragged key is kept in state as well as on the dataTransfer — Safari
   won't let you read dataTransfer during dragover, and the drop target needs to
   know whether it should light up. */
let _calDragKey = null;
function calDragStart(ev, key) {
  _calDragKey = key;
  state.calendar.hintDone = true;   // it's been learnt; the hint retires on the next paint
  ev.dataTransfer.effectAllowed = 'move';
  ev.dataTransfer.setData('text/plain', key);

  /* The thing under the cursor and the thing left in the cell are two different
     objects, so each gets its own look.
     A clone is handed to setDragImage rather than letting the browser photograph
     the element itself: left to its own devices it takes the picture after this
     handler returns AND washes it out, which defeated the point of making it
     solid. The clone is styled .is-flying — its kind's colour at full strength,
     dark text — parked off-screen only long enough to be captured, and dropped
     on the next tick. */
  const el = ev.currentTarget;
  const ghost = el.cloneNode(true);
  ghost.classList.add('is-flying');
  ghost.style.position = 'fixed';
  ghost.style.top = '-9999px';
  ghost.style.left = '-9999px';
  ghost.style.width = el.offsetWidth + 'px';
  document.body.appendChild(ghost);
  try { ev.dataTransfer.setDragImage(ghost, ev.offsetX, ev.offsetY); } catch (_) {}
  setTimeout(() => ghost.remove(), 0);

  el.classList.add('is-dragging');
}
function calDragEnd() {
  _calDragKey = null;
  document.querySelectorAll('.is-dragging, .is-flying')
    .forEach(el => el.classList.remove('is-dragging', 'is-flying'));
  document.querySelectorAll('.mcal-day.is-drop').forEach(el => el.classList.remove('is-drop'));
}
function calDragOver(ev) {
  if (!_calDragKey) return;
  ev.preventDefault();                       // without this the drop never fires
  ev.dataTransfer.dropEffect = 'move';
  ev.currentTarget.classList.add('is-drop');
}
function calDragLeave(ev) { ev.currentTarget.classList.remove('is-drop'); }

/* Landing it: a custom item gets its own record updated, a generated one gets
   an override — the same split as saving from the popover. */
function calDrop(ev, iso) {
  ev.preventDefault();
  const key = _calDragKey || ev.dataTransfer.getData('text/plain');
  calDragEnd();
  if (!key) return;
  const it = _calFindByKey(key);
  if (!it) return;
  /* Launch day isn't an event that happens to sit on a date — it IS the date.
     Dragging it moves the release date itself, and every submission deadline
     recalculates off the new one. setLaunchDate keeps the checklist pane's
     countdown and the Platforms timeline in step. */
  if (it.id === 'launch-day') { setLaunchDate(iso); _calRerender(); return; }
  if (String(it.id).startsWith('custom-')) {
    const rec = (state.calendar.custom || []).find(c => c.id === it.id);
    if (rec) rec.dateISO = iso;
  } else {
    const ov = state.calendar.overrides || (state.calendar.overrides = {});
    ov[key] = { ...(ov[key] || {}), dateISO: iso };
  }
  _calRerender();
}

/* An item names where it gets resolved; this walks you there. chkGo() is the
   jump the Shippy checklist already uses — same switch of tab, same sub-tab,
   same scroll to the field — so the two lists behave identically.
   The popover is closed first: you're leaving this screen. */
function calGoItem(key) {
  const it = _calFindByKey(key);
  if (!it || !it.go) return;
  state.calendar.draft = null;
  chkGo(it.go.view, it.go.anchor || '', it.go.section || '');
}

/* Hovering a checklist row lights up the day it lives on. Straight DOM, no
   re-render: this fires on every pointer move across the list, and rebuilding
   the grid each time would be both slow and visibly janky. */
function calHiliteDay(iso) {
  document.querySelectorAll('.mcal-day.is-hilite').forEach(el => el.classList.remove('is-hilite'));
  if (iso) document.querySelector(`.mcal-day[data-iso="${iso}"]`)?.classList.add('is-hilite');
}
function calDraftCancel() { state.calendar.draft = null; _calRerender(); }
/* Detail -> edit. The read view holds no inputs, so there is nothing to read
   back first; the draft already carries every field. */
function calDraftEdit() {
  if (!state.calendar.draft) return;
  state.calendar.draft.mode = 'edit';
  _calRerender();
  _calRefocus();
}

/* Ticking from the popover: strike the title through, then let the popover go.
   Deliberately not re-rendering until the end — a repaint mid-animation would
   rebuild the node and kill it. The timeout matches the CSS in .mcal-pop.is-striking
   (280ms of strike, then a 140ms fade). Un-ticking skips the ceremony: there's
   nothing to celebrate about undoing something. */
const CAL_STRIKE_MS = 420;
/* Ticking runs as a small sequence rather than all at once: the popover closes,
   the item is struck through on its own day in the grid, and only when that has
   played does the checklist on the right show its check. Striking inside the
   popover was the wrong place for it — the thing being crossed off is on the
   calendar, not in the dialog that happened to be covering it. */
function calDraftDone(key) {
  const done = state.calendar.done;
  state.calendar.draft = null;
  if (done[key]) { delete done[key]; _calRerender(); return; }

  done[key] = true;
  renderCalendar();                        // popover gone, chip already struck
  requestAnimationFrame(() => {
    // Draws the line rather than having it appear; the class dies with the
    // next re-render, so there's nothing to clean up.
    document.querySelector(`.mcal-chip[data-key="${key}"]`)?.classList.add('is-just-done');
  });
  setTimeout(() => { if (typeof renderGuide === 'function') renderGuide(); }, CAL_STRIKE_MS);
}

function calToggleDone(key) {
  const done = state.calendar.done || (state.calendar.done = {});
  if (done[key]) delete done[key]; else done[key] = true;
  _calRerender();
}

/* ── Launch calendar (checklist pane) ─────────────────── */
function setLaunchDate(v) {
  state.formData.releaseDate = v;
  state.formData.releaseTiming = 'specific_date';
  renderChecklist();
  if (state.activeView === 'dashboard') renderDashboard();   // refresh the Platforms timeline
  /* AND THE GUIDE, which draws this date as the month's green box and prints it
     in the lede's own Launch day row (v6.58). `renderDashboard` does NOT rebuild
     that column — the same trap `_doFinalSubmit` is written under — so without
     this the date you just picked would land on the next unrelated repaint, and
     the row you set it from would still be showing the old one. */
  if (typeof renderGuide === 'function') renderGuide();
}

// Checklist item → jump to its tab (and Marketing sub-tab), then scroll to the field.
/* ── A SUBMISSION CHECKLIST ROW POINTS AT PLATFORM STEPS ──────────────────
   The Details rows all point at one field, so chkGo can scroll to it. A
   Submission row cannot: "Set content ratings" is a step on App Store AND Mac
   App Store AND Google Play AND Steam, and there is no one destination to
   send anybody to.

   So the row does whichever of the two honest things applies.

   ONE PLATFORM ACTIVATED and there IS a single destination — open that
   platform's step, exactly as clicking the row on its card would. Literally
   so: the card's own row is clicked rather than an opener being guessed at,
   because which opener is right depends on the platform (openStepModal vs
   openTaskModal) and on the layout flag (a modal, or the step expanding in
   place). Duplicating that decision here is how the two drift apart; the
   openStepModal below is only the fallback for a row that isn't on screen —
   a platform showing its account/settings face, say.

   OTHERWISE IT POINTS, by pulsing a ring around the step on the cards once.
   That covers two cases, both by request:

     • Several platforms. There is no one destination, and v6.54's answer —
       a ring that latched on until you clicked the row again — asked the
       developer to remember to switch it off. A single pulse says the same
       thing and cleans up after itself. It pulses only the steps NOT yet
       done, since "here is what is left" is the question the row is being
       asked.

     • Upload Build and Submit, even on a single platform. Neither has
       anything to open: Upload Build's section is an empty dropzone until a
       build exists, and Submit's row is a hold rather than a click
       (buildSubmitStepCard, render.js) — firing it from a checklist would
       submit a build from a place nobody expects to. So both point instead
       of navigating, on any number of platforms. */
/* The two rows that never navigate — see the header comment above. */
const CHK_PULSE_ONLY = new Set(['uploadBuild', 'submit']);
const CHK_GLOW_STEPS = {
  uploadBuild:       { stepIds: ['uploadBuild'] },
  contentRating:     { stepIds: ['contentRating'] },
  localizations:     { stepIds: ['localizations'] },
  /* Whichever door the platform has. App Store, Mac App Store and Mac App Store
     Full all carry a real 'privacy' row now, and it sits BEFORE 'storePreview'
     in each of their step lists — _chkPlatformStepId takes the first id the
     platform's own order offers, so those three land on the step.

     GOOGLE PLAY AND STEAM NOW LAND ON A STEP TOO, and nothing here had to
     change for it. This comment used to read "Google Play has no such row:
     its data safety is still a section of the Store Listing Preview, so it
     falls through to that step with a flip to 'data'" — true until those two
     platforms gained a 'dataSafety' row (PLATFORMS.android.steps /
     PLATFORMS.steam.steps, state.js). Because the resolution is "first id
     this platform's own order offers" rather than a list of which platforms
     have which door, the new rows are picked up by construction and the flip
     simply stops being reached.

     The `flip` stays, and is still load-bearing for any platform that carries
     a preview but no data row. It is applied only when the resolved step IS a
     preview (CHK_PREVIEW_STEPS), which is what keeps the step-carrying
     platforms from being sent through a flip they no longer need. */
  dataSafety:        { stepIds: ['privacy', 'dataSafety', 'storePreview', 'storePreviewPrototype'], flip: 'data' },
  storePages:        { stepIds: ['storePreview', 'storePreviewPrototype'] },
  improveSubmission: { stepIds: ['improveSubmission'] },
  submit:            { stepIds: ['submit'] },
};
const CHK_PREVIEW_STEPS = new Set(['storePreview', 'storePreviewPrototype']);

/* Which (platform, step) pairs a checklist row is talking about. Resolved
   through the same two helpers the row's own done-state is (render.js), so a
   row can never point at a step its platform does not carry — including the
   Localizations step that _visiblePlatformSteps hides when no supporting
   languages are selected. Submit is the exception the checklist already makes
   for it: every active platform answers for Submit, not only the handful that
   list an explicit step for it. */
function _chkStepTargets(key) {
  const cfg = CHK_GLOW_STEPS[key];
  if (!cfg) return [];
  if (key === 'submit') {
    return [...(state.activePlatforms || [])].map(pid => ({ pid, stepId: 'submit' }));
  }
  if (typeof _chkPlatformsWithStep !== 'function') return [];
  return _chkPlatformsWithStep(cfg.stepIds)
    .map(pid => {
      const stepId = _chkPlatformStepId(pid, cfg.stepIds);
      // The flip only applies when the step we landed on IS the preview — a
      // platform with its own card row for this goes straight to that row.
      const flip = (cfg.flip && CHK_PREVIEW_STEPS.has(stepId)) ? cfg.flip : null;
      return { pid, stepId, flip };
    })
    .filter(t => !!t.stepId);
}

/* IS THIS STEP DONE? Asked of the card row itself wherever one is on screen,
   because `.is-complete` is literally what the developer is looking at, and a
   pulse that rings a row with a tick in it reads as a mistake. Only a platform
   whose pane isn't currently rendered (the tab strip draws one at a time) falls
   back to the status map the row itself is built from. */
function _chkStepDone(pid, stepId) {
  const el = document.getElementById(`${pid}-step-card-${stepId}`);
  if (el) return el.classList.contains('is-complete');
  /* Off screen, ask what the row would have been built from — which for every
     step but Submit is platformSectionComplete, NOT platformStepStatus. The
     two are not the same thing: the status map is written by the submit flow
     and by the card painters, while a step row's tick is recomputed from the
     answers on every render (_paneComplete → platformSectionComplete). Submit
     is the exception the checklist already makes for it: it has no
     isXxxSectionComplete arm anywhere, only the flag _doFinalSubmit writes. */
  if (stepId !== 'submit' && typeof platformSectionComplete === 'function') {
    try { return !!platformSectionComplete(pid, stepId); } catch (_) { /* fall through */ }
  }
  return (state.platformStepStatus && state.platformStepStatus[pid]
          && state.platformStepStatus[pid][stepId]) === 'complete';
}

/* ONE PULSE, THEN GONE. The class removes itself on animationend rather than
   on a timer that has to be kept in step with the CSS, with a timeout only as
   a backstop for a browser that never fires the event (a tab backgrounded
   mid-animation, say — an element left ringed forever is the exact failure the
   latch was replaced to avoid).

   The remove/reflow/add is what makes a second click on the same row pulse
   again: re-adding a class the element already has does not restart a CSS
   animation, and reading offsetWidth in between is the standard way to force
   the style flush that does. */
function _chkPulse(el, tone) {
  if (!el) return;
  const cls = tone === 'done' ? 'is-chk-pulse-done' : 'is-chk-pulse';
  el.classList.remove('is-chk-pulse', 'is-chk-pulse-done');
  void el.offsetWidth;
  el.classList.add(cls);
  const off = () => {
    el.classList.remove('is-chk-pulse', 'is-chk-pulse-done');
    el.removeEventListener('animationend', off);
  };
  el.addEventListener('animationend', off);
  setTimeout(off, 2500);
}

/* Pulses every target that is on screen, and scrolls the first of them into
   view. When none of them is — the developer is on a tab whose own step is
   already done, and the ones left to do belong to another platform — it moves
   to the first platform that still has one rather than answering the click
   with nothing at all. */
function _chkPulseTargets(targets, tone) {
  if (!targets.length) return;
  const paint = () => {
    const els = targets
      .map(t => document.getElementById(`${t.pid}-step-card-${t.stepId}`))
      .filter(Boolean);
    if (!els.length) return false;
    els.forEach(el => _chkPulse(el, tone));
    els[0].scrollIntoView({ behavior: 'smooth', block: 'center' });
    return true;
  };
  requestAnimationFrame(() => {
    if (paint()) return;
    const elsewhere = targets[0];
    if (typeof selectPlatformTab === 'function') selectPlatformTab(elsewhere.pid);
    requestAnimationFrame(paint);
  });
}

function _chkOpenStep(pid, stepId, flip) {
  if (typeof selectPlatformTab === 'function') selectPlatformTab(pid);
  requestAnimationFrame(() => {
    const row = document.getElementById(`${pid}-step-card-${stepId}`);
    if (stepId === 'submit') {
      row?.scrollIntoView({ behavior: 'smooth', block: 'center' });
      return;
    }
    /* Data Collection Questions on a platform that reaches them THROUGH its
       preview — Google Play only, now that the Apple stores have their own
       step: open the preview and turn it over, exactly as its own "Answer Data
       Collection Questions" element does. openStorePreviewSection records the
       visit too (markStepSectionSeen). That visit no longer gates the checklist
       row — _chkDataSafetyDone reads the answers alone, see its own note — but
       it still clears the preview's own review prompt, which is the surface the
       developer is about to be looking at. */
    if (flip) {
      if (typeof openStepModal === 'function') openStepModal(pid, stepId);
      if (typeof openStorePreviewSection === 'function') openStorePreviewSection(pid, flip);
      return;
    }
    /* Clicking the card's own row is what keeps this identical to opening the
       step by hand, whichever opener that platform and layout use. But not
       every row HAS a click: in the pre-tab-strip presentation
       (submission.layout === 'modal') Upload Build is rendered inline on the
       card, holding the release block itself, with no handler to fire. Test
       for the handler rather than assume one, or that row swallows the click
       and nothing opens at all. */
    if (row && (row.hasAttribute('onclick') || row.getAttribute('role') === 'button')) {
      row.click();
      row.scrollIntoView({ behavior: 'smooth', block: 'center' });
      return;
    }
    row?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    if (typeof openStepModal === 'function') openStepModal(pid, stepId);
  });
}

/* WHAT THE ROW ITSELF CLAIMS, which is not always what its target step
   claims. For most rows the two are the same question asked twice — "Set
   content ratings" is done exactly when every platform's contentRating step
   is — and for those this changes nothing.

   Data safety is the row where they come apart, and it comes apart by design:
   Data Collection Questions is a SECTION of the Product Page Preview, so the
   ring lands on the preview step (see CHK_GLOW_STEPS.dataSafety), and that
   step covers Title, Subtitle, Screenshots, Business and Content as well. The
   disclosure can be finished while the preview around it is not. Reading the
   target step's state there told the developer their completed data safety
   still needed them. */
function _chkRowDone(key) {
  if (typeof _chkGroups !== 'function') return false;
  try {
    for (const g of _chkGroups()) {
      const row = g.items.find(i => i.step === key);
      if (row) return !!row.done;
    }
  } catch (_) { /* mid-boot */ }
  return false;
}

function chkGoStep(key) {
  setView('dashboard');
  const targets = _chkStepTargets(key);
  if (!targets.length) return;

  /* "Only one selected platform" is about what the developer activated, not
     about how many of them happen to carry this step — a project with App
     Store alone should open the step even for a row whose step list is
     shared. With one platform activated there is at most one target anyway. */
  const onePlatform = (state.activePlatforms ? state.activePlatforms.size : 0) === 1;
  if (onePlatform && targets.length === 1 && !CHK_PULSE_ONLY.has(key)) {
    _chkOpenStep(targets[0].pid, targets[0].stepId, targets[0].flip);
    return;
  }

  /* TWO COLOURS, BECAUSE THE ROW IS ANSWERING TWO DIFFERENT QUESTIONS (v6.59).

     Everything left to do rings AMBER — the app's one word for "this needs
     you", the same colour the store previews ring a required-but-empty field
     in. Pointing at outstanding work in the accent blue said "here it is" and
     stopped there; amber says what about it matters.

     But when every platform has already finished the step, there is no
     outstanding work to point at, and an amber ring around a row of ticks
     reads as an alarm over something that is fine. That case rings GREEN
     instead, on all of them — the same green the previews use for a satisfied
     requirement — so the click still answers ("all of these are done") rather
     than either going quiet or crying wolf.

     Deliberately every target rather than the incomplete subset here: with
     nothing incomplete, the subset is empty, and the whole point of the green
     pass is showing the set that IS done. */
  /* GREEN IS THE ROW'S ANSWER, NOT THE STEP'S. Either the row says it is done
     — which for data safety can be true while the preview it rings is not, see
     _chkRowDone — or every target step is done and there is nothing left to
     point at. Both are "this is finished"; both ring green on every target,
     because with nothing outstanding the outstanding subset is empty and the
     whole point of the green pass is showing the set that IS done. */
  const outstanding = targets.filter(t => !_chkStepDone(t.pid, t.stepId));
  if (_chkRowDone(key) || !outstanding.length) { _chkPulseTargets(targets, 'done'); return; }
  /* On a single platform the row has exactly one thing it could be pointing
     at, so it pulses that one whatever its state — and its state is already
     covered by the green branch above. */
  _chkPulseTargets(onePlatform ? targets : outstanding, 'todo');
}

function chkGo(view, anchor, section) {
  if (section && view === 'broadcast') state.marketing.section = section;
  if (section && view === 'details') { state.details.section = section; _gdMarkSectionSeen(section); }
  setView(view);
  if (anchor) requestAnimationFrame(() => {
    const el = document.getElementById(anchor);
    if (!el) return;
    el.scrollIntoView({ behavior: 'smooth', block: 'center' });
    _gdSpotlight(el);

    /* AND THE CARET IS ALREADY IN IT. "Write a description" that lands you next
       to the box, with the box still waiting to be clicked, asks you to do the
       same thing twice. Only when the anchor IS a field or contains one —
       "Choose platforms" points at a grid, and stealing focus there would put
       the caret somewhere invisible.

       `preventScroll` because focus() scrolls the field into view its own way
       and would fight the smooth scroll above, landing the page a few pixels
       off with a jump. The caret goes to the end of whatever is already there:
       for an empty field that is the start, and for a written one it is where
       you would carry on. */
    const field = el.matches('input, textarea, select') ? el
                : el.querySelector('input:not([type=hidden]), textarea, select');
    if (field) {
      field.focus({ preventScroll: true });
      if (typeof field.setSelectionRange === 'function' && typeof field.value === 'string') {
        try { const n = field.value.length; field.setSelectionRange(n, n); } catch (e) {}
      }
    }
  });
}

/* THE GUIDE POINTS, THE FORM ANSWERS. Pressing "Write a description" used to
   scroll the form to that field and stop there — on a long page of questions
   that all look alike, "which one did it mean?" is left to the user a second
   after they asked. The platform card already answers that kind of question by
   dimming everything that is not in the way (see _smSpotlight); this is the
   same move on the form.

   The dim goes on `.ob-q` — one question — and never on `.ob-section` or the
   form itself: opacity is a filter over a whole subtree, so dimming a container
   and expecting one child to climb back out of it does not work. Same trap as
   the card's, and as `is-complete`'s green. Scoped to the onboarding form,
   which is where every guide anchor but Marketing's lands; elsewhere it is a
   no-op rather than a half-applied effect. */
let _gdSpotTimer = null;
function _gdSpotlight(el, ms) {
  if (window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) return;
  const form = el.closest('.ob-form');
  const q    = el.closest('.ob-q');
  if (!form || !q) return;

  clearTimeout(_gdSpotTimer);
  form.querySelectorAll('.is-spotlit').forEach(n => n.classList.remove('is-spotlit'));
  q.classList.add('is-spotlit');
  form.classList.add('is-spotlight');

  _gdSpotTimer = setTimeout(() => {
    form.classList.remove('is-spotlight');
    /* Marks cleared only after the fade back, or the lit question drops to the
       dim level for a frame before everything comes up together. */
    setTimeout(() => form.querySelectorAll('.is-spotlit')
      .forEach(n => n.classList.remove('is-spotlit')), 260);
  }, ms || 1700);
}

/* ── Broadcast composer handlers ──────────────────────── */
// Live-refresh only the adapted-preview pane so the textarea keeps focus.
function bcRefreshAdapt() {
  const a = document.querySelector('.bc-adapt');
  if (a) a.outerHTML = buildBroadcastAdapt();
}
function bcSetMessage(v) { state.broadcast.message = v; bcRefreshAdapt(); }
function bcPreview(id)   { state.broadcast.previewDest = id; bcRefreshAdapt(); }
// Toggle a channel on/off. Auto storefronts toggle their power (storeOff);
// opt-in channels toggle membership in the active list.
function bcToggleChannel(id) {
  const b = state.broadcast;
  if (bcAutoStores().includes(id)) {
    const i = b.storeOff.indexOf(id);
    if (i >= 0) b.storeOff.splice(i, 1); else b.storeOff.push(id);
  } else {
    const i = b.active.indexOf(id);
    if (i >= 0) b.active.splice(i, 1); else b.active.push(id);
  }
  renderBroadcast();
}
function bcConnect(id) {
  const d = bcDest(id);
  bcToast(`Connect ${d ? d.name : 'this channel'} later — account linking is coming soon.`);
}
function bcToggleGroup(gid) {
  state.broadcast.expandedGroups[gid] = !state.broadcast.expandedGroups[gid];
  renderBroadcast();
}
function bcDraftWithAI() {
  const title = state.formData.title || 'Our game';
  state.broadcast.message =
    `${title} just got a major update! New content, fixes, and quality-of-life improvements are live today. ` +
    `Thanks to everyone in the community for the feedback that shaped this release — jump back in and let us know what you think.`;
  renderBroadcast();
}
function bcBroadcastNow() {
  const n = bcActiveChannels().length;
  if (!n) return;
  bcToast(`✓ Queued to ${n} channel${n === 1 ? '' : 's'} — connect accounts to post for real.`);
}
function bcSchedule() { bcToast('Scheduling comes with connected accounts — coming soon.'); }

// Lightweight self-contained toast (no dependency on other UI).
function bcToast(msg) {
  let el = document.getElementById('bc-toast');
  if (!el) {
    el = document.createElement('div');
    el.id = 'bc-toast';
    el.className = 'bc-toast';
    document.body.appendChild(el);
  }
  el.textContent = msg;
  el.classList.add('is-shown');
  clearTimeout(bcToast._t);
  bcToast._t = setTimeout(() => el.classList.remove('is-shown'), 3200);
}

function showOnboarding() {
  // Onboarding is now the "Add Game Details" tab inside the main app (no modal).
  showMainApp('details');
  // Re-apply highlight state after every render (ob-modal markup is re-used)
  _setObValidating(false); // triggers the latch logic inside _setObValidating
  updateObSectionStates();
}


/* ── Onboarding modal ────────────────────────────────── */

function openOnboarding(tab = 0) {
  state.onboardingTab = tab;
  // Trigger B: user is returning to the modal after completing onboarding →
  // enable highlights so unanswered fields are visually flagged.
  if (state.onboardingComplete) state.showHighlights = true;
  showOnboarding();
}

function closeOnboarding() {
  if (!state.onboardingComplete) return; // can't close if not yet done
  setView('dashboard');
}

function setOnboardingTab(idx) {
  _setObValidating(false);
  state.onboardingTab = idx;
  renderOnboarding();
  // No paintShippyPanel() needed here: renderOnboarding -> renderOnboardingBody
  // -> updateObSectionStates() already repaints the guide, with the new tab
  // index in place.
}

/* Required fields per tab — maps tab index to OB_Q_ANSWERED keys */
const OB_TAB_REQUIRED = [
  ['title', 'platforms'],              // Tab 0: About
  ['distribution'],                    // Tab 1: Distribution
  ['screenshots'],                     // Tab 2: Assets
  ['compliance'],                        // Tab 3: Compliance
];

function _setObValidating(on) {
  // Once highlights are enabled by a trigger (returning visit or AI pre-pop),
  // callers can't turn them off — state.showHighlights latches it permanently.
  const active = on || state.showHighlights;
  document.getElementById('ob-modal')?.classList.toggle('is-validating', active);
  document.getElementById('submit-modal')?.classList.toggle('is-validating', active);
  document.getElementById('cq-modal')?.classList.toggle('is-validating', active);
}

function nextOnboardingTab() {
  // Prototype mode: advance freely — validation only triggers on Launch Dashboard
  _setObValidating(false);
  if (state.onboardingTab < 2) {
    state.onboardingTab++;
    renderOnboarding();
    const body = document.getElementById('ob-body');
    if (body) body.scrollTop = 0;
  }
}

function toggleOnboardingPlatform(pid) {
  // Defensive, same reasoning as activatePlatform's own COMING_SOON_PLATFORMS
  // guard below: Basic Info's Select Platforms grid (buildObPlatTilesHTML,
  // render.js) already filters HIDDEN_PLATFORMS out of the tiles it draws,
  // so this only matters if something ever calls toggleOnboardingPlatform
  // directly instead of clicking a rendered tile. Only guards ACTIVATING a
  // hidden platform — if one is already active (state predating the hide),
  // clicking its (no longer rendered) tile isn't reachable anyway, but this
  // still lets a direct call deactivate one without tripping the guard.
  if (HIDDEN_PLATFORMS.has(pid) && !state.activePlatforms.has(pid)) return;
  if (state.activePlatforms.has(pid)) {
    state.activePlatforms.delete(pid);
  } else {
    state.activePlatforms.add(pid);
    if (!state.platformStepStatus[pid]) {
      state.platformStepStatus[pid] = makeEmptyPlatformSteps()[pid] || {};
    }
    // First time Mac App Store is turned on, snapshot Game Details' current
    // listing text into its own independent copy (seedMacAppStoreListing is
    // a no-op on every activation after the first).
    if (pid === 'macos') seedMacAppStoreListing();
    // Same one-time seed for Mac App Store Full's own independent listing.
    if (pid === 'macos_full') seedMacFullAppStoreListing();
  }
  // Re-render just the platform tiles section in-place (platform is now in Game Details tab)
  const gridWrap = document.getElementById('ob-plat-grid-wrap');
  if (gridWrap) {
    gridWrap.innerHTML = buildObPlatTilesHTML();
    gridWrap.classList.toggle('is-req-empty', state.activePlatforms.size === 0);
  }
  renderOnboardingFooter();
  updateObSectionStates();
  if (typeof renderGuide === 'function') renderGuide();   // "Choose platforms" reacts live
}

function prevOnboardingTab() {
  if (state.onboardingTab > 0) {
    _setObValidating(false);
    state.onboardingTab--;
    renderOnboarding();
    const body = document.getElementById('ob-body');
    if (body) body.scrollTop = 0;
  }
}

function completeOnboarding() {
  // Prototype mode: no mandatory fields — launch dashboard freely.
  // Validation infrastructure (OB_TAB_REQUIRED, _setObValidating) retained for future use.

  // Re-entering onboarding on an already-created project (e.g. via the
  // dashboard's "Edit game details" button, which calls openOnboarding(0)
  // directly) must update that project in place instead of spawning a
  // duplicate. The only case that should create a brand-new project is
  // createNewProject()'s explicit _newProjectMode flag, or there being no
  // active project yet at all (first-ever onboarding).
  const existingProj = !state._newProjectMode
    ? state.projects.find(p => p.id === state.activeProjectId)
    : null;

  if (existingProj) {
    // Editing an existing project's details — save the live-edited flat
    // state (formData/uploads/answers/platforms) back onto it rather than
    // creating a new project record.
    saveCurrentToProject();
  } else if (state._newProjectMode) {
    // Creating a 2nd+ project — preserve activePlatforms selected during onboarding
    const ver  = makeEmptyVersion('1.0');
    const proj = {
      id:               generateId('proj'),
      name:             state.formData.title,
      formData:         JSON.parse(JSON.stringify(state.formData)),
      uploads:          JSON.parse(JSON.stringify(state.uploads)),
      questionAnswers:  JSON.parse(JSON.stringify(state.questionAnswers)),
      questionInferred: JSON.parse(JSON.stringify(state.questionInferred)),
      versions:         [ver],
      buildCounters:    makeBuildCounters(),
    };
    state.projects.push(proj);
    state.activeProjectId = proj.id;
    state.activeVersionId = ver.id;
    // Keep state.activePlatforms — already populated by platform tiles in onboarding
    state.platformStepStatus = makeEmptyPlatformSteps();
    state._newProjectMode    = false;
  } else {
    // First project ever
    const ver  = makeEmptyVersion('1.0');
    const proj = {
      id:               generateId('proj'),
      name:             state.formData.title,
      formData:         JSON.parse(JSON.stringify(state.formData)),
      uploads:          JSON.parse(JSON.stringify(state.uploads)),
      questionAnswers:  JSON.parse(JSON.stringify(state.questionAnswers)),
      questionInferred: JSON.parse(JSON.stringify(state.questionInferred)),
      versions:         [ver],
      buildCounters:    makeBuildCounters(),
    };
    state.projects.push(proj);
    state.activeProjectId = proj.id;
    state.activeVersionId = ver.id;
    // Keep state.activePlatforms — already populated by platform-select tab in onboarding
    state.platformStepStatus = makeEmptyPlatformSteps();
    // Build counters start at 0 here, so the first upload is build 1.
    ensureBuildState(proj);
  }

  state.onboardingComplete = true;
  setView('dashboard');   // main app is already visible; just switch to the Submit tab
}


/* ── Task modal ──────────────────────────────────────── */

function openTaskModal(platformId, stepId) {
  const step = PLATFORMS[platformId].steps.find(s => s.id === stepId);
  if (step && (step.isSubmit || step.isReview)) {
    openSubmitModal(platformId);
    return;
  }
  state.activeModal = { type: 'task', platformId, stepId };
  renderTaskModal();
  document.getElementById('task-overlay').classList.remove('hidden');
  document.body.style.overflow = 'hidden';
}

function closeTaskModal() {
  state.activeModal = null;
  document.getElementById('task-overlay').classList.add('hidden');
  document.body.style.overflow = '';
  // No renderDashboard() here — targeted updates handle any state changes
}

function taskOverlayClick(e) {
  if (e.target === document.getElementById('task-overlay')) {
    closeTaskModal();
  }
}

/* Repaint one step row in place, without rebuilding the card — so only this
   disc animates rather than every completed one.

   IT SPEAKS THE NEW ROW'S VOCABULARY, and that is the whole point of the
   helper. The two card systems used inverted names: the old markup put
   `is-complete` on the dot and `is-done` on the row, the prototype's row does
   exactly the reverse — `is-done` on the disc, `is-complete` on the row. So
   when buildActiveCard moved to `.ios-step-card`, these two updaters kept
   setting classes that no longer meant anything: a step marked done stayed
   looking undone until something forced a full re-render.

   The disc's content has to change too. It holds the step number when
   pending, so completing it swaps the digit for the tick — which the old code
   never did, because the old `.task-dot` was empty and drew its check in CSS. */
/* A DONE ROW CANNOT CARRY A RISK DOT, AND ONLY THE BUILDERS KNEW IT (v7.08).
   Jaco: *"sigo viendo en la platform card view, a veces cuando entro y salgo de
   un modal como content rating o data safety, una pelotita roja al lado del
   chevron. Como si faltase algo por completar. Pero creo que está todo."*

   All three step-row builders emit the dot as
   `(done || !attempted || risk === 'LOW' || risk === 'NONE') ? '' : <span>` —
   so **`done` suppressing the dot is an invariant of the markup**, and while a
   row is only ever drawn by a render the two cannot disagree.

   Four functions draw one surgically instead: `_paintStepRow` here, and
   `updateIOSCard` / `updateAndroidCard` / `updateSteamCard`. Every one of them
   repaints the disc's `is-done`, the disc's glyph and the row's `is-complete` —
   and **none of them has ever touched the `.ios-step-risk` span**, which is a
   sibling of the chevron rather than anything inside the disc. So a row drawn
   incomplete-and-risky (which needs `stepSaveAttempted`, i.e. you opened the
   step and came back out — exactly the gesture reported) and then completed
   without a full render keeps a red dot beside a green tick: the card claiming
   a problem in a step that is finished.

   That is this file's own recurring shape — a surgical repaint is an inventory
   of consequences, and the inventory was one item short. It is a helper rather
   than the same line four times, because four copies is how the next item goes
   missing in three of them.

   IT ONLY REMOVES, which is deliberate and is the half worth knowing about.
   Putting a dot BACK needs `risk` too, and that comes from a different function
   per platform (`_appStoreSectionRisk`, `computeAndroidSectionRisk`,
   `computeSteamSectionRisk`), so a row going done → not-done still waits for a
   full render to warn. A stale FALSE ALARM is what was reported and is the
   worse failure of the two; the missing warning is real, pre-existing, and
   wants deciding rather than sweeping. */
function _clearStepRiskDot(row, done) {
  if (row && done) row.querySelector('.ios-step-risk')?.remove();
}

function _paintStepRow(platformId, stepId, done) {
  const disc = document.getElementById(`dot-${platformId}-${stepId}`);
  if (!disc) return;
  const row = disc.closest('.ios-step-card');
  _clearStepRiskDot(row, done);
  disc.classList.toggle('is-done', done);
  // The row's number is its position among the non-submit steps, 1-based —
  // the same expression buildActiveCard numbers them with. Uses
  // _visiblePlatformSteps (state.js) rather than the raw steps array so a
  // currently-hidden conditional step (e.g. 'localizations' before any
  // language is added) never throws off the numbering of the steps after it.
  const n = _visiblePlatformSteps(platformId)
    .filter(s => !s.isSubmit).findIndex(s => s.id === stepId) + 1;
  disc.innerHTML = done ? smCheckSVG(20) : String(n || '');
  if (row) row.classList.toggle('is-complete', done);
  if (done) {
    disc.classList.add('just-completed');
    disc.addEventListener('animationend', () => disc.classList.remove('just-completed'), { once: true });
  } else {
    disc.classList.remove('just-completed');
  }
}

function markTaskDone(platformId, stepId) {
  state.platformStepStatus[platformId][stepId] = 'complete';

  _paintStepRow(platformId, stepId, true);

  // Recalculate progress and update bar + step count
  const counts = platformStepCount(platformId);
  const pct = counts.total ? Math.round((counts.complete / counts.total) * 100) : 0;
  const barFill = document.getElementById(`bar-fill-${platformId}`);
  if (barFill) barFill.style.width = pct + '%';
  const stepCountEl = document.getElementById(`step-count-${platformId}`);
  if (stepCountEl) stepCountEl.textContent = `${counts.complete} / ${counts.total} steps`;

  // Unlock submit button if all required steps now done
  if (counts.allRequired && !counts.submitDone) {
    const submitBtn = document.getElementById(`submit-btn-${platformId}`);
    if (submitBtn) {
      submitBtn.classList.remove('is-locked');
      submitBtn.removeAttribute('disabled');
      submitBtn.setAttribute('title', 'Submit for review');
      submitBtn.setAttribute('onclick', `finalSubmit('${platformId}')`);
    }
  }

  closeTaskModal();
}

function markTaskUndone(platformId, stepId) {
  state.platformStepStatus[platformId][stepId] = 'not_started';

  _paintStepRow(platformId, stepId, false);

  // Recalculate progress
  const counts = platformStepCount(platformId);
  const pct = counts.total ? Math.round((counts.complete / counts.total) * 100) : 0;
  const barFill = document.getElementById(`bar-fill-${platformId}`);
  if (barFill) barFill.style.width = pct + '%';
  const stepCountEl = document.getElementById(`step-count-${platformId}`);
  if (stepCountEl) stepCountEl.textContent = `${counts.complete} / ${counts.total} steps`;

  // Re-lock submit button if requirements no longer met
  if (!counts.allRequired && !counts.submitDone) {
    const submitBtn = document.getElementById(`submit-btn-${platformId}`);
    if (submitBtn) {
      submitBtn.classList.add('is-locked');
      submitBtn.setAttribute('disabled', '');
      submitBtn.setAttribute('title', 'Complete all steps first');
      submitBtn.removeAttribute('onclick');
    }
  }

  closeTaskModal();
}


/* ── iOS Step Modal ───────────────────────────────────── */

// Resolve which platform's App-Store-shaped answers/meta object to read or
// write. Most fields are still per-platform — 'macos' gets its own
// independent state.macSubmitAnswers/state.macAnswerMeta, everything else
// (in practice only 'ios') keeps using state.iosSubmitAnswers/iosAnswerMeta
// exactly as before. But Content Rating and Data Privacy fields
// (IOS_MAC_SHARED_ANSWER_FIELDS, state.js) are answered ONCE and shared with
// the App Store — pass the fieldId being touched as the second argument and,
// for pid==='macos', a shared field routes straight to state.iosSubmitAnswers/
// iosAnswerMeta instead of Mac App Store's own. Omitting fieldId (or passing
// one that isn't shared) preserves the original pid-only behavior, so every
// existing Business-Questions call site needs no change at all. Shared by
// seedOnboardingToIOS and every Content Rating/Privacy/Business/IAP answer
// handler below.
function _appStoreAnswers(pid, fieldId) {
  // Mac App Store Full is fully independent — see makeBlankMacFullAnswers'
  // comment (state.js) — so it NEVER routes through the macos/iOS sharing
  // check below, even for fields that are shared between those other two.
  if (pid === 'macos_full') return state.macFullSubmitAnswers;
  if (pid === 'macos' && fieldId && IOS_MAC_SHARED_ANSWER_FIELDS.has(fieldId)) return state.iosSubmitAnswers;
  return pid === 'macos' ? state.macSubmitAnswers : state.iosSubmitAnswers;
}
/* THE BASE PRICE, PER STORE. `price` is an ordinary independent field on each
   Apple store's own answers object (makeBlankIOSAnswers, state.js) — these two
   exist so the half-dozen readers do not each have to remember the seed
   fallback, and so macos_full keeps reading the game-wide value it was always
   documented as sharing.

   The fallback is for the window before seedOnboardingToIOS has run for a
   platform (it fills `price` from state.formData.price the first time that
   platform is seeded). `?? ` and not `||`, because '' is a real answer. */
function _appStorePrice(pid) {
  if (pid !== 'ios' && pid !== 'macos') return state.formData.price || '';
  const a = _appStoreAnswers(pid, 'price');
  return a?.price ?? (state.formData.price || '');
}

function _setAppStorePrice(pid, value) {
  if (pid !== 'ios' && pid !== 'macos') { state.formData.price = value; return; }
  const a = _appStoreAnswers(pid, 'price');
  if (a) a.price = value;
  /* The App Store goes on writing the game-wide field. Every other surface that
     shows "the price" — Game Details' metadata summary, computeRisk's free-game
     test, the marketing page — is asking a question about the GAME, and the
     phone listing is the reasonable answer to it. Mac's edits stay Mac's. */
  if (pid === 'ios') state.formData.price = value;
}

/* The inline handler the Price field calls. Public name because it is written
   into an `oninput` attribute, which resolves against window.

   NO reRenderStepModal: this fires on every keystroke and a repaint would take
   the caret with it — the same reason setIapProductField skips its own repaint
   for `price` (see its `key !== 'price'` guard). The preview behind the modal
   reads the value on its next paint, which is the flip back out of Business
   Questions. */
function setAppStorePrice(pid, value) {
  _setAppStorePrice(pid, value);
  if (typeof refreshGuideCompletion === 'function') refreshGuideCompletion();
}

function _appStoreAnswerMeta(pid, fieldId) {
  if (pid === 'macos_full') return state.macFullAnswerMeta;
  if (pid === 'macos' && fieldId && IOS_MAC_SHARED_ANSWER_FIELDS.has(fieldId)) return state.iosAnswerMeta;
  return pid === 'macos' ? state.macAnswerMeta : state.iosAnswerMeta;
}

// Seed onboarding answers into iOS (or, for pid='macos', Mac App Store)
// submission state (idempotent — only fills nulls). Called once per
// platform at app load / onboarding-complete, and again defensively every
// time that platform's step modal opens (see openStepModal's default
// branch below) — matching how it always worked for iOS. Touches a MIX of
// shared (privacyPolicyUrl, collectsData) and independent (hasIAP,
// selectedCountries, distPreset) fields, so each resolves its own answers
// object by its own fieldId rather than sharing one `ans`/`meta` pair —
// for pid='macos' the shared ones resolve to state.iosSubmitAnswers (same
// object seedOnboardingToIOS('ios') itself would have already filled, so
// there's normally nothing left for the 'macos' call to do there) while the
// independent ones resolve to state.macSubmitAnswers, exactly as before.
function seedOnboardingToIOS(pid) {
  pid = pid || 'ios';
  const privacyAns  = _appStoreAnswers(pid, 'privacyPolicyUrl');
  const collectsAns  = _appStoreAnswers(pid, 'collectsData');
  const collectsMeta = _appStoreAnswerMeta(pid, 'collectsData');
  const bizAns  = _appStoreAnswers(pid);
  const bizMeta = _appStoreAnswerMeta(pid);
  if (!privacyAns.privacyPolicyUrl && state.formData.privacyUrl) {
    privacyAns.privacyPolicyUrl = state.formData.privacyUrl;
  }
  if (bizAns.hasIAP === null && state.questionAnswers.inAppPurchases !== null) {
    bizAns.hasIAP = state.questionAnswers.inAppPurchases;
    bizMeta.hasIAP = { humanConfirmed: true };
  }
  if (collectsAns.collectsData === null && state.questionAnswers.dataCollection !== null) {
    collectsAns.collectsData = state.questionAnswers.dataCollection;
    collectsMeta.collectsData = { humanConfirmed: true };
  }
  /* Seed once, then independent — the same contract seedMacAppStoreListing has
     for the listing text. Only `null` is unseeded; '' is a real answer. */
  if (bizAns.price === null || bizAns.price === undefined) {
    bizAns.price = state.formData.price || '';
  }
  if (bizAns.selectedCountries.length === 0) {
    const langs = new Set([state.formData.primaryLanguage, ...state.formData.localizations]);
    bizAns.selectedCountries = IOS_COUNTRIES
      .filter(c => langs.has(c.lang))
      .map(c => c.code);
    bizAns.distPreset = 'custom';
  }
}

// Pre-fills Mac App Store's own independent Product Page Preview listing
// (state.macAppStoreListing) from Game Details' current values THE FIRST
// TIME the Mac App Store platform is activated (toggleOnboardingPlatform /
// activatePlatform above, and defensively again from openStepModal below in
// case 'macos' was ever added to state.activePlatforms some other way) —
// the same "seed once, then fully independent" treatment seedOnboardingToIOS
// above gives the compliance-answers layer, and the Web platform's own
// Developer/Publisher fields. A no-op on every call after the first
// (state.macAppStoreListing already exists), so re-toggling Mac App Store
// off and back on — or simply opening its modal again — never overwrites
// edits already made to its own listing. primaryLanguage/localizations are
// deliberately NOT copied in here — see state.macAppStoreListing's own
// comment in state.js — they stay shared via state.formData for every
// platform, Mac App Store included.
function seedMacAppStoreListing() {
  if (state.macAppStoreListing) return;
  const fd = state.formData;
  state.macAppStoreListing = {
    title:        fd.title        || '',
    subtitle:     fd.subtitle     || '',
    description:  fd.description  || '',
    releaseNotes: fd.releaseNotes || '',
    // Deep-copied so editing a supporting language's Mac App Store text can
    // never mutate the App Store's own localizedStoreText entry (or vice
    // versa) — they only share a starting point, never live storage.
    localizedStoreText: JSON.parse(JSON.stringify(fd.localizedStoreText || {})),
  };
}

/* ── Mac App Store — Game Center Achievements ─────────────────────────────
   Backs the "Game Center" step (PLATFORMS.macos.steps, state.js), built to
   mirror App Store Connect's real Achievements section — see
   state.macGameCenterAchievements' own comment for the full shape. This is
   deliberately independent of, and higher-fidelity than, Mac App Store
   Full's own simplified gameCenter.achievements list (setMacFullField
   etc., further below) — the two were never meant to share data.

   Per-language Localizations were removed by request: Display Name/Earned
   Description/Pre-Earned Description/Image now live directly on the
   achievement itself (single-language, matching how every other field here
   already works) rather than in a repeatable per-language sub-list. */

// New achievements start expanded (collapsed: false) with every field blank.
// Only one achievement is ever expanded at a time (see
// expandMacGcAchievement's own comment, directly below) — a new one starts
// expanded too, so whatever else is currently open gets collapsed first,
// the same way.
function addMacGameCenterAchievement() {
  _collapseOtherMacGcAchievements(null);
  /* The id is lifted out of the literal so the reveal below can name the card
     it just created — see `_macGcRevealAchievement`. NEW ACHIEVEMENT sits under
     the whole list, so a developer with a dozen of them presses a button at the
     bottom of the scroll and the editor it opens is the one thing they cannot
     see; and `_collapseOtherMacGcAchievements` folding an open card above it in
     the same paint moves the new one further still. Same travel as expanding an
     existing row, which is the point: one gesture, one behaviour. */
  const id = generateId('ach');
  state.macGameCenterAchievements.push({
    id,
    refName: '',
    pointValue: '',
    hidden: false,
    achievableMultipleTimes: false,
    collapsed: false,
    saved: false,
    displayName: '',
    earnedDescription: '',
    preEarnedDescription: '',
    image: null,
  });
  reRenderStepModal();
  _macGcRevealAchievement(id);
}
function removeMacGameCenterAchievement(id) {
  state.macGameCenterAchievements = state.macGameCenterAchievements.filter(a => a.id !== id);
  reRenderStepModal();
}
// Text fields (refName/pointValue/displayName/earnedDescription/
// preEarnedDescription) mutate silently via this same setter on oninput —
// only Hidden/Achievable More Than Once (yes/no toggles, not
// focus-sensitive) need the immediate re-render.
function setMacGameCenterAchievementField(id, key, value) {
  const a = state.macGameCenterAchievements.find(a => a.id === id);
  if (!a) return;
  a[key] = value;
  if (key === 'hidden' || key === 'achievableMultipleTimes') reRenderStepModal();
}
// Collapses every OTHER currently-expanded achievement — "only one
// achievement expanded at a time" (addMacGameCenterAchievement/
// expandMacGcAchievement both call this before opening a new one, passing
// the id of the one about to be opened — or null, from
// addMacGameCenterAchievement, since the new achievement doesn't exist
// yet at collapse-time). Reuses saveMacGcAchievement itself for the actual
// collapse rather than a bare `a.collapsed = true`, so a collapse
// triggered this way gets exactly the same Reference-Name-required gate
// AND the same Localizations auto-translate propagation a real Save/
// header-click collapse gets — an incomplete achievement with no
// Reference Name yet simply stays open, same as clicking its own header
// does today (so in that one edge case two achievements can end up
// expanded at once — the alternative, silently discarding an in-progress
// achievement's uncommitted fields, would be worse).
function _collapseOtherMacGcAchievements(keepId) {
  state.macGameCenterAchievements
    .filter(a => a.id !== keepId && !a.collapsed)
    .forEach(a => saveMacGcAchievement(a.id));
}
// Clicking a collapsed achievement's row re-expands it for editing — same
// expand-on-click convention as expandIapProduct. Collapses whatever else
// is currently open first (_collapseOtherMacGcAchievements above) so only
// one achievement is ever expanded at a time.
/* OPENING AN ACHIEVEMENT BRINGS IT TO YOU (v7.09).
   Jaco: *"cuando entro al modal de achievements, si toco en uno de los
   achievements para editar (se expande), debería el scroll moverse
   automáticamente para centrarme la view al achievement específico."*

   The list is a column of collapsed rows, so the one you press is wherever it
   happened to be — and expanding it grows that row from ~44px to a full editor,
   which pushes its own fields below the fold and, if something above it
   collapsed in the same paint (`_collapseOtherMacGcAchievements`), moves the
   card you pressed as well. You press a row and end up looking at a different
   part of the list.

   IT TRAVELS WITH `_smScrollTo`, THE ONE ANIMATOR, and not with
   `scrollIntoView`: which box an engine picks and whether it honours `smooth`
   on a nested scroller is per-engine, and this modal stacks two — the whole
   reason "The travel is ours, not the browser's" exists. It runs AFTER
   `reRenderStepModal`, which rebuilds the markup and restores the scroll it
   captured, so the ease starts from where your eye actually is rather than from
   a position the render invented.

   AND IT CENTRES ONLY WHILE THE CARD FITS. `_smScrollCentre` is the obvious
   call and is wrong here: its delta is `(elTop − scTop) − (clientHeight −
   elHeight) / 2`, so once the element is TALLER than the scrollport that second
   term goes negative and the travel lands PAST the card's top edge — you would
   open an achievement and arrive in the middle of it, with Reference Name
   scrolled off above. An expanded editor is routinely taller than the modal's
   body. So a card that cannot fit is aligned to its top with the same air
   instead, which is what "centre it" means for something bigger than the frame.

   Written here rather than inside `_smScrollCentre` deliberately: that function
   is the Mac preview's pinned nav, measured across sixteen trips, and a target
   taller than its scrollport is a question for that surface on its own terms
   rather than one to answer from in here. */
function _macGcRevealAchievement(id) {
  const el = document.querySelector(`[data-ach-id="${CSS.escape(String(id))}"]`);
  if (!el) return;
  const sc = _smNearestScroller(el);
  if (!sc) return;
  const PAD  = 16;
  const elR  = el.getBoundingClientRect();
  const scR  = sc.getBoundingClientRect();
  const max  = Math.max(0, sc.scrollHeight - sc.clientHeight);
  const delta = (elR.height + PAD * 2 > sc.clientHeight)
    ? (elR.top - scR.top) - PAD
    : (elR.top - scR.top) - (sc.clientHeight - elR.height) / 2;
  _smScrollTo(sc, Math.max(0, Math.min(max, Math.round(sc.scrollTop + delta))));
}

function expandMacGcAchievement(id) {
  _collapseOtherMacGcAchievements(id);
  const a = state.macGameCenterAchievements.find(a => a.id === id);
  if (a) a.collapsed = false;
  reRenderStepModal();
  _macGcRevealAchievement(id);
}
// Collapses an achievement into its summary row — same convention as
// saveIapProduct. Reference Name is the one required field (mirroring ASC
// itself, which won't let an achievement save without one). Used both by
// the expanded row's own Save button AND by clicking the row's header bar
// (render.js) — clicking the header of an achievement with no Reference
// Name yet simply does nothing, same as the disabled Save button.
//
// Also propagates the three localizable fields out to every supporting
// language — same "push to Localizations at save time" convention
// saveIapProduct uses for an IAP product's Name/Description
// (_iapLocPropagateName/_iapLocTriggerAutoTranslate). Achievement
// Localizations itself only WRITES these fields on an already-saved
// achievement (_masAchLocSavedAchievements filters on the persistent
// `.saved` flag set below — NOT `.collapsed`, which just tracks whether
// the row's UI is currently expanded and gets set back to false the
// moment a saved achievement is reopened for editing) — before this call was added here, a Display Name/Earned
// Description/Pre-Earned Description typed on the achievement's own
// expanded card (setMacGameCenterAchievementField, directly above) never
// triggered auto-translate at all, so every supporting language stayed
// blank in Achievement Localizations unless the developer happened to
// retype the SAME text a second time from inside that section. Steam-
// imported achievements never hit this gap (_checkSteamLocalizedAchievements
// populates their locs independently, on its own schedule), which is why
// the bug only ever showed up for non-Steam-sourced text. _masAchLocTriggerAutoTranslate
// itself no-ops per field when that field's auto-translate toggle is off,
// or when nothing actually changed since the last propagation, so calling
// all three unconditionally on every save (first save AND any later
// re-save after an edit) is always safe.
function saveMacGcAchievement(id) {
  const a = state.macGameCenterAchievements.find(a => a.id === id);
  if (!a || !a.refName.trim()) return;
  // Same "hard block on Save, soft while typing" limit treatment as
  // saveIapProduct (GC_ACHIEVEMENT_FIELD_LIMITS, render.js) — the Save
  // button is already disabled in the DOM for this case (see
  // _macGcAchievementExpandedRow's overAnyLimit), but this guard is the
  // actual source of truth.
  if (Object.keys(GC_ACHIEVEMENT_FIELD_LIMITS).some(f => (a[f] || '').length > GC_ACHIEVEMENT_FIELD_LIMITS[f])) return;
  a.collapsed = true;
  a.saved = true;
  _masAchLocTriggerAutoTranslate(id, 'displayName', a.displayName);
  _masAchLocTriggerAutoTranslate(id, 'earnedDescription', a.earnedDescription);
  _masAchLocTriggerAutoTranslate(id, 'preEarnedDescription', a.preEarnedDescription);
  reRenderStepModal();
}

// Same FileReader → dataUrl pattern as handleScreenshotFiles (further
// below) — stores the raw image inline on the achievement itself.
function handleMacGcAchievementImage(event, achId) {
  const file = event.target.files?.[0];
  if (!file) return;
  const a = state.macGameCenterAchievements.find(a => a.id === achId);
  if (!a) return;
  const reader = new FileReader();
  reader.onload = ev => {
    a.image = { name: file.name, dataUrl: ev.target.result };
    reRenderStepModal();
  };
  reader.readAsDataURL(file);
}
function removeMacGcAchievementImage(achId) {
  const a = state.macGameCenterAchievements.find(a => a.id === achId);
  if (!a) return;
  a.image = null;
  reRenderStepModal();
}

/* Drag-to-reorder for COLLAPSED achievement rows only (render.js only wires
   draggable/ondragstart etc. onto the collapsed row markup — an expanded
   row can't be dragged, mirroring the fact that App Store Connect's own
   list only supports reordering the collapsed summary rows). Same
   module-level-drag-key convention as calDragStart/calDrop above: the
   dragged id is kept off-state (purely a transient UI gesture, not
   something worth a state mutation of its own) and mirrored onto
   dataTransfer for browsers that need it read back on drop. Dropping A
   onto B moves A to B's current position — a plain splice-out/splice-in,
   not a swap, so dragging one row past several others in one gesture
   reorders correctly instead of only advancing by one slot. */
let _macGcDragId = null;
function macGcAchievementDragStart(ev, id) {
  _macGcDragId = id;
  ev.dataTransfer.effectAllowed = 'move';
  ev.dataTransfer.setData('text/plain', id);
  ev.currentTarget.classList.add('is-dragging');
}
function macGcAchievementDragOver(ev, id) {
  if (!_macGcDragId || _macGcDragId === id) return;
  ev.preventDefault(); // required for drop to fire
  ev.dataTransfer.dropEffect = 'move';
  ev.currentTarget.classList.add('is-drop');
}
function macGcAchievementDragLeave(ev) {
  ev.currentTarget.classList.remove('is-drop');
}
function macGcAchievementDrop(ev, id) {
  ev.preventDefault();
  ev.currentTarget.classList.remove('is-drop');
  const fromId = _macGcDragId || ev.dataTransfer.getData('text/plain');
  macGcAchievementDragEnd();
  if (!fromId || fromId === id) return;
  const arr = state.macGameCenterAchievements;
  const fromIdx = arr.findIndex(a => a.id === fromId);
  const toIdx   = arr.findIndex(a => a.id === id);
  if (fromIdx === -1 || toIdx === -1) return;
  const [moved] = arr.splice(fromIdx, 1);
  arr.splice(toIdx, 0, moved);
  reRenderStepModal();
}
function macGcAchievementDragEnd() {
  _macGcDragId = null;
  document.querySelectorAll('.mac-gc-row.is-dragging, .mac-gc-row.is-drop')
    .forEach(el => el.classList.remove('is-dragging', 'is-drop'));
}

/* ── App Store (ios) — Game Center Achievements ───────────────────────────
   Full twin of the Mac App Store cluster directly above (addMacGameCenter-
   Achievement through macGcAchievementDragEnd) — same shape, same "only one
   expanded at a time" invariant, same Reference-Name-required collapse
   gate, same drag-to-reorder — reading/writing state.iosGameCenterAchievements
   instead of state.macGameCenterAchievements. Added for full feature parity
   with Mac App Store's Game Center; see that cluster's own comments for the
   complete rationale behind each piece — it isn't re-explained here. */

function addIosGameCenterAchievement() {
  _collapseOtherIosGcAchievements(null);
  state.iosGameCenterAchievements.push({
    id: generateId('ach'),
    refName: '',
    pointValue: '',
    hidden: false,
    achievableMultipleTimes: false,
    collapsed: false,
    saved: false,
    displayName: '',
    earnedDescription: '',
    preEarnedDescription: '',
    image: null,
  });
  reRenderStepModal();
}
function removeIosGameCenterAchievement(id) {
  state.iosGameCenterAchievements = state.iosGameCenterAchievements.filter(a => a.id !== id);
  reRenderStepModal();
}
function setIosGameCenterAchievementField(id, key, value) {
  const a = state.iosGameCenterAchievements.find(a => a.id === id);
  if (!a) return;
  a[key] = value;
  if (key === 'hidden' || key === 'achievableMultipleTimes') reRenderStepModal();
}
function _collapseOtherIosGcAchievements(keepId) {
  state.iosGameCenterAchievements
    .filter(a => a.id !== keepId && !a.collapsed)
    .forEach(a => saveIosGcAchievement(a.id));
}
function expandIosGcAchievement(id) {
  _collapseOtherIosGcAchievements(id);
  const a = state.iosGameCenterAchievements.find(a => a.id === id);
  if (a) a.collapsed = false;
  reRenderStepModal();
}
function saveIosGcAchievement(id) {
  const a = state.iosGameCenterAchievements.find(a => a.id === id);
  if (!a || !a.refName.trim()) return;
  a.collapsed = true;
  a.saved = true;
  _iasAchLocTriggerAutoTranslate(id, 'displayName', a.displayName);
  _iasAchLocTriggerAutoTranslate(id, 'earnedDescription', a.earnedDescription);
  _iasAchLocTriggerAutoTranslate(id, 'preEarnedDescription', a.preEarnedDescription);
  reRenderStepModal();
}

function handleIosGcAchievementImage(event, achId) {
  const file = event.target.files?.[0];
  if (!file) return;
  const a = state.iosGameCenterAchievements.find(a => a.id === achId);
  if (!a) return;
  const reader = new FileReader();
  reader.onload = ev => {
    a.image = { name: file.name, dataUrl: ev.target.result };
    reRenderStepModal();
  };
  reader.readAsDataURL(file);
}
function removeIosGcAchievementImage(achId) {
  const a = state.iosGameCenterAchievements.find(a => a.id === achId);
  if (!a) return;
  a.image = null;
  reRenderStepModal();
}

let _iosGcDragId = null;
function iosGcAchievementDragStart(ev, id) {
  _iosGcDragId = id;
  ev.dataTransfer.effectAllowed = 'move';
  ev.dataTransfer.setData('text/plain', id);
  ev.currentTarget.classList.add('is-dragging');
}
function iosGcAchievementDragOver(ev, id) {
  if (!_iosGcDragId || _iosGcDragId === id) return;
  ev.preventDefault(); // required for drop to fire
  ev.dataTransfer.dropEffect = 'move';
  ev.currentTarget.classList.add('is-drop');
}
function iosGcAchievementDragLeave(ev) {
  ev.currentTarget.classList.remove('is-drop');
}
function iosGcAchievementDrop(ev, id) {
  ev.preventDefault();
  ev.currentTarget.classList.remove('is-drop');
  const fromId = _iosGcDragId || ev.dataTransfer.getData('text/plain');
  iosGcAchievementDragEnd();
  if (!fromId || fromId === id) return;
  const arr = state.iosGameCenterAchievements;
  const fromIdx = arr.findIndex(a => a.id === fromId);
  const toIdx   = arr.findIndex(a => a.id === id);
  if (fromIdx === -1 || toIdx === -1) return;
  const [moved] = arr.splice(fromIdx, 1);
  arr.splice(toIdx, 0, moved);
  reRenderStepModal();
}
function iosGcAchievementDragEnd() {
  _iosGcDragId = null;
  document.querySelectorAll('.ios-gc-row.is-dragging, .ios-gc-row.is-drop')
    .forEach(el => el.classList.remove('is-dragging', 'is-drop'));
}

/* ── Mac App Store Full — Game Center Achievements ────────────────────────
   Full twin of the Mac App Store/App Store clusters above (addMacGameCenter-
   Achievement through iosGcAchievementDragEnd) — same shape, same "only one
   expanded at a time" invariant, same Reference-Name-required collapse
   gate, same drag-to-reorder — reading/writing
   state.macFullGameCenterAchievements instead of state.macGameCenterAchievements/
   state.iosGameCenterAchievements. Added for full feature parity with Mac
   App Store's Game Center; see that cluster's own comments for the complete
   rationale behind each piece — it isn't re-explained here. This supersedes
   the old, simpler macFullSubmitAnswers.gameCenter.achievements list
   (removed along with its UI, an earlier request) — this top-level array is
   the real, actively-used one now. */

function addMacFullGameCenterAchievement() {
  _collapseOtherMacFullGcAchievements(null);
  state.macFullGameCenterAchievements.push({
    id: generateId('ach'),
    refName: '',
    pointValue: '',
    hidden: false,
    achievableMultipleTimes: false,
    collapsed: false,
    saved: false,
    displayName: '',
    earnedDescription: '',
    preEarnedDescription: '',
    image: null,
  });
  reRenderStepModal();
}
function removeMacFullGameCenterAchievement(id) {
  state.macFullGameCenterAchievements = state.macFullGameCenterAchievements.filter(a => a.id !== id);
  reRenderStepModal();
}
function setMacFullGameCenterAchievementField(id, key, value) {
  const a = state.macFullGameCenterAchievements.find(a => a.id === id);
  if (!a) return;
  a[key] = value;
  if (key === 'hidden' || key === 'achievableMultipleTimes') reRenderStepModal();
}
function _collapseOtherMacFullGcAchievements(keepId) {
  state.macFullGameCenterAchievements
    .filter(a => a.id !== keepId && !a.collapsed)
    .forEach(a => saveMacFullGcAchievement(a.id));
}
function expandMacFullGcAchievement(id) {
  _collapseOtherMacFullGcAchievements(id);
  const a = state.macFullGameCenterAchievements.find(a => a.id === id);
  if (a) a.collapsed = false;
  reRenderStepModal();
}
function saveMacFullGcAchievement(id) {
  const a = state.macFullGameCenterAchievements.find(a => a.id === id);
  if (!a || !a.refName.trim()) return;
  // Same "hard block on Save, soft while typing" limit treatment as
  // saveIapProduct (GC_ACHIEVEMENT_FIELD_LIMITS, render.js) — the Save
  // button is already disabled in the DOM for this case (see
  // _macFullGcAchievementExpandedRow's overAnyLimit), but this guard is the
  // actual source of truth.
  if (Object.keys(GC_ACHIEVEMENT_FIELD_LIMITS).some(f => (a[f] || '').length > GC_ACHIEVEMENT_FIELD_LIMITS[f])) return;
  a.collapsed = true;
  a.saved = true;
  _macFullAchLocTriggerAutoTranslate(id, 'displayName', a.displayName);
  _macFullAchLocTriggerAutoTranslate(id, 'earnedDescription', a.earnedDescription);
  _macFullAchLocTriggerAutoTranslate(id, 'preEarnedDescription', a.preEarnedDescription);
  reRenderStepModal();
}

function handleMacFullGcAchievementImage(event, achId) {
  const file = event.target.files?.[0];
  if (!file) return;
  const a = state.macFullGameCenterAchievements.find(a => a.id === achId);
  if (!a) return;
  const reader = new FileReader();
  reader.onload = ev => {
    a.image = { name: file.name, dataUrl: ev.target.result };
    reRenderStepModal();
  };
  reader.readAsDataURL(file);
}
function removeMacFullGcAchievementImage(achId) {
  const a = state.macFullGameCenterAchievements.find(a => a.id === achId);
  if (!a) return;
  a.image = null;
  reRenderStepModal();
}

let _macFullGcDragId = null;
function macFullGcAchievementDragStart(ev, id) {
  _macFullGcDragId = id;
  ev.dataTransfer.effectAllowed = 'move';
  ev.dataTransfer.setData('text/plain', id);
  ev.currentTarget.classList.add('is-dragging');
}
function macFullGcAchievementDragOver(ev, id) {
  if (!_macFullGcDragId || _macFullGcDragId === id) return;
  ev.preventDefault(); // required for drop to fire
  ev.dataTransfer.dropEffect = 'move';
  ev.currentTarget.classList.add('is-drop');
}
function macFullGcAchievementDragLeave(ev) {
  ev.currentTarget.classList.remove('is-drop');
}
function macFullGcAchievementDrop(ev, id) {
  ev.preventDefault();
  ev.currentTarget.classList.remove('is-drop');
  const fromId = _macFullGcDragId || ev.dataTransfer.getData('text/plain');
  macFullGcAchievementDragEnd();
  if (!fromId || fromId === id) return;
  const arr = state.macFullGameCenterAchievements;
  const fromIdx = arr.findIndex(a => a.id === fromId);
  const toIdx   = arr.findIndex(a => a.id === id);
  if (fromIdx === -1 || toIdx === -1) return;
  const [moved] = arr.splice(fromIdx, 1);
  arr.splice(toIdx, 0, moved);
  reRenderStepModal();
}
function macFullGcAchievementDragEnd() {
  _macFullGcDragId = null;
  document.querySelectorAll('.macfull-gc-row.is-dragging, .macfull-gc-row.is-drop')
    .forEach(el => el.classList.remove('is-dragging', 'is-drop'));
}

// Twin of seedMacAppStoreListing above, for Mac App Store Full's own
// independent Product Page Preview listing (state.macFullAppStoreListing —
// see its own comment, state.js). Same "seed once from Game Details, then
// fully independent" treatment, extended with the extra Version Information
// fields ASC actually asks for that macAppStoreListing doesn't carry
// (Promotional Text, Keywords, Support URL, Marketing URL, Copyright) —
// Title/Subtitle are NOT shared with either sibling platform here (no
// MAS_SHARED_LISTING_FIELDS-style routing for macos_full), per the "fully
// independent" design decision. Description is the one exception to "seed
// once, then fully independent": it's kept forced in sync with Game
// Details' Description going forward too — see
// _macFullPropagateDescription above.
function seedMacFullAppStoreListing() {
  if (state.macFullAppStoreListing) return;
  const fd = state.formData;
  state.macFullAppStoreListing = {
    title:            fd.title            || '',
    subtitle:         fd.subtitle         || '',
    description:      fd.description      || '',
    releaseNotes:     fd.releaseNotes     || '',
    promotionalText:  '',
    keywords:         '',
    // Pre-populated from Steam's appdetails 'support_info.url'/'website'
    // fields when the linked title has a Steam page that provides them
    // (state.steamSupportUrl / state.webSite.officialWebsite — see
    // _applySteamAboutData, above) — same "auto-fill once, then freely
    // editable" treatment as every other Steam-sourced field on this
    // listing; left blank when Steam has nothing (or there's no Steam
    // link at all).
    supportUrl:       state.steamSupportUrl || '',
    marketingUrl:     (state.webSite && state.webSite.officialWebsite) || '',
    copyright:        '',
    localizedStoreText: JSON.parse(JSON.stringify(fd.localizedStoreText || {})),
  };
}

/* ── Mac App Store Full — generic nested-field setters ──────────────────
   Most of macFullSubmitAnswers' App-Store-Connect-specific fields are flat
   top-level fields (contentRights, bundleId, hasIAP, etc.) and already work
   through answerIOSField/updateIOSTextField above (both resolve pid from
   state.stepModal generically, and _appStoreAnswers/_appStoreAnswerMeta
   already route 'macos_full' to its own state.macFullSubmitAnswers/
   macFullAnswerMeta — see those functions' own comments). A handful of
   fields are nested objects instead (category.subcategory1, demoAccount.username,
   etc.) — these two helpers walk a dot-separated
   path into state.macFullSubmitAnswers for those, rather than adding a
   dedicated setter function per field. setMacFullField re-renders
   immediately (for selects/toggles/checkboxes, where there's no focused
   input to preserve); setMacFullTextField mutates silently (for oninput on
   free-typing text inputs — call reRenderStepModal() separately on blur
   where the row needs to react, matching updateIOSTextField's own
   convention). Every one of macFullSubmitAnswers' new fields lives ONLY on
   Mac App Store Full — there is no ios/macos equivalent field these could
   ever collide with. */
function _mfNestedContainer(path) {
  const parts = path.split('.');
  let obj = state.macFullSubmitAnswers;
  for (let i = 0; i < parts.length - 1; i++) obj = obj[parts[i]];
  return { obj, key: parts[parts.length - 1] };
}
function setMacFullField(path, value) {
  const { obj, key } = _mfNestedContainer(path);
  obj[key] = value;
  reRenderStepModal();
  updateIOSCard('macos_full');
}
function setMacFullTextField(path, value) {
  const { obj, key } = _mfNestedContainer(path);
  obj[key] = value;
}

/* ── Mac App Store Full — App Information (new) ──────────────────────── */
// Writes straight into state.macFullAppStoreListing — the extended,
// FULLY INDEPENDENT superset of macAppStoreListing (see its own comment,
// state.js). Seeds first in case this is somehow the first touch of the
// listing (defensive — openStepModal/toggleOnboardingPlatform/
// activatePlatform already seed it before this step can be reached).
// Promotional Text/Keywords/Support URL/Marketing URL/Copyright — plain,
// primary-language-only, no per-language translation of their own — used
// to be Version Information's own fields; now edited from the new App
// Information section instead (buildMacFullAppInformationSection,
// render.js), same setter, just called from a different step. Title/
// Subtitle/Description/What's New are edited only from the Product Page
// Preview / Localization Review now (_macFullSetFieldValue, further below),
// never through here.
function setMacFullListingField(field, value) {
  seedMacFullAppStoreListing();
  state.macFullAppStoreListing[field] = value;
}

