async function openStepModal(pid, stepId) {
  // A PENDING CROP IS FLUSHED ON THE WAY OUT, and it sits here for this
  // function's own stated reason: every per-platform branch below returns
  // early, so anything that has to happen on EVERY open has to happen before
  // them or be forgotten in the sixth. Leaving the Screenshots editor — back to
  // the store preview, or to any other step — is the end of the gesture, and a
  // debounced write that nothing flushes is a write that is simply dropped.
  // No-op unless something is pending; see _shotEdFlush.
  _shotEdFlush();
  // Opening the step IS the visit — recorded before any of the per-platform
  // branches below, every one of which returns early, so this would otherwise
  // have to be repeated in five places (and be forgotten in the sixth).
  // Gates the steps in STEP_REQUIRES_VISIT; a no-op for every other step.
  markStepSectionSeen(pid, stepId);
  // Always reset storePreview sub-section — never restore last flip position
  if (stepId === 'storePreview') {
    if (!state.storePreviewFlipTarget) state.storePreviewFlipTarget = {};
    state.storePreviewFlipTarget[pid] = null;
    // Also clear any explicit footer-nav focus choice (setStorePreviewFocus)
    // left over from the last time this preview was open. Un-cleared, the
    // footer would reopen wherever the user last clicked to (done, optional,
    // or otherwise) instead of where they actually need to pick back up.
    // With it null, _sppFocusIndex's own fallback (render.js) takes over on
    // the very next render and lands on the earliest required-and-not-done
    // element, exactly like opening the preview for the first time would.
    if (!state.storePreviewFocus) state.storePreviewFocus = { ios: null, macos: null };
    state.storePreviewFocus[pid] = null;
  }

  if (pid === 'web') {
    state.stepModal = { platformId: pid, stepId, inferenceStatus: null };
    document.getElementById('submit-overlay').classList.remove('hidden');
    document.body.style.overflow = 'hidden';
    // Visiting the Preview Website step marks it complete (unlocks Deploy)
    if (stepId === 'storePreview' && state.platformStepStatus?.web) {
      state.platformStepStatus.web.storePreview = 'complete';
    }
    renderStepModal();
    return;
  }

  if (pid === 'android') {
    seedOnboardingToAndroid();
    state.stepModal = { platformId: pid, stepId, inferenceStatus: null };
    document.getElementById('submit-overlay').classList.remove('hidden');
    document.body.style.overflow = 'hidden';
    const andStep = PLATFORMS[pid].steps.find(s => s.id === stepId);
    if (andStep?.hasInference && CLAUDE_API_KEY) {
      state.stepModal.inferenceStatus = 'loading';
      renderStepModal();
      try {
        await runInference(pid, stepId);
        state.stepModal.inferenceStatus = 'done';
        _postInferenceSetup(stepId);
      } catch(err) {
        state.stepModal.inferenceStatus = 'error';
        state.stepModal.inferenceError  = err.message === 'NO_KEY' ? 'No API key set.' : err.message;
      }
      reRenderAndroidStepModal();
      updateAndroidCard();
    } else if (stepId === 'improveSubmission') {
      _autoRunImproveSubmission(pid);
    } else {
      renderStepModal();
    }
    return;
  }
  if (pid === 'steam') {
    state.stepModal = { platformId: pid, stepId, inferenceStatus: null };
    document.getElementById('submit-overlay').classList.remove('hidden');
    document.body.style.overflow = 'hidden';
    const stmStep = PLATFORMS[pid].steps.find(s => s.id === stepId);
    if (stmStep?.hasInference && CLAUDE_API_KEY) {
      state.stepModal.inferenceStatus = 'loading';
      renderStepModal();
      try {
        await runInference(pid, stepId);
        state.stepModal.inferenceStatus = 'done';
        _postInferenceSetup(stepId);
      } catch(err) {
        state.stepModal.inferenceStatus = 'error';
        state.stepModal.inferenceError  = err.message === 'NO_KEY' ? 'No API key set.' : err.message;
      }
      reRenderSteamStepModal();
      updateSteamCard();
    } else if (stepId === 'improveSubmission') {
      _autoRunImproveSubmission(pid);
    } else {
      renderStepModal();
    }
    return;
  }

  seedOnboardingToIOS(pid);
  if (pid === 'macos') seedMacAppStoreListing();
  if (pid === 'macos_full') seedMacFullAppStoreListing();

  state.stepModal = { platformId: pid, stepId, inferenceStatus: null };

  /* THE FLAGS GO IN BEFORE THE PAINT, WHICH IS WHAT THEIR OWN COMMENTS ALWAYS
     SAID — "Mark Store Page Preview as visited before rendering", "Mark
     Localizations as visited before rendering" — while both blocks sat AFTER
     the renderStepModal() call they were describing.

     Nothing repaints after them. A step with inference re-renders when the
     call comes back, and localizations has none, so `macLocalizationsSeen`
     became true the moment the modal opened and then waited for some unrelated
     render to be believed. Symptom: open Localizations on every platform,
     finish everything the step asks for, and "Complete localizations" stays
     grey on the Shippy Checklist — the predicate really was true, and the two
     surfaces that read it had both already been painted one line earlier.
     (This is why the v6.78 completion refresh on renderStepModal's tail could
     not catch it: the flag was written after the tail had run.)

     toggleStepSection — the inline pane's opener — already writes them in this
     order, so this is the modal path catching up with the pane's.

     Both openers now stamp through _markStepVisited (state.js) rather than
     each spelling the branches out; the ORDER this comment is about is
     unchanged, only the duplication is gone. See that function for what the
     two hand-written copies had already drifted into. */
  _markStepVisited(pid, stepId);

  // Open overlay immediately so user sees something
  renderStepModal();

  document.getElementById('submit-overlay').classList.remove('hidden');
  document.body.style.overflow = 'hidden';

  // For inference steps: re-run every open to use latest accumulated knowledge
  const step = PLATFORMS[pid].steps.find(s => s.id === stepId);
  if (step?.hasInference) {
    state.stepModal.inferenceStatus = 'loading';
    renderStepModal();
    try {
      await runInference(pid, stepId);
      state.stepModal.inferenceStatus = 'done';
      _postInferenceSetup(stepId);
    } catch(err) {
      state.stepModal.inferenceStatus = 'error';
      state.stepModal.inferenceError  = err.message === 'NO_KEY' ? 'No API key set.' : err.message;
    }
    reRenderStepModal();
    updateIOSCard(pid);
  } else if (stepId === 'improveSubmission') {
    _autoRunImproveSubmission(pid);
  }
}

function closeStepModal() {
  /* THE OTHER DOOR OUT, and it takes the same flush as openStepModal — the ×,
     Save & Close and Escape all land here, and a crop you made 200ms before
     pressing one of them is still sitting in a timer. Same no-op-unless-pending
     guarantee; this is the exit the file's own "every other field writes as you
     leave it" was always talking about. */
  _shotEdFlush();
  /* The read-only lock lives for one visit. Clearing it here rather than on
     open is what lets a submitted card and a live one coexist: the flag is
     set by the one entry point that should lock (openSubmittedStep) and
     dropped by every exit, so no path can leave a modal locked behind it. */
  state.stepModalReadOnly = null;
  /* Same reasoning for the pane's hoist flag: it is set by the one entry point
     that hoists (openStorePreviewSection) and has to be dropped by EVERY exit,
     or closing with the × instead of the back arrow leaves the next sub-section
     believing it was opened from a pane that has since moved on. */
  if (state.submission) state.submission.flipFromPane = null;
  // Record that this step has been saved/attempted at least once
  // (drives red-dot visibility and required-field alert visibility)
  const sm = state.stepModal;
  if (sm?.platformId && sm?.stepId) {
    if (!state.stepSaveAttempted) state.stepSaveAttempted = new Set();
    state.stepSaveAttempted.add(`${sm.platformId}-${sm.stepId}`);
  }

  // Tear down doc pane group wrapper if present
  const overlay = document.getElementById('submit-overlay');
  const group   = document.getElementById('step-modal-group');
  const modal   = document.getElementById('submit-modal');
  if (group && modal) {
    overlay.insertBefore(modal, group);
    group.remove();
  }
  overlay.classList.add('hidden');
  document.body.style.overflow = '';
  // Nothing left to show a deferred background-translate re-render onto —
  // drop it rather than let it fire pointlessly (harmlessly, but wastefully)
  // against a closed modal later. See _deferredRerenderStepModal's own
  // comment, further down this file.
  _stepModalRerenderPending = false;
  updateIOSCard();
  updateIOSCard('macos');
  updateIOSCard('macos_full');
  updateAndroidCard();
  updateSteamCard();
  if (sm?.platformId === 'web') renderDashboard();
}

function toggleDocPane() {
  const pane  = document.getElementById('doc-pane');
  const tab   = document.getElementById('doc-pane-tab');
  const group = document.getElementById('step-modal-group');
  if (!pane) return;
  const willOpen = !pane.classList.contains('is-open');
  pane.classList.toggle('is-open', willOpen);
  if (tab)   tab.classList.toggle('is-open', willOpen);
  if (group) group.classList.toggle('pane-open', willOpen);
}

// Called by click-activated (?) icons — toggles the pane for the same section,
// or opens/navigates when a different section is clicked.
function openDocPaneSection(section, event) {
  event.stopPropagation();

  const pane  = document.getElementById('doc-pane');
  const tab   = document.getElementById('doc-pane-tab');
  const group = document.getElementById('step-modal-group');
  if (!pane) return;

  const isOpen        = pane.classList.contains('is-open');
  const activeSection = pane.dataset.activeSection;

  // Toggle: collapse if clicking the same section's (?) while pane is open
  if (isOpen && activeSection === section) {
    pane.classList.remove('is-open');
    if (tab)   tab.classList.remove('is-open');
    if (group) group.classList.remove('pane-open');
    delete pane.dataset.activeSection;
    const tip = document.getElementById('g-tip');
    if (tip) tip.classList.remove('is-visible');
    return;
  }

  // Open / switch section
  pane.dataset.activeSection = section;
  if (!isOpen) {
    pane.classList.add('is-open');
    if (tab)   tab.classList.add('is-open');
    if (group) group.classList.add('pane-open');
  }

  // Show the global tooltip next to the clicked (?) anchor
  const anchor = event.currentTarget;
  const tip    = document.getElementById('g-tip');
  if (tip && anchor) {
    const text = anchor.dataset.tip
      || (anchor.querySelector('.tooltip-body')?.textContent?.trim() || '');
    if (text) {
      const TIP_W  = 230;
      const MARGIN = 10;
      tip.textContent = text;
      tip.classList.add('is-visible');
      const r  = anchor.getBoundingClientRect();
      const vw = window.innerWidth;
      const th = tip.offsetHeight;
      let left = r.left + r.width / 2 - TIP_W / 2;
      left = Math.max(MARGIN, Math.min(left, vw - TIP_W - MARGIN));
      let top = r.top - th - 8;
      if (top < MARGIN) top = r.bottom + 8;
      tip.style.left = left + 'px';
      tip.style.top  = top  + 'px';
      // Dismiss on the next click anywhere
      setTimeout(() => {
        document.addEventListener('click', () => tip.classList.remove('is-visible'), { once: true });
      }, 0);
    }
  }

  // Scroll to and flash-highlight the relevant doc section
  requestAnimationFrame(() => {
    const sectionEl = document.getElementById('doc-section-' + section);
    if (!sectionEl) return;
    const paneBody = document.querySelector('.doc-pane-body');
    if (paneBody) {
      const bodyRect    = paneBody.getBoundingClientRect();
      const sectionRect = sectionEl.getBoundingClientRect();
      const scrollDelta = sectionRect.top - bodyRect.top - 12;
      paneBody.scrollBy({ top: scrollDelta, behavior: 'smooth' });
    }
    // Remove any existing highlight, then re-add
    document.querySelectorAll('.doc-section-highlight').forEach(el => {
      el.classList.remove('doc-section-highlight');
      void el.offsetWidth; // force reflow so animation restarts
    });
    sectionEl.classList.add('doc-section-highlight');
    setTimeout(() => sectionEl.classList.remove('doc-section-highlight'), 2200);
  });
}

// Row hover → softly highlight the corresponding doc section while pane is open
;(function initDocPaneRowHover() {
  let _lastHovered = null;
  document.addEventListener('mouseover', e => {
    const row = e.target.closest('.ios-q-row[data-doc-section]');
    if (!row) return;
    const pane = document.getElementById('doc-pane');
    if (!pane?.classList.contains('is-open')) return;
    const section = row.dataset.docSection;
    if (section === _lastHovered) return;
    // Remove old hover
    if (_lastHovered) {
      const prev = document.getElementById('doc-section-' + _lastHovered);
      if (prev) prev.classList.remove('doc-section-hover');
    }
    _lastHovered = section;
    const sectionEl = document.getElementById('doc-section-' + section);
    if (sectionEl) sectionEl.classList.add('doc-section-hover');
  });
  document.addEventListener('mouseout', e => {
    const row = e.target.closest('.ios-q-row[data-doc-section]');
    if (!row || row.contains(e.relatedTarget)) return;
    if (_lastHovered) {
      const el = document.getElementById('doc-section-' + _lastHovered);
      if (el) el.classList.remove('doc-section-hover');
      _lastHovered = null;
    }
  });
})();

function submitOverlayClick(e) {
  if (e.target === document.getElementById('submit-overlay')) closeStepModal();
}

// Update the iOS (or, via the optional pid param, Mac App Store) active
// card step completion states without full re-render. pid defaults to
// 'ios' for backward compatibility with existing no-arg call sites;
// updateIOSCard('macos') updates Mac App Store's card using its own
// independent completion data (isMacSectionComplete/macSubmitAnswers)
// instead of iOS's.
function updateIOSCard(pid) {
  pid = pid || 'ios';
  if (!state.activePlatforms.has(pid)) return;
  // Same tick the first render drew (render.js) — smCheckSVG, state.js.
  const checkSVG = smCheckSVG(20);

  // _visiblePlatformSteps (state.js), not the raw steps array — keeps this
  // in sync with buildIOSActiveCard's own numbering (render.js) when a
  // conditional step like 'localizations' is currently hidden.
  _visiblePlatformSteps(pid).forEach((step, i) => {
    const card = document.getElementById(`${pid}-step-card-${step.id}`);
    if (!card) return;
    const done = _appStoreSectionComplete(pid, step.id);
    card.classList.toggle('is-complete', done);
    _clearStepRiskDot(card, done);
    const numEl = card.querySelector('.ios-step-num');
    if (numEl) {
      numEl.classList.toggle('is-done', done);
      numEl.classList.remove('is-risk-warn', 'is-risk-high');
      numEl.innerHTML = done ? checkSVG : String(i + 1);
    }
  });

  // Update submit step card lock state
  const counts = platformStepCount(pid);
  const submitCard = document.getElementById(`${pid}-step-card-submit`);
  if (submitCard) submitCard.classList.toggle('submit-step-locked', !counts.allRequired);
}

/* ── Legacy submit modal (non-iOS platforms) ─────────── */

function openSubmitModal(platformId) {
  state.submitModal.platformId = platformId;
  state.submitModal.expanded   = [];
  renderSubmitModal();
  document.getElementById('submit-overlay').classList.remove('hidden');
  document.body.style.overflow = 'hidden';
}

function closeSubmitModal() {
  document.getElementById('submit-overlay').classList.add('hidden');
  document.body.style.overflow = '';
}

function toggleRiskCategory(catId) {
  const idx = state.submitModal.expanded.indexOf(catId);
  if (idx === -1) state.submitModal.expanded.push(catId);
  else            state.submitModal.expanded.splice(idx, 1);
  // Toggle directly in DOM — no full re-render needed
  const el = document.getElementById('risk-cat-' + catId);
  if (el) el.classList.toggle('is-expanded', state.submitModal.expanded.includes(catId));
}

/* ── iOS Submit Modal — section toggle ───────────────── */

function toggleIOSSection(sectionId) {
  const idx = state.submitModal.expanded.indexOf(sectionId);
  if (idx === -1) state.submitModal.expanded.push(sectionId);
  else            state.submitModal.expanded.splice(idx, 1);
  const isOpen = state.submitModal.expanded.includes(sectionId);
  const el = document.getElementById('ios-sec-' + sectionId);
  if (el) el.classList.toggle('is-expanded', isOpen);
  if (sectionId === 'ios-distribution' && isOpen) {
    requestAnimationFrame(() => initDistributionMap());
  }
}

/* ── iOS Submit Modal — answer handlers ──────────────── */

// Re-render the step modal body while preserving scroll position
/* REPAINT THE STEP, WHEREVER IT IS — and call THIS, never `renderStepModal`.

   `renderStepModal` (render.js) paints `#submit-modal` and returns immediately
   if that element is not there. Since v6.29 a step is usually NOT there: it is
   expanded inline in the Submission pane, in `#sub-step-body`. So every app.js
   caller that meant "show what just changed" was painting a surface nobody was
   looking at, and the symptom was a section that simply never updated.

   Improve Your Submission had it worst, because its whole pipeline repaints
   this way: the Store Page analysis really did complete and really did write
   `state.storePageInsights.issues`, and the pane went on showing the failure it
   had rendered before the fetch resolved. Its Retry button reset the state and
   re-fired both calls correctly — and painted nothing, twice. What "fixed" it
   was pressing Got it in the Binary batch, because `acknowledgeBinFinding` is
   one of the few handlers that already called reRenderStepModal: it rebuilt the
   pane from state that had been correct for some time.

   22 call sites were swapped in v6.36. The only ones left on the bare function
   are openStepModal's own per-platform paints (there the modal genuinely IS the
   surface) and the fallback below. */
function reRenderStepModal() {
  /* THE CHECKLIST REPAINTS WITH THE STEP. This is the one hook every answer
     handler in the app already calls — four platforms, a dozen builders,
     hundreds of call sites — which is exactly why teaching the inline pane
     about itself belonged here too (see the note below). The Shippy Checklist
     reads the same answers those handlers just changed, so it belongs on the
     same hook: without it the column only ever refreshed on navigation, and a
     step you had just finished stayed grey until you clicked it.

     First, and outside every early return below — each of the three surfaces
     this function can paint returns as soon as it has painted one, so anything
     that has to happen on EVERY repaint has to happen before them.
     refreshGuideCompletion is a no-op unless the done-state actually moved. */
  if (typeof refreshGuideCompletion === 'function') refreshGuideCompletion();

  // The Content rating questionnaire also lives inline in the Game Details pane
  // (not just the legacy step modal). When it's showing there, re-render just
  // that pane in place so every questionnaire interaction updates.
  if (state.activeView === 'details' && state.details && state.details.section === 'content') {
    const pane = document.querySelector('.gd-pane--content');
    if (pane && typeof buildContentQuestionsPane === 'function') {
      pane.innerHTML = buildContentQuestionsPane();
      return;
    }
  }
  /* THE SUBMISSION PANE IS THE THIRD PLACE A STEP BODY CAN BE, and this is the
     one hook that has to know it. Every answer handler in the app — four
     platforms, a dozen builders, hundreds of call sites — repaints by calling
     this function, so teaching it about the inline pane is what let the pane
     exist without touching any of them. The alternative was a second repaint
     function and a rule about which to call, which is the shape that guarantees
     one of the two goes stale.

     Guarded on the overlay being hidden: while a Product Page Preview
     sub-section is open the modal really is the surface on screen, and it must
     keep the repaint. Nested scrollers get the same capture/restore the modal's
     do — a Data Types table or a Mac preview that snaps to the top on every
     keystroke is the bug this pattern already exists to prevent. */
  const overlayOpen = !document.getElementById('submit-overlay')?.classList.contains('hidden');
  if (!overlayOpen && state.activeView === 'dashboard' && _repaintSubStepBody()) return;

  const bodyEl   = document.getElementById('step-modal-body');
  const scrollTop = bodyEl ? bodyEl.scrollTop : 0;
  // The Data Types table (buildPrivacyMatrix) scrolls independently of the
  // step modal body — it's its own overflow-y:auto pane (.prv-matrix-wrap,
  // style.css) nested inside #step-modal-body, not the same scroll
  // container. Re-rendering replaces its DOM node outright (a fresh
  // .prv-matrix-wrap string every buildPrivacyMatrix call), which reset its
  // scrollTop to 0 on every toggle — most noticeably when manually
  // expanding/collapsing a group (togglePrivacyGroup) scrolled partway down
  // the table, which visibly snapped back to the top. Captured/restored the
  // same way as bodyEl's own scroll above, so any Data Types table action
  // that re-renders (group toggle, checkbox, preset) keeps its place.
  //
  // AND v6.52 RENAMED THAT PANE, WHICH SILENTLY UNDID ALL OF THE ABOVE. The
  // accordion's scroller is `.pvt-scroll`, so this selector stopped matching
  // anything on the App Store table and the capture went back to `null` — no
  // error, no warning, and the restore below simply skipped. Measured on a cell
  // press with a group open near the bottom: the block you were working in
  // jumped **326.5px** to the top of the table, on every tick. Jaco: *"al
  // rellenar cualquier casilla, se mueve arriba, no hagas eso."*
  //
  // Both are listed rather than one replacing the other: `.prv-matrix-wrap` is
  // still Google Play's and Steam's, and will be until those two are ported.
  // Whichever is on screen is the one that answers — they never co-exist.
  //
  // The rule this leaves: **a selector is a dependency.** Renaming a class in a
  // builder breaks every rule and every query that named it, and the ones in JS
  // fail quietly where CSS at least stops painting.
  const matrixEl = document.querySelector('.pvt-scroll, .prv-matrix-wrap');
  const matrixScrollTop = matrixEl ? matrixEl.scrollTop : null;
  // Mac App Store's own Product Page Preview scrolls independently too —
  // .mac-spp-main (style.css) is its own overflow-y:auto pane nested inside
  // #step-modal-body, with the sidebar beside it staying fixed. Committing
  // an inline-edited field (startMasInlineEdit's blur handler, above)
  // calls this same function, which replaces #step-modal-body's whole
  // innerHTML — including a brand-new .mac-spp-main with scrollTop reset
  // to 0 — so without this, finishing an edit while scrolled down (e.g.
  // past the screenshots) snapped the preview back to the top every time,
  // per request. Same capture/restore pattern as matrixEl above.
  const macMainEl = document.querySelector('.mac-spp-main');
  const macMainScrollTop = macMainEl ? macMainEl.scrollTop : null;
  renderStepModal();
  /* EVERY RESTORE BELOW FLUSHES LAYOUT FIRST, AND WITHOUT THAT LINE THE RESTORE
     SILENTLY BECOMES ZERO. `renderStepModal` has just replaced this element with
     a brand-new node whose children have been parsed but NOT laid out, so its
     `scrollHeight` is still its `clientHeight` — it has no overflow yet — and a
     `scrollTop` assignment is CLAMPED to that maximum, which is 0. The write
     does not throw and does not warn; it just lands on 0.

     Reading `scrollHeight` forces the pending layout, and after that the same
     assignment sticks. `void` because the value is not wanted, only the flush.

     This was found through the Mac preview's pinned nav. Pressing a pill calls
     `setStorePreviewFocus`, which re-renders and then smooth-scrolls the target
     into view one frame later — and from the bottom of the page, clicking Title
     teleported to the top with no motion at all. The travel was innocent: the
     scroller had already been snapped to 0 here, so there was nothing left for
     the animation to cross. Measured on a clean load, real mouse: 5ms after the
     click the scroller read 0, and the smooth scroll was a no-op.

     It also hid from every probe, which is the part worth remembering. Reading
     `scrollTop` in a console check IS a layout flush, so any attempt to watch
     the bug made the restore start working — it measured 466 → 466 by hand and
     466 → 0 when nobody was looking. Trust a trace taken with no reads in it. */
  const restoreScroll = (el, top) => {
    if (!el || top == null) return;
    void el.scrollHeight;
    el.scrollTop = top;
  };
  restoreScroll(document.getElementById('step-modal-body'), scrollTop);
  restoreScroll(document.querySelector('.pvt-scroll, .prv-matrix-wrap'), matrixScrollTop);
  restoreScroll(document.querySelector('.mac-spp-main'), macMainScrollTop);
}

// ── Deferred step-modal re-render for background auto-translate updates ──
// Adding a language (or bulk-applying a language preset) kicks off a wave
// of background translation passes across every already-authored field —
// Store Preview's own Title/Subtitle/Description/What's New, PLUS every
// saved achievement's and IAP product's own localizable fields
// (_propagateAllLocalizationFeatures, further up this file) — each a real,
// separately-timed network call to Claude, for every platform at once.
// Every one of those calls re-renders the open step modal both when it
// starts (to show a loading spinner) and when it resolves (to show the
// translated result), via reRenderStepModal() above — which works by
// fully replacing #step-modal-body's HTML. That's fine when nothing is
// happening, but destructive if the user is actively clicking a button or
// scrolling through whichever step modal happens to be open at that exact
// instant: a click's original target element doesn't survive having its
// whole DOM subtree replaced out from under it mid-gesture (so the click
// silently does nothing), and a scroll/trackpad gesture's native momentum
// dies the same way — reported repeatedly as buttons and scrolling both
// breaking "while translations are happening in background".
//
// _deferredRerenderStepModal() is what every one of those background call
// sites (every *TriggerAutoTranslate function) uses instead of calling
// reRenderStepModal() directly: it renders immediately, exactly as
// before, UNLESS the user currently has a pointer down somewhere in the
// modal or has scrolled it within the last moment — in which case it just
// remembers a render is owed and performs it the instant that interaction
// actually ends (pointerup/cancel, or once scrolling has been still for a
// beat), so a background update can never land mid-gesture. Purely
// additive — anything that isn't mid-interaction behaves exactly as it
// did before this existed, and every OTHER reRenderStepModal() call in
// this file (a direct result of the user's own current action — an inline
// edit's blur, a dropdown's onchange, an undo/redo click) is untouched:
// those need no deferring since nothing else can run concurrently with
// them in the first place (JS is single-threaded — the handler for the
// user's own action always finishes before any background completion
// gets a chance to fire).
let _stepModalPointerDown     = false;
let _stepModalScrollingUntil  = 0;
let _stepModalRerenderPending = false;

/* AN OPEN INLINE EDITOR IS A LIVE INTERACTION (v6.40), and adding it here is
   what makes "click straight from one field to another" one click instead of
   two. The whole point of this guard is "do not rebuild the modal under the
   user's hands", and a caret sitting in an input is exactly that — it was only
   ever missing because the pointer flag happened to cover the common case.

   The test is `:focus`, NOT merely mounted, and that distinction is the whole
   rule: an editor commits on `blur`, so at the moment its commit asks for a
   render the input is still in the DOM. Keyed on presence this would never
   render again — the editor that is closing would keep vetoing the render that
   closes it. Keyed on focus, a closing editor has already lost it and the
   render goes through, while an editor that is OPENING has just taken it and
   the render waits. */
/* AN OPEN DROPDOWN IS A LIVE INTERACTION TOO (v6.51), and this is the case the
   pointer flag cannot cover.

   swSelect's open state is a bare `.is-open` DOM class and nothing else —
   closeAllDropdowns says so in as many words ("purely transient DOM classes,
   never read back by render"). So the pill is clicked, `.is-open` goes on,
   pointerUP fires immediately and clears _stepModalPointerDown, and the list
   then sits open with no guard at all while the user reads it. Any background
   render arriving in that window rebuilds #step-modal-body, swSelect re-emits
   the wrapper WITHOUT `.is-open`, and the list vanishes mid-reach — or worse,
   survives visually but every .loc-dd-item under the cursor is a fresh node,
   so the click lands on nothing. That is the "intermittent, hard to pick
   anything out of a dropdown" report: intermittent precisely because it
   depends on whether a completion happens to land during the second or two
   the list is open.

   It bites hardest right after adding supported languages to a scraped title,
   which is the sequence that reported it: each language fires three localized
   checks (description, listing, achievements), every one of which ends in
   _deferredRerenderStepModal, so the modal is being asked to rebuild itself
   repeatedly for several seconds — exactly while the developer is trying to
   use the Localizations step's own pickers.

   Deliberately NOT scoped to #submit-modal, matching the inline-input check
   above: a false positive costs only a deferral that the very next pointerup
   flushes, while a miss costs a lost click. Self-clearing for the same
   reason the editor case is — swSelectChoose and the document handler both
   run closeAllDropdowns on `click`, which lands BEFORE the pointerup flush's
   setTimeout(0), so by the time the pending render runs the class is gone. */
function _stepModalInteractionActive() {
  return _stepModalPointerDown
      || Date.now() < _stepModalScrollingUntil
      || !!document.querySelector('.ias-inline-input:focus')
      || !!document.querySelector('.sw-select-wrap.is-open, #loc-primary-wrap.is-open');
}

function _flushPendingStepModalRerender() {
  if (_stepModalRerenderPending && !_stepModalInteractionActive()) {
    _stepModalRerenderPending = false;
    reRenderStepModal();
  }
}

// _deferredRerenderStepModal()'s "not mid-gesture" branch used to call
// reRenderStepModal() directly, synchronously, every single time it was
// invoked. That's fine for a single call, but toggleObLang/addLangFromSearch
// (adding a language) walks straight into
// _propagateAllLocalizationFeatures(), which — for a Steam-linked title with
// many achievements, e.g. Hades' 49 — calls _masAchLocTriggerAutoTranslate/
// _iasAchLocTriggerAutoTranslate/_macFullAchLocTriggerAutoTranslate once per
// achievement per translatable field per platform (up to 49 x 3 x 3 = 441
// calls), all in one synchronous pass, before any of their network requests
// even go out. Every one of those calls sets a loading flag and then called
// this function to show it, so all 441+ used to trigger their own immediate,
// full reRenderStepModal() — a full rebuild of #step-modal-body's HTML —
// back to back in a single tick. That synchronous render storm, not the
// (now-throttled, see TRANSLATE_CONCURRENCY) network calls themselves, is
// what actually froze the tab for several seconds immediately after clicking
// to add a language.
//
// The fix: coalesce same-tick calls into a single render. Instead of
// rendering immediately, schedule one microtask-deferred render (if one
// isn't already pending) and return. Every call made during the same
// synchronous burst sees a render already scheduled and just returns
// instantly, so the whole burst still ends in exactly one reRenderStepModal()
// call, fired as a microtask right after the burst's call stack unwinds —
// imperceptibly delayed, but no longer proportional to achievement count.
let _stepModalCoalescedRerenderScheduled = false;

function _scheduleCoalescedStepModalRerender() {
  if (_stepModalCoalescedRerenderScheduled) return;
  _stepModalCoalescedRerenderScheduled = true;
  Promise.resolve().then(() => {
    _stepModalCoalescedRerenderScheduled = false;
    // A gesture could have started during the microtask wait (vanishingly
    // unlikely, but cheap to guard) — defer to the normal pending-flag path
    // if so, same as _deferredRerenderStepModal itself does.
    if (_stepModalInteractionActive()) {
      _stepModalRerenderPending = true;
      return;
    }
    reRenderStepModal();
  });
}

function _deferredRerenderStepModal() {
  if (_stepModalInteractionActive()) {
    _stepModalRerenderPending = true;
    return;
  }
  _scheduleCoalescedStepModalRerender();
}

/* ══════════════════════════════════════════════════════════════════════════
   A BACKGROUND TRANSLATION SHOULD NOT REPAINT A SCREEN IT DID NOT CHANGE
   ══════════════════════════════════════════════════════════════════════════
   Deferring a render until the user's gesture ends (above) stops a rebuild
   landing mid-click, but it does not stop the rebuilds. Adding one supporting
   language to a Steam-linked title fans out to every field of every saved IAP
   and achievement on every active platform — the file's own note upstream
   puts Hades at 49 achievements x 3 fields x 3 platforms — and each of those
   calls asks for a repaint up to three times (clear, announce loading,
   complete). The result is a modal rebuilding itself every few hundred
   milliseconds for as long as the queue drains, which is what makes its
   dropdowns and buttons feel unreliable.

   Almost none of those repaints show anything. The Localizations step renders
   exactly ONE (view, item, field) triple at a time — the pickers at the top
   choose it — across every selected language at once. So a translation that
   lands for a different field, or a different achievement, or a different
   IAP, or while a different platform's step is open, changes nothing a person
   can see. Only the triple on screen needs the repaint; the rest can land in
   state silently and be there when the user navigates to them.

   Generalises _masPreviewNeedsTranslateRefresh, which already did exactly
   this for one surface (Mac's store preview) and whose reasoning is the same.

   Language is deliberately NOT part of the test: every selected language
   renders as its own card simultaneously, so any language that finished IS on
   screen. The multiplier this cuts is fields and items, which is where the
   volume actually is. */
/* WHAT THE VISIBILITY TEST HAS TO KNOW (v6.53)

   v6.52 described each platform by ONE screen — its unified Localizations
   step — and mapped only ios and macos. Both limits were bugs, and together
   they are why the modal still rebuilt itself while the queue drained:

     • macos_full was unmapped, so every one of its calls took the "unknown
       surface, repaint to be safe" branch. It is in HIDDEN_PLATFORMS — a
       developer can never even see it — yet a 32-achievement title had it
       asking for 32 repaints of whichever OTHER platform's modal was open.
       That alone was 32 of the 36 repaints measured for the reported
       sequence.

     • The same localization data is rendered by TWO different screens: the
       unified Localizations step, and the Store Page Preview's own
       "Localizations" flip (plus the Business step's "IAP Locs" and Game
       Center's "Achievement Locs" flips, which share the same flip state).
       Testing only the step meant a translation landing while the developer
       sat in the preview's own review section silently never repainted it.

   So the map below carries, per platform, every screen that can render that
   platform's localization cards, and what each of them is showing:

     unifiedStep  the Localizations step id, plus the state key holding which
                  of Store Page/IAPs/Achievements it has selected
     views        per domain: which state key holds the selected field, what
                  that key defaults to, how to resolve the selected item
                  (IAPs/Achievements only), and which storePreviewFlipTarget
                  flips render that same domain

   Steam has no unified Localizations step at all — its review section exists
   only as a flip off the Store Page Preview - Prototype step — so it maps
   with unifiedStep null and its own five fields' state key. */
/* THREE SCREENS SHOW A STORE-PAGE LOCALIZATION, NOT TWO (v6.63).

   The unified Localizations step, the Store Page Preview turned over to its
   own "Localizations" flip, and — the one this list was missing — the preview
   NOT turned over at all, which draws whichever language its own dropdown has
   selected. `flip: null` is exactly that state, and needs no new machinery:
   _locFlipOnScreen compares against storePreviewFlipTarget, which IS null for
   a step that hasn't been turned over. */
const LOC_STORE_PAGE_SCREENS = [
  { stepId: 'storePreview', flip: 'localization' },
  { stepId: 'storePreview', flip: null },
];

const LOC_SURFACE = {
  ios: {
    unifiedStep: 'localizations',
    viewKey: 'iosLocsView',
    views: {
      storePage:    { fieldKey: 'locReviewField',   modeKey: 'locReviewMode',       defaultField: 'title',
                      screens: LOC_STORE_PAGE_SCREENS },
      iaps:         { fieldKey: 'iapLocField',      modeKey: 'iapLocMode',          defaultField: 'name',
                      itemFn: () => _iapLocEffectiveIapId(),
                      screens: [{ stepId: 'storePreview', flip: 'iapLocalizations' }] },
      achievements: { fieldKey: 'iasAchLocField',   modeKey: 'iasAchLocMode',       defaultField: 'displayName',
                      itemFn: () => _iasAchLocEffectiveAchId(),
                      screens: [{ stepId: 'gameCenter', flip: 'achievementLocalizations' }] },
    },
  },
  macos: {
    unifiedStep: 'localizations',
    viewKey: 'macLocsView',
    views: {
      storePage:    { fieldKey: 'masLocReviewField', modeKey: 'masLocReviewMode',   defaultField: 'title',
                      screens: LOC_STORE_PAGE_SCREENS },
      iaps:         { fieldKey: 'masIapLocField',    modeKey: 'masIapLocMode',      defaultField: 'name',
                      itemFn: () => _masIapLocEffectiveIapId(),
                      screens: [{ stepId: 'storePreview', flip: 'iapLocalizations' }] },
      achievements: { fieldKey: 'masAchLocField',    modeKey: 'masAchLocMode',      defaultField: 'displayName',
                      itemFn: () => _masAchLocEffectiveAchId(),
                      screens: [{ stepId: 'gameCenter', flip: 'achievementLocalizations' }] },
    },
  },
  macos_full: {
    unifiedStep: 'localizations',
    viewKey: 'macFullLocsView',
    views: {
      storePage:    { fieldKey: 'macFullLocReviewField', modeKey: 'macFullLocReviewMode', defaultField: 'title',
                      screens: LOC_STORE_PAGE_SCREENS },
      iaps:         { fieldKey: 'macFullIapLocField',    modeKey: 'macFullIapLocMode',    defaultField: 'name',
                      itemFn: () => _macFullIapLocEffectiveIapId(),
                      screens: [{ stepId: 'storePreview', flip: 'iapLocalizations' }] },
      achievements: { fieldKey: 'macFullAchLocField',    modeKey: 'macFullAchLocMode',    defaultField: 'displayName',
                      itemFn: () => _macFullAchLocEffectiveAchId(),
                      screens: [{ stepId: 'gameCenter', flip: 'achievementLocalizations' }] },
    },
  },
  steam: {
    unifiedStep: null,
    viewKey: null,
    views: {
      storePage:    { fieldKey: 'steamLocReviewField', modeKey: 'steamLocReviewMode', defaultField: 'title',
                      screens: [{ stepId: 'storePreviewPrototype', flip: 'localization' }] },
    },
  },
};

/* IS THIS PLATFORM'S <stepId> ACTUALLY ON SCREEN?

   state.stepModal cannot answer this by itself: closeStepModal deliberately
   leaves it set, because it means "which step am I in", not "is a modal
   open" — twenty-odd handlers resolve their platform through it and would
   fall back to 'ios' if it were nulled. So closing the modal and asking
   state.stepModal alone reports the step as still visible, which is the one
   case that matters most (a closed step should never repaint).

   Both layouts therefore get their own real test: the modal is on screen when
   #submit-overlay is not `hidden`, and the inline pane when this platform's
   own openStep says so. */
function _locStepOnScreen(platformId, stepId) {
  if (!stepId) return false;
  const inlineOpen = ((state.submission && state.submission.openStep) || {})[platformId] === stepId;
  if (inlineOpen) return true;
  const overlay = document.getElementById('submit-overlay');
  if (!overlay || overlay.classList.contains('hidden')) return false;
  const sm = state.stepModal;
  return !!sm && sm.platformId === platformId && sm.stepId === stepId;
}

/* A flip section is on screen when its host step is AND that step is turned
   over to it — _subFlipTarget (render.js) resolves exactly this pair, and
   storePreviewFlipTarget is keyed by platform, so both halves are needed. */
function _locFlipOnScreen(platformId, screen) {
  if (!_locStepOnScreen(platformId, screen.stepId)) return false;
  return ((state.storePreviewFlipTarget || {})[platformId] || null) === screen.flip;
}

/* `field` and `itemId` are both optional: pass null for either to mean "any".
   The Steam achievement importers write every achievement's every field in one
   pass, so they have no single field/item to name — for them the honest test
   is just "is this platform's Achievements view on screen at all". */
function _locTranslateVisible(platformId, view, field, itemId) {
  const cfg = LOC_SURFACE[platformId];
  if (!cfg) return true;   // unmapped surface — repaint, same as before this existed
  const vcfg = cfg.views && cfg.views[view];
  if (!vcfg) return true;

  let onScreen = false;
  if (cfg.unifiedStep && _locStepOnScreen(platformId, cfg.unifiedStep)) {
    onScreen = (state[cfg.viewKey] || 'storePage') === view;
  }
  if (!onScreen && vcfg.screens) onScreen = vcfg.screens.some(s => _locFlipOnScreen(platformId, s));
  if (!onScreen) return false;

  if (field != null) {
    if ((state[vcfg.fieldKey] || vcfg.defaultField) !== field) return false;
  }
  // Store-page fields have no per-item selector; IAPs and achievements show
  // one saved item at a time.
  if (itemId != null && vcfg.itemFn) {
    let curItem = null;
    try { curItem = vcfg.itemFn(); } catch (_) { return true; }
    if (curItem !== itemId) return false;
  }
  return true;
}

/* The render call the Localizations auto-translate triggers use instead of
   _deferredRerenderStepModal. Same deferral behaviour once it decides to
   render — it just declines to ask at all for work nobody is looking at. */
function _locDeferredRerender(platformId, view, field, itemId) {
  if (!_locTranslateVisible(platformId, view, field, itemId)) return;
  _deferredRerenderStepModal();
}

/* A BACK-TRANSLATION ONLY EXISTS ON THE FLIPPED SIDE (v6.53)

   This is where the repaint storm actually lived, and why gating the
   *TriggerAutoTranslate functions twice changed nothing a developer could
   feel. Every trigger and every Steam achievement import ends by calling its
   surface's *RefreshBackTranslation for each (item, field, language) it
   touched — and each of those called reRenderStepModal() DIRECTLY, three
   times over (clear, announce loading, complete), never going through the
   deferral machinery at all. Instrumenting reRenderStepModal itself for the
   reported sequence — scrape Celeste, add French and German, sit in Mac App
   Store's Localizations step — counted 462 full rebuilds of
   #step-modal-body, all of them from these ten functions, against 0 requests
   through _deferredRerenderStepModal. 462 rebuilds over a few seconds is
   about one every eight milliseconds: any dropdown open during that window
   is re-emitted without its `.is-open` class and every item under the cursor
   is a fresh node, which is exactly the "can't click anything" report.

   Almost none of them show anything, for a second reason on top of the
   view/field/item test every other caller uses: a back-translation is drawn
   only on the flipped side of a card, so unless THIS surface is currently in
   Review mode the value can land silently and be there when the developer
   flips. Hence the extra mode test here. */
function _locBackTranslationVisible(platformId, view, field, itemId) {
  const cfg  = LOC_SURFACE[platformId];
  const vcfg = cfg && cfg.views && cfg.views[view];
  if (!vcfg) return true;                                   // unmapped — behave as before
  if (vcfg.modeKey && state[vcfg.modeKey] !== 'review') return false;
  return _locTranslateVisible(platformId, view, field, itemId);
}

function _locDeferredRerenderBack(platformId, view, field, itemId) {
  if (!_locBackTranslationVisible(platformId, view, field, itemId)) return;
  _deferredRerenderStepModal();
}

/* One write, several surfaces. Steam's localized-listing scrape writes the
   SHARED listing fields (Title, Description — see STEAM_SHARED_LISTING_FIELDS),
   which every Apple platform's Store Page renders from the same state, as well
   as Steam's own independent copies. Whichever of those happens to be the
   screen in front of the developer is the one owed a repaint, so ask them all
   and render once if any says yes. Each spec is [platform, view, field, item].*/
function _locDeferredRerenderAny(specs) {
  if (!specs.some(s => _locTranslateVisible(s[0], s[1], s[2], s[3]))) return;
  _deferredRerenderStepModal();
}

const LOC_APPLE_PLATFORMS = ['ios', 'macos', 'macos_full'];

/* Shorthand for the shared-listing case above: `field` is the Apple-side
   field name (null = any), `steamField` Steam's own (null = any, false =
   Steam's review section doesn't show this write at all). */
function _locDeferredRerenderStorePage(field, steamField) {
  const specs = LOC_APPLE_PLATFORMS.map(p => [p, 'storePage', field, null]);
  if (steamField !== false) specs.push(['steam', 'storePage', steamField, null]);
  _locDeferredRerenderAny(specs);
}

/* ── Steam first, machine translation only as the fallback ────────────────
   The write-time guard each trigger already carries —
   `if (entry[field+'FromSteam'] && entry[sourceKey] === text) return;` — threw
   the translation away AFTER paying for it: the request went out, the queue
   slot was spent, the spinner rendered, and Steam's real text won the race at
   the end anyway. For a title whose store page Steam has genuinely localized,
   that is the common case, not the edge one.

   These two move the decision to BEFORE the request:

   _steamAlreadySupplied — Steam's scrape has already written this exact field
   for this language against this same source text. Nothing to translate.

   _steamMayStillSupply — Steam lists this language as supported and its scrape
   for that language has not settled yet, so a real localization is probably
   still in flight. Hold off; the scrape marks itself settled when it finishes
   (whether or not it found anything) and re-runs the propagate pass, at which
   point anything Steam did NOT fill becomes eligible and gets translated as
   the fallback. A title with no Steam link at all has no steamLocInfo, so this
   is false and translation proceeds immediately, exactly as before. */
function _steamAlreadySupplied(entry, field, text) {
  if (!entry) return false;
  return !!entry[field + 'FromSteam'] && entry[field + 'SourceText'] === text;
}

/* MAC APP STORE READS THE APP STORE'S COPY UNTIL IT HAS ONE OF ITS OWN (v6.53)

   _masFieldValue's fallback chain for Description/What's New is
   `ml.localizedStoreText[lang][field] || fd.localizedStoreText[lang][field]`,
   and Steam's localized-description scrape writes only the second of those.
   So a Mac App Store card showing Steam's real French description is showing
   the App Store's entry — Mac's own is still empty and carries no
   `descriptionFromSteam` flag at all. _steamAlreadySupplied, asked about Mac's
   own entry, therefore answered "no, Steam has not supplied this", and once
   the domain settled _masTriggerAutoTranslate wrote a machine translation into
   Mac's own copy, which then SHADOWED Steam's text through that same fallback.
   From the developer's seat: the Mac App Store's Store Page - Description
   localization silently replaced itself with an AI translation a few seconds
   after the real Steam one appeared. That is the reported "Steam localizations
   are still being overridden, particularly Description".

   Asking both entries is the fix. Note the source-text test still applies to
   whichever entry answers yes, so a developer who genuinely rewrites Mac's own
   primary Description still gets it translated — the two texts diverge, and
   Steam's authority over the old one stops applying.

   Mac App Store FULL deliberately does NOT need this: _macFullFieldValue has
   no cross-platform fallback, and seedMacFullAppStoreListing deep-copies the
   App Store's entries (flags included), so its own entry always knows. */
/* IS PRE-EARNED STILL THE COPY OF EARNED THAT THE IMPORT MADE IT? (v6.56)

   Scraped achievements start with the two descriptions identical (see
   _applySteamAchievements). While that is still true, Steam's own localized
   description is the right text for BOTH of them, so the localized-achievement
   importers seed the pre-earned translations from it as well — otherwise the
   Localizations step ends up showing Steam's real French for Earned and a
   machine translation of the same English sentence for Pre-Earned, two
   different Frenchs for one line of text.

   The moment the developer makes the two differ — by editing either one — this
   goes false and the seeding stops, which is what keeps "a copy, not a link"
   true all the way down into the translations. */
function _steamAchPreEarnedMirrors(a) {
  const earned = ((a && a.earnedDescription) || '').trim();
  return !!earned && (((a && a.preEarnedDescription) || '').trim() === earned);
}

function _steamSuppliedShared(field, lang, text) {
  const shared = (state.formData.localizedStoreText || {})[lang];
  return _steamAlreadySupplied(shared, field, text);
}

function _steamMayStillSupply(lang, domain) {
  const info = state.steamLocInfo;
  if (!info || !info.appId) return false;                 // not a Steam-linked title
  const steamLang = STEAM_LOCALIZATION_LANG_MAP[lang];
  if (!steamLang) return false;                           // Steam has no code for it
  if (!_steamSupportsLanguageCandidate(steamLang, info.supportedLanguages)) return false;
  const settled = state.steamLocSettled && state.steamLocSettled[domain];
  return !(settled && settled[lang]);
}

/* ── IS ANYTHING STILL ON ITS WAY TO THIS CARD? (v6.57) ───────────────────
   The Localizations cards already showed a spinner while an auto-translation
   was in flight (each surface's own *FieldTranslatePending). That covered one
   of the three ways a card can be waiting, and it was the short one.

   The other two both come from the Steam-first rule (v6.52): a language Steam
   might genuinely localize does not get translated at all until Steam's own
   scrape has settled for it. So between adding a language and that settle, the
   card sits blank with nothing to say — first while the localized /game call
   is in flight, and then, if Steam turns out to have nothing for it, for as
   long as the fallback translation is queued behind TRANSLATE_CONCURRENCY. On
   a Steam-linked title with several languages that is the majority of the
   wait, and it read as "the scrape missed this one".

   _steamMayStillSupply answers both at once: it is true from the moment the
   title has a Steam app id until that domain settles for that language, which
   is exactly the window in which something is still coming. The two extra
   tests below stop it claiming a wait that will never end in anything —
   nothing is coming for a field with no source text, or for one that Steam
   does not supply AND the developer has switched auto-translation off for. */
const STEAM_SUPPLIES_FIELDS = {
  listing:      new Set(['title', 'description']),
  achievements: new Set(['displayName', 'earnedDescription', 'preEarnedDescription']),
};

function _locAwaitingSteamOrQueue(domain, lang, field, autoEnabled, primaryText) {
  if (!domain) return false;                                    // IAPs: Steam has no source
  if (lang === (state.formData.primaryLanguage || 'en')) return false;
  if (!(primaryText || '').trim()) return false;
  const supplies = STEAM_SUPPLIES_FIELDS[domain];
  if (!autoEnabled && !(supplies && supplies.has(field))) return false;
  return _steamMayStillSupply(lang, domain);
}

/* Called by each Steam localization scrape once it has finished with a
   language — success, "Steam had nothing", or outright failure, because all
   three equally mean "stop waiting for Steam on this one". Re-runs the
   propagate pass so any field the scrape left empty now falls through to
   machine translation. */
function _markSteamLocSettled(lang, domain, repropagate) {
  if (!state.steamLocSettled) state.steamLocSettled = {};
  if (!state.steamLocSettled[domain]) state.steamLocSettled[domain] = {};
  if (state.steamLocSettled[domain][lang]) return;        // already settled
  state.steamLocSettled[domain][lang] = true;
  if (typeof repropagate === 'function') repropagate();
}

/* The store page is scraped by TWO independently-timed calls — the listing
   (title/short description/developer/publisher) and the description — and a
   language is only done with Steam once BOTH have landed. This counts them in
   and out so the domain settles on the last one out rather than the first,
   which would release machine translation while the other was still in
   flight. Achievements are their own domain and their own single call. */
function _steamLocScrapeStart(lang, domain) {
  if (!state.steamLocPending) state.steamLocPending = {};
  if (!state.steamLocPending[domain]) state.steamLocPending[domain] = {};
  const m = state.steamLocPending[domain];
  m[lang] = (m[lang] || 0) + 1;
}

function _steamLocScrapeDone(lang, domain, repropagate) {
  if (!state.steamLocPending) state.steamLocPending = {};
  if (!state.steamLocPending[domain]) state.steamLocPending[domain] = {};
  const m = state.steamLocPending[domain];
  m[lang] = (m[lang] || 1) - 1;
  if (m[lang] > 0) return;                     // a sibling scrape is still out
  delete m[lang];
  _markSteamLocSettled(lang, domain, repropagate);
}

/* THE WRAPPERS EXIST SO SETTLING CANNOT BE FORGOTTEN. Each of these three
   functions has between seven and ten early returns — no Steam link, no
   language code, Steam doesn't list the language, the fetch threw, the user
   switched title mid-flight, Steam returned the default-language text — and
   every one of them means the same thing to a language waiting on Steam:
   stop waiting. A `finally` settles on all of them at once, the throw
   included, rather than asking each return site to remember.

   The repropagate pass is what makes machine translation the FALLBACK rather
   than something merely skipped: whatever Steam just wrote is now guarded by
   _steamAlreadySupplied, so re-running propagate translates exactly the
   fields Steam left empty, and nothing else. */
async function _checkSteamLocalizedListing(lang) {
  _steamLocScrapeStart(lang, 'listing');
  try {
    return await _checkSteamLocalizedListingInner(lang);
  } finally {
    _steamLocScrapeDone(lang, 'listing', _steamRepropagateStorePage);
  }
}

async function _checkSteamLocalizedDescription(lang) {
  _steamLocScrapeStart(lang, 'listing');
  try {
    return await _checkSteamLocalizedDescriptionInner(lang);
  } finally {
    _steamLocScrapeDone(lang, 'listing', _steamRepropagateStorePage);
  }
}

async function _checkSteamLocalizedAchievements(lang) {
  _steamLocScrapeStart(lang, 'achievements');
  try {
    return await _checkSteamLocalizedAchievementsInner(lang);
  } finally {
    _steamLocScrapeDone(lang, 'achievements', _steamRepropagateAchievements);
  }
}

function _steamRepropagateStorePage() {
  if (typeof _iasPropagateAllFields === 'function') _iasPropagateAllFields();
  if (typeof _masPropagateAllFields === 'function') _masPropagateAllFields();
}

function _steamRepropagateAchievements() {
  if (typeof _iasAchLocPropagateAllFields === 'function') _iasAchLocPropagateAllFields();
  if (typeof _masAchLocPropagateAllFields === 'function') _masAchLocPropagateAllFields();
}

(function initStepModalInteractionTracking() {
  const inModal = el => !!(el && el.closest && el.closest('#submit-modal'));

  document.addEventListener('pointerdown', e => {
    if (inModal(e.target)) _stepModalPointerDown = true;
  }, true);
  /* THE FLUSH WAITS FOR THE CLICK, AND THAT IS ONE LINE AGAINST A WHOLE CLASS
     OF "IT TAKES TWO CLICKS" (v6.40). Jaco: *"si entro a editar algo y toco
     cualquier otro pill de arriba, no me lleva directamente a esa zona,
     necesito 2 clicks."*

     `pointerup` fires BEFORE `click`. Flushed synchronously here, a render that
     had been correctly deferred out of the press then lands in the one gap
     where it does the most damage: between up and click. `click` is only
     dispatched when the down and the up share a target, and the target has just
     been replaced by innerHTML — so no click is generated at all, and every
     control in the modal silently eats the first press that follows an edit.
     The pinned pills are where it shows, because pressing one is the natural
     thing to do straight after typing.

     `setTimeout(…, 0)` puts the flush in the next task, after the click has
     been delivered to the live node. The gesture flags are still cleared
     immediately — only the repaint moves — so nothing else can mistake the
     pointer for still being down. Cheap, and it fixes the pills, the footer,
     the language picker and anything added later, rather than teaching each
     control its own workaround. */
  const flushAfterClick = () => setTimeout(_flushPendingStepModalRerender, 0);
  document.addEventListener('pointerup', () => {
    _stepModalPointerDown = false;
    flushAfterClick();
  }, true);
  document.addEventListener('pointercancel', () => {
    _stepModalPointerDown = false;
    flushAfterClick();
  }, true);
  // 'scroll' doesn't bubble, but a capture-phase listener on document still
  // sees it fire (on its way down) for any scrollable element inside the
  // modal — #step-modal-body itself, or any nested scrollable region.
  document.addEventListener('scroll', e => {
    if (!inModal(e.target)) return;
    _stepModalScrollingUntil = Date.now() + 200;
    setTimeout(_flushPendingStepModalRerender, 210);
  }, true);
})();

// ── Shared throttle for background auto-translate network calls ────────
// Adding a language (or a Steam scrape's initial import) can fan out into a
// LOT of translate calls at once: _propagateAllLocalizationFeatures runs
// every *TriggerAutoTranslate function below across every platform, and the
// achievement/IAP ones loop over every SAVED achievement/product times every
// translatable field. A Steam-linked title with a big achievement list makes
// this concrete — Hades has 49 achievements, imported into all three of Mac
// App Store/App Store/Mac App Store Full's own Game Center lists
// (_applySteamAchievements), so adding ONE supporting language fires
// 49 achievements x 3 fields x 3 platforms = 441 separate Claude API calls,
// all started in the same synchronous pass (each *TriggerAutoTranslate call
// is fire-and-forget, not awaited by its caller). Firing all 441 at once
// isn't just wasteful — real-world network/API concurrency limits mean a
// large fraction end up genuinely in flight together, and when a cluster of
// them resolves at close to the same moment, draining hundreds of Promise
// continuations back to back (JSON.parse of each response, the per-language
// forEach, back-translation refresh, a status write) is enough continuous
// synchronous work to make the tab visibly unresponsive for as long as that
// backlog keeps arriving — reported as Shipmate "freezing up" after a
// Steam scrape + adding languages, for exactly this reason.
//
// _enqueueTranslateTask queues the actual network call (NOT the cheap
// eligibility-check/loading-state part every *TriggerAutoTranslate function
// still does immediately, synchronously, before enqueueing — so every
// field's status flips to "loading" right away with no visible delay) and
// only ever runs TRANSLATE_CONCURRENCY of them at a time, across every
// platform's translate functions combined (one shared queue, not one per
// platform — the 441-call fan-out above is the sum across all three, so
// throttling each platform independently would still let 3x
// TRANSLATE_CONCURRENCY run at once). Queued-but-not-yet-running tasks are
// just plain closures sitting in an array — cheap to hold thousands of, so
// nothing here caps how many languages/achievements can be queued, only how
// many are ever actually in flight to Claude at once. This keeps the
// completions trickling in a few at a time instead of arriving in one huge
// burst, so the main thread is never asked to drain hundreds of them back to
// back — background translation keeps making progress exactly as before,
// it's just spread out over time instead of piled up in one moment.
const TRANSLATE_CONCURRENCY = 4;
const _translateQueue = [];
let _translateActiveCount = 0;

function _pumpTranslateQueue() {
  while (_translateActiveCount < TRANSLATE_CONCURRENCY && _translateQueue.length) {
    const { taskFn, resolve, reject } = _translateQueue.shift();
    _translateActiveCount++;
    Promise.resolve().then(taskFn).then(
      result => { _translateActiveCount--; resolve(result); _pumpTranslateQueue(); },
      err     => { _translateActiveCount--; reject(err);    _pumpTranslateQueue(); }
    );
  }
}

function _enqueueTranslateTask(taskFn) {
  return new Promise((resolve, reject) => {
    _translateQueue.push({ taskFn, resolve, reject });
    _pumpTranslateQueue();
  });
}

/* ── Global fixed-position tooltip ───────────────────── */
// Single delegated handler on document — avoids overflow/z-index clipping
// from scrolling containers. Tooltip text lives in data-tip on the anchor.
(function initGlobalTooltip() {
  const TIP_W = 230;
  const MARGIN = 10;

  function showTip(anchor) {
    const tip = document.getElementById('g-tip');
    if (!tip) return;
    // Prefer data-tip attribute; fall back to hidden .tooltip-body text
    let text = anchor.dataset.tip || '';
    if (!text) {
      const body = anchor.querySelector('.tooltip-body');
      if (body) text = body.textContent.trim();
    }
    if (!text) return;
    tip.textContent = text;
    /* The bubble is shared with smTipAt's nudge variant, which reshapes and
       recolours it. Dropping that here rather than trying to undo it on the
       way out is what makes the reset unconditional: whatever state the last
       caller left, a hover tooltip always starts from the base shape. */
    tip.classList.remove('g-tip--nudge');
    /* THE TONE IS THE ANCHOR'S, AND IT IS RESET EVERY TIME for the same reason
       the nudge class is: the bubble is ONE element shared by every hint in the
       app, so whatever the last hover left has to be dropped before this one is
       drawn, or a red tooltip would follow the pointer onto the next control. */
    tip.classList.toggle('g-tip--danger', anchor.dataset.tipTone === 'danger');
    tip.classList.add('is-visible');

    const r = anchor.getBoundingClientRect();
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    const th = tip.offsetHeight;
    /* MEASURED, NOT THE CONSTANT. The box shrink-wraps its text now (see
       .g-tip in style.css), so centring against a fixed 230 would push a short
       bubble left of the control it belongs to — by half the slack, which on
       "Hold to Submit" is most of the box. Read after the text and the classes
       are set, or it measures the PREVIOUS tooltip. */
    const tw = tip.offsetWidth || TIP_W;

    // Horizontal: center on anchor, clamp to viewport
    let left = r.left + r.width / 2 - tw / 2;
    left = Math.max(MARGIN, Math.min(left, vw - tw - MARGIN));

    // Vertical: prefer above; fall back to below
    let top = r.top - th - 8;
    if (top < MARGIN) top = r.bottom + 8;

    tip.style.left = left + 'px';
    tip.style.top  = top  + 'px';
  }

  function hideTip() {
    const tip = document.getElementById('g-tip');
    if (tip) tip.classList.remove('is-visible');
  }

  /* REDRAW A BUBBLE THAT IS ALREADY UP, FROM ITS ANCHOR (v6.81).
     A hint is normally a constant — the control means one thing and says it —
     but a HOLD is a control whose meaning changes halfway through: "Hold to
     delete" is an instruction until you start, and a report of what is
     happening after. The thumbnail's × rewrites its own `data-tip` mid-gesture
     and calls this.

     **It redraws FROM THE ANCHOR rather than taking a string**, which is what
     stops it becoming a second `smTipAt`: the anchor is already the one thing
     that knows the text and the tone, so a caller cannot put a word in the
     bubble that the control does not also carry in its `data-tip` for the next
     ordinary hover. And it re-runs the whole of `showTip`, which means the box
     is re-MEASURED — the bubble shrink-wraps its text (v6.72), so a longer or
     shorter word must move the box or it drifts off the button it points at.

     **Silent when nothing is on screen.** A hold can be started from a click
     with no hover behind it (touch, or a pointer that entered on the press),
     and raising a tooltip nobody asked for would be this app putting a label
     on a gesture rather than on a control. */
  window.smTipRefresh = function (anchor) {
    const tip = document.getElementById('g-tip');
    if (!tip || !anchor || !tip.classList.contains('is-visible')) return;
    showTip(anchor);
  };

  /* Published for the one case the pointer cannot answer: an anchor that is
     REMOVED while its tooltip is up never fires `mouseout`, so something has
     to take the bubble down on its behalf. */
  window.hideGlobalTip = hideTip;

  /* THE ATTRIBUTE IS THE TOOLTIP; THE CLASS IS THE LAYOUT (v6.70).
     `.tooltip-anchor` sets four layout properties (inline-flex, align-items,
     vertical-align, relative) that a SPAN IN PROSE needs and a 30px icon
     button does not — and `position: relative` in particular is the trap this
     file has already paid for twice (it REPLACES `sticky` on the privacy
     headings, and the gear carries an alert dot). So the selector accepts
     either: showTip has always read `dataset.tip` first, which means the
     attribute was already the real trigger and the class was only ever coming
     along for the ride.

     Nothing new becomes a tooltip by accident — checked, every `data-tip` in
     the codebase was already on a `.tooltip-anchor`, so this widens the door
     without adding a single anchor today. What it buys is that a control can
     take the app's INSTANT bubble with no CSS at all, and therefore with no
     way for its geometry to move. */
  const TIP_SEL = '.tooltip-anchor, [data-tip]';
  document.addEventListener('mouseover', e => {
    const anchor = e.target.closest(TIP_SEL);
    if (anchor) showTip(anchor);
  });
  document.addEventListener('mouseout', e => {
    const anchor = e.target.closest(TIP_SEL);
    if (anchor && !anchor.contains(e.relatedTarget)) hideTip();
  });
  document.addEventListener('scroll', hideTip, true);

  /* THE SAME BUBBLE, SHOWN ON DEMAND. Everything above is hover-driven off a
     `.tooltip-anchor`; this publishes the one thing a click-driven caller
     needs — point the existing #g-tip at any element, with any text, for a
     moment. Reusing it rather than building a second bubble means one look,
     one z-index, and one piece of placement logic: the above/below fallback
     and the viewport clamping in showTip() are exactly what a tooltip pinned
     to a gear in the card's top-right corner needs, and they are easy to get
     subtly wrong twice.
     The timer is stored on the element so a second call replaces the first
     rather than letting an old timeout hide a fresh tip. */
  let _atTimer = null;
  /* THE TRAILING RESET NEEDS A HANDLE TOO, and not having one was a real bug.
     dropNudge strips the variant 160ms later, after the fade. Press Submit
     twice and the order is: pointerdown → dropNudge schedules the strip; click
     → smTipAt raises a fresh nudge; 160ms later that orphaned timeout fires
     and takes the variant off a tooltip that is on screen. The bubble kept its
     narrow position and snapped to the base 230px grey — measured, 127.5 → 230
     at t=180ms — which is exactly the "second, wider, older card" it looked
     like. One shared element, two overlapping lifetimes. */
  let _resetTimer = null;

  /* Take the nudge down now, wherever it is in its life. Split out because two
     things end it — its own timer and the user acting — and both have to leave
     the shared bubble in the same state. */
  function dropNudge() {
    const tip = document.getElementById('g-tip');
    if (!tip || !tip.classList.contains('g-tip--nudge')) return;
    clearTimeout(_atTimer);
    clearTimeout(_resetTimer);
    hideTip();
    // After the fade, or the bubble snaps back to 230px grey while still lit.
    _resetTimer = setTimeout(() => tip.classList.remove('g-tip--nudge'), 160);
  }

  /* ACTING DISMISSES IT. The nudge points at a control and says what to do
     with it; the moment you touch anything it has been read, and leaving it
     hovering over a gear you just pressed makes it look stuck rather than
     timed.
     `pointerdown` and not `click` for the ordering: the press that SPAWNS a
     nudge fires pointerdown first and click after, so this cannot cancel the
     tip the same gesture is about to raise. On `click` it would. */
  document.addEventListener('pointerdown', dropNudge, true);

  window.smTipAt = function (el, text, ms) {
    const tip = document.getElementById('g-tip');
    if (!tip || !el || !text) return;
    /* BOTH timers, because raising a nudge has to cancel the previous one's
       whole tail — its hide AND its trailing reset. Clearing only _atTimer is
       what let an orphaned reset strip this tooltip mid-life. */
    clearTimeout(_atTimer);
    clearTimeout(_resetTimer);
    tip.textContent = text;
    /* The nudge variant shrink-wraps, so the class has to go on BEFORE the
       measurement below — width is what everything here is computed from. */
    tip.classList.add('g-tip--nudge', 'is-visible');

    const r = el.getBoundingClientRect();
    /* MEASURED, NOT THE TIP_W CONSTANT. showTip() above can use the constant
       because the hover tooltip really is a fixed 230px; this one is sized by
       its text, so centring it on 230 would put a 120px bubble 55px to the
       left of its anchor — which is exactly the "off-centre" it looked. */
    const tw = tip.offsetWidth;
    const th = tip.offsetHeight;
    let left = r.left + r.width / 2 - tw / 2;
    left = Math.max(MARGIN, Math.min(left, window.innerWidth - tw - MARGIN));
    let top = r.top - th - 8;
    if (top < MARGIN) top = r.bottom + 8;
    tip.style.left = left + 'px';
    tip.style.top  = top  + 'px';

    _atTimer = setTimeout(dropNudge, ms || 2200);
  };
})();

// Called by YES/NO and intensity/chip clicks — re-renders immediately
// Clicking the already-selected value toggles it back to null (deselect)
// pid resolves from the currently-open step modal (state.stepModal.platformId)
// — this and every other Content Rating/Privacy/Business/IAP handler below
// are only ever invoked via onclick/oninput from inside that modal, for
// whichever App-Store-shaped platform (ios or macos) is currently open —
// so this is always the right platform without needing an explicit
// parameter threaded through every onclick="...()" call site.
function answerIOSField(field, value) {
  const pid  = state.stepModal?.platformId || 'ios';
  const ans  = _appStoreAnswers(pid, field);
  const meta = _appStoreAnswerMeta(pid, field);
  const current      = ans[field];
  const fmeta        = meta[field];
  const humanAlready = fmeta?.humanConfirmed === true;

  if (current === value && humanAlready) {
    // Human-confirmed answer clicked again → unselect
    ans[field] = null;
    delete meta[field];
  } else if (current === value && !humanAlready) {
    // AI-inferred answer clicked → promote to human-confirmed, keep value
    meta[field] = { ...(fmeta || {}), humanConfirmed: true };
  } else {
    // Different value selected → set and mark human
    ans[field] = value;
    meta[field] = { ...(fmeta || {}), humanConfirmed: true };
  }
  // Saying "yes" to in-app purchases pre-fills a demo-ready product list.
  if (field === 'hasIAP' && ans[field] === 'yes') _seedStubIapProducts(pid);
  reRenderStepModal();
}

// Called by text oninput — updates state only, no re-render (prevents cursor jumping)
function updateIOSTextField(field, value) {
  const pid = state.stepModal?.platformId || 'ios';
  _appStoreAnswers(pid, field)[field] = value;
}

/**
 * Set privacy policy URL across ALL platforms and the global formData at once.
 * Called from any platform's privacy URL input so they stay in sync.
 * privacyPolicyUrl is one of Mac App Store's fields SHARED with the App
 * Store (IOS_MAC_SHARED_ANSWER_FIELDS, state.js) — state.iosSubmitAnswers is
 * the one object _appStoreAnswers(pid, 'privacyPolicyUrl') actually resolves
 * to for either platform now, so the state.macSubmitAnswers.privacyPolicyUrl
 * write below is inert (nothing reads it any more) but is left in place as
 * harmless, self-documenting redundancy rather than removed.
 */
function setPrivacyUrl(url) {
  state.formData.privacyUrl                    = url;
  state.iosSubmitAnswers.privacyPolicyUrl      = url;
  state.macSubmitAnswers.privacyPolicyUrl      = url;
  state.androidSubmitAnswers.privacyPolicyUrl  = url;
  state.steamSubmitAnswers.privacyPolicyUrl    = url;
  // Unlike macSubmitAnswers above (inert redundancy — see this function's
  // own comment further up), Mac App Store Full genuinely reads its own
  // independent copy (_appStoreAnswers('macos_full', 'privacyPolicyUrl')
  // never routes to iOS's — see makeBlankMacFullAnswers' comment, state.js),
  // so this write is required, not redundant.
  state.macFullSubmitAnswers.privacyPolicyUrl  = url;
  // Sync sibling platform inputs that are currently in the DOM
  // (but don't change the one that's actively focused — it's the source)
  const active = document.activeElement;
  ['ios-privacy-url', 'macos-privacy-url', 'macos_full-privacy-url', 'android-privacy-url', 'steam-privacy-url'].forEach(id => {
    const el = document.getElementById(id);
    if (el && el !== active && el.value !== url) el.value = url;
  });
  // Update card progress bars and section states — NO full re-render here
  // because that would destroy the focused input. Re-render happens on blur (see inputs).
  updateObSectionStates();
  updateAndroidCard();
  updateIOSCard();
  updateIOSCard('macos');
  updateIOSCard('macos_full');
  updateSteamCard?.();
}

/* ── Privacy matrix handlers ─────────────────────────── */

/* THE ORDER IS STAMPED ON THE WAY IN, ONCE (v6.52). Flagged groups float to
   the top, and deciding that on every render meant marking the first cell of an
   untouched group sent that group to the top of the table **under the pointer
   that had just pressed it**. Frozen at open time it cannot move while you
   work; the counter on each header is what stops a group you have filled in
   from getting lost further down. Re-stamped on every open, so the next visit
   leads with whatever you declared last time. */
/* AND IT OPENS WITH EVERYTHING FOLDED (v6.70). Jaco: *"cuando cierro y vuelvo a
   abrir la tabla, quiero que todo esté comprimido por defecto."*

   The open group was kept per platform, and that was defended as a feature —
   come back and you are where you left off. It is the wrong claim for a control
   whose whole gesture is OPENING something: a table you have just unfolded
   should show you the 16 groups and their counts, which is the view the
   accordion exists to give, not one block already expanded from a visit you may
   not remember making. Sixteen closed groups fit on one screen; one open one
   spends a third of it on a decision nobody has just made.

   It clears on the way IN rather than on the way out, beside the order stamp,
   because those are one sentence: **the table opens fresh** — the order is
   frozen and nothing is expanded. Clearing on close would work identically on
   screen and would leave the state carrying an answer to a question the next
   open has not asked yet. Still keyed per platform, so Mac and Mac Full stay
   independent; they now simply both start closed. */
function togglePrivacyMatrix() {
  state.privacyMatrixExpanded = !state.privacyMatrixExpanded;
  if (state.privacyMatrixExpanded) {
    _privacyStampOrder();
    const pid = state.stepModal?.platformId || 'ios';
    if (!state.privacyGroupOpen) state.privacyGroupOpen = {};
    state.privacyGroupOpen[pid] = null;
  }
  reRenderStepModal();
}

function _privacyStampOrder() {
  const pid = state.stepModal?.platformId || 'ios';
  const a   = _appStoreAnswers(pid, 'dataPerType');
  const sel = new Set(Object.keys(a.dataPerType || {}));
  if (!state.privacyGroupOrder) state.privacyGroupOrder = {};
  state.privacyGroupOrder[pid] = IOS_DATA_TYPES
    .map((g, i) => ({ g, i, flagged: g.types.some(t => sel.has(t.id)) }))
    .sort((x, y) => (x.flagged === y.flagged) ? x.i - y.i : (x.flagged ? -1 : 1))
    .map(x => x.g.group);
}

/* ONE GROUP AT A TIME. Pressing the open group closes it and leaves the table
   with none open, which is the state the accordion starts in — so the header is
   never a button that does nothing, and the lighter ground never marks more
   than one place. Nothing is remembered per group: the whole model is a single
   name, or null. */
/* THE TRAVEL IS IN THE RENDER'S OWN FRAME, NOT THE NEXT ONE (v6.66).
   Jaco: *"cuando toco algún item que está a media altura de la tabla, hace un
   raro, como que baja antes de ponerse en focus centrado"* — and then: *"si
   revisas el html que te pasé, me gustaba mucho más su comportamiento, cópialo
   igual y no inventes."*

   DIFFED AGAINST THE MOCK, THE MATHS WERE ALREADY IDENTICAL AND THE TIMING WAS
   NOT. `apple-privacy-modal-990.html` restores the old scrollTop onto the fresh
   markup and calls `scrollTo` on the very next line — one synchronous pass, so
   the restored position is never painted. This deferred the same block to a
   `requestAnimationFrame`, which is one whole frame at the restored position
   before the ease begins. And this is a one-at-a-time accordion, so that
   position is usually WRONG: opening a group closes the one that was open, and
   if that one sat above you everything below jumps up by its height. The frame
   you saw was that jump. Two motions for one gesture, the second correcting the
   first.

   So the rAF is gone and nothing else moved. A pin — measure the row before,
   put the scroller back by the drift after — was written first and thrown away:
   it fixes the same frame by inventing a mechanism the mock does not have, and
   the mock is the thing that was approved.

   AND THE TRAVEL IS `_smScrollTo`, WHICH IS THE HALF THE FIRST PASS GOT WRONG
   (v6.68). Jaco, still on it after the rAF came out: *"sigue haciendo un
   recorrido rarísimo"*, then *"¿puede ser safari? ¿en chrome no pasa?"* — yes,
   and in Chrome it does not: measured here, first-frame delta 0 and one
   continuous ease 220 → 218.5 → 213.5 → … → 77.

   v6.66 kept native `scrollTo({behavior: 'smooth'})` on the argument that *"the
   mock is the evidence it does not [misbehave]"*. **That is evidence about the
   MOCK, not about this DOM** — a standalone file with its own boxes, opened
   once. This is the sentence "The travel is ours, not the browser's" exists to
   refuse: which box an engine scrolls, and whether it honours `smooth` on a
   NESTED scroller whose content changed height in the same tick, is per-engine,
   and Safari is the engine nobody here can drive. Copying the mock's TIMING was
   right; copying its choice of animator was the part that was never verifiable.

   `_smScrollTo` names one element and writes `scrollTop` frame by frame on the
   app's own 420ms sine, so no engine's smooth implementation is involved at
   all. Same arithmetic, same single motion, one less thing that can differ.
   **A mechanism with no per-engine behaviour beats one that has to be checked
   in an engine you cannot open** — this file's standing preference, stated
   three times before this and overruled once, here.

   The +2 keeps the group's top rule off the sticky header's own, where the two
   read as one thick smeared band. Closing does not travel: you are already
   looking at the thing you just folded away. */
function togglePrivacyGroup(pid, groupName) {
  if (!state.privacyGroupOpen) state.privacyGroupOpen = {};
  const open = state.privacyGroupOpen[pid] === groupName;
  state.privacyGroupOpen[pid] = open ? null : groupName;
  const goTo = open ? null : groupName;

  reRenderStepModal();
  if (!goTo) return;

  const sc = document.getElementById('pvt-scroll');
  // Found by scanning `data-g` rather than by a selector: a group name can
  // hold a space, an `&` or an apostrophe ("Health & Fitness"), and every one
  // of those needs different escaping inside a selector string. A comparison
  // needs none.
  const td = sc && [...sc.querySelectorAll('tr.pvt-g td')]
    .find(el => el.dataset.g === goTo);
  if (!sc || !td) return;
  // Reading scrollHeight flushes the pending layout of the node that has just
  // replaced this one, so the clamp below is against the real maximum rather
  // than a clientHeight that has not been solved yet — see "A scroll restore
  // must flush layout first".
  const max  = Math.max(0, sc.scrollHeight - sc.clientHeight);
  const head = sc.querySelector('thead')?.getBoundingClientRect().height || 0;
  const top  = td.getBoundingClientRect().top - sc.getBoundingClientRect().top
             + sc.scrollTop - head + 2;
  _smScrollTo(sc, Math.max(0, Math.min(max, top)));
}

function toggleContentRatingExpanded(value) {
  const pid = state.stepModal?.platformId || 'ios';
  /* SWITCHING THE VIEW GOES BACK TO THE TOP. The two views are different lists,
     not two states of one: "All" has every question and "Unanswered" only what
     is left, so a scroll position carried across lands you in the middle of a
     list you have not seen, beside rows you did not choose. reRenderStepModal
     deliberately restores scrollTop (see its own note) — this clears the memory
     of it first, so the restore has nothing to put back. */
  const body = document.getElementById('step-modal-body');
  if (body) body.scrollTop = 0;
  // Re-snapshot on "Unanswered" click so newly-answered questions get hidden
  if (!value) takeFilterSnapshot(pid);
  if (pid === 'macos')      state.macContentRatingExpanded     = value;
  else if (pid === 'macos_full') state.macFullContentRatingExpanded = value;
  else                      state.iosContentRatingExpanded     = value;
  reRenderStepModal();   // routes to the inline pane when it's the active surface
}

function toggleAndroidContentRatingExpanded(value) {
  if (!value) takeFilterSnapshot('android');
  state.androidContentRatingExpanded = value;
  reRenderStepModal();
}

function toggleSteamContentRatingExpanded(value) {
  if (!value) takeFilterSnapshot('steam');
  state.steamContentRatingExpanded = value;
  reRenderStepModal();
}

/* ── Privacy preset chips ─────────────────────────────
   collectsData/privacyDescription/dataPerType are Mac App Store fields
   SHARED with the App Store (IOS_MAC_SHARED_ANSWER_FIELDS, state.js) — a
   single write to state.iosSubmitAnswers below is all either platform ever
   reads for these, so there is no separate state.macSubmitAnswers.* write
   here at all (unlike setPrivacyUrl, which keeps its now-inert
   macSubmitAnswers write as harmless redundancy — this function never had
   one worth preserving, since it's being written fresh either way). */
function togglePrivacyPreset(id) {
  const preset = PRIVACY_PRESETS.find(p => p.id === id);
  if (!preset) return;

  let curr = [...(state.privacyPresets || [])];

  if (id === 'guest') {
    // Guest is exclusive — toggle off all others
    state.privacyPresets = curr.includes('guest') ? [] : ['guest'];
  } else {
    // Any non-guest preset: deselect guest, toggle this one
    curr = curr.filter(p => p !== 'guest');
    state.privacyPresets = curr.includes(id)
      ? curr.filter(p => p !== id)
      : [...curr, id];
  }

  const selected  = state.privacyPresets;
  const hasGuest  = selected.includes('guest');
  const pid       = state.stepModal?.platformId;

  /* A PRESET CLICK IS THE ONE MOMENT THE TABLE MAY RE-SORT ITSELF (v6.52).
     The order is otherwise frozen at open time precisely so nothing moves
     under a pointer that is working inside the table — but a preset chip lives
     ABOVE the table, and pressing one is exactly the event that changes which
     groups hold data. So the groups it just filled float up, in the one case
     where the thing you are pointing at cannot be the thing that moves.

     The group you have OPEN is left alone: re-stamping reorders the list, it
     does not fold anything. Stamped after dataPerType is written, below, or it
     would sort on the previous answer. */

  // Which App-Store-shaped answers object this preset click should write
  // into. 'ios' and 'macos' both resolve to state.iosSubmitAnswers (macos's
  // collectsData/privacyDescription are the SAME shared field — see
  // buildPrivacySection's own comment above), matching this function's
  // original iOS-only behavior exactly. 'macos_full' is fully independent
  // (see makeBlankMacFullAnswers' comment, state.js) so it gets its own
  // state.macFullSubmitAnswers instead — writing into iosSubmitAnswers here
  // would silently corrupt the App Store's own privacy answers.
  const iosAns = (pid === 'macos_full') ? state.macFullSubmitAnswers : state.iosSubmitAnswers;

  if (selected.length === 0) {
    // Nothing selected — clear descriptions AND any AI-inferred data types, then re-render
    if (iosAns) {
      iosAns.privacyDescription = '';
      iosAns.dataPerType        = {};
      iosAns.collectsData       = null;
    }
    if (state.androidSubmitAnswers) {
      state.androidSubmitAnswers.androidDataDescription = '';
    }
    state.privacyAIStatus = null;
    reRenderStepModal();
    return;
  }

  if (hasGuest) {
    iosAns.collectsData                             = 'no';
    state.androidSubmitAnswers.collectsOrSharesData = 'no';
    iosAns.privacyDescription                       = '';
    state.androidSubmitAnswers.androidDataDescription = '';
    reRenderStepModal();
    return;
  }

  // Non-guest presets selected
  iosAns.collectsData                             = 'yes';
  state.androidSubmitAnswers.collectsOrSharesData = 'yes';
  const combined = selected
    .map(pid2 => PRIVACY_PRESETS.find(p => p.id === pid2)?.description || '')
    .filter(Boolean)
    .join(' ');
  iosAns.privacyDescription                       = combined;
  state.androidSubmitAnswers.androidDataDescription = combined;

  /* **THE PRESETS FILL THE TABLE THEMSELVES, AND UNTIL NOW NOTHING DID.**
     Jaco: *"si elijo varias casillas como cloud save, leaderboards, no guarda
     el resultado y nunca marca como completado el paso."*

     Everything above this line was already being written correctly — measured
     with cloudsave + leaderboards: both ids in `privacyPresets`, both chips
     lit, `collectsData: 'yes'`, a 692-character description. What stayed empty
     was `dataPerType`, and that is the ONE thing the completion test asks for
     once `collectsData` is `'yes'` (isIOSSectionComplete, state.js). So the
     answer was saved and the step still could not finish.

     **`_triggerPrivacyAI` was the only writer of that field**, and its first
     line is `if (!CLAUDE_API_KEY) return` — every local session, plus any live
     one where the call fails. A checklist item that cannot complete without a
     network round trip is not a checklist item.

     The union is per TYPE rather than per preset, because two presets naming
     the same type are one row with both purposes: Cloud Save and Leaderboards
     both collect `user_id` and `gameplay`, and the table has one line each.
     `tracking` and `identity` take the STRONGER claim — a type that any
     selected preset tracks is tracked, and Apple's label is a statement about
     the app rather than about one feature, so the safer answer has to win.

     Fresh each time, never merged into what is there: this recomputes from the
     selection, so DESELECTING a preset removes exactly its rows rather than
     leaving them behind. Hand edits inside the table are overwritten by the
     next preset press, which is the same contract the AI path already had.

     The AI still runs below and still replaces this wholesale when it answers.
     That is not a conflict: it reads these very descriptions and can be more
     nuanced than a table lookup. What changed is that nothing DEPENDS on it. */
  const perType = {};
  selected.forEach(pid2 => {
    const t = PRIVACY_PRESETS.find(p => p.id === pid2)?.types;
    if (!t) return;
    Object.entries(t).forEach(([typeId, row]) => {
      const cur = perType[typeId] || { purposes: [], identity: 'no', tracking: 'no' };
      row.purposes.forEach(p => { if (!cur.purposes.includes(p)) cur.purposes.push(p); });
      if (row.identity === 'yes') cur.identity = 'yes';
      if (row.tracking === 'yes') cur.tracking = 'yes';
      perType[typeId] = cur;
    });
  });
  iosAns.dataPerType = perType;

  // Now that dataPerType is written, re-sort the accordion so the groups this
  // preset just filled lead the table. See the note at the top of this
  // function for why a preset click is the one safe moment to do that.
  _privacyStampOrder();

  // Trigger AI translation for the active platform only
  if (combined.length >= 20) {
    if (pid === 'ios' || pid === 'macos' || pid === 'macos_full') _triggerPrivacyAI(pid);
    if (pid === 'android')                                        _triggerAndroidDataAI();
  }
  reRenderStepModal();
}

/* ── Privacy NLP → privacy label AI translation ───────── */

// Fires on blur (focus-out) — not on every keystroke
function updatePrivacyDescription(val) {
  const pid = state.stepModal?.platformId || 'ios';
  _appStoreAnswers(pid, 'privacyDescription').privacyDescription = val;
  _setInputComplete('ob-prv-nlp-textarea', !!(val?.trim()));
  if (!val || val.trim().length < 20) return;
  _triggerPrivacyAI(pid);
}

async function _triggerPrivacyAI(pid) {
  pid = pid || state.stepModal?.platformId || 'ios';
  const ans = _appStoreAnswers(pid, 'privacyDescription');
  if (!CLAUDE_API_KEY) return;
  const desc = (ans.privacyDescription || '').trim();
  if (desc.length < 20) return;

  // If this exact description succeeded before, restore cached result instantly.
  // privacyDescription/dataPerType are now genuinely the SAME shared answer
  // for ios and macos (IOS_MAC_SHARED_ANSWER_FIELDS, state.js) — `ans` above
  // already resolves to the one shared state.iosSubmitAnswers object for
  // either pid, so this cache is almost never consulted for a cross-platform
  // hit any more (there's only ever one live description to match against);
  // it still helps if the description is edited and then edited BACK.
  if (desc === state.privacyLastSuccessDesc && state.privacyLastSuccessResult) {
    ans.dataPerType = state.privacyLastSuccessResult;
    state.privacyAIStatus = 'complete';
    reRenderStepModal();
    return;
  }

  state.privacyAIStatus = 'loading';
  reRenderStepModal();

  const typeList    = IOS_DATA_TYPES.flatMap(g => g.types)
    .map(t => `${t.id}: ${t.label} — ${t.desc}`).join('\n');
  const purposeList = IOS_PURPOSES
    .map(p => `${p.id}: ${p.label} — ${p.desc}`).join('\n');

  const prompt = `You are helping a mobile game developer fill in Apple App Store Data Privacy labels.

Developer's description of their data collection:
"${desc}"

Available data type IDs:
${typeList}

Available purpose IDs:
${purposeList}

Return ONLY valid JSON — no markdown fences, no extra text:
{
  "selections": [
    { "typeId": "<exact data type id>", "purposes": ["<purpose id>", ...], "tracking": "yes|no" }
  ]
}

Rules:
- Only include types clearly mentioned or strongly implied by the description.
- Only include purposes that genuinely apply to each type.
- Set tracking "yes" only if data crosses into third-party apps/websites for advertising.
- Be conservative — omit rather than guess.`;

  try {
    const res = await fetch(CLAUDE_ENDPOINT, {
      method: 'POST',
      headers: {
        'x-api-key':                                 CLAUDE_API_KEY,
        'anthropic-version':                         '2023-06-01',
        'content-type':                              'application/json',
        'anthropic-dangerous-direct-browser-access': 'true',
      },
      body: JSON.stringify({
        model:      CLAUDE_MODEL,
        max_tokens: 800,
        messages:   [{ role: 'user', content: [{ type: 'text', text: prompt }] }],
      }),
    });

    if (!res.ok) throw new Error('API ' + res.status);
    const data    = await res.json();
    const text    = (data.content?.[0]?.text || '').trim();
    const cleaned = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
    const parsed  = JSON.parse(cleaned);

    const validTypeIds    = new Set(IOS_DATA_TYPES.flatMap(g => g.types).map(t => t.id));
    const validPurposeIds = new Set(IOS_PURPOSES.map(p => p.id));
    const newPerType      = {};

    for (const sel of (parsed.selections || [])) {
      if (!validTypeIds.has(sel.typeId)) continue;
      const purposes = (sel.purposes || []).filter(p => validPurposeIds.has(p));
      newPerType[sel.typeId] = {
        purposes,
        identity: 'no',
        tracking: sel.tracking === 'yes' ? 'yes' : 'no',
      };
    }

    ans.dataPerType = newPerType;
    state.privacyAIStatus = 'complete';
    state.privacyLastSuccessDesc   = desc;
    state.privacyLastSuccessResult = newPerType;
  } catch (e) {
    console.warn('[Privacy AI]', e.message);
    state.privacyAIStatus = 'error';
  }

  reRenderStepModal();
}

function togglePrivacyDataType(typeId) {
  const pid = state.stepModal?.platformId || 'ios';
  // Clicking a row (but not a checkbox inside it) toggles selection
  const perType = _appStoreAnswers(pid, 'dataPerType').dataPerType;
  if (perType[typeId]) {
    delete perType[typeId];
  } else {
    // identity/tracking default to 'no' (unchecked = no, not unknown)
    perType[typeId] = { purposes: [], identity: 'no', tracking: 'no' };
  }
  reRenderStepModal();
}

/* ── A CELL PRESS WRITES, AND THEN IT RENDERS ─────────────────────────
   Both of these are called from _prvCell (render.js), which passes the value
   the press should PRODUCE rather than reading `this.checked` off an input —
   a button has no checked state to read, and the new value is already known at
   render time.

   `setPrivacyMeta` WAS DEFINED TWICE, twenty lines apart. The second won, and
   the two differed in exactly one line: the first called reRenderStepModal(),
   the second carried a comment saying "Tracking warning updates lazily on next
   section re-open" — which was not a decision, it was the duplicate quietly
   describing its own symptom. Ticking Used for Tracking is supposed to print
   Apple's AppTrackingTransparency note under the table, and it did not appear
   until you closed the section and came back. One definition, same rule as
   smCheckSVG and SM_STEP_CHEVRON.

   AND THEY BOTH RENDER NOW, where togglePrivacyPurpose used to say
   "checkboxes manage themselves". A native checkbox did paint its own tick; a
   button does not — its appearance IS the render. Rendering is also the only
   correct answer here rather than a surgical class flip, for this file's own
   reason: dataPerType is read by the count badge, the tracking note, the group
   ORDERING (a flagged group floats to the top) and isIOSSectionComplete — a
   repaint would be an inventory of those, and an inventory goes stale. The
   table's own scroll position is captured and restored by reRenderStepModal,
   so it keeps its place.

   PRESSING A CELL ON AN UNSELECTED ROW TURNS THE TYPE ON. Both used to bail on
   `if (!perType[typeId]) return`, because the cell was disabled and could not
   be reached; now it can, and refusing it would be a control that lies. Saying
   "I collect Crash Data for Analytics" is saying "I collect Crash Data", so the
   row is created with the same defaults togglePrivacyDataType uses — identity
   and tracking at 'no', which is an answer, not an unknown. */
function togglePrivacyPurpose(typeId, purposeId, next) {
  const perType = _prvEnsureType(typeId);
  const arr = perType[typeId].purposes;
  if (next && !arr.includes(purposeId)) arr.push(purposeId);
  if (!next) perType[typeId].purposes = arr.filter(p => p !== purposeId);
  reRenderStepModal();
}

function setPrivacyMeta(typeId, field, next) {
  const perType = _prvEnsureType(typeId);
  perType[typeId][field] = next ? 'yes' : 'no';
  reRenderStepModal();
}

function _prvEnsureType(typeId) {
  const pid = state.stepModal?.platformId || 'ios';
  const perType = _appStoreAnswers(pid, 'dataPerType').dataPerType;
  if (!perType[typeId]) perType[typeId] = { purposes: [], identity: 'no', tracking: 'no' };
  return perType;
}

/* ── Business — IAP Products list ─────────────────────
   state.iosSubmitAnswers.iapProducts, each a { id, name, desc, price, type,
   trial, collapsed } — see buildIapProductRow (render.js) for the row this
   backs. Same add/remove/field-mutate split as addWebLink/removeWebLink/
   setWebLinkField (Web Factsheet Links, further down this file): structural
   changes (add, remove, Type — which can reveal/hide the Free Trial row —
   Save, and expand) go through reRenderStepModal(); plain text fields
   mutate directly on oninput with no re-render, so typing doesn't lose
   focus mid-word. */
function addIapProduct() {
  const pid = state.stepModal?.platformId || 'ios';
  _appStoreAnswers(pid).iapProducts.push({
    // locs holds this product's Name/Description localizations for every
    // supporting language — { [lang]: { name, desc, nameSourceText,
    // descSourceText } }, keyed by language exactly like
    // state.formData.localizedStoreText is keyed by language for the app's
    // own fields. Populated by IAP Localizations (buildIapLocalizationsSection,
    // render.js; _iapLocPropagateName/_iapLocTriggerAutoTranslate below) —
    // empty until the product is actually saved once (see saveIapProduct).
    id: generateId('iap'), name: '', desc: '', price: '', type: 'consumable', trial: 'no', collapsed: false, locs: {},
  });
  reRenderStepModal();
}
function removeIapProduct(id) {
  const pid = state.stepModal?.platformId || 'ios';
  const ans = _appStoreAnswers(pid);
  ans.iapProducts = ans.iapProducts.filter(p => p.id !== id);
  reRenderStepModal();
}

/* Demo convenience: when a developer (or AI inference) says the app HAS in-app
   purchases, open ONE pre-filled product card ready to save — so the whole demo
   IAP flow is: click "Yes" → a filled-in product appears → click "Save". Left
   expanded (collapsed:false) so its fields are visible for review. Only seeds
   when the list is empty, so it never clobbers a developer's own entries. */
function _seedStubIapProducts(pid) {
  const ans = _appStoreAnswers(pid);
  if (!Array.isArray(ans.iapProducts)) ans.iapProducts = [];
  if (ans.iapProducts.length) return;
  ans.iapProducts.push({
    id: generateId('iap'),
    name: 'Full Game Unlock',
    desc: 'Unlock the remainder of the game',
    price: '4.99',
    type: 'non-consumable',
    trial: 'no',
    collapsed: false,
    locs: {},
  });
}
function setIapProductField(id, key, value) {
  const pid = state.stepModal?.platformId || 'ios';
  const p = _appStoreAnswers(pid).iapProducts.find(p => p.id === id);
  if (p) p[key] = value;
}
// Live character-limit feedback for a product's Name/Description field
// (IAP_PRODUCT_FIELD_LIMITS, render.js) — the same soft-limit pattern as the
// App Store Product Page Preview's own startIasInlineEdit: a live remaining-
// count that goes negative and red, the field itself tinted red, and an
// inline "Must be less than N characters." message once over, but typing is
// never hard-blocked. Runs on every keystroke without a full
// reRenderStepModal() (same reason setIapProductField's own text fields
// skip it — re-rendering mid-word would lose focus/cursor position);
// instead it reaches directly into the DOM for the input's own counter row
// (its real next sibling, same technique as startLocReviewInlineEdit) and
// this card's Save button, disabling Save for as long as ANY field in the
// card is over its limit (saveIapProduct below also re-checks this itself,
// so the button staying enabled by some other means can never bypass it).
function updateIapCharCounter(inputEl, limit) {
  const remaining = limit - inputEl.value.length;
  const isOver = remaining < 0;
  inputEl.classList.toggle('is-over-limit', isOver);
  const counterRow = inputEl.nextElementSibling;
  if (counterRow && counterRow.classList.contains('ias-char-counter-row')) {
    const errorEl = counterRow.querySelector('.ias-char-error');
    const countEl = counterRow.querySelector('.ias-char-count');
    if (errorEl) errorEl.textContent = isOver ? `Must be less than ${limit} characters.` : '';
    if (countEl) { countEl.textContent = String(remaining); countEl.classList.toggle('is-over', isOver); }
  }
  const row = inputEl.closest('.iap-product-row');
  const saveBtn = row?.querySelector('.iap-product-actions .btn-primary');
  if (saveBtn) saveBtn.disabled = !!row.querySelector('.form-input.is-over-limit');
}
function setIapProductType(id, type) {
  const pid = state.stepModal?.platformId || 'ios';
  const p = _appStoreAnswers(pid).iapProducts.find(p => p.id === id);
  if (!p) return;
  p.type = type;
  // Type governs whether the Free Trial row even applies (see
  // buildIapProductRow's isSub check) — re-render so switching to/from a
  // subscription type shows/hides it immediately.
  reRenderStepModal();
}
function setIapProductTrial(id, trial) {
  const pid = state.stepModal?.platformId || 'ios';
  const p = _appStoreAnswers(pid).iapProducts.find(p => p.id === id);
  if (p) p.trial = trial;
  reRenderStepModal();
}
// Save collapses the card to just its name; clicking that name (expandIapProduct)
// reopens the full editable form. Both are structural (re-render) changes.
// The Save button is already disabled in the DOM whenever Name/Description
// is over its limit (buildIapProductRow's initial render + updateIapCharCounter's
// live updates above), but this guard is the actual source of truth — it's
// what makes going over the limit truly block saving, rather than merely
// looking disabled.
//
// Saving is also this product's "commit point" for IAP Localizations
// (buildIapLocalizationsSection, render.js) — the same role blur plays for
// the App Store Product Page Preview's own Title/Description fields
// (_iasSetFieldValue). Every save (not just the first) re-propagates Name
// and re-triggers Description's auto-translation into every supporting
// language, so a product's localizations stay in sync with whatever its
// Name/Description were most recently saved as — see
// _iapLocPropagateName/_iapLocTriggerAutoTranslate below. Both are no-ops
// with no supporting languages configured, and neither blocks the collapse
// above (fired-and-forgotten, same "kick off in the background" pattern
// _iasSetFieldValue itself uses).
function saveIapProduct(id) {
  const pid = state.stepModal?.platformId || 'ios';
  const p = _appStoreAnswers(pid).iapProducts.find(p => p.id === id);
  if (!p) return;
  if (p.name.length > IAP_PRODUCT_FIELD_LIMITS.name || p.desc.length > IAP_PRODUCT_FIELD_LIMITS.desc) return;
  p.collapsed = true;
  // IAP Localizations propagation is platform-specific — each platform keeps
  // its own fully independent iapProducts array AND its own IAP
  // Localizations cluster (_iapLoc* for iOS/Android, _masIapLoc* for Mac App
  // Store, _macFullIapLoc* for Mac App Store Full — see each cluster's own
  // header comment). Route to the one matching THIS product's platform, or
  // Mac App Store's and Mac App Store Full's own saves never populate their
  // own IAP Localizations at all (previously this always called the iOS
  // cluster, which simply looks up `id` in the wrong array, finds nothing,
  // and no-ops — silently, so Mac App Store/Mac App Store Full's
  // localizations never got auto-generated on save).
  if (pid === 'macos') {
    _masIapLocPropagateName(id, p.name);
    _masIapLocTriggerAutoTranslate(id, 'desc', p.desc);
  } else if (pid === 'macos_full') {
    _macFullIapLocPropagateName(id, p.name);
    _macFullIapLocTriggerAutoTranslate(id, 'desc', p.desc);
  } else {
    _iapLocPropagateName(id, p.name);
    _iapLocTriggerAutoTranslate(id, 'desc', p.desc);
  }
  reRenderStepModal();
}
function expandIapProduct(id) {
  const pid = state.stepModal?.platformId || 'ios';
  const p = _appStoreAnswers(pid).iapProducts.find(p => p.id === id);
  if (p) p.collapsed = false;
  reRenderStepModal();
}
// Same "round to a .99 price" polish as the base game price (roundPrice
// above) — kept as its own function rather than reusing roundPrice
// directly, since that one hardcodes state.formData.price and would
// overwrite the base game price instead of this product's own.
function roundIapPrice(id, inputEl) {
  let val = parseFloat(inputEl.value);
  if (isNaN(val) || val <= 0) return; // free / blank — leave as-is
  if (Math.abs(val - Math.floor(val) - 0.99) < 0.001) return;
  const rounded = Math.round(val);
  const result = rounded > 0 ? (rounded - 0.01).toFixed(2) : val.toFixed(2);
  inputEl.value = result;
  setIapProductField(id, 'price', result);
}

/* ── Distribution map ────────────────────────────────── */

async function initDistributionMap() {
  const container = document.getElementById('distribution-map-container');
  if (!container) return;

  if (!_worldTopology) {
    container.innerHTML = '<div class="world-map-loading">Loading map…</div>';
    try {
      const res = await fetch('https://cdn.jsdelivr.net/npm/world-atlas@2/countries-110m.json');
      _worldTopology = await res.json();
    } catch (e) {
      container.innerHTML = '<div class="world-map-loading">Map unavailable offline</div>';
      return;
    }
  }
  renderDistributionMap();
}

function renderDistributionMap() {
  const container = document.getElementById('distribution-map-container');
  if (!container || !_worldTopology) return;

  const W = container.offsetWidth || 480;

  const selected = new Set(
    (state.iosSubmitAnswers.selectedCountries || [])
      .map(code => (IOS_COUNTRIES.find(c => c.code === code) || {}).num)
      .filter(Boolean)
  );

  _drawMap(container, W, selected, new Set());
}

function toggleDistExpand() {
  const list = document.getElementById('dist-country-list');
  const btn  = document.getElementById('dist-expand-btn');
  if (!list || !btn) return;

  const isExpanded = list.classList.toggle('is-expanded');
  const extraCount = IOS_COUNTRIES.length - 10;

  if (isExpanded) {
    btn.innerHTML = `
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="18 15 12 9 6 15"/></svg>
      Show fewer markets`;
  } else {
    btn.innerHTML = `
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg>
      Show ${extraCount} more markets`;
    // Scroll the button back into view when collapsing
    btn.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  }
}

function toggleIOSCountry(code) {
  // Manual edit → switch to Custom preset
  state.iosSubmitAnswers.distPreset = 'custom';

  const arr = state.iosSubmitAnswers.selectedCountries;
  const idx = arr.indexOf(code);
  if (idx === -1) arr.push(code); else arr.splice(idx, 1);

  // Update chip visual directly (avoid full re-render)
  const chip = document.getElementById('dist-chip-' + code);
  if (chip) chip.classList.toggle('is-on', idx === -1);

  // Update bar color directly
  const row = chip && chip.closest('.dist-country-row');
  const fill = row && row.querySelector('.dist-bar-fill');
  if (fill) fill.style.background = (idx === -1) ? 'rgba(74,222,128,0.5)' : 'var(--border-hover)';

  // Update preset button highlights without full re-render
  document.querySelectorAll('.dist-preset-btn').forEach(btn => {
    btn.classList.toggle('is-active', btn.textContent.trim() === 'Custom');
  });

  renderDistributionMap();
}

/* ── Claude AI handlers ───────────────────────────────── */

// Called by the Retry button on analysis error — delegates to unified retry
async function _runClaudeAnalysis() {
  await _retryInference('ios', state.stepModal?.stepId || 'questionnaire');
  updateIOSCard();
}

function clearClaudeResults() {
  state.iosSubmitAnswers        = makeBlankIOSAnswers();
  state.iosAnswerMeta           = {};
  state.claudeCache             = null;
  state.iosStorePreviewSeen     = false;
  state.stepModal.inferenceStatus = null;
  state.stepModal.inferenceError  = null;
  reRenderStepModal();
  updateIOSCard();
}


// English-speaking iOS markets
const DIST_PRESET_ENGLISH = IOS_COUNTRIES.filter(c => c.lang === 'en').map(c => c.code);

function setDistPreset(preset) {
  const ans = state.iosSubmitAnswers;
  ans.distPreset = preset;

  if (preset === 'everywhere') {
    ans.selectedCountries = IOS_COUNTRIES.map(c => c.code);
  } else if (preset === 'everywhere_except_cn') {
    ans.selectedCountries = IOS_COUNTRIES.filter(c => c.code !== 'CN').map(c => c.code);
  } else if (preset === 'english_only') {
    ans.selectedCountries = [...DIST_PRESET_ENGLISH];
  }
  // 'custom' → keep current selection as-is

  reRenderStepModal();
  requestAnimationFrame(() => initDistributionMap());
}

function confirmAndSubmit(platformId) {
  state.platformStepStatus[platformId]['reviewSubmission'] = 'complete';
  closeSubmitModal();
  renderDashboard();
}

// Opens the track-selection submit modal for platforms that have defined tracks
// (ios / android / steam). For platforms without tracks, submits directly.
/* Persist selected track from the inline card dropdown (no modal needed) */
function selectTrack(pid, trackId) {
  if (!state.selectedTracks) state.selectedTracks = {};
  state.selectedTracks[pid] = trackId;

  /* A TRACK IS NOT A LABEL, IT IS HALF OF UPLOAD BUILD — so the whole surface
     repaints, and this function stops patching two boxes by hand.

     It used to refresh exactly the two things the pill had ever lived in: the
     submit step card (where it started) and the release block (where shape 4
     moved it, added when choosing "Default branch" left the label reading
     "Beta branch"). Both patches were correct and both were an inventory, and
     the inventory was two short. `_uploadBuildComplete` (state.js) reads
     `selectedTracks` — "a build with no destination is not a finished step" —
     so choosing one also ticks Upload Build's disc, promotes its row, moves
     the step count and the progress bar, and takes `.active-card` into
     `submit-ready`. None of those five were repainted, so the step you had
     just finished stayed grey until something unrelated forced a render, and
     the card said the destination was chosen while the step asking for it said
     it was not.

     `_refreshBuildUI`'s own note is the precedent and the argument is identical:
     "an upload changes more than the body it happened in… repainting only the
     body would leave four of those stale, and branching on which to do would be
     two code paths for one event". The picker's panel is already closed —
     swSelectChoose calls closeAllDropdowns() before the callback — so there is
     nothing on screen to lose.

     It also fixes both presentations at once. `_paintStepRow` could not be used
     here: the card builders emit `.ios-step-num` with no `dot-<pid>-<stepId>`
     id, so on a card row that helper returns on its first line (see CLAUDE.md).
     A render has no such blind spot. */
  renderDashboard();

  // The Upload Build step has a modal form of its own (buildBuildDropdown's
  // `inModal` arm); if it is open, it holds a stale destination too. Guarded
  // and ordered exactly as handleBuildUpload does it.
  if (typeof reRenderStepModal === 'function') reRenderStepModal();
}

/* ONE SHAKE, REPLAYABLE — and it has to be element.animate(), not a class.
   A CSS animation attached by adding a class plays once and then does nothing
   on a second click, because the class is already there; the usual dodge is
   remove → force a reflow → re-add, which is three lines of ceremony that only
   exist to defeat the cascade. A WAAPI animation starts from the beginning
   every time it is created, by definition.
   Cancelling any shake already running on the element is what makes rapid
   clicks read as one insistent object rather than a stack of overlapping
   transforms fighting each other. */
function _smShake(el, kind, delay) {
  if (!el) return;
  /* Respect the OS switch. A shake is pure emphasis — there is no information
     in it that the colour and the position don't already carry — so when
     motion is turned down it simply doesn't happen. */
  if (window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) return;

  el.getAnimations?.().forEach(a => { if (a.id === 'sm-shake') a.cancel(); });

  /* THE GEAR PULSES, A ROW SLIDES — and the gear does NOT rotate, which it did
     for a round. Rotation looked like the obvious choice because the gear
     already turns 90° on hover, so a rotary shake reads as the same object
     insisting. It was wrong for a reason worth writing down: this gear has
     eight lobes and, as measured when its hover turn was tuned, its only real
     symmetry is 90° — at ±20° the silhouette does not map onto itself at any
     point in the swing, so the icon appears to wander even though its centre
     is provably fixed (0.00px of drift in both axes, sampled across the
     animation). A shape that changes outline while it rocks reads as a shape
     that moved.
     So the motion comes off the glyph entirely and goes onto the button's
     box: its amber fill surges and a ring blooms out of it. Nothing
     translates, nothing rotates, and it is louder than the shake was. */
  /* ONE RIPPLE, NOT TWO FLASHES. The first pulse strobed the fill between .14
     and .55 twice and bloomed a ring on each beat — three things happening in
     760ms, which is why it read as cheap rather than as emphasis. A single
     expanding ring that fades as it grows is the gesture everything else uses
     for "here", and the fill only swells behind it, to .34 rather than .55.
     The ring carries the attention and the fill carries the colour, instead of
     both shouting.
     The fill starts and ends on .14, the alert gear's own resting value, so
     there is no step at either edge — and the button's `transition:
     background .15s` has nothing to catch on the way out. */
  /* NOTHING MOVES ANY MORE, on either target. The rows used to slide sideways
     and it was the same objection the gear's rotation drew: displacement reads
     as a glitch in a card whose whole layout is a pair of fixed columns, and
     with four rows shaking at once it read as the card coming apart.

     THE ROWS BLINK THEIR TEXT, IN WHITE, ALL AT ONCE. Three corrections in one
     round, each worth keeping:
       • the box was wrong — filling four 50px rows is a lot of surface for a
         hint, and the fill is already spoken for by hover;
       • amber was wrong here — the gear and the tooltip carry the colour
         because they are the ONE thing to go do; the rows are just a list of
         what is outstanding, and tinting them made four things look like four
         alerts;
       • the cascade was wrong — a stagger narrates, and this is a glance, not
         a sentence. All together, once.
     A white blink on text that is ALREADY near-white has to go down before it
     goes up: adding white to #f5f5f5 is invisible. So it drops to 28% and
     returns, twice — the text stays exactly where it is and only its presence
     flickers. */
  const ease = 'cubic-bezier(.22,1,.36,1)';
  const opts = { duration: 560, easing: ease, delay: delay || 0, fill: 'backwards' };

  const anim = kind === 'pulse'
    ? el.animate([
        { backgroundColor: 'rgba(255,184,107,.14)', boxShadow: '0 0 0 0 rgba(255,184,107,.45)' },
        { backgroundColor: 'rgba(255,184,107,.34)', boxShadow: '0 0 0 5px rgba(255,184,107,.18)', offset: .45 },
        { backgroundColor: 'rgba(255,184,107,.14)', boxShadow: '0 0 0 10px rgba(255,184,107,0)' },
      ], opts)
    : el.animate([
        { color: 'rgb(245,245,245)' },
        { color: 'rgba(255,255,255,.28)', offset: .22 },
        { color: 'rgb(255,255,255)',      offset: .44 },
        { color: 'rgba(255,255,255,.28)', offset: .68 },
        { color: 'rgb(245,245,245)' },
      ], { ...opts, easing: 'ease-in-out' });
  anim.id = 'sm-shake';
}

/* THE SPOTLIGHT — dim the whole card except the things standing in the way.
   Every gesture before this one tried to make the obstacles louder: shake
   them, tint them, flash them. This does the opposite and is better for it —
   it takes everything else AWAY, so the answer to "why can't I submit" is
   whatever is still lit. Nothing moves, nothing changes colour, and it scales
   to one obstacle or five without becoming five alerts.
   The dimming lives on leaf groups, never on .ios-step-cards, because opacity
   is a filter over a subtree: dim the container and the lit row inside it can
   never climb back out. */
let _spotTimer = null;
/* The host the spotlight is currently running on. `_smSpotlight` serves two
   surfaces now — a platform card and the Mac preview's shell — and they can be
   on screen at once (the step modal opens over the dashboard). Without this,
   starting one while the other was running cleared only the NEW host's marks
   and left `is-spotlight` on the old one for good, because the shared timer had
   just been cancelled. One variable, and a host can always be put back. */
let _spotHost = null;
/* DEV TOOL — hold a loading screen open so it can actually be looked at.
   The keys are injected at deploy time, so locally every inference fails in
   about a second and the loader is gone before you can judge it. Open a step
   modal, then from the console:

     smPreviewLoader('report')      Improve's "Generating Report Card…"
     smPreviewLoader('inference')   the step modal's "Shipmate is working…"
     smPreviewLoader(false)         let go — the step renders normally again

   It only writes the same state the real run writes, so nothing here is a
   special path through the loader: what you see is what ships. */
function smPreviewLoader(which = 'report') {
  if (which === false || which === 'off') {
    state.storePageInsights = null;
    state.improveSubmissionAnalysis = null;
    if (state.stepModal) state.stepModal.inferenceStatus = null;
  } else if (which === 'inference') {
    if (!state.stepModal) { console.warn('smPreviewLoader: open a step modal first'); return; }
    state.stepModal.inferenceStatus = 'loading';
  } else {
    state.storePageInsights = { loading: true };
    state.improveSubmissionAnalysis = { loading: true };
  }
  reRenderStepModal();
}

/* DEV TOOL — stand in for a successful inference, so the states that only
   exist AFTER one can be looked at locally. The Unanswered / All toggle and the
   "Shipmate inferred X out of Y" banner are both gated on
   `state.<plat>AnsweredAtInference` being a Set, which never happens with no
   API key: the call fails and the snapshot is never taken.

     smFakeInference()             two thirds of the questions answered
     smFakeInference('macos', 1)   all of them  → the Unanswered view is empty
     smFakeInference('macos', 0)   none         → toggle shows, banner does not

   It fills the same answer fields a real inference fills and then calls the
   real `takeFilterSnapshot`, so the filter sees exactly what it would see in
   production. Answers are 'no' / 'none' — the quiet end of every question,
   which is also the honest default for a demo. */
function smFakeInference(pid = 'macos', fraction = 0.66) {
  const shared = (pid === 'macos_full') ? state.macFullSubmitAnswers : state.iosSubmitAnswers;
  if (!shared) { console.warn('smFakeInference: no answer store for ' + pid); return; }
  /* THE ANSWER AND WHERE IT CAME FROM ARE TWO WRITES. An inferred answer is
     marked by its meta entry ({ confidence, humanConfirmed: false }), which is
     what draws the ✦ and the dimming — write only the answer and the questions
     look hand-picked, which is the one thing this preview must not fake.

     The bucket has to be asked for PER FIELD: _appStoreAnswerMeta routes a
     shared Content Rating field to state.iosAnswerMeta and everything else to
     the platform's own, and called without a field id it hands back the
     platform bucket — where the badge never looks. */
  const metaFor = (qid) => (typeof _appStoreAnswerMeta === 'function')
    ? _appStoreAnswerMeta(pid, qid)
    : (state.iosAnswerMeta || {});
  const take = (list, value) => (list || []).forEach((q, i) => {
    if (i / Math.max(1, list.length) >= fraction) return;
    shared[q.id] = value;
    metaFor(q.id)[q.id] = { confidence: 0.9, humanConfirmed: false };
  });
  take(typeof IOS_INTENSITY_QUESTIONS !== 'undefined' ? IOS_INTENSITY_QUESTIONS : [], 'none');
  take(typeof IOS_CONTENT_YN_QUESTIONS !== 'undefined' ? IOS_CONTENT_YN_QUESTIONS : [], 'no');
  takeFilterSnapshot(pid);
  if (pid === 'macos')      state.macContentRatingExpanded     = false;
  if (pid === 'ios')        state.iosContentRatingExpanded     = false;
  if (pid === 'macos_full') state.macFullContentRatingExpanded = false;
  /* A SUCCESSFUL RUN LEAVES NO ERROR BEHIND. Without this the faked inference
     sat under the red "Analysis failed: No API key set." banner from the real
     call that failed a second earlier — which is exactly the thing that makes
     the preview unreadable. */
  if (state.stepModal) {
    state.stepModal.inferenceStatus = 'done';
    state.stepModal.inferenceError  = null;
  }
  reRenderStepModal();
}

/* DEV TOOL — a plausible Store Page analysis, so Improve's suggestion boxes can
   be looked at locally. Same shape the real call returns (state.storePageInsights
   with an `issues` array; _mergedStoreItems keeps the ones carrying a
   `fixedValue`). Open Improve Your Submission, then:

     smFakeStoreInsights()      three suggestions
     smFakeStoreInsights(false) clear them again */
/* ── DEV: see any submitted-card phase without doing the work ──────────────
   The four post-submit faces are otherwise reachable only by completing every
   step, linking an account, choosing a track and pressing Submit — which is
   several minutes per look, and the reason these faces went a long time
   unexamined.

     smCardState('ios')                every phase, 2.5s apart, on a loop
     smCardState('ios', 'accepted')    one phase, held
     smCardState('ios', 'off')         back to the steps face

   It writes the same `state.platformFlipped[pid]` the real submit writes, so
   what you are looking at is the real card, not a mock of it. */
let _smPhaseTimer = null;
/* The third argument is the SENT DATE, and it exists so the calendar can be
   looked at rather than waited for. The band under the month is drawn from
   `platformFlipped[pid].time` plus that platform's own review length, so with
   the time pinned to "yesterday" there was exactly one band you could ever see,
   always in the same place, always the same length. Tuning a mark you cannot
   move is guesswork.

   It is a parameter on THIS function rather than a second `smFakeSubmit`,
   because a helper that writes the same state through its own copy of the
   fields is how the fake and the real drift apart — the trap this file names
   every time it comes up. One writer, one extra argument.

   `T12:00:00` rather than a bare `new Date(iso)`: the bare form parses as UTC,
   so west of Greenwich the band starts on the day BEFORE the one you typed. */
function smCardState(pid = 'ios', phase, sentISO) {
  clearInterval(_smPhaseTimer); _smPhaseTimer = null;
  /* TAKE ME TO WHERE THE CARD IS. On a cold page the view is the landing, so
     this built the card into a dashboard nobody was looking at and read as
     "the command did nothing". A dev helper that renders something you cannot
     see is worse than no helper. */
  if (state.activeView !== 'dashboard') setView('dashboard');
  if (!state.activePlatforms.has(pid)) state.activePlatforms.add(pid);
  if (!state.platformBuilds[pid]) {
    state.platformBuilds[pid] = { name: 'Game.ipa', size: 130937, buildNumber: 42, uploadedAt: Date.now() - 2 * 864e5 };
  }
  if (!(state.selectedTracks || {})[pid]) {
    state.selectedTracks = state.selectedTracks || {};
    state.selectedTracks[pid] = (PLATFORM_TRACKS[pid] || [{ id: 'production' }])[0].id;
  }
  if (phase === 'off') {
    delete state.platformFlipped[pid];
    renderDashboard();
    return 'steps face';
  }
  const set = (ph) => {
    /* A card cannot be in review without its Submit step being done — the real
       `_doFinalSubmit` writes both. Without this the release block dropped the
       TRACK fact, because that is gated on the step, and the fake state was
       subtly unlike the real one in exactly the place being looked at. */
    state.platformStepStatus[pid] = state.platformStepStatus[pid] || {};
    state.platformStepStatus[pid].submit = 'complete';
    state.platformFlipped[pid] = {
      track: state.selectedTracks[pid],
      /* Backdated so "Day N of M" has somewhere to count from — a phase set
         with `time: Date.now()` always reads Day 1, which hides the counter
         bug you are most likely to be looking for. */
      time: sentISO ? new Date(sentISO + 'T12:00:00').getTime() : Date.now() - 864e5,
      phase: ph,
    };
    /* The fake submit copies the real one's side effect, or the guide's month
       face — and the lede that explains it — would only ever be reachable by
       actually walking every step. The point of this helper is that what you
       are looking at is the real thing. */
    state.guideCal = true;
    state.calendar.monthOffset = 0;
    renderDashboard();
    if (typeof renderGuide === 'function') renderGuide();
    /* The band's two dates are PRINTED, not left to be counted off the grid.
       They are derived — sent date plus `OB_PLATFORM_TIMING[pid]`, ceilinged
       the way the calendar ceilings it — so reading them back is the only way
       to know the mark you are looking at is the one you asked for. It is also
       the fastest way to notice the timezone trap above, if it ever returns. */
    const f = state.platformFlipped[pid];
    const tm = (typeof OB_PLATFORM_TIMING !== 'undefined' && (OB_PLATFORM_TIMING[pid] || OB_PLATFORM_TIMING.ios)) || null;
    let band = '';
    if (tm && ph === 'in_review') {
      const a = new Date(f.time);
      const b = new Date(a.getFullYear(), a.getMonth(), a.getDate() + Math.ceil(tm.days));
      band = ' | band ' + a.toDateString().slice(4, 10) + ' → ' + b.toDateString().slice(4, 10)
           + ' (' + Math.ceil(tm.days) + 'd)';
    }
    console.log('[smCardState]', pid, ph, '→', storeReviewPhase(pid, ph).label + band);
  };
  if (phase) { set(phase); return phase; }
  let i = 0;
  set(STORE_REVIEW_PHASES[i]);
  _smPhaseTimer = setInterval(() => {
    i = (i + 1) % STORE_REVIEW_PHASES.length;
    set(STORE_REVIEW_PHASES[i]);
  }, 2500);
  return 'cycling — smCardState("' + pid + '", "off") to stop';
}

/* THE ASK, AND THE ANSWER. `true` opens the question inside the card, `false`
   puts it away, `'go'` actually withdraws. Three states rather than a
   `confirm()` because a native dialog is a different app interrupting this one,
   and because the question belongs beside the thing it is about.
   The flag is cleared before `cancelSubmission` runs — that unflips the card,
   and a question left standing on a card that no longer exists would reappear
   the next time this platform was submitted. */
/* ── HOLD TO CANCEL ──────────────────────────────────────────────────────────
   A press that opened two buttons was a dialog wearing a card's clothes: it
   asked the question in the same place it had just been answered, and the safe
   answer sat one pixel from the destructive one. A HOLD is the confirmation —
   the gesture and the consent are the same act, there is no wrong button to
   land on, and letting go is the undo.
   Everything it changes is a class and one line of text, so releasing early
   costs one class removal and no render at all; only the completed hold
   re-renders, because only then has anything actually changed. */
const SM_CANCEL_HOLD_MS = 1400;
let _cancelHold = null;

/* The submitting fill's duration, and the ONE number behind it — the CSS reads
   it through `--submit-fill` and the timer that commits the submission reads it
   directly, so the bar physically cannot finish out of step with the act it is
   measuring.

   **IT IS `SM_CANCEL_HOLD_MS`, BY REFERENCE (v6.62).** It was its own 1100,
   argued at the time as "you are watching, not deciding, and a second of
   watching is already generous". That was true of a CLICK and is false now that
   Submit is a hold: you are deciding, the whole point is that letting go is the
   undo, and a gesture you must be able to abandon has to be long enough to
   abandon. Send and withdraw are one gesture in two directions, so they take
   one duration — written as the reference rather than as a second 1400, because
   a card that teaches two different "hold" lengths has taught neither. */
const SM_SUBMIT_HOLD_MS = SM_CANCEL_HOLD_MS;

function cancelHoldStart(pid, btn) {
  cancelHoldEnd();
  const card = btn?.closest('.submitted-card');
  if (!card) return;
  const line = card.querySelector('.sub-state-line');
  /* The original word is kept on the node rather than re-derived, because the
     label is the store's (IN REVIEW / PENDING DEVELOPER RELEASE / …) and
     reconstructing it here would be a second copy of STORE_REVIEW's job. */
  _cancelHold = { pid, card, line, was: line ? line.textContent : '' };
  card.style.setProperty('--cancel-hold', SM_CANCEL_HOLD_MS + 'ms');
  card.classList.add('is-cancelling');
  if (line) line.textContent = 'CANCELING SUBMISSION';
  _cancelHold.timer = setTimeout(() => {
    const { pid: p } = _cancelHold || {};
    cancelHoldEnd();
    if (p) cancelSubmission(p);
  }, SM_CANCEL_HOLD_MS);
}

function cancelHoldEnd() {
  if (!_cancelHold) return;
  clearTimeout(_cancelHold.timer);
  _cancelHold.card.classList.remove('is-cancelling');
  _cancelHold.card.style.removeProperty('--cancel-hold');
  if (_cancelHold.line) _cancelHold.line.textContent = _cancelHold.was;
  _cancelHold = null;
}

/* ── REVIEWING A SUBMISSION ──────────────────────────────────────────────── */
function toggleSubReview(pid) {
  state.subReview = state.subReview || {};
  if (state.subReview[pid]) delete state.subReview[pid]; else state.subReview[pid] = true;
  renderDashboard();
}

/* Opens the step the normal way and marks the modal read-only for the length
   of that visit. The flag is per-platform rather than global: two cards can be
   in different phases, and only a SUBMITTED one locks its steps. */
function openSubmittedStep(pid, stepId) {
  state.stepModalReadOnly = pid;
  openStepModal(pid, stepId);
}

/* The on-screen dev bar that used to live here is GONE — the whole block, its
   `.sm-devbar` rules in style.css and the call at the top of `renderDashboard`.
   It was a fixed bar switching the submitted card's shape and phase, built for
   reviewing in a preview pane with no console, and it was always going to be
   deleted rather than hidden: a comparison control left on screen is how one
   quietly becomes part of the app. Everything it did is still reachable from a
   real console, through `smReviewVariant` and `smCardState` below. */

/* DEV: the two shapes being compared for the in-review card.
     smReviewVariant(1)  four segments + the store's wait claim
     smReviewVariant(2)  no segments, the two dates instead */
function smReviewVariant(n) {
  state.subVariant = n === 2 ? 2 : 1;
  renderDashboard();
  return 'variant ' + state.subVariant;
}

/* The button each phase's own store puts in front of you. It only moves the
   prototype forward one phase; there is no real store on the other end. */
function smAdvancePhase(pid) {
  const cur  = state.platformFlipped?.[pid]?.phase || 'in_review';
  const next = cur === 'accepted' ? 'live' : cur === 'rejected' ? 'in_review' : 'accepted';
  state.platformFlipped[pid] = { ...state.platformFlipped[pid], phase: next };
  renderDashboard();
}

function smFakeStoreInsights(on = true) {
  if (!on) { state.storePageInsights = null; reRenderStepModal(); return; }
  state.storePageInsights = {
    grade: 'B',
    issues: [
      { field: 'subtitle', issue: 'Subtitle repeats the title',
        suggestion: 'Say what the player DOES, not what the game is called.',
        fixedValue: 'Build a colony, survive the winter' },
      { field: 'description', issue: 'Opening line buries the hook',
        suggestion: 'Lead with the fantasy, not the genre.',
        fixedValue: 'You are the last engineer on a dying station — keep it breathing until dawn.' },
      { field: 'title', issue: 'Title is missing a searchable keyword',
        suggestion: 'Players look for the genre by name.',
        fixedValue: 'Frostline: Colony Survival' },
    ],
  };
  /* OVERWRITE, don't `||`. The card's error state is `spi?.error || ana?.error`,
     so leaving the failed analysis in place kept "Analysis failed" on screen
     over a perfectly good set of suggestions. */
  state.improveSubmissionAnalysis = { grade: 'B' };
  reRenderStepModal();
}

/* ── Step modal: the body dissolves instead of being cut by a line ─────────
   The header's and footer's 1px borders are gone; in their place the scroller
   fades into the panel at both ends. A fade is only honest while there IS more
   content that way, so both are gated: the top one hides at the top, the bottom
   one at the bottom, and BOTH hide when the body does not scroll at all —
   otherwise a short step would sit under a permanent shadow with nothing behind
   it. That "not scrollable" case is why the class is set to true rather than
   left alone: the wrapper ships with both classes on, so the first paint of a
   short body never flashes a fade.

   The 2px slack in each comparison is for fractional scroll heights — a body at
   999.4 of 1000 never satisfies a strict equality and the bottom fade would
   never clear. Re-armed after every render (renderStepModal). */
/* THE PINNED NAV'S "WE DID IT" — a MOMENT plus a state, and they are two
   different mechanisms on purpose.

   The state is `.spp-pinned-bar.is-complete`, derived in `_sppPinnedNav`
   (render.js) from the sections themselves, so it is exactly as true as they
   are. It shows as a quiet green EDGE, not a green fill: the pills' resting
   contrast was tuned against the container's white 15%, and tinting that fill
   green would pull the ground out from under all eight of them. `.submit-ready`
   and the cancel hold already say a state this way — the border carries it —
   which makes this one idea in three places rather than a third invention.

   The moment is `.is-celebrating`, and it CANNOT be derived, which is the whole
   reason this function exists. A render knows "everything is done"; it cannot
   tell that from "you re-opened a step that was already done", and a bar that
   sweeps green every time you open the modal is a bar whose sweep means
   nothing. So the flank is detected here, after the paint, against what was
   last seen — the same shape `_impPostRender` uses to tell a grade that ROSE
   from a grade that was merely redrawn, down to the `undefined` guard that
   stops the very first paint from counting as a rise. Someone who opens a
   finished step gets the green edge and no sweep, which is correct: they did
   not just do anything.

   Keyed by platform, because two previews can be open across a session and
   finishing Mac must not spend Steam's celebration. */
const _sppLastComplete = {};
function _sppCelebrate() {
  const bar = document.querySelector('.spp-pinned-bar');
  if (!bar) return;
  /* The pid is read off the row's own handler rather than threaded through four
     callers — the pills already name it, and one source beats a parameter that
     can be passed wrong. */
  const pid = document.querySelector('.spp-pin')?.getAttribute('onclick')?.match(/'([^']+)'/)?.[1];
  if (!pid) return;
  const now  = bar.classList.contains('is-complete');
  const prev = _sppLastComplete[pid];
  _sppLastComplete[pid] = now;
  if (prev === undefined || !now || prev) return;   // first paint, not done, or already was
  if (window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) return;
  /* Stripped on `animationend` so the class is only ever on during the sweep —
     left behind, the next render would inherit a finished animation and the
     element would be permanently mid-celebration. */
  bar.classList.add('is-celebrating');
  bar.addEventListener('animationend', () => bar.classList.remove('is-celebrating'), { once: true });
}

/* ── THE PINNED NAV SCROLLS SIDEWAYS, AND THAT COSTS TWO SMALL THINGS ─────
   Eight pills want 919px and the App Store preview's 680 modal gives the row
   603, so `overflow-x: auto` is the ordinary state rather than the backstop its
   own CSS note calls it. A strip with its scrollbar hidden — deliberately, since
   4px of bar under a row of pills reads as damage — then owes the reader the two
   things the bar would otherwise have said.

   ONE: WHICH ENDS HAVE MORE. `.is-more-l` / `.is-more-r` drive a mask on the row
   (see `.spp-pinned-row`), stated positively so a row that fits carries neither
   and is untouched. The 1px of slack is the same allowance `_macShotsArrows`
   takes: `scrollLeft` is fractional on a scaled pane and an exact comparison
   flickers across a smooth scroll.

   TWO: THE LIT PILL HAS TO BE ON SCREEN. `setStorePreviewFocus` re-renders, so
   the row is a fresh node at `scrollLeft: 0` — press Data privacy and the page
   travels correctly to a section whose own pill is 300px off the right-hand end.
   `_sppPinnedReveal` puts it back, and it is deliberately NOT centred: a nav is
   read as a sequence, so the cheapest correct move is the one that brings the
   pill just inside the edge it fell off and leaves the row alone when it is
   already visible. The 24 clears the mask's own fade, or the pill you were sent
   to arrives half dissolved.

   `behavior: 'smooth'` is allowed here against this file's standing preference
   for `_smScrollTo`, and the reason is the one that rule turns on: this is a
   single element with no nested scroller under it and no ambiguity about which
   box an engine would pick, which is the entire failure `_smScrollTo` exists to
   remove. Nothing to disagree about between two browsers.

   ARMED FROM `renderStepModal` (render.js) for `_smModalFades`'s own contract —
   the modal is rebuilt with innerHTML and the old row's listener goes with it —
   and a no-op on every other step, since it looks for the row and leaves. */
function _sppPinnedFades(row) {
  if (!row) return;
  const max = row.scrollWidth - row.clientWidth;
  row.classList.toggle('is-more-l', row.scrollLeft > 1);
  row.classList.toggle('is-more-r', row.scrollLeft < max - 1);
}

function _sppPinnedReveal(row) {
  const pill = row && row.querySelector('.spp-pin.is-on');
  if (!pill) return;
  const r = row.getBoundingClientRect(), p = pill.getBoundingClientRect();
  /* 24 = the mask's own fade width, so the pill lands clear of it rather than
     flush against an edge that is busy dissolving. */
  if (p.left   < r.left  + 24) row.scrollBy({ left: p.left - r.left - 24,   behavior: 'smooth' });
  else if (p.right > r.right - 24) row.scrollBy({ left: p.right - r.right + 24, behavior: 'smooth' });
}

function _sppPinnedArm() {
  const row = document.querySelector('.spp-pinned-row');
  if (!row) return;
  _sppPinnedFades(row);
  _sppPinnedReveal(row);
  row.addEventListener('scroll', () => _sppPinnedFades(row), { passive: true });
}

/* ── TWO CONFIRMATIONS, AND THEY ANSWER DIFFERENT QUESTIONS ──────────────
   Both are Jaco's, lifted from the questionnaire prototype:
   1. *"nice animation of glimmering green on input text once I leave the field
      (as a confirmation, at least the first time I do)"*
   2. *"nice animation when I come back from a flipped modal and some
      information is put in place (content age rating or data privacy) —
      there's a little animation that's kinda celebratory"*

   THE SPLIT BETWEEN THEM IS NOT DECORATIVE, it is what stops them being two
   marks for one fact. A text field you type in place confirms ITSELF: you are
   looking at the words, and the sweep says "that is now saved". An element you
   set SOMEWHERE ELSE has the opposite problem — you were on another screen when
   it changed, so when the page comes back there is no reason to look at the one
   box that is different. One confirms; the other locates. So the sweep is for
   the three text fields and the pop is for the four that open a step, and no
   element can ever get both. */

/* ── 1. THE COMMIT SWEEP ─────────────────────────────────────────────────
   `.flash-char` + `charToOwn`, the prototype's own: each letter starts green
   and fades to its real colour on a left-to-right stagger.

   IT IS AN OVERLAY OVER THE INPUT, AND THE FIRST VERSION WAS NOT. Painting the
   DISPLAY element after the commit is the obvious shape — by then the field is
   a plain box again and can host per-char spans, which costs no cloned metrics
   at all — and it does not work, for a reason worth keeping: **the render that
   turns the editor back into a display element is DEFERRED, and can be deferred
   indefinitely.** `_stepModalInteractionActive` vetoes a rebuild while any
   inline editor holds focus, so the single most ordinary gesture here — leaving
   Title by clicking straight into Subtitle — commits Title and then renders
   nothing until Subtitle is done too. Measured: the title committed, the title
   element still held its editor, and zero `.flash-char` were ever created. A
   confirmation that waits for an unrelated event is not a confirmation.

   So it is the reference's own approach: a `position: fixed` box, pixel-matched
   to the input, carrying the text as spans for ~600ms and removing itself. It
   is tied to nothing — not to a render, not to the element surviving, not to
   what the user does next — which is exactly the property the queued version
   lacked. The cost, knowingly: the metrics are copied, so a field whose padding
   or font changes needs this checked. That is why it copies rather than
   guesses — every value comes off `getComputedStyle` of the real input. */
/* ── THE OVERLAY HAS TO BE THE ONLY TEXT ON SCREEN (v7.08) ───────────────
   Jaco: *"cuando busco distintos juegos sin avanzar a la siguiente pantalla,
   algunos caracteres de la descripción se superponen."*

   THE FIELD'S BACKGROUND IS TRANSLUCENT AND THE OVERLAY COPIES IT. `--inp-bg`
   is `rgba(102, 97, 122, .16)`, so `background: s.backgroundColor` below paints
   a 16% wash and the real textarea goes on showing straight through it. For the
   whole life of this function that was invisible and therefore harmless: both
   layers carried the SAME string, pixel-matched, so the double paint read as
   one. It stops being the same string the moment a SECOND fetch lands — pick
   another game from the picklist and `_fillDescriptionField` writes B into the
   field while an overlay still holding A is pinned on top of it. Two different
   paragraphs, one box: the letters interleave. That is the report, and it is
   why it only shows up when you search again without advancing.

   The fix is at both ends of that one fact.

   1. ONE SWEEP AT A TIME, AND THE GUARD CANNOT LIVE ON THE NODE.
      `input._masGlimmering` was the only re-entry test and it is a property of
      the ELEMENT, so any render that swaps the textarea for a fresh one — and a
      picklist selection reaches several — hands the next call a node with a
      clean flag while the previous overlay is still in `document.body` on its
      own timer. The registry below is global for exactly that reason: starting
      a sweep tears down every live one first, so an overlay can never outlive
      the value it was drawn for, whether or not its input survived the render.
      The same-node case keeps its cheap early return (blur and click both fire)
      but now compares the VALUE, because a refill into a surviving node is a
      new fact to confirm, not a duplicate call to ignore.

   2. WHILE THE OVERLAY IS UP, THE FIELD UNDER IT IS COLOURLESS. Compositing an
      opaque backdrop instead would mean resolving whatever sits behind a
      translucent field, which is a guess that breaks the next time a pane
      changes colour. Hiding the text that should not be visible says the same
      thing directly, and it restores through the single cleanup path, so a
      cancelled sweep and a completed sweep both put it back.

   AND IT DIES ON SCROLL OR RESIZE. The box is `position: fixed`, pinned to a
   rect measured once; a field that moves under it is the same superposition
   arriving by a different road. */
const _masGlimmerLive = new Set();
function _masGlimmerCancelAll() {
  for (const end of Array.from(_masGlimmerLive)) end();
}

function _masCommitGlimmer(input) {
  if (!input) return;
  const val = input.value;
  if (!val || !val.trim()) return;                  // nothing committed to confirm
  if (window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) return;
  // Blur and click can both fire for the same commit — but only while the text
  // is still the text that sweep was drawn for.
  if (input._masGlimmering && input._masGlimmerVal === val) return;
  _masGlimmerCancelAll();

  /* A PELÍN FASTER (v7.09). Jaco: *"que el barrido sea un pelín más rápido para
     que no sea agobiante la espera."* The pair below used to be 280 + 80 a line
     capped at 900, which on the description's eight visible lines came to 840,
     and 840 + 320 of fade is a beat over a second spent watching a field you
     have already read. The shape is untouched — still one line's crossing plus
     a slower wave for each further VISIBLE line — only the numbers: 660 at
     eight lines against 840, and a single-line field 240 against 280. */
  const FADE = 260;
  const px = v => parseFloat(v) || 0;
  const r = input.getBoundingClientRect();
  /* A FIELD WITH NO BOX CANNOT BE CONFIRMED. The overlay is pinned to the
     input's rect, so on a field that is rendered but not shown — Game Details
     draws all four sub-tabs and CSS reveals one — that rect is 0×0 and this
     would paint a zero-size box at the top-left of the window. Only reachable
     since v6.75 gave this function a second caller that fires from a fetch
     rather than from a gesture: a blur only happens on something you can see.
     `state` already carries the value, so the sub-tab draws it filled in when
     you arrive; there is simply nothing to sweep. */
  if (r.width < 1 || r.height < 1) return;
  input._masGlimmering = true;
  input._masGlimmerVal = val;
  const s = getComputedStyle(input);
  const isArea = input.tagName === 'TEXTAREA';
  /* The overlay renders from the top, so a textarea scrolled down would sweep
     text that is not where the user left it. Pinning the real field to the top
     first means the two agree. */
  input.scrollTop = 0;

  /* THE SCROLLBAR IS PART OF THE BOX AND NOT PART OF THE TEXT COLUMN (v7.09).
     Jaco: *"hay un redibujado con la animación de verde, que hace que se mueva
     un salto de línea, puedes revisarlo para que no cambie nada de sitio."*

     The overlay was sized from `getBoundingClientRect().width` — the BORDER
     box — while a description long enough to be worth sweeping is long enough
     to overflow, so the textarea under it is showing a vertical scrollbar and
     its text column is that much narrower. Measured on this field's own
     metrics: 633 against 627, a six-pixel gutter. Six pixels is a whole word
     at the end of some line, so the overlay wrapped one word earlier or later
     than the field and the paragraph visibly re-flowed at the moment it was
     supposed to be reassuring.

     `clientWidth` is the width INSIDE the border and INSIDE the scrollbar, so
     adding the two borders back gives a border box whose content column is the
     field's exactly. It is derived rather than a constant on purpose: where the
     scrollbar is an overlay one and takes no space — Safari's default, which is
     where this is actually used — the gutter is 0 and this changes nothing. */
  const fx = document.createElement('div');
  fx.setAttribute('aria-hidden', 'true');
  Object.assign(fx.style, {
    position: 'fixed', left: r.left + 'px', top: r.top + 'px',
    width: (input.clientWidth + px(s.borderLeftWidth) + px(s.borderRightWidth)) + 'px',
    height: r.height + 'px', margin: '0',
    boxSizing: 'border-box',
    paddingTop: s.paddingTop, paddingRight: s.paddingRight,
    paddingBottom: s.paddingBottom, paddingLeft: s.paddingLeft,
    borderWidth: s.borderTopWidth, borderStyle: 'solid', borderColor: 'transparent',
    borderRadius: s.borderRadius,
    fontFamily: s.fontFamily, fontSize: s.fontSize, fontWeight: s.fontWeight,
    fontStyle: s.fontStyle, letterSpacing: s.letterSpacing, textAlign: s.textAlign,
    /* A single-line input centres its text in the box no matter what its
       line-height says, so the overlay has to be told the box's own height
       instead; a textarea really does lay out on its line-height. */
    lineHeight: isArea ? s.lineHeight
      : (r.height - px(s.borderTopWidth) - px(s.borderBottomWidth)
         - px(s.paddingTop) - px(s.paddingBottom)) + 'px',
    color: s.color, background: s.backgroundColor,
    /* `overflow-wrap` is copied for the same reason the description's own rule
       states it: the UA gives a textarea `break-word` and a div `normal`, and
       an overlay that wraps differently from the field under it is a paragraph
       that jumps at the moment it is meant to reassure. */
    whiteSpace: isArea ? 'pre-wrap' : 'pre',
    overflowWrap: s.overflowWrap, wordBreak: s.wordBreak,
    overflow: 'hidden', pointerEvents: 'none', zIndex: '9999',
  });

  /* THE STAGGER IS SPREAD OVER WHAT YOU CAN SEE, NOT OVER THE STRING (v6.76).
     Jaco: *"el description field da como un flashazo"*, and *"el glimmer debería
     ser más lento porque solo debería ser percibido en la parte que es visible,
     los 175px del input field, aunque la descripción sea mucho más larga."*

     Both halves are one bug and the arithmetic says so. The delay was
     `i / (n − 1) × SWEEP` over the WHOLE value, so on a 1500-character store
     blurb in a box that shows ~300 of them the visible band was crossed in
     `280 × 300/1500` = **56ms** and the remaining 224 were spent sweeping text
     that is scrolled out of sight. 56ms across eight lines is not a wave, it is
     a flash — and it is the same flash however long the description is, getting
     worse the more there is to celebrate. **A sweep is a fact about the VIEWPORT,
     not about the value.**

     So the spans are laid down first and the rate is solved from the last one
     that FITS: `offsetTop` past the content box is where the eye stops, and
     everything after it keeps the same per-character rate rather than a second
     one — off screen it costs nothing and it means there is one number, not a
     visible run and a hidden run that disagree.

     They get `.flash-char` only in that second pass. Pausing them and restarting
     with a delay is the obvious shape and is exactly the per-engine behaviour
     this file refuses: adding the class is what starts the animation, so the
     delay is read once, at the start, by every browser.

     AND THE SWEEP IS PER LINE, WHICH IS WHAT MAKES IT SLOWER HERE AND NOT
     ELSEWHERE. 280 is one line's crossing — the Assets found line, and every
     single-line field on the Mac preview, are unchanged by construction. A
     paragraph is a wave travelling down as well as across, so each further
     visible line adds 80, capped at 900: measured, the description's 175px shows
     ~8 lines, which is 840. */
  const chars = Array.from(val), spans = [];
  chars.forEach(ch => {
    if (ch === '\n') { fx.appendChild(document.createElement('br')); return; }
    const sp = document.createElement('span');
    sp.textContent = ch;
    fx.appendChild(sp);
    spans.push(sp);
  });
  document.body.appendChild(fx);
  /* The overlay is now the text. Inline so it wins over the stylesheet, and
     remembered rather than assumed, so the restore is a restore. */
  const prevColor = input.style.color;
  input.style.color = 'transparent';

  const padT = px(s.paddingTop), bT = px(s.borderTopWidth);
  const contentH = r.height - bT - px(s.borderBottomWidth) - padT - px(s.paddingBottom);
  const lineH = (isArea && px(s.lineHeight)) || contentH || 1;
  let vis = spans.length;
  for (let i = 0; i < spans.length; i++) {
    if (spans[i].offsetTop - bT - padT >= contentH) { vis = i; break; }
  }
  const lines = Math.max(1, Math.round(contentH / lineH));
  const SWEEP = Math.min(720, 240 + 60 * (lines - 1));
  const rate = SWEEP / Math.max(1, vis - 1);
  spans.forEach((sp, i) => {
    sp.style.animationDelay = Math.round(i * rate) + 'ms';
    sp.classList.add('flash-char');
  });
  /* ONE EXIT, WHOEVER CALLS IT. The timer, a newer sweep, a scroll, a resize
     and the user typing all end the same way — remove the box, give the field
     its colour back, drop out of the registry — because every one of them
     leaves the overlay lying about the value underneath it. `ended` makes it
     idempotent: the timer fires after a cancel and must find nothing to do. */
  let ended = false;
  const end = () => {
    if (ended) return;
    ended = true;
    clearTimeout(timer);
    _masGlimmerLive.delete(end);
    window.removeEventListener('scroll', end, true);
    window.removeEventListener('resize', end);
    input.removeEventListener('input', end);
    fx.remove();
    input.style.color = prevColor;
    input._masGlimmering = false;
    input._masGlimmerVal = null;
  };
  const timer = setTimeout(end, SWEEP + FADE + 80);
  _masGlimmerLive.add(end);
  // Capture phase: the field scrolls inside a pane, not the window.
  window.addEventListener('scroll', end, true);
  window.addEventListener('resize', end);
  input.addEventListener('input', end);
}

/* ── 2. THE RETURN POP ───────────────────────────────────────────────────
   `.spp-just-changed`, the prototype's `storeJustChanged`: the element that
   just gained a value lifts 3% with a green ring while a 9999px shadow dims
   everything around it, then eases back.

   IT IS THE SAME FLANK TEST AS `_sppCelebrate` ABOVE, one level finer. That one
   asks "did the WHOLE bar just complete"; this asks "did THIS element just fill
   in", per target, against what was last seen. The `undefined` guard is the
   same and does the same job: opening a step that was already answered is not
   an event, so a first paint never pops.

   ONLY THE FOUR THAT OPEN A STEP. Title, subtitle and description are excluded
   by construction — they get the sweep above, and an element that both swept
   and popped would be saying one thing twice in two vocabularies. Achievements
   is excluded too: it is permanently done, so it can never have a flank, and a
   test that can only ever be false is a line to delete rather than write.

   THE DIM IS PART OF THE ELEMENT'S OWN SHADOW, not a separate scrim, which is
   what makes it free: no overlay node to insert, position, and remove, and
   nothing that can be left behind if a render lands mid-animation. It is
   clipped by `.ias-page`'s own `overflow: hidden`, so it darkens the store page
   and stops at its edge instead of covering the modal. */
const SPP_POP_TARGETS = ['content', 'business', 'data', 'screenshots'];
const _sppLastFilled = {};
function _sppJustChanged() {
  const page = document.querySelector('.mac-spp-page');
  if (!page) return;
  const pid = document.querySelector('.spp-pin')?.getAttribute('onclick')?.match(/'([^']+)'/)?.[1];
  if (!pid) return;
  const seen = _sppLastFilled[pid] || (_sppLastFilled[pid] = {});
  const reduce = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;

  SPP_POP_TARGETS.forEach(id => {
    const el = page.querySelector(`[data-spp-el="${id}"]`);
    if (!el) return;
    /* "Filled" is read off the page rather than out of the state, so this
       cannot disagree with what is actually drawn — the same reason
       `_sppCelebrate` reads the bar's own class instead of recomputing it.
       Each target says so in its own way and all four already did before this
       function existed: an answered cell wears `--seen`, privacy swaps element
       for `.ias-privacy-block` without `--ask`, screenshots take
       `is-shots-done`, and Business stops saying "Set price". */
    let filled;
    if (id === 'content')          filled = el.classList.contains('ias-meta-cell--seen');
    else if (id === 'data')        filled = !el.classList.contains('ias-privacy-block--ask');
    else if (id === 'screenshots') filled = !!el.closest('.spp-shots-row.is-shots-done');
    else                           filled = el.textContent.trim() !== 'Set price';

    const prev = seen[id];
    seen[id] = filled;
    if (prev === undefined || !filled || prev || reduce) return;

    /* The cell's mark is its `::after` well, so the pop has to land on the box
       that PAINTS — on Content the cell itself draws nothing. Every other
       target is its own painted box. */
    const mark = id === 'screenshots' ? el.closest('.spp-shots-row') : el;
    mark.classList.add('spp-just-changed');
    mark.addEventListener('animationend',
      () => mark.classList.remove('spp-just-changed'), { once: true });
  });
}

function _smModalFades() {
  const wrap = document.getElementById('step-modal-body-wrap');
  const body = document.getElementById('step-modal-body');
  if (!wrap || !body) return;
  /* `instant` is for the first update after a render, and it is not a nicety.
     The fresh markup ships with both classes on (so nothing flashes on a short
     body), which means the fades start at opacity 0 — and measuring the
     scroller here resolves that 0 as a real starting value, so restoring the
     bottom fade animates it in. Every answered question re-renders the modal,
     so the fade pulsed on every single click. Suppressing the transition for
     that one application makes a re-render look like no change at all, which
     is what it is: the scroll position never moved. */
  const update = (instant) => {
    /* A TALLER CONTENT IS NOT A SCROLLER. The Mac Product Page Preview hands
       its scrolling to .mac-spp-main and leaves this element `overflow:hidden`
       with content still taller than its box — read as scrollable, it pinned
       the bottom fade on permanently and washed out the footer nav underneath.
       So the overflow is asked first, and only then the heights. */
    const ov = getComputedStyle(body).overflowY;
    const scrollable = (ov === 'auto' || ov === 'scroll') &&
                       body.scrollHeight > body.clientHeight + 2;

    /* AND THE PRIVACY STEP PUT A SECOND SCROLLER *INSIDE* THE BODY (v6.55).
       The data-types table scrolls within itself so the preset chips stay put,
       which means the body itself never overflows — so every test above says
       "not scrollable", both fades sit at 0, and the table is guillotined on the
       modal's bottom edge with nothing to say there is more.

       ONE FADE, NOT A SECOND SET. It belongs to the modal and spans the whole
       body, which is exactly where the cut is; giving `.pvt-scroll` its own
       would be a second boundary a few pixels inside the first. So the fades ask
       whoever is really scrolling: the body when it scrolls, and otherwise the
       inner one. Generalised past `#pvt-scroll` on purpose — `[data-inner-scroll]`
       means any step can hand its scrolling downwards later without editing this
       function, which is the same contract `.mac-spp-main` gets below. */
    const inner = body.querySelector('[data-inner-scroll]');
    const innerScrolls = inner && inner.scrollHeight > inner.clientHeight + 2;
    const src = scrollable ? body : (innerScrolls ? inner : null);

    /* An inner scroller draws its OWN top fade, hanging off whatever sticky
       header it has — the modal's fades are about the modal's body and cannot
       reach inside one. Stated positively (`is-scrolled`) so the resting state
       at the top needs no class at all and a fresh render never flashes one. */
    if (inner) inner.classList.toggle('is-scrolled', innerScrolls && inner.scrollTop > 2);

    if (instant) wrap.classList.add('no-fade-anim');
    wrap.classList.toggle('at-top',    !src || src.scrollTop <= 2);
    wrap.classList.toggle('at-bottom', !src ||
      src.scrollTop + src.clientHeight >= src.scrollHeight - 2);
    // The inner scroller is rebuilt with the modal, so its listener goes with
    // it — re-armed here, the way the body's own is.
    if (inner && !inner._smFadeBound) {
      inner._smFadeBound = true;
      inner.addEventListener('scroll', () => update(false), { passive: true });
    }
    if (instant) {
      void wrap.offsetWidth;                 // commit the new opacities untransitioned
      requestAnimationFrame(() => wrap.classList.remove('no-fade-anim'));
    }
  };
  body.addEventListener('scroll', () => update(false), { passive: true });
  update(true);

  /* THE MAC PREVIEW HAS A SECOND SCROLLER, AND IT GETS ARMED HERE FOR THE SAME
     REASON THE FIRST ONE DOES. `.mac-spp-main` is where that step actually
     scrolls (this modal's own body is `overflow: hidden` there — see the note
     above), so its top fade needs the same treatment: re-armed after EVERY
     render, because the modal is rebuilt with innerHTML and the previous
     scroller's listener goes with it.
     TWO CLASSES, ONE PER END — and this note used to say one, on the claim that
     "the page ends in the footer's own space and nothing is cut there". That was
     asserted, not measured, and measuring it proved it false: 464px still below
     the fold, a section sitting hard on the scrollport's bottom edge, and 12px
     between that edge and the footer. So the bottom gets the mirrored fade.

     BOTH ARE STATED POSITIVELY (`is-scrolled` / `is-scrollable-down`) rather
     than as `at-top` / `at-bottom`, so the resting state at each end needs no
     class at all — which is what stops a freshly rendered scroller from flashing
     a fade for one frame before this runs. Each one is only on while there is
     really content that way: a fade with nothing behind it is a shadow claiming
     content that is not there. */
  const spp = document.querySelector('.mac-spp-main');
  if (spp) {
    const sppUpdate = () => {
      spp.classList.toggle('is-scrolled', spp.scrollTop > 2);
      spp.classList.toggle('is-scrollable-down',
        spp.scrollTop + spp.clientHeight < spp.scrollHeight - 2);
    };
    spp.addEventListener('scroll', sppUpdate, { passive: true });
    sppUpdate();
  }
}

function _smSpotlight(card, targets, ms) {
  if (!card || !targets || !targets.length) return;
  if (window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) return;

  clearTimeout(_spotTimer);
  if (_spotHost && _spotHost !== card) {
    _spotHost.classList.remove('is-spotlight');
    _spotHost.querySelectorAll('.is-spotlit').forEach(el => el.classList.remove('is-spotlit'));
  }
  card.querySelectorAll('.is-spotlit').forEach(el => el.classList.remove('is-spotlit'));
  targets.forEach(el => el && el.classList.add('is-spotlit'));
  card.classList.add('is-spotlight');
  _spotHost = card;

  _spotTimer = setTimeout(() => {
    card.classList.remove('is-spotlight');
    /* Clear the marks only after the fade back, or the last thing you see is
       the spotlit rows dropping to the dim level for a frame before everything
       comes up together. */
    setTimeout(() => card.querySelectorAll('.is-spotlit')
      .forEach(el => el.classList.remove('is-spotlit')), 260);
  }, ms || 1100);
}

/* THE PINNED NAV SPOTLIGHTS WHERE IT LANDED YOU, and it is the platform card's
   own mechanism rather than a second one — `_smSpotlight` above, with the Mac
   preview's shell standing in for the card.

   Why this surface earns it: the pills are a MAP of eight sections and a press
   can move you past six of them. Arriving somewhere you did not travel through
   leaves you looking for the thing you asked for, and the page's own "needs
   attention" glow cannot answer that — it marks what is unfinished, which is a
   different question from where you just landed. Dimming everything else says
   "here" in the one register the page was not already using.

   THE DIM STARTS WITH THE TRAVEL, NOT ON ARRIVAL. It is what carries the eye
   across the scroll; lit on arrival it would read as a second event happening
   to you after the first.

   SO THE DURATION IS THE TRAVEL PLUS A BEAT, AND BOTH HALVES ARE NOW KNOWN.
   It was 1600 — 515ms, the longest travel the browser's own smooth scroll
   happened to take, plus the card's 1100 — and that was a guess wearing a
   measurement's clothes, because the browser's duration was never ours to
   know. `_smScrollCentre` fixed the travel at 420, so this is simply
   `420 + 480`: the trip, then under half a second of "here it is". **900.**
   A locator has to get out of the way faster than the card's 1100, which is
   explaining a prerequisite and can afford to wait; asked twice to be quieter,
   this is the half of it that is time rather than light.

   AND IT DOES NOT LOCK THE POINTER, where the card's spotlight does. That one
   is explaining a PREREQUISITE — a dimmed row that still opens its step invites
   you to act on the thing being de-emphasised. This one is a locator, and you
   are free to go anywhere; freezing the page for 1.6s because you pressed a
   navigation pill would punish the gesture. The pills themselves stay live and
   undimmed for the same reason: they sit outside the shell, so the class cannot
   reach them, and a navigator that greys itself out after one press reads as
   refusing the next one.

   iOS keeps the footer stepper and gets none of this on purpose: PREV / NEXT
   moves you exactly one section, so you already know where you arrived. */
/* ONE HOST CLASS, TWO PREVIEWS. This looked for `.mac-spp-shell` by name, so
   the locator existed on exactly one of the two Apple previews — the App Store
   had the same eight-pill nav, the same press, the same long travel, and
   nothing to say "here" when you arrived. `spp-spot-host` is carried by
   Mac's shell and by the App Store's own `.ias-device-wrap` (render.js), which
   is the same box on that surface: it holds the page and nothing else. */
function _sppSpotlight(target) {
  const host = target && target.closest('.spp-spot-host');
  if (!host) return;
  _smSpotlight(host, [target], 900);
}

/* THE SUBMIT ROW'S ONE HANDLER. Every press of the row lands here, whether or
   not it is allowed to submit, because a control that silently ignores you is
   the worst answer available — the user cannot tell a locked button from a
   broken one.
   The order is the order a person would hit the walls in: you cannot submit
   without an account, you cannot submit with steps outstanding, and you cannot
   submit without saying where it goes. Each one points at the thing that fixes
   it rather than describing it. */
function submitStepClick(pid) {
  const isWeb     = pid === 'web';
  /* Through platformAccountReady (state.js) rather than repeating the web
     exemption here: that helper is now also what the card's green border and
     the Submit row's lock read, so this gate and those two cannot disagree
     about whether an account is still owed. */
  const connected = platformAccountReady(pid);
  const card      = document.getElementById('active-card-' + pid);

  /* 1 — no account linked. The gear is where linking happens, so the gear
     answers: it shakes, and a tooltip over it says what the shake is about.
     The two together are the point — motion alone tells you WHERE to look but
     not what for, and a tooltip alone is easy to miss when your eye is on the
     row you just pressed at the other end of the card. */
  if (!connected) {
    /* THE GEAR MOVED TO THE TAB, so the shake follows it there. It is still the
       same answer — point at where linking happens rather than withhold the
       click — but the gear is no longer inside `card`, and a querySelector that
       quietly returns null would have turned this gate back into the dead
       control it was written to replace. Falls back to the card's own gear,
       which is where a submitted card still keeps one. */
    const gear = document.querySelector(`#sub-tab-${pid} .active-card-settings`)
              || card?.querySelector('.active-card-settings');
    _smShake(gear, 'pulse');
    window.smTipAt?.(gear, t('card.connect_account') || 'Connect account');
    return false;
  }

  /* 2 — steps outstanding. Shake the ones that are actually outstanding, which
     is read off the DOM rather than recomputed: `is-complete` on the row is
     what _paintStepRow() maintains, so this cannot disagree with what the user
     is looking at. The submit row excludes itself — it is the thing being
     pressed, not a thing in the way. */
  const pending = [...(card?.querySelectorAll('.ios-step-card:not(.is-complete)') || [])]
    .filter(row => !row.classList.contains('submit-step-card'));
  if (pending.length) {
    _smSpotlight(card, pending);
    return false;
  }

  /* 3 — no destination yet. The picker is the `.submit-track-pick` chip on the
     release block's first row (shape 4), so this spotlights UP the card rather
     than at this row. That is the cost of the move and it is paid knowingly:
     the block is the card's second element, always on screen, and the
     spotlight dims everything else to .18 — `.card-release-block:not(:has(
     .is-spotlit))` in style.css is what lets the block stay lit when the lit
     thing is inside it. The selector below is unchanged because the chip kept
     its class when it moved; if it is ever renamed, rename it here too.
     Nothing is preselected, here or anywhere — the destination is a decision,
     and a silent default would make it on your behalf. */
  if (!isWeb && !(state.selectedTracks || {})[pid]) {
    /* THE CHIP CAN NOW BE FOLDED AWAY, which shape 4 never had to consider.
       The release block came down into Upload Build's body when the steps went
       inline, so the picker this gate spotlights is only in the DOM while that
       section is expanded — and a spotlight on nothing is exactly the dead
       press this gate exists to prevent. So it opens the section first and
       spotlights on the next frame, once the chip is really there. Uncollapsed
       already, it behaves as it always did. */
    const spotlightChip = () => {
      const c = document.getElementById('active-card-' + pid);
      const chip = c?.querySelector('.submit-track-pick');
      if (!chip) return;
      _smSpotlight(c, [chip]);
      _smShake?.(chip, 'nudge');
    };
    /* **ASK THE DOM WHETHER THE CHIP IS THERE, NOT THE STATE WHETHER A SECTION
       IS OPEN.** The test above was `openStep[pid] !== 'uploadBuild'` — a fact
       about the PANE, where the picker is inside a collapsible body. In the
       card grid the chip is in the release block and has been on screen since
       the build landed, so that test was true, and the branch called
       `toggleStepSection` — whose first line is `if (layout === 'modal') return
       openStepModal(...)`. Measured: pressing Submit with no track OPENED THE
       UPLOAD BUILD MODAL over the card and spotlighted nothing (`is-spotlight`
       absent, no `.is-spotlit`). The one press this gate exists to answer
       navigated somewhere instead.

       Third instance of one shape in this flag's life: a control re-pointed at
       the pane, still aimed there from the card. The fix is to stop asking
       which presentation this is — the chip either is in the document or it is
       not, and that is true in both arms without a flag. */
    if (card?.querySelector('.submit-track-pick')) {
      spotlightChip();
    } else {
      Promise.resolve(toggleStepSection(pid, 'uploadBuild'))
        .then(() => requestAnimationFrame(spotlightChip));
    }
    return false;
  }

  /* **IT NO LONGER SUBMITS — IT REPORTS (v6.62).** This function is the three
     gates and nothing else now, returning `true` when the press is clear and
     `false` when it has already answered with a shake or a spotlight. The act
     itself is `submitHoldStart` below, because Submit became a HOLD.

     Keeping the gates here rather than inlining them into the hold is the
     point: a refusal must happen on the press, instantly, whether or not you
     go on to hold — so the hold asks this first and simply does not start. */
  return true;
}

/* ── SUBMITTING IS A HOLD, AND THE FILL IS WHAT YOUR THUMB IS DOING ──────────
   Jaco: *"mantener pulsado el botón de submit ES LO QUE RELLENA el
   contenedor."* He is right, and it closes an asymmetry this file had been
   describing without noticing.

   **THE CARD ALREADY HAD THIS GESTURE, RUNNING THE OTHER WAY.** Cancelling is a
   hold: a red sweep crosses the card for exactly as long as the button is down,
   the status line says CANCELING SUBMISSION, and letting go is the undo. The
   note beside it argues the whole case — "holding makes the gesture and the
   consent the same act; there is no wrong button to land on". Every word of
   that is true of sending, which is the same size of decision pointing forward.

   The green fill has been called "the cancel hold run forward" since v6.39 and
   it was not: it was a 1100ms animation you started with a click and could not
   stop. So the card had a bar you could abandon for the reversible act and a
   bar you could not for the irreversible one — exactly backwards. It also meant
   the fill was measuring nothing. A bar that only reports elapsed time on a
   thing already decided is a loading screen; a bar tied to a thumb is a clock
   you are holding the hands of.

   **ONE NUMBER, AND IT IS THE CANCEL HOLD'S OWN.** `SM_SUBMIT_HOLD_MS` is
   `SM_CANCEL_HOLD_MS`, by reference rather than by a second literal — two
   directions of one gesture must take the same time or the card teaches two
   different "hold" lengths. This retires v6.61's argument for 1100 ("you are
   watching, not deciding"), which was correct about a click and is wrong about
   a hold: now you ARE deciding, and the duration has to be long enough to
   abandon.

   `--submit-fill` still carries it to the CSS from the same constant the timer
   uses, so the bar cannot finish early or late relative to the act — the rule
   the cancel sweep exists to demonstrate, now with two consumers each.

   Three things it has to get right, all of them the cancel hold's lessons:

   - **A refusal is not a hold.** The gates run on `pointerdown` and a `false`
     ends it there, so an unconnected account still shakes the gear and an
     outstanding step still spotlights — instantly, with no fill starting behind
     the refusal.
   - **Letting go anywhere cancels.** `pointerup`, `pointerleave` and
     `pointercancel` all end it, so sliding off the row mid-hold is an undo
     rather than a submission you cannot see the bar for.
   - **Only a completed hold changes anything.** An early release costs one
     class removal, one node removed and no render — `cancelHoldEnd`'s own rule,
     because nothing has happened yet.

   `prefers-reduced-motion` keeps the hold and drops only the fill: the gesture
   is the safety, not the animation, so removing the bar must not remove the
   second chance. */
let _submitHold = null;

function submitHoldStart(pid, row, ev) {
  if (ev && ev.button !== undefined && ev.button !== 0) return;  // primary press only
  submitHoldEnd();
  if (row?.classList.contains('is-complete')) return;

  if (submitStepClick(pid) !== true) return;   // a gate answered; no hold

  const card = document.getElementById('active-card-' + pid);
  if (!card) { confirmSubmit(pid); return; }

  const reduced = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;

  /* The word is the submitted card's own status line, borrowed rather than
     approximated — the v6.61 argument, unchanged.

     **IT GOES INSIDE THE STEP LIST, AND THAT IS WHAT KILLED THE ANCHOR BRANCH.**
     It used to be inserted in FLOW after `:scope > .card-release-block`, falling
     back to the header — two selectors because both layout arms exist and
     neither has the same children. Measured, that insertion pushed the Submit
     row 39.1px DOWN, out from under the thumb holding it (see the long note
     beside `.is-submitting` in style.css: on a hold that is not cosmetic, it
     cancels the gesture).

     Prepending into `.ios-step-cards` and positioning it absolutely solves both
     at once: the card cannot change size, and the list exists in every arm, so
     there is nothing to branch on. All the geometry is in CSS — no
     `getBoundingClientRect`, no arithmetic that could go stale. */
  const sending = document.createElement('div');
  sending.className = 'sub-state sub-state-sending';
  sending.innerHTML = '<span class="sub-state-line">SUBMITTING…</span>';
  const list = card.querySelector('.ios-step-cards');
  if (list) list.prepend(sending);
  else card.prepend(sending);

  if (!reduced) {
    card.style.setProperty('--submit-fill', SM_SUBMIT_HOLD_MS + 'ms');
    card.classList.add('is-submitting');
  }

  _submitHold = { pid, card, sending };
  _submitHold.timer = setTimeout(() => {
    const p = _submitHold?.pid;
    submitHoldEnd();
    if (p) confirmSubmit(p);
  }, SM_SUBMIT_HOLD_MS);
}

function submitHoldEnd() {
  if (!_submitHold) return;
  clearTimeout(_submitHold.timer);
  _submitHold.sending?.remove();
  _submitHold.card.classList.remove('is-submitting');
  _submitHold.card.style.removeProperty('--submit-fill');
  _submitHold = null;
}

/* Confirm and execute the submit from the inline step card */
function confirmSubmit(pid) {
  // Web has no release track — deploy directly.
  if (pid === 'web') { _doFinalSubmit('web', 'production'); return; }
  if (!state.selectedTracks) state.selectedTracks = {};
  const trackId = state.selectedTracks[pid] || null;
  if (!trackId) {
    // Pulse the dropdown AND show a brief inline message
    const sel = document.getElementById('track-sel-' + pid);
    if (sel) {
      sel.classList.add('pulse-error');
      setTimeout(() => sel.classList.remove('pulse-error'), 700);
    }
    // Show a temporary "Choose Track first" chip near the submit card
    const card = document.getElementById(`${pid}-step-card-submit`);
    if (card && !card.querySelector('.submit-track-err')) {
      const err = document.createElement('div');
      err.className = 'submit-track-err';
      err.textContent = 'Select a track before submitting';
      card.appendChild(err);
      setTimeout(() => err.remove(), 2500);
    }
    return;
  }
  _doFinalSubmit(pid, trackId);
}

function openTrackSubmitModal(platformId) {
  const tracks = PLATFORM_TRACKS[platformId];
  if (!tracks || !tracks.length) {
    // No tracks defined — submit straight to production
    _doFinalSubmit(platformId, 'production');
    return;
  }
  renderTrackSubmitModal(platformId);
  document.getElementById('submit-overlay').classList.remove('hidden');
  document.body.style.overflow = 'hidden';
}

// Called by the "Submit →" button inside the track-selection modal.
function _confirmTrackSubmit(platformId) {
  const radios = document.querySelectorAll(`input[name="track-sel-${platformId}"]`);
  let trackId = 'production';
  radios.forEach(r => { if (r.checked) trackId = r.value; });
  closeSubmitModal();
  _doFinalSubmit(platformId, trackId);
}

// Mints a ReleaseRecord and marks the submit step complete.
// Build numbers / version strings are always derived automatically — never typed.
function _doFinalSubmit(platformId, trackId) {
  const proj = state.projects.find(p => p.id === state.activeProjectId);
  const ver  = proj?.versions.find(v => v.id === state.activeVersionId);
  if (proj && ver) {
    if (!ver.platformReleases) ver.platformReleases = {};
    if (!ver.platformReleases[platformId]) ver.platformReleases[platformId] = [];
    const rel = makeReleaseRecord(proj, platformId, trackId, ver.versionNumber);
    ver.platformReleases[platformId].push(rel);
  }
  state.platformStepStatus[platformId]['submit'] = 'complete';

  /* SUBMITTING DOES NOT FLIP THE CARD — IT CLOSES IT. Read this before
     reaching for `rotateY` here again.

     The flip is already spoken for, and it means one specific thing: THE OTHER
     SIDE OF THIS CARD. The gear turns the card over to the account/connect
     face, the same gear turns it back, and nothing about the card has changed
     in between — it is a reversible look at the reverse of the same object.
     Submitting is not that. It is the card moving FORWARD into another state,
     one that costs a 1.4-second hold to undo. Turning something over to say it
     has advanced spends the "look at the back" gesture on a change of state,
     and the two then cannot be told apart.

     That overload had already produced a real bug, which is how it was caught:
     `_platformHeadActions` branched only on `steps` vs everything-else, so a
     submitted card fell into the ACCOUNT arm and its gear came out lit with the
     tooltip "Back to steps" — the card announcing itself as a reversible
     settings detour.

     So the motion is vertical now: the steps are gone and the box closes over
     the space they occupied, from the steps face's height to the submitted
     card's own. The header and the release block are IDENTICAL in both faces
     (see buildSubmittedCard), so they are deliberately left alone — nothing
     fades that did not change, and the eye reads one continuous object losing
     its list rather than two cards swapping places.

     `state.platformFlippedCardHeight` went with the rotation. It existed to pin
     the new card at the OLD card's height so the flip did not end in a jump,
     and it was written and deleted in four places while no render function ever
     read it. Here the height change is the animation; pinning it would be
     pinning the thing being animated. */
  if (!state.platformFlipped) state.platformFlipped = {};
  const card = document.getElementById('active-card-' + platformId);
  const flipData = { track: trackId, time: Date.now() };

  function _applyFlip() {
    // Lock the entire active-cards-grid height BEFORE re-rendering so the row
    // doesn't shift as the submitted card (shorter) replaces the active card.
    const grid = document.querySelector('.active-cards-grid');
    const gridHeight = grid ? grid.offsetHeight : 0;
    if (grid && gridHeight > 0) grid.style.minHeight = gridHeight + 'px';

    state.platformFlipped[platformId] = flipData;
    /* THE GUIDE TURNS INTO THE MONTH. Submitting answers the question the
       checklist was asking and replaces it with a different one — not "what is
       left to do" but "when do I hear back, and what do I do until then" — and
       the month is the surface that answers it. `_guideCalLede` prints the why
       at the top of it, so the face does not change under you unexplained.
       `monthOffset` goes to 0 because the wait starts today: the guide's face
       must never open on a month with no "today" in it, the same rule
       `toggleGuideCal` follows on the way in.
       Set ONCE, here, at the moment of the event — not derived from "is
       anything in review", which would keep dragging you back onto the
       calendar every time you closed it for the next three days. */
    state.guideCal = true;
    state.calendar.monthOffset = 0;
    renderDashboard();
    /* renderDashboard does NOT rebuild the guide column — they are two
       independent renders sharing one state — so the face change has to be
       asked for by name or it lands on the next unrelated repaint. */
    if (typeof renderGuide === 'function') renderGuide();

    const newCard = document.getElementById('active-card-' + platformId);
    if (newCard) {
      /* THE HEIGHT IS THE ANIMATION, so it has to be measured, not guessed:
         `offsetHeight` here is the submitted card's own natural height, taken
         before anything is pinned. Then the box is put back at the steps face's
         height and released to travel to it. `overflow: hidden` is what makes
         the close read as a close rather than as content spilling past a
         shrinking frame, and it goes away with everything else at the end —
         leaving it on would clip a card that later grows (opening "See what you
         sent" does exactly that). */
      const toH = newCard.offsetHeight;
      newCard.classList.add('is-advancing');
      newCard.style.overflow   = 'hidden';
      newCard.style.height     = (cardHeight || toH) + 'px';
      newCard.style.transition = 'none';
      // Double rAF ensures the starting height is painted before it is changed.
      requestAnimationFrame(() => requestAnimationFrame(() => {
        newCard.style.transition = 'height 0.42s cubic-bezier(0.22, 0.61, 0.36, 1)';
        newCard.style.height     = toH + 'px';
        setTimeout(() => {
          newCard.style.transition = '';
          newCard.style.height     = '';
          newCard.style.overflow   = '';
          newCard.classList.remove('is-advancing');
          if (grid) grid.style.minHeight = '';
        }, 440);
      }));
    } else {
      setTimeout(() => { if (grid) grid.style.minHeight = ''; }, 440);
    }
  }

  // Where the close STARTS: the steps face's height, measured while it is still
  // on screen. Nothing is stored — it is consumed by the animation and gone.
  const cardHeight = card ? card.offsetHeight : 0;

  /* No out-phase. There is nothing to animate away: the header and the release
     block survive the swap unchanged, and the steps are what the closing box is
     removing. A fade-out here would dim the two things that did not change.

     **AND THE FILL IS NOT HERE ANY MORE (v6.62).** It used to run at this point:
     press Submit, and a 1100ms green wash crossed the card with SUBMITTING… over
     it before the close. That whole block has moved into `submitHoldStart`,
     because the fill is now what your THUMB is doing — Submit is a hold, the bar
     measures the hold, and by the time this function is reached the bar has
     already finished and the decision is made. Running it again would be the
     card asking twice.

     What is left here is the state change and the close, which is what this
     function was before v6.39 and what it should have stayed: the beat that
     "gives the advance something to be the end of" belongs to the gesture, not
     to the commit. The whole argument is in `submitHoldStart` (app.js) and
     beside `.is-submitting` (style.css).

     One consequence worth stating: **the commit no longer depends on an
     animation finishing.** The old version's note had to explain at length why
     it used a `setTimeout` rather than `animationend` — a backgrounded tab or a
     changed motion preference would have left the card green forever with the
     submission never applied. There is no timer between the press and the state
     change at all now; the hold's own timer is the only clock, and it owns both
     the bar and the decision. Reduced motion never needed a branch here either,
     since the hold drops only the fill and keeps the gesture. */
  _applyFlip();
}

/* ── PRESSING SUBMIT FOR REAL, WITHOUT DOING THE WORK FOR REAL (v6.61) ───────
   `smReadyToShip('macos')` in the console, then press Submit on the card.

   **IT SATISFIES THE GATES, IT DOES NOT BYPASS THEM** — and that distinction is
   the whole reason this is worth having. `submitStepClick` refuses on three
   counts: no account linked, steps outstanding, no track chosen. A helper that
   jumped straight to `_doFinalSubmit` would test the animation and nothing
   else, leaving the three refusals — the shake, the spotlight, the chip nudge —
   unexercised in the one place they matter. This writes the same three pieces
   of state a real afternoon would, so the button then behaves exactly as it
   does for a developer who finished: the gates pass because they are satisfied.

   **AND v6.61's VERSION DID NOT WORK. IT ANSWERED THE WRONG QUESTION, TWICE.**
   Jaco: *"no marca los pasos anteriores como completados, y al dar a submit me
   muestra el estado dim de lo no completado."* Measured, he was exactly right —
   the log said "4 steps ticked" and `platformStepCount('macos')` said
   `complete: 0`. Two separate mistakes stacked, and both are worth writing down
   because either alone is silent:

   1. **`markTaskDone` writes a status nothing reads.** `platformStepCount` has a
      per-platform branch, and for ios / macos / macos_full / android / steam it
      counts `is<X>SectionComplete(step)` — derived from the ANSWERS. Only the
      remaining platforms fall through to the `platformStepStatus` default. So on
      Mac App Store the status map this was writing has no consumer at all.
   2. **`_paintStepRow` returned on its first line.** It looks up
      `#dot-<pid>-<stepId>`, and only two builders emit that id
      (render.js:5119 and 5897). The builder this card uses emits `.ios-step-num`
      with NO id, so `document.getElementById` came back null and the function
      returned before touching a class — no error, no warning, nothing painted.

   v6.61's note theorised about ordering ("mark AFTER the render") and that was
   a real trap but not this bug: the ordering fix cannot help a status nobody
   reads or a paint that never runs. **A helper that reports success from its own
   arguments rather than from the state afterwards will do this every time** —
   which is why this one now finishes by ASKING `platformStepCount` and printing
   what it really got, and warns if it fell short.

   **So it fills the DATA, and the ticks are then real.** Each completion
   predicate is asked for the minimum it wants — a build that is not processing
   plus a track, every content-rating question answered, a privacy URL with
   `collectsData: 'no'`, the two business questions, one screenshot, and the
   "you have looked at this" flags. Nothing is painted by hand, so nothing
   evaporates on the next render: the steps are complete because they ARE.

   **The answers go through `_appStoreAnswers(pid, field)`**, the app's own
   router, not to a bucket picked by hand. Mac App Store shares Content Rating
   and Data Privacy with the App Store (`IOS_MAC_SHARED_ANSWER_FIELDS`) and keeps
   Business Questions to itself, so a helper writing `state.macSubmitAnswers`
   directly would fill three fields into a bucket nothing checks — the same class
   of mistake as (1), one layer down.

   The values are the quietest true ones: intensity `none`, yes/no `no`,
   age `not_applicable`. This is a dev helper, and a submission it fabricates
   should claim as little as possible about the game.

   It only ever FILLS BLANKS (`??=` semantics): anything you already answered is
   left alone, so running it over real work does not overwrite it.

   The track is the platform's FIRST, not a hard-coded 'production', since the
   list differs per store and a missing key would fail gate 3 in a way that looks
   like the helper working.

   **What it does not cover, said out loud rather than failing quietly:** Android
   and Steam are also answer-derived, and their fillers are not written — the
   helper says so instead of pretending. The status-based platforms (Web, PSN,
   Xbox, Switch, Epic) really are `platformStepStatus`, so those keep
   `markTaskDone`, which for them is the right tool.

   Console-only, like `smCardState` and `smWaitStyle`, for the reason the dev bar
   was deleted under: a visible control that fills in your submission for you is
   a feature nobody asked for, waiting to be found. */

/* A 16:10 placeholder, so the screenshot gate is satisfied by a real image
   rather than by a shape that only looks like one. Small enough to sit in a
   source file and correct enough that the preview draws a frame instead of a
   broken icon. */
const SM_STUB_SHOT = 'data:image/svg+xml;utf8,' + encodeURIComponent(
  '<svg xmlns="http://www.w3.org/2000/svg" width="2880" height="1800">' +
  '<rect width="2880" height="1800" fill="#1b1b1f"/>' +
  '<text x="1440" y="920" font-family="monospace" font-size="120" fill="#4a4a55"' +
  ' text-anchor="middle">PLACEHOLDER</text></svg>');

function smReadyToShip(pid) {
  if (!pid) { console.warn('smReadyToShip(pid) — e.g. smReadyToShip("macos")'); return; }

  /* ACTIVATE IT FIRST, or there is no card to press. Found by measuring: the
     helper set all three pieces of state correctly and nothing appeared,
     because `activePlatforms` was empty and the grid draws from that. A
     platform you have not added has no card, and a card is what this exists to
     get you to. */
  if (!state.activePlatforms?.has?.(pid) && !(state.activePlatforms || []).includes?.(pid)) {
    if (typeof activatePlatform === 'function') activatePlatform(pid);
    else state.activePlatforms?.add?.(pid);
  }
  (state.platformAuth || (state.platformAuth = {}))[pid] = { loggedIn: true };

  /* Gate 3 asks for a DESTINATION, and nothing is preselected anywhere in this
     app on purpose — so the helper has to choose one, and it says which. */
  const tracks = (typeof PLATFORM_TRACKS !== 'undefined' && PLATFORM_TRACKS[pid]) || [];
  const track  = tracks[0]?.id || tracks[0] || 'production';
  (state.selectedTracks || (state.selectedTracks = {}))[pid] = track;

  /* A BUILD THAT IS NOT STILL PROCESSING. `_uploadBuildComplete` wants all
     three — a build, no processing flag, and the track set above. */
  (state.platformBuilds || (state.platformBuilds = {}))[pid] ||=
    { name: 'Game.ipa', size: 130937, buildNumber: 42, uploadedAt: Date.now() - 2 * 864e5 };
  (state.platformBuildProcessing || (state.platformBuildProcessing = {}))[pid] = false;

  const steps = (typeof _visiblePlatformSteps === 'function' ? _visiblePlatformSteps(pid) : [])
    .filter(s => !s.isSubmit);

  if (pid === 'ios' || pid === 'macos' || pid === 'macos_full') {
    /* FILL A BLANK, NEVER OVERWRITE AN ANSWER — and route every field through
       the app's own `_appStoreAnswers`, which knows that Mac App Store shares
       these first three groups with the App Store and keeps Business to
       itself. */
    const fill = (field, value) => {
      const a = _appStoreAnswers(pid, field);
      if (a && (a[field] === null || a[field] === undefined || a[field] === '')) a[field] = value;
    };

    IOS_INTENSITY_QUESTIONS.forEach(q => fill(q.id, 'none'));
    IOS_CONTENT_YN_QUESTIONS.forEach(q => fill(q.id, 'no'));
    fill('ageCategory', 'not_applicable');

    fill('privacyPolicyUrl', (state.formData?.privacyUrl || '').trim() || 'https://example.com/privacy');
    fill('collectsData', 'no');

    fill('hasIAP', 'no');
    fill('usesEncryption', 'no');
    if (pid === 'macos_full') fill('contentRights', 'no');

    /* The "you have actually looked at this" flags. They are booleans rather
       than answers, so `fill`'s blank test does not apply — `false` is a real
       value there, and it is precisely the one to replace. */
    const seenAns = _appStoreAnswers(pid, 'improveSubmissionSeen');
    if (seenAns) seenAns.improveSubmissionSeen = true;
    state[pid === 'ios' ? 'iosLocalizationsSeen'
       : pid === 'macos' ? 'macLocalizationsSeen'
       : 'macFullLocalizationsSeen'] = true;

    /* One screenshot. The gate is "optional once present" and reads the asset
       pool before the per-platform selection, so the pool is where it goes. */
    state.uploads ||= {};
    state.uploads.screenshots ||= [];
    if (!state.uploads.screenshots.length &&
        !(state.platformScreenshots?.[pid]?.selected?.length) &&
        !(state.platformScreenshots?.[pid]?.custom?.length)) {
      /* IT NEEDS AN `id`, AND LEAVING IT OUT FAKED AN EMPTY LISTING. Every
         real door into this pool mints one — `ss_…` from the Assets well,
         `igdb-…` from a fetched title, `pshot-…` from the editor's own + —
         because `order`, `removed` and `crops` are all keyed on it. This seed
         had none, so `shots[0]?.id` came back `undefined`, the Screenshots
         editor drew its EMPTY stage with the thumbnail sitting in the strip
         underneath it, and that thumbnail rendered as
         `data-shot-thumb="undefined"` and could not be opened at all.

         A helper that fabricates state has to fabricate it in the shape the
         real doors produce, or it tests a state the app cannot reach — the
         same failure as v6.61's ticks, which reported success while writing a
         status nothing read. */
      state.uploads.screenshots.push({
        id: 'ss_seed_' + pid,
        name: 'placeholder.svg',
        dataUrl: SM_STUB_SHOT,
      });
    }
  } else if (pid === 'android' || pid === 'steam') {
    console.warn(`[smReadyToShip] ${pid} computes its steps from ${pid}SubmitAnswers and this helper has no filler for them yet — the card will still show them outstanding.`);
  } else {
    /* These platforms really are status-based (`platformStepCount`'s default
       branch), so `markTaskDone` is the right tool for them and only them. */
    state.platformStepStatus ||= {};
    state.platformStepStatus[pid] ||= {};
    steps.forEach(s => markTaskDone(pid, s.id));
  }

  if (typeof renderDashboard === 'function') renderDashboard();

  /* **IT ASKS THE APP WHAT IT ACHIEVED, IT DOES NOT ASSERT IT.** The previous
     version printed "4 steps ticked" from the length of its own loop while the
     real count was 0 — a helper reporting its intentions back to you. This reads
     `platformStepCount` after the render, which is the same function the card's
     own progress bar and gate 2 read, so the line cannot be more optimistic than
     the screen. */
  const counts = (typeof platformStepCount === 'function') ? platformStepCount(pid) : null;
  if (counts && !counts.allRequired) {
    const missing = steps.filter(s => {
      const f = pid === 'ios' ? isIOSSectionComplete
              : pid === 'macos' ? isMacSectionComplete
              : pid === 'macos_full' ? isMacFullSectionComplete : null;
      return f ? !f(s.id) : false;
    }).map(s => s.id);
    console.warn(`[smReadyToShip] ${pid}: ${counts.complete}/${counts.total} steps complete — Submit will still refuse.`,
                 missing.length ? `Outstanding: ${missing.join(', ')}` : '');
    return;
  }
  console.log(`[smReadyToShip] ${pid}: account linked, track "${track}", ${counts ? `${counts.complete}/${counts.total}` : 'all'} steps complete. Press Submit.`);
}

// Legacy alias kept for any paths that still call finalSubmit directly.
function finalSubmit(platformId) {
  openTrackSubmitModal(platformId);
}

// Cancels a submission — removes the flip state and release record, returns card to pre-submission.
function cancelSubmission(pid) {
  const proj = state.projects.find(p => p.id === state.activeProjectId);
  const ver  = proj?.versions.find(v => v.id === state.activeVersionId);

  // Remove the release record that was minted on submit
  if (ver?.platformReleases?.[pid]) {
    ver.platformReleases[pid].pop();
    if (ver.platformReleases[pid].length === 0) delete ver.platformReleases[pid];
  }

  // Reset submit step status
  if (state.platformStepStatus?.[pid]) {
    state.platformStepStatus[pid]['submit'] = 'not_started';
  }

  /* THE UNDO IS THE SAME MOTION RUN BACKWARDS — the box OPENS, giving the steps
     back the height the submit took from them. It used to counter-rotate, and
     it had to stop for the same reason the submit did: withdrawing is not
     turning the card over either. Sharing one mechanism also means the two
     cannot drift into different durations or curves, which is what two hand-
     written rotation blocks 120 lines apart were already halfway to doing. */
  const card = document.getElementById('active-card-' + pid);
  const cardHeight = card ? card.offsetHeight : 0;

  function _applyUnflip() {
    if (state.platformFlipped) delete state.platformFlipped[pid];
    /* THE MONTH HAS TO BE TOLD, and it was the missing half of this mirror.
       `renderDashboard` does NOT rebuild the guide column — that is written in
       the submit path, which calls `renderGuide()` by name for exactly this
       reason — so a cancelled submission vanished from the state and its wait
       stayed painted on the calendar until some unrelated repaint came along.
       The card said withdrawn and the month three inches away said the store
       still had it.

       Both sides of the wait live in `platformFlipped`, so the band, the lede
       and the day panel's wait line all clear from this one call; there is
       nothing per-surface to undo. The focused platform is the exception —
       it is a pointer, not derived — and a pointer at a submission that no
       longer exists would leave the panel empty for no stated reason. */
    if (state.guideCalWait === pid) state.guideCalWait = null;
    renderDashboard();
    renderGuide();
    const newCard = document.getElementById('active-card-' + pid);
    if (!newCard) return;
    const toH = newCard.offsetHeight;
    newCard.classList.add('is-advancing');
    newCard.style.overflow   = 'hidden';
    newCard.style.height     = (cardHeight || toH) + 'px';
    newCard.style.transition = 'none';
    requestAnimationFrame(() => requestAnimationFrame(() => {
      newCard.style.transition = 'height 0.42s cubic-bezier(0.22, 0.61, 0.36, 1)';
      newCard.style.height     = toH + 'px';
      setTimeout(() => {
        newCard.style.transition = '';
        newCard.style.height     = '';
        newCard.style.overflow   = '';
        newCard.classList.remove('is-advancing');
      }, 440);
    }));
  }

  _applyUnflip();
}


/* ── Platform activate / deactivate ──────────────────── */

function blinkComingSoon(pid) {
  const badge = document.getElementById(`cs-badge-${pid}`);
  if (!badge || badge.classList.contains('is-blinking')) return;
  badge.classList.add('is-blinking');
  setTimeout(() => badge.classList.remove('is-blinking'), 700);
}

function activatePlatform(platformId) {
  // Defensive: the "+ Add platform" picker (renderDashboard, render.js)
  // already disables the button for COMING_SOON_PLATFORMS (render.js —
  // egs/psn/xbox/nintendo), so this only matters if something ever calls
  // activatePlatform directly instead of going through it.
  if (COMING_SOON_PLATFORMS.has(platformId)) return;
  // Same reasoning, for a platform hidden while still in development
  // (HIDDEN_PLATFORMS, render.js) — renderDashboard's own `inactive` list
  // already excludes it from the picker entirely, so it can't be clicked
  // there either; this only matters for a direct call.
  if (HIDDEN_PLATFORMS.has(platformId)) return;
  state.activePlatforms.add(platformId);
  // See toggleOnboardingPlatform's identical call — Submission's own
  // "add a platform" entry point needs the same one-time seed.
  if (platformId === 'macos') seedMacAppStoreListing();
  if (platformId === 'macos_full') seedMacFullAppStoreListing();
  /* And the build state, on the same reasoning: a platform added here never
     went through onboarding, so nothing had guaranteed the objects its card
     reads. It only fills in what is missing, so calling it per activation is
     safe. */
  {
    const proj = state.projects.find(p => p.id === state.activeProjectId);
    if (proj && typeof ensureBuildState === 'function') ensureBuildState(proj);
  }
  /* SELECT WHAT YOU JUST ADDED. Adding a platform from the picker is a stated
     intention to work on it, and leaving the pane on the previous tab answers
     a question nobody asked — the new tab would appear in the strip and
     nothing else would change, which reads as the press having failed.
     Also closes the picker: it has done its job. */
  state.submission.tab     = platformId;
  state.submission.addOpen = false;
  renderDashboard();
  /* The add menu lives in the sub-nav row, which renderDashboard() does not
     touch — the same trap _doFinalSubmit and setLaunchDate are both written
     under for the guide column. Without this the platform you just added stays
     listed as available, and the menu redraws open next time. */
  if (typeof renderAppSubnav === 'function') renderAppSubnav();
  // Shippy's platform item lives in the Details view, which renderDashboard()
  // never touches. Without this the checklist stays stale until something
  // else on the Details tab happens to fire a recalculation.
  updateObSectionStates();
  // Measure the steps face now so the credentials face can match its height on
  // the very first flip (before any steps face has actually been shown).
  _cacheStepsFaceHeight(platformId);
}

function deactivatePlatform(platformId) {
  state.activePlatforms.delete(platformId);
  // Reset the transient face (keep platformAuth so sign-in persists).
  if (state.platformFace) delete state.platformFace[platformId];
  /* Switching a platform off while looking at it leaves the tab pointing at
     nothing. submissionTab() falls back on every read, so the pane is never
     blank either way — this just makes the state say what the screen shows
     rather than leaving a dead id behind for the next reader to puzzle over. */
  if (state.submission?.tab === platformId) state.submission.tab = null;
  if (state.submission?.openStep) delete state.submission.openStep[platformId];
  renderDashboard();
  // A platform switched off becomes available again, so the add menu's list
  // has changed — same reason as activatePlatform's own call.
  if (typeof renderAppSubnav === 'function') renderAppSubnav();
  updateObSectionStates();   // same reason as activatePlatform
}


/* ── Platform developer-portal auth (prototype/faked) ─────────────────────────
   Each active card has two faces on one shell: STEPS and ACCOUNT (credentials).
   • Not signed in → ACCOUNT face shows the login form. Submitting flips to STEPS.
   • Signed in     → card rests on STEPS. The steps gear flips to the ACCOUNT face,
                     which shows a compact "signed in" summary; the account gear
                     reveals the login boxes again to change credentials.
   Credentials are faked — any non-empty pair is accepted, nothing is stored/sent.
   Sign-in persists for the session. Flip mirrors the submit flip in _doFinalSubmit.
   The ACCOUNT face is pinned to the cached STEPS height so flips stay size-stable. */

function _setPlatformFace(pid, face) {
  if (!state.platformFace) state.platformFace = {};
  state.platformFace[pid] = face;
}

// Measure the STEPS face height off-screen and cache it (px) for height parity.
function _cacheStepsFaceHeight(pid) {
  const live = document.getElementById('active-card-' + pid);
  if (!live) return;
  const width = live.offsetWidth;
  const probe = document.createElement('div');
  probe.style.cssText = 'position:absolute;left:-99999px;top:0;visibility:hidden;pointer-events:none;'
    + (width ? ('width:' + width + 'px;') : '');
  probe.innerHTML = buildActiveCard(pid, true); // force STEPS face
  document.body.appendChild(probe);
  const inner = probe.querySelector('.active-card');
  const h = inner ? inner.offsetHeight : 0;
  probe.remove();
  if (h > 0) {
    if (!state.platformCardHeight) state.platformCardHeight = {};
    state.platformCardHeight[pid] = h;
    // If the credentials face is currently on screen, apply the new height now.
    if (live.classList.contains('platform-account-card')) live.style.minHeight = h + 'px';
  }
}

// STATE 1 → STATE 3: sign in. Prototype accepts anything, including blank fields.
function submitPlatformLogin(pid) {
  const userEl = document.getElementById('login-user-' + pid);
  const username = userEl ? userEl.value.trim() : '';
  if (!state.platformAuth) state.platformAuth = {};
  state.platformAuth[pid] = { loggedIn: true, username };
  _flipPlatformCard(pid, 'steps', 1); // signed out → platform linked (steps)
}

// Linked (steps) gear → flip to the signed-in settings face (STATE 3 → STATE 2).
function platformGearFromSteps(pid) {
  _flipPlatformCard(pid, 'account', -1);
}

// Signed-in settings gear → flip back to the linked (steps) face (STATE 2 → STATE 3).
function platformGearFromAccount(pid) {
  _flipPlatformCard(pid, 'steps', 1);
}

// Signed-out gear → just highlight the login fields (no flip).
function highlightLoginFields(pid) {
  const els = ['login-user-' + pid, 'login-pass-' + pid]
    .map(id => document.getElementById(id)).filter(Boolean);
  els.forEach(el => {
    el.classList.remove('platform-login-input--highlight');
    void el.offsetWidth; // restart the animation
    el.classList.add('platform-login-input--highlight');
    setTimeout(() => el.classList.remove('platform-login-input--highlight'), 1200);
  });
  if (els[0]) els[0].focus();
}

// Sign out → return to the signed-out form (STATE 2 → STATE 1), in place.
function platformSignOut(pid) {
  if (state.platformAuth?.[pid]) state.platformAuth[pid].loggedIn = false;
  _setPlatformFace(pid, 'account');
  _rerenderPlatformCard(pid);
  const u = document.getElementById('login-user-' + pid); if (u) u.focus();
}

// Faked "Linked App" selection on the signed-in settings face.
function selectLinkedApp(pid, val) {
  if (!state.platformLinkedApp) state.platformLinkedApp = {};
  state.platformLinkedApp[pid] = val;
}


/* ── Connect flow (prototype, on-card + realistic sign-in modal) ──────────────
   Connecting is optional up front — cards start on the steps face with an
   alert-red cog. The cog flips to the connect face, which walks three short
   stages: install → sign in (opens the browser-framed sign-in modal) → add.
   Completing "Add" links the bot and flips back to steps. All faked. */

function _setConnectStage(pid, stage) {
  if (!state.connectStage) state.connectStage = {};
  state.connectStage[pid] = stage;
}

// Stage 1 → 2: "Install extension" (sticky global; re-render the connect face).
function connectInstall(pid) {
  state.extensionInstalled = true;
  _setConnectStage(pid, 'signin');
  _rerenderPlatformCard(pid);
}

// Open the browser-framed sign-in modal (simulates the real portal via extension).
function openAscLogin(pid) {
  state.ascLogin = pid;
  if (pid === 'android') { state.googleView = 'choose'; state.googleAccount = null; } // reset OAuth chooser
  renderAscLogin();
  const overlay = document.getElementById('connect-overlay');
  if (overlay) { overlay.classList.remove('hidden'); document.body.style.overflow = 'hidden'; }
  requestAnimationFrame(() => { const u = document.getElementById('asc-user'); if (u) u.focus(); });
}

/* Google OAuth sub-flow: account chooser → consent. */
function googleSelectAccount(email) {
  state.googleAccount = email;
  state.googleView = 'consent';
  renderAscLogin();
}
function googleUseAnother() {
  state.googleView = 'add';
  renderAscLogin();
  requestAnimationFrame(() => { const e = document.getElementById('gp-email'); if (e) e.focus(); });
}
function googleAddNext() {
  const e = document.getElementById('gp-email');
  state.googleAccount = (e && e.value.trim()) || 'you@studio.com';
  state.googleView = 'consent';
  renderAscLogin();
}
// "Allow" on the consent screen → grant, close modal, advance to the add step.
function googleAllow(pid) {
  state.connectAccountEmail = state.connectAccountEmail || {};
  state.connectAccountEmail[pid] = state.googleAccount || shipmateBotEmail();
  closeAscLogin();
  _setConnectStage(pid, 'confirm');
  _rerenderPlatformCard(pid);
}

function closeAscLogin() {
  state.ascLogin = null;
  const overlay = document.getElementById('connect-overlay');
  if (overlay) { overlay.classList.add('hidden'); document.body.style.overflow = ''; }
}

function connectOverlayClick(e) {
  if (e.target === document.getElementById('connect-overlay')) closeAscLogin();
}

function renderAscLogin() {
  const m = document.getElementById('connect-modal');
  if (m) m.innerHTML = buildAscLoginModal();
}

// Sign-in submitted → close modal, advance the connect face to the "add" stage.
function ascLoginSubmit(pid) {
  const u = document.getElementById('asc-user');
  state.connectAccountEmail = state.connectAccountEmail || {};
  state.connectAccountEmail[pid] = (u && u.value.trim()) || '';
  closeAscLogin();
  _setConnectStage(pid, 'confirm');
  _rerenderPlatformCard(pid);
}

// Stage 3: "Add & connect" — link the bot and flip the card back to steps.
function connectAdd(pid) {
  if (!state.platformAuth) state.platformAuth = {};
  const email = state.connectAccountEmail?.[pid] || shipmateBotEmail();
  state.platformAuth[pid] = { loggedIn: true, username: email };
  if (state.connectStage) delete state.connectStage[pid];
  _flipPlatformCard(pid, 'steps', 1); // connect face → steps (now connected)
}

// Re-render a single active card in place (no flip animation).
/* THE ACCOUNT FACE IS A MODAL NOW, so the connect flow's own repaints have to
   land there and not on the pane.

   Every stage of that flow (install → sign in → add, plus sign-out and the
   linked-app picker) ends by calling this, and it used to swap `#active-card-<pid>`
   for a freshly built card. That id now belongs to the SUBMISSION PANE, so the
   un-patched version would quietly replace a pane full of expanded inline steps
   with a platform card whose rows reopen the modal — the old surface growing
   back out of the new one, mid-flow, with no way to tell which you were looking
   at. Going through platformGearFromTab means the modal rebuilds from exactly
   the state the flow has just written, which is what the card face used to get. */
function _rerenderPlatformCard(pid) {
  renderDashboard();
}

// Flip a card to the target face. dir = 1 / -1 sets the rotation direction.
function _flipPlatformCard(pid, toFace, dir) {
  /* THERE IS NO CARD TO TURN OVER IN THE PANE. A flip means "the other side of
     this card" — the gear's one job on the card face — and in the Submission
     tab the account face has stopped being a face: it is what the pane SHOWS
     while `submission.settings` names a platform. Reaching here from there
     (signing in, or finishing the connect flow) would rotate the pane itself on
     its Y axis, because the pane inherited the card's id. So finishing the flow
     just swaps the pane back: the thing the flip was announcing — you are
     connected now — is already true, and the steps are where you were going. */
  /* THE GUARD IS ABOUT THE PANE, SO IT HAS TO ASK WHETHER THERE IS ONE.
     `submission.settings` names a platform whose account face the PANE is
     showing — a fact that only exists in the inline presentation. Tested
     alone it also fired in the card grid, where the gear is a real flip
     again: a stale value left there by a press under the old handler would
     have sent the next flip straight into closePlatformSettings, i.e. the
     card refusing to turn over for a reason belonging to another layout.
     The flag is what says which presentation is on screen, so it is what the
     guard asks. */
  if (state.submission?.settings === pid && state.submission?.layout !== 'modal') {
    _setPlatformFace(pid, 'steps');
    if (toFace === 'steps') { closePlatformSettings(); return; }
    renderDashboard();
    return;
  }

  const outDeg = 90 * dir;
  const inDeg  = -90 * dir;
  const card   = document.getElementById('active-card-' + pid);

  // Leaving the STEPS face → cache its live height so the account face matches.
  if (toFace === 'account' && card && !card.classList.contains('platform-account-card')) {
    if (!state.platformCardHeight) state.platformCardHeight = {};
    const h = card.offsetHeight;
    if (h > 0) state.platformCardHeight[pid] = h;
  }
  _setPlatformFace(pid, toFace);

  function _apply() {
    /* The column is pinned to its live height so the flip does not collapse
       what is under the card being turned. `.active-cards-grid` is the only
       name this ever looked for and it is rendered NOWHERE — the card grid is
       `.dash-column` (renderSubmission's 'modal' arm), so the query came back
       null and the pin has been a no-op for as long as that markup has been
       the one in use. Both names, because they are the same object. */
    const grid = document.querySelector('.active-cards-grid, .dash-column');
    const gridHeight = grid ? grid.offsetHeight : 0;
    if (grid && gridHeight > 0) grid.style.minHeight = gridHeight + 'px';

    renderDashboard();

    const newCard = document.getElementById('active-card-' + pid);
    if (newCard) {
      newCard.style.transform  = `perspective(700px) rotateY(${inDeg}deg)`;
      newCard.style.transition = 'none';
      requestAnimationFrame(() => requestAnimationFrame(() => {
        newCard.style.transition = 'transform 0.32s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
        newCard.style.transform  = 'perspective(700px) rotateY(0deg)';
        if (toFace === 'account') {
          const u = document.getElementById('login-user-' + pid); if (u) u.focus();
        }
        setTimeout(() => {
          newCard.style.transition = '';
          newCard.style.transform  = '';
          if (grid) grid.style.minHeight = '';
        }, 340);
      }));
    } else if (grid) {
      setTimeout(() => { grid.style.minHeight = ''; }, 340);
    }
  }

  if (card) {
    card.style.transition = 'transform 0.28s cubic-bezier(0.55, 0, 1, 0.45)';
    card.style.transform  = `perspective(700px) rotateY(${outDeg}deg)`;
    setTimeout(_apply, 290);
  } else {
    _apply();
  }
}


/* ── Form helpers ────────────────────────────────────── */

// Auto-round prices to .99 convention (e.g. 5 → 4.99, 10 → 9.99)
function roundPrice(inputEl) {
  let val = parseFloat(inputEl.value);
  if (isNaN(val) || val <= 0) return; // free / blank — leave as-is
  // If the cents portion is already .99 don't touch it
  if (Math.abs(val - Math.floor(val) - 0.99) < 0.001) return;
  // Round to nearest whole dollar then subtract 0.01
  const rounded = Math.round(val);
  const result = rounded > 0 ? (rounded - 0.01).toFixed(2) : val.toFixed(2);
  inputEl.value = result;
  /* Through the accessor, and the pid comes off the input's own id
     (`${pid}-price`, buildBusinessSection) rather than from the step modal —
     this fires on blur, and a blur can land after the modal state has moved
     on. Falls back to the App Store, which is where this field lived before it
     was split. */
  const pid = (inputEl.id || '').replace(/-price$/, '') || 'ios';
  if (typeof _setAppStorePrice === 'function') _setAppStorePrice(pid, result);
  else state.formData['price'] = result;
}

// Same "round to a .99 price" polish as the base game price (roundPrice
// above) — kept as its own function rather than reusing roundPrice
// directly, since that one hardcodes state.formData.price (the App Store/
// Mac App Store shared price) and would overwrite that field instead of
// Steam's own, independent price (state.webSite.price — see
// buildSteamBusinessSection, render.js, for why Steam gets its own).
function roundSteamPrice(inputEl) {
  let val = parseFloat(inputEl.value);
  if (isNaN(val) || val <= 0) return; // free / blank — leave as-is
  if (Math.abs(val - Math.floor(val) - 0.99) < 0.001) return;
  const rounded = Math.round(val);
  const result = rounded > 0 ? (rounded - 0.01).toFixed(2) : val.toFixed(2);
  inputEl.value = result;
  setWebSiteField('price', result);
}

/* ── Onboarding section rail predicates ──────────────── */

// Returns true when all required fields for a given section are filled.
// Called by updateObSectionStates() to drive the amber rail + header tint.
const OB_SECTION_ANSWERED = {
  about:        () => !!(state.formData.title?.trim()) &&
                      !!(state.formData.description?.trim()),
  platforms:    () => state.activePlatforms.size > 0,
  distribution: () => !!state.formData.distributionPreset,
  localization: () => !!state.formData.primaryLanguage,  // defaults to 'en' — always answered
  screenshots:  () => state.uploads.screenshots.length > 0,
  compliance:   () => QUESTIONS.every(q => state.questionAnswers[q.id] !== null),
  // Optional sections — never shown as unanswered
  trailer:      () => true,
};

// Per-question answered predicates (drives ob-q data-answered for individual field rails)
const OB_Q_ANSWERED = {
  title:        () => !!(state.formData.title?.trim()),
  desc:         () => !!(state.formData.description?.trim()),
  platforms:    () => state.activePlatforms.size > 0,
  distribution: () => !!state.formData.distributionPreset,
  screenshots:  () => state.uploads.screenshots.length > 0,
  compliance:   () => QUESTIONS.every(q => state.questionAnswers[q.id] !== null),
};

// Toggle is-complete on a specific input element (used for text inputs/textareas)
function _setInputComplete(id, isComplete) {
  const el = document.getElementById(id);
  if (el) el.classList.toggle('is-complete', isComplete);
}

function updateObSectionStates() {
  // Per-question rails — each individual field gets its own amber indicator
  for (const [id, pred] of Object.entries(OB_Q_ANSWERED)) {
    const el = document.getElementById('ob-q-' + id);
    if (el) el.setAttribute('data-answered', pred() ? '1' : '0');
  }
  // Section-level state kept for header tinting only (no visual rail)
  for (const [id, pred] of Object.entries(OB_SECTION_ANSWERED)) {
    const el = document.getElementById('ob-sec-' + id);
    if (el) el.classList.toggle('is-unanswered', !pred());
  }
  // If in validation mode and all required fields for this tab are now filled, clear validation
  const required = OB_TAB_REQUIRED[state.onboardingTab] || [];
  if (required.every(id => OB_Q_ANSWERED[id]?.())) {
    _setObValidating(false);
  }
  // Sync is-complete on text inputs — correct after any tab render
  _setInputComplete('ob-title',            !!(state.formData.title?.trim()));
  _setInputComplete('ob-desc',             !!(state.formData.description?.trim()));
  _setInputComplete('ob-prv-nlp-textarea', !!(state.iosSubmitAnswers?.privacyDescription?.trim()));
  // Shippy's checklist reads the same predicates, so it repaints here. This is
  // the one hook every field change already funnels through — a dozen call
  // sites, from keystrokes to platform toggles to screenshot drops — which is
  // why the panel goes here rather than being wired up at each of them.
  paintShippyPanel();
}

// Keeps the top-right project bar's game title in sync the moment
// state.formData.title changes, without waiting for the next full
// renderProjectBar() (which also rebuilds the nav labels, the release
// dropdown, and re-measures the nav glow — unnecessary work on every
// keystroke). Called from syncField('title', ...) (typing the title field)
// and selectPicklistItem (picking a game from the IGDB search picklist) —
// the two places the title can change during onboarding.
//
// Patches two things: the closed chip (#projectSelectorTitle) and, if the
// project dropdown is currently open, the active project's own row inside
// it (.project-item.active, #projectDropdown) — that row previously only
// ever showed the PROJECT RECORD's saved name (proj.name, written back only
// by saveCurrentToProject() at save points like switching project/version
// or completing onboarding), so a title just typed or picked here wouldn't
// show up in the dropdown until some unrelated action happened to trigger
// one of those saves — it would keep reading "Untitled Game" even after a
// game was clearly already selected. An earlier version of this function
// tried to patch a #projectItemCurrent element that was never actually
// given that id anywhere in the dropdown's own markup (renderProjectBar,
// render.js) — a dead, always-null lookup — which is how this went
// unnoticed. renderProjectBar's own dropdown-row template (render.js) now
// separately falls back to this same live title for its permanent fix on
// every full re-render; this function is just the fast path in between.
function _syncProjectBarTitle(value) {
  const selEl = document.getElementById('projectSelectorTitle');
  if (selEl) selEl.textContent = value || 'My Game';
  const activeDropdownItem = document.querySelector('#projectDropdown .project-item.active');
  if (activeDropdownItem) activeDropdownItem.textContent = value || t('bar.untitled_game');
}

function syncField(field, value) {
  /* EDITING THE TITLE INVALIDATES EVERYTHING SHIPMATE FETCHED FOR THE OLD ONE.
     Scraped art, screenshots and the trailer preview all describe whatever
     game was last resolved from the picklist; the moment the developer types
     over that title by hand, they describe a game this project is no longer
     about. Clearing only on picklist selection left exactly that hole — type
     a different name and the previous game's screenshots stayed in Assets
     indefinitely, with nothing on screen admitting where they came from.

     Guarded three ways because this runs on every keystroke: only for the
     title field, only when the text actually changed (oninput fires for
     arrow keys and re-selection of the same value too), and only re-rendering
     when something was genuinely removed. Manual uploads are untouched —
     see _smClearAllScrapedAssets. selectPicklistItem does NOT come through
     here (it assigns state.formData.title directly), so picking a title runs
     that function's own call instead of this one and the two never double up. */
  if (field === 'title' && state.formData[field] !== value) {
    if (_smClearAllScrapedAssets()) {
      if (typeof _refreshScreenshotGrid === 'function') _refreshScreenshotGrid();
      if (typeof renderAssetLibrary === 'function') renderAssetLibrary();
    }
  }
  state.formData[field] = value;
  // Keep platform privacy URLs in sync when the global field is updated
  if (field === 'privacyUrl') {
    state.iosSubmitAnswers.privacyPolicyUrl     = value;
    state.macSubmitAnswers.privacyPolicyUrl     = value;
    state.androidSubmitAnswers.privacyPolicyUrl = value;
  }
  if (field === 'title') _syncProjectBarTitle(value);
  if (field === 'description') { _wsPropagateAboutGame(value); _macFullPropagateDescription(value); _applePropagateDescription(value); }
  // Force-sync into the Web platform's own independent trailer slot — same
  // whole-value overwrite treatment as the trailer FILE gets in
  // handleTrailerFiles/removeTrailer (see the state.js comment above
  // webSite.trailerFile).
  if (field === 'trailerUrl') { if (!state.webSite) state.webSite = {}; state.webSite.trailerUrl = value; }
  // Live is-complete on the typed input — immediate feedback as user types/clears
  const FIELD_INPUT_MAP = { title: 'ob-title', description: 'ob-desc' };
  if (FIELD_INPUT_MAP[field]) _setInputComplete(FIELD_INPUT_MAP[field], !!(value?.trim()));
  // Update section rails reactively
  updateObSectionStates();
  /* Reactively refresh the Shippy Guide checklist (a field gaining/losing a
     value flips its checkbox) — event-driven, not polling.

     Through refreshGuideCompletion rather than renderGuide, because "flips its
     checkbox" is the whole of what this line wants and renderGuide is the
     expensive way to get it: this runs on EVERY KEYSTROKE, and it was tearing
     down and rebuilding the guide column — innerHTML plus a Shippy remount —
     once per character, to change nothing at all on the 60 characters of a
     title after the first. The gated call compares the done-state of every row
     against what is on screen and returns without touching the DOM unless one
     actually moved, which for this field is the first character typed and the
     last one deleted. Same behaviour, paid for once instead of per key. */
  if (typeof refreshGuideCompletion === 'function') refreshGuideCompletion();
  else if (typeof renderGuide === 'function') renderGuide();
}

function charCount(countId, value, max) {
  const el = document.getElementById(countId);
  if (!el) return;
  const len = (value || '').length;
  const note = el.querySelector('.char-note');
  // "12/30", not "12 / 30" — the prototype's spacing.
  el.textContent = `${len}/${max}`;
  if (note) el.appendChild(note);
  el.className = 'char-count';
  if (len > max * 0.9) el.classList.add('is-warn');
  if (len > max)       el.classList.add('is-over');
}


function toggleLang(el, code) {
  const idx = state.formData.localizations.indexOf(code);
  if (idx === -1) { state.formData.localizations.push(code); el.classList.add('is-on'); }
  else            { state.formData.localizations.splice(idx, 1); el.classList.remove('is-on'); }
  updateWorldMap();
}

/* ── Onboarding Distribution Map & Localization ──────── */

const OB_REGULATORY_EXCLUSIONS = ['CN', 'KR', 'JP', 'DE', 'BE', 'VN', 'ZA'];

// Normalizes a Languages-step code (state.formData.primaryLanguage /
// .localizations — which can carry a region suffix: zh-TW, pt-BR, es-419)
// down to the bare code IOS_COUNTRIES' own `lang` field uses. One further
// alias: OB_LANG_NAMES' Norwegian is 'nb' (Bokmål), but IOS_COUNTRIES keys
// Norway as 'no' — with no 'nb' entry, 'nb' would otherwise silently match
// zero countries.
function _obLangBaseCode(code) {
  const base = (code || '').split('-')[0];
  return base === 'nb' ? 'no' : base;
}

function _obCountriesForPreset(preset) {
  const fd = state.formData;
  switch (preset) {
    case 'everywhere':
    case 'global':              return IOS_COUNTRIES.map(c => c.code);
    case 'english_only':        return IOS_COUNTRIES.filter(c => c.lang === 'en').map(c => c.code);
    // "{lang} only" pill (buildDistributionTab, render.js — hidden there
    // when the primary language is English, so this case is only ever
    // reached with a non-English primary in normal use).
    case 'primary_lang_only': {
      const base = _obLangBaseCode(fd.primaryLanguage || 'en');
      return IOS_COUNTRIES.filter(c => c.lang === base).map(c => c.code);
    }
    // Primary language plus every supported language from the Languages
    // step (state.formData.localizations), combined.
    case 'selected_languages': {
      const bases = new Set([
        _obLangBaseCode(fd.primaryLanguage || 'en'),
        ...(fd.localizations || []).map(_obLangBaseCode),
      ]);
      return IOS_COUNTRIES.filter(c => bases.has(c.lang)).map(c => c.code);
    }
    // regTip(), not OB_REG_TIPS directly — regTip() is what also hides Korea/
    // Brazil/Australia/Japan/Germany's tips (OB_REG_TIP_HIDDEN, render.js),
    // so this preset and the "Excluded" chips it surfaces (buildObExcludedChips)
    // agree on exactly which countries count as "regulated" without a second
    // copy of that judgment call to keep in sync.
    case 'minimize_regulation': return IOS_COUNTRIES.filter(c => !regTip(c.code)).map(c => c.code);
    default:                    return state.formData.selectedCountries || IOS_COUNTRIES.map(c => c.code);
  }
}

// Distribution presets 'primary_lang_only' and 'selected_languages' are
// defined in terms of the Languages step's current primary/supported
// languages (_obCountriesForPreset above) — so every place that mutates
// primaryLanguage/localizations (selectLocPrimary, toggleObLang,
// addLangFromSearch, further below) calls this afterward to keep a
// currently-active one of those two presets in sync, rather than leaving
// its pill highlighted against a now-stale country selection. Re-snapping
// the preset id (not just leaving it as the same id) covers the one edge
// case that needs it: switching primary language to English hides the
// "{lang} only" pill entirely (buildDistributionTab) — english_only is
// checked first below, so the identical resulting country set relabels to
// that pill instead of leaving 'primary_lang_only' active with no matching
// button to highlight.
function _obResyncDistPresetIfLangDriven() {
  const preset = state.formData.distributionPreset;
  if (preset !== 'primary_lang_only' && preset !== 'selected_languages') return;
  state.formData.selectedCountries = _obCountriesForPreset(preset);
  const namedPresets = ['everywhere', 'english_only', 'minimize_regulation', 'primary_lang_only', 'selected_languages'];
  const matched = namedPresets.find(p => _selectionMatchesPreset(p));
  state.formData.distributionPreset = matched || 'custom';
  _refreshObDistSection();
}

function setObDistPreset(preset) {
  if (state.formData.distributionPreset === preset) {
    // Toggle off — deselect the preset
    state.formData.distributionPreset = null;
  } else {
    state.formData.distributionPreset = preset;
    if (preset !== 'custom') {
      // Apply the preset's country list
      state.formData.selectedCountries = _obCountriesForPreset(preset);
    }
    // 'custom' keeps whatever countries are currently selected
  }
  _refreshObDistSection();
  if (typeof renderGuide === 'function') renderGuide();   // "Select target countries" reacts live
}

function _selectionMatchesPreset(preset) {
  const expected = new Set(_obCountriesForPreset(preset));
  const actual   = new Set(state.formData.selectedCountries || []);
  if (expected.size !== actual.size) return false;
  for (const c of expected) { if (!actual.has(c)) return false; }
  return true;
}

function toggleObCountry(code) {
  const arr = state.formData.selectedCountries;
  const idx = arr.indexOf(code);
  if (idx === -1) arr.push(code); else arr.splice(idx, 1);

  // Snap preset label to whichever named preset matches the new selection,
  // else 'custom'. english_only is checked before primary_lang_only so a
  // non-English-primary game whose manually-picked countries happen to be
  // English-speaking still snaps to the pill that's actually shown (see
  // _obResyncDistPresetIfLangDriven's own note on the same ordering).
  const namedPresets = ['everywhere', 'english_only', 'minimize_regulation', 'primary_lang_only', 'selected_languages'];
  const matched = namedPresets.find(p => _selectionMatchesPreset(p));
  state.formData.distributionPreset = matched || 'custom';

  // Update map + lang list; update chips in-place to preserve expand state
  renderObDistMap();
  updateObLangListWrap();
  _refreshCountryListInPlace();
  // Toggling a country can change which preset it snapped to (above) —
  // buildObExcludedChips (render.js) reads distributionPreset directly now,
  // so a full rebuild here is what picks that up; there's no separate flag
  // left to keep in sync.
  updateObExcludedSection();
  // Refresh preset pills
  document.querySelectorAll('.ob-preset-pill[data-preset]').forEach(btn => {
    btn.classList.toggle('is-active', btn.dataset.preset === state.formData.distributionPreset);
  });
  // Picking countries can flip the preset, and the preset is what the
  // checklist reads for Distribution.
  updateObSectionStates();
  if (typeof renderGuide === 'function') renderGuide();
}

// No longer a plain in-place class toggle. The countries list now sorts
// selected-first (buildObCountryChips, render.js), so toggling a country
// can change its own position in the list (a newly-selected country in the
// bottom half needs to jump to the top, alphabetically, not just re-mark
// itself where it already sits) — something re-marking classes on the
// existing DOM nodes can't do. Falls back to a full rebuild via
// buildObCountryChips instead, but reads the list's CURRENT expanded/
// collapsed state first and forces the rebuild to match it (forceExpanded),
// so clicking a country never snaps an already-open list shut — the one
// thing the old in-place approach existed to protect in the first place.
function _refreshCountryListInPlace() {
  const wrap = document.getElementById('ob-country-list-wrap');
  if (!wrap) return;
  const list = document.getElementById('ob-dist-country-list');
  const wasExpanded = list ? !list.classList.contains('hidden') : false;
  wrap.innerHTML = buildObCountryChips(wasExpanded);
}

// Clicking "Market" or "Gamers (approx.)" in the countries list header
// (buildObCountryChips, render.js). Either one sorts the ENTIRE country
// list. Selected countries used to float to the top and sorting only
// reordered within that grouping; removed by request — selection still
// shows per row, but it no longer overrides the sort.
//
// Re-clicking the column that's already active flips its direction —
// Market toggles A→Z / Z→A, Gamers (approx.) toggles biggest-first /
// smallest-first — rather than being a no-op. Clicking the OTHER column
// switches to it and resets dir to that column's own natural starting
// point (Market starts A→Z, Gamers starts biggest-first), so switching
// columns never lands on a direction the user didn't ask for. Reuses
// _refreshCountryListInPlace's own expand-state-preserving rebuild so
// sorting never collapses an open list, same as toggling a country.
function setObDistSort(mode) {
  const cur = state.obDistCountrySort || { by: 'name', dir: 'asc' };
  state.obDistCountrySort = (cur.by === mode)
    ? { by: mode, dir: cur.dir === 'desc' ? 'asc' : 'desc' }
    : { by: mode, dir: mode === 'gamers' ? 'desc' : 'asc' };
  _refreshCountryListInPlace();
}

function _refreshObDistSection() {
  renderObDistMap();
  updateObCountryList();
  updateObExcludedSection();
  updateObLangListWrap();
  // Refresh dist preset pill active states
  document.querySelectorAll('.ob-preset-pill[data-preset]').forEach(btn => {
    btn.classList.toggle('is-active', btn.dataset.preset === state.formData.distributionPreset);
  });
  // Update required-empty indicator on preset group
  const presetGroup = document.getElementById('ob-dist-preset-group');
  if (presetGroup) {
    presetGroup.classList.toggle('is-req-empty', !state.formData.distributionPreset);
  }
  updateObSectionStates();
}

function _refreshCountrySummary() {
  const el = document.querySelector('.ob-country-count');
  if (!el) return;
  const count = (state.formData.selectedCountries || []).length;
  el.textContent = `${count} ${count === 1 ? 'country' : 'countries'} selected`;
}

function updateObCountryList() {
  const el = document.getElementById('ob-country-list-wrap');
  if (el) el.innerHTML = buildObCountryChips();
}

// The "Regulation:" chips (buildObExcludedChips, render.js) — always a full
// rebuild, since which countries show here (and whether the block shows at
// all) depends on the active preset, not just which chips are on.
function updateObExcludedSection() {
  const el = document.getElementById('ob-dist-excluded-wrap');
  if (el) el.innerHTML = buildObExcludedChips();
}

function toggleObCountryList() {
  const table   = document.getElementById('ob-country-table');
  const chevron = document.getElementById('ob-country-chevron');
  if (!table) return;
  const nowExpanded = table.classList.toggle('is-expanded');
  if (chevron) chevron.innerHTML = nowExpanded ? _chevUp : _chevDown;
}

/* ── Localization handlers ───────────────────────────── */

function _computeLangPresetSelections(preset) {
  const fd      = state.formData;
  const primary = fd.primaryLanguage || 'en';
  const countries = fd.selectedCountries || [];

  // Aggregate gamers per non-primary language
  const langTotals = {};
  IOS_COUNTRIES.forEach(c => {
    if (!countries.includes(c.code) || c.lang === primary) return;
    langTotals[c.lang] = (langTotals[c.lang] || 0) + (c.gamers || 0);
  });
  const ranked = Object.entries(langTotals).sort(([,a],[,b]) => b - a).map(([l]) => l);

  if (preset === 'recommended')  return ranked.slice(0, 2);
  if (preset === 'primary_only') return [];
  if (preset === 'all_regions')  return ranked;
  return fd.localizations || [];
}

/* ── Localization picker handlers ────────────────────── */

function toggleLocPrimaryDropdown(event) {
  event.stopPropagation();
  const wrap = document.getElementById('loc-primary-wrap');
  if (!wrap) return;
  const isOpen = wrap.classList.contains('is-open');
  closeAllDropdowns();
  if (!isOpen) wrap.classList.add('is-open');
}

// Shared by selectLocPrimary below for both the App Store's own flat listing
// (state.formData) and Mac App Store's independent one (state.macAppStoreListing,
// when it exists) — promotes `lang`'s stored translation into whichever
// listing's own flat fields, stashing the outgoing primary's copy under its
// own language code first (only if it's staying around as a supported
// language — see selectLocPrimary's own comment). `blank` is that listing's
// own blank-entry shape helper (_iasBlankLocalizedText / _masBlankLocalizedText)
// — the two listings are identically shaped, so this works for either
// without caring which one it is, and never touches the other. `fields`
// restricts which of the four listing fields this call actually promotes —
// defaults to all four (the App Store's own call, and any other full
// listing); selectLocPrimary passes just ['description','releaseNotes'] for
// Mac App Store's call, since Title/Subtitle are shared with the App Store
// (MAS_SHARED_LISTING_FIELDS) and are already promoted once by the App
// Store's own call into the single shared storage — promoting them again
// here, into state.macAppStoreListing, would just write into fields nothing
// reads any more.
function _promoteLangPrimary(listing, oldPrimary, lang, oldPrimaryKept, blank, fields = ['title', 'subtitle', 'description', 'releaseNotes']) {
  if (!listing.localizedStoreText) listing.localizedStoreText = {};
  if (oldPrimaryKept) {
    const stash = listing.localizedStoreText[oldPrimary] || blank();
    fields.forEach(f => { stash[f] = listing[f] || ''; });
    listing.localizedStoreText[oldPrimary] = stash;
  }
  const incoming = listing.localizedStoreText[lang] || blank();
  fields.forEach(f => { listing[f] = incoming[f]; });
  delete listing.localizedStoreText[lang];
}

function selectLocPrimary(lang) {
  const fd = state.formData;
  const oldPrimary = fd.primaryLanguage || 'en';
  // Demote old primary into supported (if it's in the featured set and not already there)
  if (lang !== oldPrimary) {
    const locs = new Set(fd.localizations || []);
    const oldPrimaryKept = OB_LANG_FEATURED.includes(oldPrimary);
    if (oldPrimaryKept) locs.add(oldPrimary);
    locs.delete(lang); // new primary leaves supported
    fd.localizations  = [...locs];

    // Keep each language's App Store Product Page Preview Title/Subtitle/
    // Description/What's New attached to its own language code rather than
    // to whichever language happens to be "primary" right now — otherwise
    // switching Primary Language would make the new primary's preview
    // suddenly show the OLD primary's text (since the preview always reads
    // the flat fields for whichever language is primary), silently hiding
    // any translation already written for the incoming primary language.
    _promoteLangPrimary(fd, oldPrimary, lang, oldPrimaryKept, _iasBlankLocalizedText);

    fd.primaryLanguage = lang;
    // Every supporting language's Title/Subtitle/Description/What's New is
    // now stale against the newly-promoted primary's text (including the
    // language just stashed above, which is a regular supported language
    // again) — refresh everything from the new primary, since nothing
    // protects any supporting language's copy from this update.
    _iasPropagateAllFields();

    // Mac App Store shares this same primary-language promotion — its own
    // independent listing (when it exists) goes through the identical
    // stash/promote/re-propagate dance, on its own storage, so switching
    // Primary Language never lets Mac App Store's preview show the App
    // Store's text (or vice versa).
    if (state.macAppStoreListing) {
      _promoteLangPrimary(state.macAppStoreListing, oldPrimary, lang, oldPrimaryKept, _masBlankLocalizedText, ['description', 'releaseNotes']);
      _masPropagateAllFields();
    }

    // Mac App Store Full's own independent listing goes through the same
    // stash/promote/re-propagate dance, on its own storage -- all four
    // fields this time (Title/Subtitle included), since none of them are
    // shared with any other platform here (see macFullAppStoreListing's
    // own comment, state.js).
    if (state.macFullAppStoreListing) {
      _promoteLangPrimary(state.macFullAppStoreListing, oldPrimary, lang, oldPrimaryKept, _macFullBlankLocalizedText);
      _macFullPropagateAllFields();
    }

    // Steam's own Store Page Preview - Prototype listing text (Short
    // Description/Developer/Publisher/About This Game) shares this same
    // stash/promote/re-propagate dance, against its own independent storage
    // (state.webSite.localizedStoreText) — always present (state.webSite is
    // never lazily created the way state.macAppStoreListing is), so this
    // call is unconditional. Title is NOT included here — it's promoted once
    // by the App Store's own call above, into the single shared storage
    // every platform's Title reads (see STEAM_SHARED_LISTING_FIELDS, app.js).
    _promoteLangPrimary(state.webSite, oldPrimary, lang, oldPrimaryKept, _steamBlankLocalizedText, ['description', 'developer', 'publisher', 'aboutGame']);
    _steamPropagateAllFields();
  }
  closeAllDropdowns();
  updateObLangListWrap();
  // Keep a language-driven Distribution preset ('primary_lang_only' /
  // 'selected_languages') in sync with the new primary language.
  _obResyncDistPresetIfLangDriven();
}

// Legacy alias — kept for any older callers
function setObPrimaryLang(lang) { selectLocPrimary(lang); }

// Every "a new supporting language now exists" call site (toggleObLang,
// setObLangPreset, applyObLangPreset, addLangFromSearch below) needs to
// give that language an initial translation of every already-authored
// primary-language field right away, for every platform/feature that
// keeps its own per-language overrides (the app's own Title/Subtitle/
// Description/What's New, Mac App Store's and Mac App Store Full's and
// Steam's own independent listings, IAP Localizations for both IAP-product
// pickers, and Mac App Store's Achievement Localizations) — otherwise a
// field/product/achievement saved BEFORE this language existed shows a
// blank card for it until whatever last touched it happens to be edited
// again. Bundled into one helper — rather than each call site re-listing
// every *PropagateAllFields function on its own — specifically so a future
// propagatable feature only ever needs to be wired in HERE, not hunted
// down across every "a language was just added" call site (this is
// exactly the bug IAP Localizations and Achievement Localizations both had
// until now: every one of the four call sites below had to independently
// remember to call their own PropagateAllFields, and none of them did).
// Every function called here already loops over ALL of
// state.formData.localizations on its own, and no-ops per-language for
// anything already in sync — so calling this once covers however many
// languages just got added, whether one at a time or in bulk.
function _propagateAllLocalizationFeatures() {
  _iasPropagateAllFields();
  _masPropagateAllFields();       // no-op until Mac App Store is activated
  _macFullPropagateAllFields();   // no-op until Mac App Store Full is activated
  _steamPropagateAllFields();
  _iapLocPropagateAllFields();
  _masIapLocPropagateAllFields(); // no-op until Mac App Store has saved IAP products
  _macFullIapLocPropagateAllFields(); // no-op until Mac App Store Full has saved IAP products
  _masAchLocPropagateAllFields(); // no-op until Mac App Store has saved achievements
  _iasAchLocPropagateAllFields(); // no-op until the App Store has saved achievements
  _macFullAchLocPropagateAllFields(); // no-op until Mac App Store Full has saved achievements
}

function setObLangPreset(preset) {
  const beforeLangs = state.formData.localizations || [];
  state.formData.localizationPreset = preset;
  state.formData.localizations      = _computeLangPresetSelections(preset);
  updateObLangListWrap();
  // Bulk selection bypasses toggleObLang entirely, so any newly-added
  // language needs its own initial translation pass triggered here.
  _propagateAllLocalizationFeatures();
  // Same reasoning as toggleObLang — bulk selection also bypasses the
  // per-language Steam localization check, so run it for every language
  // this preset newly added.
  _checkSteamLocalizedDescriptionForNewLangs(beforeLangs, state.formData.localizations);
  // Update pill states
  document.querySelectorAll('.ob-preset-pill').forEach(btn => {
    const presetMap = {
      'Recommended':'recommended',
      'Primary Language only':'primary_only',
      'Localize for all selected regions':'all_regions',
    };
    const pid = presetMap[btn.textContent.trim()];
    if (pid) btn.classList.toggle('is-active', pid === preset);
  });
}

function applyObLangPreset() {
  // Re-apply current lang preset when primary language changes
  const beforeLangs = state.formData.localizations || [];
  const preset = state.formData.localizationPreset || 'recommended';
  state.formData.localizations = _computeLangPresetSelections(preset);
  updateObLangListWrap();
  _propagateAllLocalizationFeatures();
  _checkSteamLocalizedDescriptionForNewLangs(beforeLangs, state.formData.localizations);
}

function toggleObLang(lang) {
  const primary = state.formData.primaryLanguage || 'en';
  if (lang === primary) return;
  const arr = state.formData.localizations || [];
  const idx = arr.indexOf(lang);
  if (idx === -1) {
    arr.push(lang);
    state.formData.localizations = arr;
    // Newly-added language — give it an initial translation of every
    // already-authored primary-language field right away rather than
    // waiting for those fields to change again.
    _propagateAllLocalizationFeatures();
    // If this game is Steam-linked and its store page has been localized
    // into this language, prefer Steam's own "About This Game" copy for the
    // Description field over the Claude translation just triggered above
    // (see _checkSteamLocalizedDescription — it's async and, if it finds a
    // genuine localization, overwrites the field after the fact). Same idea
    // for Steam's own Localization Review fields (Title/Short Description/
    // Developer/Publisher/About This Game) via _checkSteamLocalizedListing.
    // Same idea again for Mac App Store's Achievement Localizations, via
    // _checkSteamLocalizedAchievements.
    _checkSteamLocalizedDescription(lang);
    _checkSteamLocalizedListing(lang);
    _checkSteamLocalizedAchievements(lang);
    _checkIosLocalizedAchievements(lang);
    _checkMacFullLocalizedAchievements(lang);
  } else {
    arr.splice(idx, 1);
    state.formData.localizations = arr;
  }
  // Full re-render so the Shipmate tip ! badge moves to the next best candidate
  updateObLangListWrap();
  // Keep a language-driven Distribution preset ('primary_lang_only' /
  // 'selected_languages') in sync with the new supported-language set.
  _obResyncDistPresetIfLangDriven();
}

function _refreshLangListInPlace() {
  const selected = new Set(state.formData.localizations || []);
  // Update chip states in-place
  document.querySelectorAll('#loc-chips .loc-chip:not(.loc-chip-add)').forEach(chip => {
    const onclick = chip.getAttribute('onclick') || '';
    const m = onclick.match(/toggleObLang\('([^']+)'\)/);
    if (!m) return;
    const lang = m[1];
    const isOn = selected.has(lang);
    chip.classList.toggle('is-on', isOn);
  });
}

function updateObLangListWrap() {
  const el = document.getElementById('ob-lang-list-wrap');
  if (el) el.innerHTML = buildObLangList();
}

function updateObLangRecs() { updateObLangListWrap(); } // alias for old callers

function toggleObLangList(btn) {
  const list = document.getElementById('ob-lang-list');
  if (!list) return;
  const expanded = list.classList.toggle('is-expanded');
  btn.innerHTML = expanded
    ? `<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="18 15 12 9 6 15"/></svg> Show fewer languages`
    : `<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg> Show more languages`;
}

async function initObDistMap() {
  // Populate selectedCountries from preset only if a preset is already chosen
  const preset = state.formData.distributionPreset;
  if (!state.formData.selectedCountries?.length && preset && preset !== 'custom') {
    state.formData.selectedCountries = _obCountriesForPreset(preset);
    updateObLangRecs();
  }

  const container = document.getElementById('ob-dist-map-container');
  if (!container) return;

  if (!_worldTopology) {
    container.innerHTML = '<div class="world-map-loading">Loading map…</div>';
    try {
      const res = await fetch('https://cdn.jsdelivr.net/npm/world-atlas@2/countries-110m.json');
      _worldTopology = await res.json();
    } catch (e) {
      container.innerHTML = '<div class="world-map-loading">Map unavailable offline</div>';
      return;
    }
  }
  renderObDistMap();
}

function renderObDistMap() {
  const container = document.getElementById('ob-dist-map-container');
  if (!container || !_worldTopology) return;

  const W = container.offsetWidth || 480;
  const selected = new Set(
    (state.formData.selectedCountries || [])
      .map(code => (IOS_COUNTRIES.find(c => c.code === code) || {}).num)
      .filter(Boolean)
  );
  _drawMap(container, W, selected, new Set());
}

function updateObLangRecs() {
  const el = document.getElementById('ob-lang-recs');
  if (el) el.innerHTML = buildObLangRecs();
}

/* ── World Map ───────────────────────────────────────── */

let _worldTopology = null;  // cached fetch

async function initWorldMap() {
  const container = document.getElementById('world-map-container');
  if (!container) return;

  if (!_worldTopology) {
    container.innerHTML = '<div class="world-map-loading">Loading map…</div>';
    try {
      const res = await fetch('https://cdn.jsdelivr.net/npm/world-atlas@2/countries-110m.json');
      _worldTopology = await res.json();
    } catch (e) {
      container.innerHTML = '<div class="world-map-loading">Map unavailable offline</div>';
      return;
    }
  }
  renderWorldMap();
}

function updateWorldMap() {
  if (_worldTopology) renderWorldMap();
}

function renderWorldMap() {
  const container = document.getElementById('world-map-container');
  if (!container || !_worldTopology || typeof d3 === 'undefined' || typeof topojson === 'undefined') return;

  const W = container.offsetWidth || 480;

  // Build set of active numeric ISO codes
  const activeCodes = new Set();
  const primary = state.formData.primaryLanguage || 'en';
  const extras  = state.formData.localizations   || [];
  [primary, ...extras].forEach(lang => {
    (LANG_COUNTRY_CODES[lang] || []).forEach(c => activeCodes.add(c));
  });

  // Build primary-language-only set for a slightly different shade
  const primaryCodes = new Set((LANG_COUNTRY_CODES[primary] || []).map(Number));

  _drawMap(container, W, activeCodes, primaryCodes);
}

/* ── Shared map renderer ─────────────────────────────── */
// activeCodes  : Set of numeric ISO codes to highlight (active blue)
// primaryCodes : Set of numeric ISO codes for primary shade (brighter blue)
function _drawMap(container, W, activeCodes, primaryCodes) {
  if (!_worldTopology || typeof d3 === 'undefined' || typeof topojson === 'undefined') return;

  // Natural Earth projection fits ~2:1 width-to-height; use 0.50 for full uncropped world
  const H = Math.round(W * 0.50);

  /* Colours come from the stylesheet (the --map-* block next to
     .world-map-container), not from hexes here. The container's background and
     this ocean must be the same value — the container is what the user sees
     while the topology is still downloading — and two copies of a colour is
     two chances to change only one of them.
     C_BORDER is the ocean on purpose: the country outlines are drawn as gaps,
     not as lines, so they read as water between the landmasses. */
  const _mapVar = (n, fallback) => {
    const v = getComputedStyle(document.documentElement).getPropertyValue(n).trim();
    return v || fallback;
  };
  const C_OCEAN    = _mapVar('--map-ocean',   '#0a0a0a');
  const C_INACTIVE = _mapVar('--map-land',    '#1e2230');
  const C_ACTIVE   = _mapVar('--map-active',  '#009AFF');
  const C_PRIMARY  = _mapVar('--map-primary', '#52BAFF');
  const C_BORDER   = C_OCEAN;

  const projection = d3.geoNaturalEarth1()
    .scale(W / 5.5)
    .translate([W / 2, H / 2]);

  const path      = d3.geoPath().projection(projection);
  const countries = topojson.feature(_worldTopology, _worldTopology.objects.countries);
  const borders   = topojson.mesh(_worldTopology, _worldTopology.objects.countries, (a, b) => a !== b);

  const svg = d3.create('svg')
    .attr('viewBox', `0 0 ${W} ${H}`)
    .attr('width',  W)
    .attr('height', H)
    .style('display', 'block');

  // Ocean background
  svg.append('path')
    .datum({ type: 'Sphere' })
    .attr('d', path)
    .attr('fill', C_OCEAN);

  // Country fills
  svg.append('g')
    .selectAll('path')
    .data(countries.features)
    .join('path')
      .attr('d', path)
      .attr('fill', d => {
        const code = +d.id;
        if (!activeCodes.has(code))  return C_INACTIVE;
        if (primaryCodes.has(code))  return C_PRIMARY;
        return C_ACTIVE;
      })
      .attr('stroke', 'none');

  // Country borders (thin, dark)
  svg.append('path')
    .datum(borders)
    .attr('d', path)
    .attr('fill', 'none')
    .attr('stroke', C_BORDER)
    .attr('stroke-width', 0.4);

  container.innerHTML = '';
  container.appendChild(svg.node());
}

function pickTiming(value) {
  state.formData.releaseTiming = value;
  // Pre-fill launch date to 14 days from today when first selecting specific_date
  if (value === 'specific_date' && !state.formData.releaseDate) {
    const d = new Date();
    d.setDate(d.getDate() + 14);
    state.formData.releaseDate = d.toISOString().split('T')[0]; // YYYY-MM-DD
  }
  // Update chip active state
  document.querySelectorAll('.ob-timing-chip').forEach(chip => {
    chip.classList.toggle('is-on', chip.dataset.timing === value);
  });
  // Re-render the content area
  _refreshTimingContent();
}

function _refreshTimingContent() {
  const content = document.getElementById('ob-timing-content');
  if (!content) return;
  content.innerHTML = buildReleaseTimingContent();
  // Restore date value in newly created input (state already has it)
  const dateInput = document.getElementById('ob-date');
  if (dateInput && state.formData.releaseDate) dateInput.value = state.formData.releaseDate;
}

/* ── Scenario widget — game search ───────────────────────── */

function _renderScenarioSection() {
  const wrap = document.getElementById('ob-scenario-wrap');
  if (wrap) wrap.innerHTML = buildScenarioWidget();
  // The confirmed note lives in the Description label row, not in this wrap
  // (see _giImportNote). Repainted from the same call so the widget and the
  // note cannot disagree about whether an import happened — the one thing a
  // second, separate repaint would eventually get wrong.
  _giRenderImportNote();
}

/* Writes the import note into the slot the Description head always emits.
   A write, never an insert: the slot exists in both states and the row it
   sits in is a fixed 18px, so nothing below it can move. */
function _giRenderImportNote() {
  const slot = document.getElementById('ob-desc-import');
  if (!slot) return;
  slot.innerHTML = _giImportNote();
}

/* One field, two marks that can never both be up. The flag is transient by
   design — never persisted, never read by anything but these two — so a reload
   during a fetch cannot leave the form claiming to be collecting something.

   IT TOUCHES THE DOM, IT DOES NOT RENDER, which is `gcalWaitHover`'s rule and
   is load-bearing here for a sharper reason: `renderDetails` rebuilds this pane
   with innerHTML, so a render would throw away a half-typed title and its caret
   every time a request started or finished. Both halves are already in the
   markup — the import slot is emitted empty and the wait overlay is emitted in
   both states — so this is one write and one class. */
function _setDescLoading(on) {
  state.descLoading = !!on;
  _giRenderImportNote();
  document.getElementById('ob-desc-group')
    ?.classList.toggle('is-waiting', state.descLoading);
}

function _triggerScenarioSearch() {
  const title = (state.formData.title || '').trim();
  if (!title) {
    state.liveSearch = { status: 'error', found: false, error: 'NO_TITLE' };
    _renderScenarioSection();
    const wrap = document.getElementById('ob-scenario-wrap');
    const msg  = wrap ? wrap.querySelector('.ob-live-not-found') : null;
    if (msg) msg.textContent = "Enter your game title above first — then we'll search for it.";
    return;
  }
  state.liveSearch = { status: 'loading', found: false };
  _renderScenarioSection();
  searchGameByTitle(title)
    .then(result => {
      state.liveSearch = {
        status:      'done',
        found:       !!result.found,
        title:       result.title       || null,
        description: result.description || null,
        source:      result.source      || null,
        allStores:   result.allStores   || [],
        confidence:  result.confidence  || 0,
        confirmed:   false,
      };
      _renderScenarioSection();
    })
    .catch(err => {
      console.warn('[Scenario Search] failed:', err.message);
      state.liveSearch = { status: 'error', found: false, error: err.message };
      _renderScenarioSection();
    });
}

function setGameScenario(scenario) {
  // Toggle off if same chip clicked again
  if (state.formData.gameScenario === scenario) {
    state.formData.gameScenario = null;
    state.liveSearch = null;
    _renderScenarioSection();
    return;
  }

  state.formData.gameScenario = scenario;
  state.liveSearch = null;
  _renderScenarioSection();
  updateObSectionStates();

  // Scenarios that need a store search
  if (scenario === 'new_platform' || scenario === 'update') {
    _triggerScenarioSearch();
  }
}

function confirmGameImport() {
  const ls = state.liveSearch;
  if (!ls || !ls.found || !ls.description) return;

  // Pre-populate the description field
  state.formData.description = ls.description;
  _wsPropagateAboutGame(ls.description);
  _macFullPropagateDescription(ls.description);
  _applePropagateDescription(ls.description);
  const descEl = document.getElementById('ob-desc');
  if (descEl) {
    descEl.value = ls.description;
    charCount('ob-desc-count', ls.description, 4000);
  }
  _iasTriggerAutoTranslate('description', ls.description);

  // Auto-activate platforms where the game was found — replace any prior auto-selection
  // STORE_NAME_TO_PID is defined in claude.js (loaded first)
  const foundPids = [...new Set(
    (ls.allStores || []).map(s => STORE_NAME_TO_PID[(s || '').toLowerCase().trim()] || s)
      .filter(pid => !!PLATFORMS[pid] && !COMING_SOON_PLATFORMS.has(pid))
  )];
  if (foundPids.length) {
    state.activePlatforms.clear();
    foundPids.forEach(pid => {
      state.activePlatforms.add(pid);
      if (!state.platformStepStatus[pid]) {
        state.platformStepStatus[pid] = makeEmptyPlatformSteps()[pid] || {};
      }
    });
    const gridWrap = document.getElementById('ob-plat-grid-wrap');
    if (gridWrap) {
      gridWrap.innerHTML = buildObPlatTilesHTML();
      gridWrap.classList.remove('is-req-empty');
    }
    renderOnboardingFooter();
    updateObSectionStates();
  }

  ls.confirmed = true;
  _renderScenarioSection();
}

function rejectGameImport() {
  state.liveSearch = { status: 'done', found: false };
  _renderScenarioSection();
  const wrap = document.getElementById('ob-scenario-wrap');
  const msg  = wrap ? wrap.querySelector('.ob-live-not-found') : null;
  if (msg) msg.textContent = "Got it — fill in the description below and we'll work from that.";
}

/* ── Dashboard timeline handlers ─────────────────────────── */

function _refreshDashTimeline() {
  const wrap = document.getElementById('dash-timeline-wrap');
  if (!wrap) return;
  wrap.innerHTML = buildDashboardTimeline();
}

function dashPickTiming(value) {
  state.formData.releaseTiming = value;
  if (value === 'specific_date' && !state.formData.releaseDate) {
    const d = new Date();
    d.setDate(d.getDate() + 14);
    state.formData.releaseDate = d.toISOString().split('T')[0];
  }
  _refreshDashTimeline();
}

function dashSetDate(value) {
  state.formData.releaseDate = value;
  _refreshDashTimeline();
}

/* ── IGDB title picklist ─────────────────────────────────── */

let _titleSearchTimer  = null;
let _closePicklistTimer = null;

function _renderTitlePicklist() {
  const el = document.getElementById('ob-title-picklist');
  if (el) el.innerHTML = buildTitlePicklist();
}

// Called from picklist row onmousedown — prevents blur from closing
// the list before the click registers
function _cancelPicklistClose() {
  clearTimeout(_closePicklistTimer);
}

// Called from title input onblur — close picklist shortly after
function _onTitleBlur() {
  _closePicklistTimer = setTimeout(() => {
    state.titlePicklist = [];
    state.titlePicklistError = null;
    _renderTitlePicklist();
  }, 200);
}

// Debounce-search on every title keystroke
function _onTitleFocus(value) {
  // If there's already text when the field is focused, show the picklist immediately
  const trimmed = (value || '').trim();
  if (trimmed.length >= 3 && !state.titlePicklist?.length) {
    _runTitlePicklist(trimmed);
  } else if (state.titlePicklist?.length) {
    _renderTitlePicklist(); // re-show if results are cached
  }
}

function _onTitleInputScenario(value) {
  // If user edits after confirming, clear confirmation so search can re-run
  if (state.liveSearch && state.liveSearch.confirmed) {
    state.liveSearch = null;
    _renderScenarioSection();
  }
  clearTimeout(_titleSearchTimer);
  const trimmed = (value || '').trim();
  if (trimmed.length < 3) {
    state.titlePicklist = [];
    state.titlePicklistError = null;
    _renderTitlePicklist();
    return;
  }
  _titleSearchTimer = setTimeout(() => _runTitlePicklist(trimmed), 150);
}

async function _runTitlePicklist(title) {
  // (No IGDB_CLIENT_ID gate anymore — search goes through our own backend,
  // IGDB_SEARCH_ENDPOINT in claude.js, which needs no client-side key.)
  try {
    const results = await igdbSearch(title);
    // Only apply if the title hasn't changed since the search started
    if ((state.formData.title || '').trim() === title) {
      state.titlePicklist = results;
      state.titlePicklistError = null;
      _renderTitlePicklist();
    }
  } catch (err) {
    console.warn('[Picklist] IGDB search failed:', err.message);
    state.titlePicklist = [];
    // Distinct from "no games matched" — buildTitlePicklist (render.js)
    // shows this so a proxy/network/auth failure doesn't look identical to
    // a genuine no-results title (see titlePicklistError, state.js).
    state.titlePicklistError = err.message || 'Search failed';
    _renderTitlePicklist();
  }
}

// Clears an auto-scraped Key Art slot (state.uploads.<fieldName>) when a
// new title is picked — used instead of a bare `state.uploads.x = null`
// because these slots don't hold the image itself, just a { ref: id }
// pointer into the shared asset pool (state.assets — see assets.js). The
// Assets tab's unified library (_smLibraryHTML, further below) renders
// every record IN THAT POOL, regardless of whether any state.uploads.*
// slot still points at it — so nulling the pointer alone only hides the
// previous game's art from this one slot, it doesn't stop the actual
// image from still showing up in the library grid, permanently, as an
// orphaned leftover nothing ever removes. smRemove (assets.js) deletes the
// pool record itself and, as a side effect, also nulls every state.uploads
// slot (and filters every screenshots array) that still referenced it — so
// calling it here does the whole job in one step. Only ever removes what
// the developer didn't choose themselves (smIsOwn) — a manual upload for
// this slot is never deleted just because a different title was picked.
// Falls back to a bare null for the rare legacy shape that predates the
// asset pool (no .ref at all, so there's no pool record to remove).
function _smClearAutoField(fieldName) {
  const v = state.uploads[fieldName];
  if (!v || smIsOwn(v)) return;
  if (v.ref) smRemove(v.ref);
  else state.uploads[fieldName] = null;
}

// Same reasoning as _smClearAutoField above, applied to the screenshot grid:
// removes the underlying pool record for every currently-auto-imported
// screenshot (not just its entry in state.uploads.screenshots) before a new
// batch replaces them, so a previous game's screenshots stop showing up in
// the Assets library once a different title is picked. smRemove's own
// filtering of state.uploads.screenshots/state.webSite.screenshots means
// the .filter(smIsOwn) each caller already does afterward becomes a no-op
// safety net for any legacy (pre-pool) entry with no .ref, rather than the
// only thing standing between a stale asset and the pool.
function _smClearAutoScreenshots() {
  (state.uploads.screenshots || []).forEach(s => {
    if (s && s.ref && !smIsOwn(s)) smRemove(s.ref);
  });
}

/* EVERY SCRAPED ASSET, GONE — because the game they described is gone.

   The two clearers above are per-slot and were called piecemeal: picking a
   new title cleared the four Key Art slots by name, and screenshots only got
   cleared indirectly, later, inside whichever _fillScreenshotGridFrom* call
   happened to run. That left two ways to keep a dead game's art: pick a title
   whose Steam fetch then fails (no fill runs, so the previous game's
   screenshots stay), or edit the title by hand (nothing cleared at all,
   because only the picklist had a clearing path).

   So this is the whole sweep, and it ends with a pass over the pool itself
   rather than a list of slot names. A named-slot list can only ever delete
   what someone remembered to name — the pool knows what it actually holds,
   and `origin` already records how each record got there ('upload' when the
   developer chose it, 'steam'/'igdb' when Shipmate fetched it). Anything not
   uploaded by hand described the old title and goes.

   MANUAL UPLOADS SURVIVE, which is the one invariant here: smIsOwn/origin is
   what separates them, and a developer's own screenshot is never collateral
   for a title edit. smRemove does the rest of the bookkeeping — it deletes
   the pool record AND nulls every state.uploads slot pointing at it AND
   filters both screenshot arrays — so no slot is left holding a dangling ref.

   Returns whether it actually removed anything, so callers on a hot path
   (every keystroke in the title field) can skip their re-render when there
   was nothing to clear. */
function _smClearAllScrapedAssets() {
  if (!state.uploads) state.uploads = {};
  const before = (state.assets || []).length;
  const hadSteamTrailer = !!state.uploads.steamTrailer;

  ['steamCapsuleImage', 'steamHeaderImage', 'steamKeyArtCapsule', 'steamKeyArtHero']
    .forEach(_smClearAutoField);
  _smClearAutoScreenshots();
  if (Array.isArray(state.uploads.screenshots)) {
    state.uploads.screenshots = state.uploads.screenshots.filter(smIsOwn);
  }
  // Never adopted into the pool — a plain { name, thumbnail, hlsUrl } lifted
  // straight off Steam's movies[0], so there is no record for smRemove to
  // find and the slot has to be nulled directly.
  state.uploads.steamTrailer = null;

  // The sweep. .slice() because smRemove splices the array being walked.
  (state.assets || []).slice()
    .filter(a => a && a.origin && a.origin !== 'upload')
    .forEach(a => smRemove(a.id));

  return hadSteamTrailer || (state.assets || []).length !== before;
}

function selectPicklistItem(igdbId) {
  const item = (state.titlePicklist || []).find(x => x.id === igdbId);
  if (!item) return;

  // Close picklist immediately
  clearTimeout(_closePicklistTimer);
  state.titlePicklist = [];
  _renderTitlePicklist();

  // Any language previously flagged as "Steam-authoritative" for the
  // Description field (see _checkSteamLocalizedDescription) only means
  // something for the PREVIOUSLY-selected game's own Steam store page.
  // Normally this expires on its own the moment the new game's Description
  // loads (_iasTriggerAutoTranslate compares against the cached source
  // text, which won't match), but that comparison would wrongly treat the
  // flag as still valid in the unlikely case where the new game's initial
  // Description happens to be textually identical to the old game's — so
  // clear it explicitly here too, as a defense-in-depth backstop, whether
  // or not this new title turns out to be Steam-linked itself.
  _clearSteamDescriptionAuthority();

  // Set game title
  state.formData.title = item.name;
  // Picking a game here is exactly the kind of title change syncField's own
  // oninput handler would normally catch (see _syncProjectBarTitle, further
  // above) — but this path sets state.formData.title directly rather than
  // going through syncField, so without this call the top-right project bar
  // (both the closed chip and, if open, the dropdown's active row) would
  // keep showing whatever it showed before this pick — "Untitled Game" on a
  // fresh project — until some unrelated action happened to re-render it.
  _syncProjectBarTitle(item.name);
  const titleEl = document.getElementById('ob-title');
  if (titleEl) {
    titleEl.value = item.name;
    charCount('ob-title-count', item.name, 30);
  }
  _iasPropagateTitle(item.name);

  // Clear whatever's already in Steam's "Select Key Art" section — Capsule
  // Image, Header Image, IGDB Cover Art, Library Hero — before this new
  // selection's own auto-fill (below) has a chance to run, AND remove the
  // previous game's own copies from the shared asset pool itself (see
  // _smClearAutoField above), not just from these four slots — otherwise
  // they'd go on sitting in the Assets tab's library grid forever, orphaned
  // but still visible, even after this function moves on to a different
  // game entirely. Only clears/removes auto-filled art; a manual upload for
  // one of these slots is preserved, same convention the screenshot grid
  // uses below (_fillScreenshotGridFromIgdb/FromSteam via smIsOwn) — a
  // developer who's deliberately uploaded their own art for this slot
  // shouldn't have it silently wiped just because they picked a different
  // title in the picklist. Doing this eagerly (not inside the async
  // appliers below) also means a fast re-pick can't race a slow-resolving
  // previous fetch into clobbering the new selection: by the time any of
  // those promises settle, the stale-title guard already in each of them
  // (comparing against state.formData.title) rejects a late write for the
  // old game anyway, but clearing here means the user never sees the old
  // game's auto-filled art flash on screen in the meantime either.
  // Now the whole sweep rather than the four Key Art slots by name — this
  // also takes the screenshot grid and the trailer preview, and finishes on
  // the asset pool itself so nothing scraped for the previous title survives
  // in the Assets library. See _smClearAllScrapedAssets for the argument;
  // manual uploads are still protected by exactly the same smIsOwn/origin
  // test the four named calls used to apply.
  state.uploads = state.uploads || {};
  _smClearAllScrapedAssets();
  // Per product decision: picking a new title always resets Mac App Store's
  // Game Center Achievements — unlike the Key Art slots above, a manually
  // entered achievement is NOT preserved across a title switch, since a new
  // game means a new (or absent) achievement set entirely. This is cleared
  // unconditionally and eagerly, before _applySteamAchievements' own async
  // Steam lookup below has a chance to run, so the previous title's
  // achievements can never linger or flash on screen for the new one. If
  // the new title has Steam achievements, _applySteamAchievements
  // repopulates the list; if not (or the lookup fails), it's left empty.
  state.macGameCenterAchievements = [];

  // Where the rest of this game's data comes from depends on whether the
  // IGDB search backend gave us a Steam app id for this title (item.
  // steamAppId, sourced straight from that endpoint's own steam_id field —
  // see _igdbSearchRaw, claude.js). If it did, Steam is treated as the
  // source of truth for Description / Web Factsheet Developer / Web
  // Factsheet Publisher / Web Factsheet Links "Official Website" / Web
  // "About This Game" / screenshots — Steam's own store-page copy and full
  // screenshot set is generally more complete and current than IGDB's
  // community-submitted summary/screenshots for a title
  // that's actually live on Steam. That fetch (fetchShipmateGame in claude.js,
  // against Shipmate's own /game endpoint) is async, so _applySteamAboutData fills these
  // fields in shortly after this function returns, not immediately; if the
  // fetch fails, it falls back to filling from IGDB's own summary/
  // screenshots (via the same helpers used in the no-Steam-app-id branch
  // below) rather than leaving the About section and screenshot grid empty.
  // Having item.steamAppId in hand up front doesn't mean Steam data has
  // arrived yet, since fetchShipmateGame itself is still async — fill
  // the screenshot grid baseline from IGDB immediately so it isn't left
  // blank, then let Steam's own screenshots upgrade it once that resolves.
  //
  // Description is handled differently: when this title has a Steam app id,
  // Steam's own "About This Game" text is the eventual source of truth for
  // it (see _applySteamAboutData below) — filling Description from IGDB's
  // summary here first would just flash that shorter/different text on
  // screen for the moment before the Steam fetch overwrites it. So that
  // fill is deferred until _applySteamAboutData settles one way or the
  // other (it has its own IGDB-summary fallback if the fetch fails — see
  // its own comment), and IGDB's summary is used immediately only when
  // there's no Steam app id for this title at all.
  const hasSteamAppId = !!item.steamAppId;
  if (!hasSteamAppId && item.summary) _fillDescriptionField(item.summary, 'IGDB');
  _fillScreenshotGridFromIgdb(item.screenshots || []);
  // No Steam app id for this title — go straight to IGDB's own screenshots
  // rather than leaving the grid empty (item.screenshots above is always []
  // now; see _igdbSearchRaw in claude.js).
  if (!hasSteamAppId) _applyIgdbScreenshotFallback(item.id, item.name);
  // Clear any Steam localization cache/content left over from a
  // previously-selected game: state.steamLocInfo (the comparison baseline)
  // so a later language-add on THIS title can't be checked against the
  // wrong game's Steam data before (or if) a real Steam link resolves below,
  // AND the actual per-language Steam Localization Review content itself
  // (state.webSite.localizedStoreText — Short Description/Developer/
  // Publisher/About This Game overrides, see state.js) plus its scratch
  // review-UI state (back-translations, undo history, in-flight translate
  // trackers) — otherwise the previous game's written/scraped/translated
  // text would still be sitting in the Localization Review cards for
  // whatever languages this new title happens to share, until each field
  // happened to get individually re-translated. View-only state
  // (steamPreviewLang/steamLocReviewField/steamLocReviewMode) and user
  // preferences (steamAutoTranslateFields/steamReviewSettingsOpen) aren't
  // game-specific, so those are deliberately left alone.
  state.steamLocInfo = null;
  // The previous title's "Steam has finished with this language" record goes
  // with it. Left behind, the new game's languages would look already settled
  // and fall straight through to machine translation instead of waiting for
  // their own scrape (see _steamMayStillSupply).
  state.steamLocSettled = null;
  state.steamLocPending = null;
  if (!state.webSite) state.webSite = {};
  state.webSite.localizedStoreText = {};
  state.steamLocReviewBackTranslation = {};
  state.steamLocReviewUndoHistory = { real: {}, draft: {} };
  state.steamTranslateStatus = {};
  state.steamTranslatePendingLangs = {};
  // Mac App Store's own independent Localization Review content is the same
  // kind of stale-content risk as Steam's above, just one level further up:
  // state.macAppStoreListing (Description/Release Notes + their own
  // localizedStoreText) is seeded ONCE from formData the first time Mac App
  // Store is activated (seedMacAppStoreListing) and never touched again —
  // so if it was already seeded for a previously-selected game and Mac App
  // Store stays active for this new one, it would otherwise keep showing
  // the OLD game's Description/Release Notes and translations indefinitely.
  // Nulling it here lets it reseed fresh from THIS game's data — either via
  // _refreshLocalizationForNewGame below (once Description has its final
  // value) or, failing that, the next time the Mac App Store step is
  // opened. Its scratch review-UI state is cleared the same way Steam's is
  // above, same reasoning.
  state.macAppStoreListing = null;
  state.masLocReviewBackTranslation = {};
  state.masLocReviewUndoHistory = { real: {}, draft: {} };
  state.masTranslateStatus = {};
  state.masTranslatePendingLangs = {};
  // No Steam app id for this title (see hasSteamAppId above) —
  // Description/webSite fields already have their final value from the
  // IGDB-only fill just above, so this is the only chance to bring already-
  // selected supporting languages' Steam/Mac App Store Localization Review
  // cards up to date for this game (see _refreshLocalizationForNewGame's own
  // comment for why nothing else does this on a game switch). When there IS
  // a Steam app id, _applySteamAboutData calls this itself once Steam's
  // data (or the lack of it) is known instead — see its own comment.
  if (!hasSteamAppId) _refreshLocalizationForNewGame();

  // Drive Steam enrichment straight off item.steamAppId — sourced directly
  // from IGDB_SEARCH_ENDPOINT's own steam_id field (see _igdbSearchRaw,
  // claude.js), so there's no separate app-id lookup to make anymore. This
  // used to resolve the app id with a follow-up query (_igdbFetchSteamAppId,
  // claude.js) straight to IGDB itself via IGDB_ENDPOINT/_cors() — that
  // function was deleted in v6.62, having had no callers since, and is no
  // longer called from
  // here, which removes both the extra network round-trip and this call's
  // dependency on the same _cors()/proxy.cors.sh path the Steam appdetails/
  // store-page fetches below still separately rely on.
  //
  // Each of these calls only overwrites a field once it actually has Steam
  // content for it (see _applySteamAboutData), so this safely upgrades the
  // IGDB-sourced baseline filled in above rather than fighting with it.
  // _applySteamAboutData in particular already has its own complete
  // fallback for when the Steam fetch itself fails — fill Description/
  // screenshots from IGDB, clear steamLocInfo, refresh localization (see
  // its own comment) — so, unlike the old lookup-based version, no separate
  // failure handling is needed here; each function also has its own
  // stale-title guard, so no wrapping guard is needed here either.
  if (hasSteamAppId) {
    /* THE WAIT IS STATED IN THE DESCRIPTION'S OWN LABEL ROW — see _giImportNote.
       Wrapped at the CALL SITE rather than inside _applySteamAboutData, which
       returns early from four places: `.finally` catches every one of them,
       including a throw, where four hand-written clears would be an inventory
       to keep. Only the Steam path gets it, because only the Steam path waits:
       the no-app-id branch fills Description from IGDB's summary synchronously
       above, and a spinner for something already on screen is noise. */
    /* AND THE FIELD IS EMPTIED FIRST, OR THE WAIT CANNOT BE SEEN AT ALL (v7.08).
       Jaco: *"si busco otro juego, debería quitar el texto antiguo y volver a
       poner en el description field el 'Collecting the description'."*

       Two things were wrong and the CSS ties them into one. The deferral above
       is right — filling from IGDB first would flash a shorter text — but it
       leaves the textarea holding the PREVIOUS game's description for the whole
       of the fetch, so the form states a paragraph about a game you are no
       longer looking at. And the wait overlay is gated on `:placeholder-shown`
       (see `.gi-desc-group.is-waiting` in style.css), so a non-empty field
       hides the spinner: the one moment the step most needs to say something
       was the one moment it said nothing, precisely because the stale text was
       still there. **Emptying the field and showing the wait are one act.**

       It goes through `_fillDescriptionField`, the same one door the fills use,
       rather than writing `descEl.value` by hand — that function is what also
       clears `formData.description`, the character count, `descSource` (so the
       import note goes silent, which is true: nothing has been imported yet)
       and the three preview propagations. A hand-written clear would be the
       inventory this file keeps paying for, and would leave the Website, Mac
       Full and Apple previews quoting the old game. The glimmer's own empty-text
       guard means no sweep fires for a clear.

       If the fetch fails, `_applySteamAboutData`'s own IGDB fallback fills it a
       moment later; if that has nothing either, the field stays empty, which is
       the honest answer for a game we have no description for. */
    _fillDescriptionField('', null);
    _setDescLoading(true);
    Promise.resolve(_applySteamAboutData(item.steamAppId, item.name, item))
      .finally(() => _setDescLoading(false));
    _applySteamHeroBanner(item.steamAppId, item.name);
    _applySteamAchievements(item.steamAppId, item.name);
    // Steam's logotype into the pool when it is genuinely transparent, and
    // then the two built icons. Two calls rather than one: the logotype is a
    // file worth having whatever happens to the icon, and the icons get built
    // whether or not that file turned out usable.
    _applySteamLogo(item.steamAppId, item.name);
    _addSteamIconCandidates(item.steamAppId, item.name);
  }

  // Auto-activate platforms — use strict activationPlatforms (no unconfirmed console ports)
  const validPids = (item.activationPlatforms || item.platforms || []).filter(pid => !!PLATFORMS[pid] && !COMING_SOON_PLATFORMS.has(pid));
  if (validPids.length) {
    state.activePlatforms.clear();
    validPids.forEach(pid => {
      state.activePlatforms.add(pid);
      if (!state.platformStepStatus[pid]) {
        state.platformStepStatus[pid] = makeEmptyPlatformSteps()[pid] || {};
      }
    });
    const gridWrap = document.getElementById('ob-plat-grid-wrap');
    if (gridWrap) {
      gridWrap.innerHTML = buildObPlatTilesHTML();
      gridWrap.classList.remove('is-req-empty');
    }
    renderOnboardingFooter();
  }

  // Show confirmed state in the scenario widget
  state.liveSearch = {
    status:    'done',
    found:     true,
    confirmed: true,
    title:     item.name,
    allStores: item.platforms,
    source:    'IGDB',
  };
  _renderScenarioSection();
  updateObSectionStates();

  // Mark title question as answered
  const qTitle = document.getElementById('ob-q-title');
  if (qTitle) qTitle.dataset.answered = '1';

  // (Library Hero and social links are fired together with the About Data
  // call above, right after item.steamAppId is checked — see the Steam
  // enrichment block earlier in this function.)

  // Populate "IGDB Cover Art" from IGDB's own cover art. Runs independent
  // of item.steamAppId — it only depends on IGDB's own cover field, which
  // every platform's picklist item can have, not just ones with a linked
  // Steam page.
  if (item.coverBigUrl) {
    _applySteamCapsuleFromCover(item.coverBigUrl, item.name);
  }
}

/* Runs after selectPicklistItem when the picked title has a linked Steam
   page (item.steamAppId). Preloads Steam's library_hero image directly
   from its stable, hash-free CDN URL (steamLibraryHeroUrl, claude.js) —
   using an off-DOM Image() so a missing asset (some games just don't have
   one) shows up as a load failure to handle gracefully, rather than a
   broken <img> the user sees in the app. Only on a successful load, and
   only if the title hasn't changed since (same guard used elsewhere for
   this kind of fire-and-forget enrichment), sets:
     - state.uploads.steamKeyArtHero ← { name: 'library_hero.jpg', url }
   No network request our own code has to reason about failing/blocking —
   the browser's own image loading handles the request, and there's no
   proxy in the loop to get rate-limited or IP-blocked. */
function _applySteamHeroBanner(appId, expectedTitle) {
  const url = steamLibraryHeroUrl(appId);
  const img = new Image();
  img.onload = () => {
    if ((state.formData.title || '').trim() !== (expectedTitle || '').trim()) return;
    state.uploads = state.uploads || {};
    state.uploads.steamKeyArtHero = smRef(smAdopt({ name:'library_hero.jpg', url }, 'steam'));
    reRenderStepModal();
  };
  img.onerror = () => {
    console.warn('[Steam Hero Banner] no library_hero.jpg found for app', appId);
  };
  img.src = url;
}

/* ── STEAM'S LOGOTYPE JOINS THE LIBRARY (v7.09) ──────────────────────────
   Jaco: *"me gustaría que añadieras a los assets el 'logo', porque nos puede
   ser útil en el futuro, por ejemplo para la website. Así que si existe un
   logo transparente, añádelo al dropwell por defecto."*

   It goes into the POOL rather than into a slot of its own, which is the whole
   difference between this and `_applySteamHeroBanner`: the hero is fetched to
   fill a named Key Art field, where this is a file that will be useful and has
   no single destination yet. The library is exactly the box for that — it
   groups it under Logotype, the Website builder already reads the same pool,
   and "Shipmate found N assets" counts it without being told to.

   TRANSPARENT OR NOT AT ALL, which is his condition and also the only test
   worth making: a logotype baked onto a background is not a logotype, it is a
   picture of one, and it would be useless over key art on the marketing page.

   AND `smHasAlpha` IS THE WRONG TEST HERE, which was measured rather than
   assumed — the first version of this reused it and would have adopted almost
   nothing. That function asks whether all FOUR CORNERS of an 8×8 downscale are
   clear, and its own comment says it is conservative on purpose because a
   false 'logo' sends key art to the corner slot. At 8×8 each corner averages a
   vast block of the original, so a wide wordmark whose flourishes reach the
   edges reads as opaque: measured, it rejected Mina the Hollower, Spilled! AND
   Vampire Survivors, all three of which are genuinely cut out.

   The question there is "is this file a logotype"; the question HERE is "is
   this file cut out", and we already know it is a logotype because we asked
   for logo.png by name. So the test is the FRACTION that is see-through, on a
   48×48 sample. Measured: real cut-outs land between 26% and 78% (Spilled!
   26.6, Mina 35.3, Vampire 38.4, Hollow Knight 68.8, Hades 78.4) and a flat
   image lands at 0.0 — an opaque JPEG control and Spilled!'s own logo_2x.png
   both measure exactly zero. The floor is 5%, which is nowhere near anything.

   `_2x` WINS ONLY IF IT IS ALSO CUT OUT, and Spilled! is why that sentence
   exists: its logo_2x.png is 560×720 and flat while its logo.png is 640×320
   and transparent. The bigger file is not automatically the better asset, so
   both are tested and the largest one that passes is adopted.

   AND THE KIND IS FORCED, WHICH IS THE PART TO READ BEFORE SIMPLIFYING IT.
   `smAssetKind` sends a transparent image to 'logo' when it is oblong and to
   'icon' when it is SQUARE — and `smAppIcon()`'s second door is exactly
   `smPool().find(a => a.kind === 'icon')`. So a studio whose Steam logotype
   happens to be square would have it silently become the game's app icon, and
   would never be shown the icon proposal, because the proposal is gated on
   that same call. Nothing measured is square today, which is precisely why
   this would be discovered by a developer rather than by us. The fetcher knows
   what this file is — it asked for logo.png by name — so it says so.

   The cost, stated: `smSetKind` stamps `kindBy: 'user'`, whose name claims a
   person decided. It is the only flag that survives `smAdopt`'s async
   re-classification, so it is the mechanism available rather than the one that
   reads best. The broader question it points at — whether `smAppIcon()`'s pool
   fallback should ignore anything whose `origin` is not 'upload', since
   "recognised" ought to mean recognised from a file the developer handed us —
   is a change to a function seven surfaces read, and belongs in its own pass
   rather than riding in here. */
/* How much of the image is see-through. `clearRect` first, because a canvas
   starts transparent and drawing an OPAQUE image over it must leave zero —
   that is what makes the control read 0.0 rather than inheriting anything.
   Returns 0 on a tainted canvas, so an image we cannot read is never adopted. */
function _logoClearFraction(img) {
  try {
    const N = 48, c = document.createElement('canvas');
    c.width = c.height = N;
    const x = c.getContext('2d', { willReadFrequently: true });
    x.clearRect(0, 0, N, N);
    x.drawImage(img, 0, 0, N, N);
    const d = x.getImageData(0, 0, N, N).data;
    let n = 0;
    for (let p = 3; p < d.length; p += 4) if (d[p] < 16) n++;
    return n / (N * N);
  } catch (_) { return 0; }
}
const SM_LOGO_MIN_CLEAR = 0.05;   // real cut-outs measure .27–.78; flat art measures .00

function _applySteamLogo(appId, expectedTitle) {
  Promise.all([
    _iconLoadCors(steamLogoUrl(appId, true)),
    _iconLoadCors(steamLogoUrl(appId, false)),
  ]).then(([big, small]) => {
    if ((state.formData.title || '').trim() !== (expectedTitle || '').trim()) return;
    const ok = [big, small].filter(i => i && _logoClearFraction(i) >= SM_LOGO_MIN_CLEAR);
    if (!ok.length) return;                       // no transparent logotype — add nothing
    const pick = ok.sort((a, b) => b.naturalWidth - a.naturalWidth)[0];
    const id = smAdopt({ name: 'logo.png', url: pick.src, w: pick.naturalWidth, h: pick.naturalHeight }, 'steam');
    if (!id) return;
    smSetKind(id, 'logo');
    if (typeof renderAssetLibrary === 'function') renderAssetLibrary();
  });
}

/* ══════════════════════════════════════════════════════════════════════
   TWO BUILT ICONS, AND ONE OF THEM IS ALREADY THE ICON (v7.09)
   ══════════════════════════════════════════════════════════════════════
   Jaco: *"no quiero que los iconos aparezcan en otro sitio, quiero que estén
   las 2 propuestas en el mismo sitio que el resto de thumbnails, y que no me
   preguntes, quizás coge automáticamente uno, pero no me quites el otro, para
   que los tenga como opción si quisiera editar."*

   STEAM PUBLISHES NO SQUARE ART, so there is nothing to fetch — the icon has
   to be BUILT. What makes that possible rather than theoretical is that
   Steam's CDN sends CORS headers (see steamLogoUrl, claude.js): these images
   draw into a canvas that `toDataURL` can still read, so a real PNG comes out
   the other end, adopted through `smAdopt` exactly like a cropped screenshot.

   THIS WENT THROUGH TWO WRONG SHAPES FIRST AND THE THIRD IS SMALLER THAN
   EITHER. It began as a violet panel asking which icon you wanted, with a
   Not-now button; then as two ringed tiles in their own row, still waiting to
   be picked. Both were a QUESTION drawn in a well whose entire language is
   files you can see and press — and both needed their own element, their own
   repaint, their own CSS and their own strings to ask it.

   The answer is that a generated icon is just an ASSET. Both candidates go
   into the pool like everything else Steam hands us, land in the Icon group
   beside the rest of the thumbnails, and one of them is assigned to the slot
   on the spot. Nothing is asked because nothing needs asking: the other
   candidate is still sitting there, so changing your mind is picking up a file
   that is already in front of you rather than answering a prompt. The whole
   proposal mechanism — `state.iconProposal`, `_iconProposalHtml`,
   `_renderIconProposal`, `adoptProposedIcon`, five locale keys and two CSS
   rules — is deleted rather than switched off.

   TWO CANDIDATES, BECAUSE THEY FAIL IN DIFFERENT DIRECTIONS:

     · `logo` — the wordmark on a colour sampled out of the key art. It depends
                only on the assets existing, not on what the art happens to
                show, which is why it is the one taken by default.
     · `art`  — a square crop of the key art. Better when there is a character
                worth showing, useless when the hero is a texture — so it is
                the one worth having AVAILABLE rather than the one to assume.

   THE CROP IS GUIDED, NOT CENTRED, and that is what makes the second candidate
   usable at all. A Steam hero is composed with the wordmark overlaid, so the
   subject is routinely off-centre: measured, Mina the Hollower's sits at 68%
   of the width and Vampire Survivors' at 38%, and a dead-centre crop takes
   half a face on both. `_iconSalientX` finds the square window with the most
   local contrast instead. It cannot make anything worse, which is the property
   worth having: on art that IS centred it returns the centre (Spilled! 50%,
   Hollow Knight 53%, both pixel-identical to the naive crop).

   AND IT NEVER TAKES AN ICON YOU ALREADY HAD. Jaco, earlier: *"si han subido
   su propio icono, que no salga la propuesta."* The slot is only written when
   `smAppIcon()` came back empty BEFORE any of this ran — which is also why
   that answer is captured first. The second half of that guard is subtler and
   is the reason the pin exists: `smAppIcon()`'s other door is
   `smPool().find(a => a.kind === 'icon')`, i.e. the FIRST icon in the pool, so
   a developer whose icon was merely recognised there rather than chosen would
   have it silently displaced by two new icons landing beside it. Pinning what
   they already had into the slot before adopting anything is not a change to
   their submission — it is what keeps it from being changed. */

/* Where the picture actually has its content: column-wise local contrast,
   then the square window that maximises it, returned as a 0–1 centre.
   Deliberately crude — this is choosing between crops of the same picture,
   not detecting objects, and anything heavier would be a library. */
function _iconSalientX(img) {
  const W = 240, H = Math.max(1, Math.round(img.height * W / img.width));
  const c = document.createElement('canvas');
  c.width = W; c.height = H;
  const x = c.getContext('2d');
  x.drawImage(img, 0, 0, W, H);
  const d = x.getImageData(0, 0, W, H).data;
  const col = new Float64Array(W);
  for (let px = 0; px < W; px++) {
    for (let py = 1; py < H; py++) {
      const a = (py * W + px) * 4, b = ((py - 1) * W + px) * 4;
      col[px] += Math.abs(d[a] - d[b]) + Math.abs(d[a + 1] - d[b + 1]) + Math.abs(d[a + 2] - d[b + 2]);
    }
    if (px > 0) for (let py = 0; py < H; py++) {
      const a = (py * W + px) * 4, b = (py * W + px - 1) * 4;
      col[px] += Math.abs(d[a] - d[b]) + Math.abs(d[a + 1] - d[b + 1]) + Math.abs(d[a + 2] - d[b + 2]);
    }
  }
  const w = Math.min(W, Math.max(1, Math.round(H)));   // the square, in this small space
  let run = 0;
  for (let i = 0; i < w; i++) run += col[i];
  let best = run, bi = 0;
  for (let i = w; i < W; i++) { run += col[i] - col[i - w]; if (run > best) { best = run; bi = i - w + 1; } }
  return (bi + w / 2) / W;
}

/* The colour the logotype sits on. Sampled at 64×64 with the extremes thrown
   away — a near-black or near-white bucket is usually the art's vignette or
   its sky, and neither is the game's colour — and scored by population TIMES
   saturation, because the most COMMON colour in a piece of key art is very
   often a flat background nobody would name. Falls back to the panel grey
   rather than to black, so a failure reads as neutral rather than as a hole. */
function _iconArtColour(img) {
  try {
    const c = document.createElement('canvas');
    c.width = c.height = 64;
    const x = c.getContext('2d');
    x.drawImage(img, 0, 0, 64, 64);
    const d = x.getImageData(0, 0, 64, 64).data;
    const buckets = {};
    for (let p = 0; p < d.length; p += 4) {
      const r = d[p], g = d[p + 1], b = d[p + 2];
      const mx = Math.max(r, g, b), mn = Math.min(r, g, b);
      if (mx < 28 || mn > 232) continue;
      const k = `${r >> 5},${g >> 5},${b >> 5}`;
      (buckets[k] = buckets[k] || { n: 0, r: 0, g: 0, b: 0 });
      buckets[k].n++; buckets[k].r += r; buckets[k].g += g; buckets[k].b += b;
    }
    let best = null;
    for (const k in buckets) {
      const v = buckets[k];
      const sat = Math.max(v.r, v.g, v.b) - Math.min(v.r, v.g, v.b);
      const score = v.n * (1 + sat / v.n / 128);
      if (!best || score > best.s) best = { s: score, v };
    }
    if (!best) return '#242424';
    const v = best.v;
    return `rgb(${Math.round(v.r / v.n)},${Math.round(v.g / v.n)},${Math.round(v.b / v.n)})`;
  } catch (_) { return '#242424'; }
}

/* CORS first and NO retry without it, which inverts smMeasure's dance on
   purpose. That function retries bare because DIMENSIONS are worth having
   even off a tainted image; here a tainted image is worth nothing at all —
   the whole output is `toDataURL`. So a host that will not send the header
   simply produces no icons, which is the honest failure. */
function _iconLoadCors(url) {
  return new Promise(res => {
    const i = new Image();
    i.crossOrigin = 'anonymous';
    i.onload = () => res(i);
    i.onerror = () => res(null);
    i.src = url;
  });
}

/* THE LOGOTYPE'S OWN INK — where it is, and how solid it is (v7.09).
   One measurement, two answers, because both questions are about the same
   bounding box and reading the pixels twice to ask them separately would be
   two chances to disagree.

   WHERE, because a delivered logotype almost never fills its own file. Jaco:
   *"sería posible que uno de los iconos propuestos fuera el wordmark con un
   fondo sólido?"* — it already was, and the reason it did not look like it is
   that the whole FILE was being scaled into the icon, empty alpha margins
   included, so the wordmark landed small inside its own padding. Drawing the
   ink box instead lets it fill the 76% the icon reserves for it. This file
   already knows the lesson in another place: the marketing page's LOGOTYPE INK
   TRIM (web-page.js) measures the ink for exactly this reason, and notes that
   Spilled!'s logotype is 35% empty alpha by height. Same fact, same fix, and
   like that one this only changes what is DRAWN — nothing is re-encoded, so a
   baked-in shadow outside the box is scaled with everything else rather than
   being sliced off against a new rectangle.

   HOW SOLID, because Steam's `logo.png` is only USUALLY a cut-out wordmark.
   Jaco, on Spilled!: *"hay alguna manera de filtrar? esto es una cosa fea
   dentro de otro cuadrado azul."* Some studios ship a whole illustration in
   that file, and compositing one onto a colour puts a picture inside a square
   inside a square.

   TRANSPARENCY ALONE CANNOT TELL THOSE APART — Spilled!'s logo is 63% clear,
   more than Slay the Spire's 53% and the same ballpark as Celeste's 68%, both
   real wordmarks. What separates them is how solid the ink is INSIDE THIS BOX:
   letters leave gaps between and around themselves, a picture fills its
   rectangle. Measured across fifteen store pages:

     33.9 Cult of the Lamb · 35.5 Hades · 41.7 Cuphead · 52.6 Stardew ·
     52.8 Celeste · 54.2 Hollow Knight · 58.3 Slay the Spire · 65.3 Blasphemous ·
     67.1 Hi-Fi Rush · 70.9 Vampire Survivors · 71.3 Mina · 73.0 Terraria ·
     76.1 Balatro      ← every one of these is a real wordmark
     ─────────────────────────────────────────────────────────────────
     87.7 Spilled! · 89.7 Dave the Diver   ← both are solid illustrations

   Eleven and a half points of empty space between the two groups, so the floor
   at 80 is nowhere near anything rather than fitted to the sample. It changes
   which candidate is the DEFAULT, never which ones exist: a studio whose
   logotype is a picture may well still want it, and taking the choice away to
   fix a default would be the interface deciding more than it knows.

   Returns null when nothing is opaque, which the caller reads as unusable. */
function _iconInkBox(img) {
  try {
    const LONG = 200;
    const k = Math.min(LONG / img.naturalWidth, LONG / img.naturalHeight);
    const cw = Math.max(1, Math.round(img.naturalWidth * k));
    const ch = Math.max(1, Math.round(img.naturalHeight * k));
    const c = document.createElement('canvas');
    c.width = cw; c.height = ch;
    const x = c.getContext('2d', { willReadFrequently: true });
    x.clearRect(0, 0, cw, ch);
    x.drawImage(img, 0, 0, cw, ch);
    const d = x.getImageData(0, 0, cw, ch).data;
    let minx = cw, maxx = -1, miny = ch, maxy = -1, ink = 0;
    for (let y = 0; y < ch; y++) for (let px = 0; px < cw; px++) {
      if (d[(y * cw + px) * 4 + 3] < 16) continue;
      ink++;
      if (px < minx) minx = px; if (px > maxx) maxx = px;
      if (y < miny) miny = y;  if (y > maxy) maxy = y;
    }
    if (maxx < 0) return null;
    const bw = maxx - minx + 1, bh = maxy - miny + 1;
    const back = img.naturalWidth / cw;          // sample space → source pixels
    return {
      x: minx * back, y: miny * back, w: bw * back, h: bh * back,
      density: ink / (bw * bh),
    };
  } catch (_) { return null; }
}
const SM_LOGO_SOLID = 0.80;   // above this the "logotype" is a picture, not a wordmark

const SM_ICON_PX = 1024;   // Apple's App Store icon, and the largest any store asks for

async function _steamIconCandidates(appId) {
  const [hero2, hero1, logo2, logo1] = await Promise.all([
    _iconLoadCors(steamLibraryHeroUrl2x(appId)),
    _iconLoadCors(steamLibraryHeroUrl(appId)),
    _iconLoadCors(steamLogoUrl(appId, true)),
    _iconLoadCors(steamLogoUrl(appId, false)),
  ]);
  const hero = hero2 || hero1;
  /* CUT OUT FIRST, THEN BIGGER — and the expression this replaces was simply
     wrong. `(a && b && a.w >= b.w) ? a : (a || b)` returns `a` in BOTH arms
     whenever `a` exists, so it never once picked the smaller file. On Spilled!
     that meant logo_2x.png at 560×720 and 0.0% transparent — the flat
     illustration — instead of logo.png at 640×320, which is the cut-out one.
     Jaco: *"spilled sigue teniendo la ilustración ponzoñosa."* It was not the
     filter failing; it was being handed the wrong file to judge.

     `_applySteamLogo` had this right already (transparency, then width), so
     this is the same two-line sort rather than a second rule. */
  const logo = [logo2, logo1]
    .filter(i => i && _logoClearFraction(i) >= SM_LOGO_MIN_CLEAR)
    .sort((a, b) => b.naturalWidth - a.naturalWidth)[0] || null;
  const out = [];
  try {
    if (hero && logo) {
      const c = document.createElement('canvas');
      c.width = c.height = SM_ICON_PX;
      const x = c.getContext('2d');
      /* OPAQUE BY CONSTRUCTION, because SM_REQS marks the App Store and Mac
         App Store icons `noA: true` — Apple rejects an icon with alpha. The
         fill is not decoration, it is what makes this file legal. */
      x.fillStyle = _iconArtColour(hero);
      x.fillRect(0, 0, SM_ICON_PX, SM_ICON_PX);
      const box = SM_ICON_PX * 0.76;   // the wordmark, with a margin that survives a rounded mask
      /* The INK, not the file — see `_iconInkBox`. Falls back to the whole
         frame if nothing is opaque, which cannot happen for an image that got
         this far but costs one `||` to not have to reason about. */
      const k = _iconInkBox(logo)
             || { x: 0, y: 0, w: logo.naturalWidth, h: logo.naturalHeight, density: 1 };
      const s = Math.min(box / k.w, box / k.h);
      const w = k.w * s, h = k.h * s;
      x.drawImage(logo, k.x, k.y, k.w, k.h, (SM_ICON_PX - w) / 2, (SM_ICON_PX - h) / 2, w, h);
      /* A SOLID "LOGOTYPE" IS NOT OFFERED AT ALL, which reverses the first
         answer to this. It was demoted — built, kept in the library, just not
         the default — on the argument that a studio shipping a picture there
         might still want it. Jaco, looking at the result: *"spilled sigue
         teniendo la ilustración ponzoñosa."* He is right, and the earlier
         argument was about a CHOICE where this is about a CANDIDATE: offering
         a picture-inside-a-square as one of two app icons is offering junk and
         calling it an option. The logotype FILE is still in the library on its
         own terms (`_applySteamLogo`), so nothing is lost — only this derived
         icon is not made. */
      if (k.density < SM_LOGO_SOLID) out.push({ key: 'logo', src: c.toDataURL('image/png') });
    }
    if (hero) {
      const c = document.createElement('canvas');
      c.width = c.height = SM_ICON_PX;
      const x = c.getContext('2d');
      const s = Math.min(hero.naturalWidth, hero.naturalHeight);
      let sx = Math.round(_iconSalientX(hero) * hero.naturalWidth - s / 2);
      sx = Math.max(0, Math.min(hero.naturalWidth - s, sx));
      x.drawImage(hero, sx, Math.round((hero.naturalHeight - s) / 2), s, s, 0, 0, SM_ICON_PX, SM_ICON_PX);
      out.push({ key: 'art', src: c.toDataURL('image/jpeg', 0.92) });
    }
  } catch (_) {
    /* A tainted canvas, or no canvas at all. No icons rather than broken ones;
       the developer's own uploader is untouched either way. */
    return [];
  }
  /* THE FIRST ONE IS THE DEFAULT. `logo` is pushed before `art` and is only
     pushed at all when it is a real wordmark, so the order needs no sort: a
     game whose logotype is a picture simply gets one icon, the key-art crop. */
  return out;
}

/* Same fire-and-forget shape as _applySteamHeroBanner, including its
   stale-title guard: by the time the images decode the developer may have
   searched for something else, and an icon built for the previous game is
   worse than none. */
function _addSteamIconCandidates(appId, expectedTitle) {
  const hadIcon = typeof smAppIcon === 'function' ? smAppIcon() : null;
  _steamIconCandidates(appId).then(cands => {
    if (!cands.length) return;
    if ((state.formData.title || '').trim() !== (expectedTitle || '').trim()) return;
    state.uploads = state.uploads || {};

    /* Their icon was only ever RECOGNISED in the pool, never chosen — so pin
       it before two more icons land in front of it. See the block above. */
    if (hadIcon && !state.uploads.appIcon && hadIcon.id) {
      state.uploads.appIcon = smRef(hadIcon.id);
    }

    const ids = {};
    cands.forEach(c => {
      const id = smAdopt({ name: `app-icon-${c.key}.png`, dataUrl: c.src }, 'steam');
      if (!id) return;
      /* Say what it is rather than waiting for the classifier to agree. These
         are 1024×1024 and opaque, so `smAssetKind` would reach 'icon' on its
         own — but only after smMeasure's async read, and the slot is written
         on the line below. */
      smSetKind(id, 'icon');
      ids[c.key] = id;
    });

    /* `_steamIconCandidates` has already put the default first, so this does
       not repeat the reasoning — it just takes the head. The other one stays
       in the library either way. */
    if (!hadIcon) {
      const pick = ids[cands[0].key] || ids.logo || ids.art;
      if (pick) state.uploads.appIcon = smRef(pick);
    }
    if (typeof renderDetails === 'function') renderDetails();
    else if (typeof renderAssetLibrary === 'function') renderAssetLibrary();
  });
}

/* Runs after selectPicklistItem whenever the picked title has IGDB cover
   art (item.coverBigUrl). Same off-DOM Image() preload pattern as
   _applySteamHeroBanner above, so a missing/broken cover URL just logs a
   warning instead of showing a broken <img>. Only on a successful load,
   and only if the title hasn't changed since (same stale-response guard),
   sets:
     - state.uploads.steamKeyArtCapsule ← { name: 'cover.jpg', url }
   This backs the Key Art "IGDB Cover Art" field — IGDB's own cover
   crop/resolution (t_cover_big, nominally 264×374, though real delivered
   images don't always land on that exact ratio — see
   _pkSyncCapsuleAspect below for how the preview website's capsule box
   handles that). */
function _applySteamCapsuleFromCover(url, expectedTitle) {
  const img = new Image();
  img.onload = () => {
    if ((state.formData.title || '').trim() !== (expectedTitle || '').trim()) return;
    state.uploads = state.uploads || {};
    state.uploads.steamKeyArtCapsule = smRef(smAdopt({ name:'cover.jpg', url }, 'igdb'));
    reRenderStepModal();
  };
  img.onerror = () => {
    console.warn('[Steam IGDB Cover Art] failed to load IGDB cover art', url);
  };
  img.src = url;
}

/* ── About-section data source helpers (IGDB vs. Steam) ──────────────────
   Shared by selectPicklistItem's two branches (no linked Steam page /
   Steam fetch failed → IGDB; Steam fetch succeeded → Steam), so both
   sources fill the Description field and screenshot grid the same way. */

/* THE NOTE NAMES WHERE THE TEXT CAME FROM, SO THE WRITER IS WHAT RECORDS IT
   (v6.75). Jaco: *"la descripción la cogemos o bien de Steam o bien de IGDB,
   así que quiero que olvides el mensaje ese de Imported from Steam · Google
   Play · App Store y pongas solo Imported from Steam o IGDB."*

   The old note read `liveSearch.allStores` — the platforms the GAME is listed
   on, which is what activates the platform tiles. That is a different fact
   from where this paragraph was fetched, and printing it beside the
   Description said "Imported from App Store · Google Play" about text that
   came from exactly one place and never from either of those.

   THE SOURCE IS A FACT ABOUT THE WRITE, so it is stamped by the one function
   that writes — the same shape as `smAdopt`'s `origin` on an asset. Four call
   sites fill this field and each of them KNOWS which it is (IGDB's summary
   when there is no Steam page, Steam's About This Game when the fetch lands,
   IGDB again on either Steam failure), so the argument is never a guess. A
   note that derived it afterwards would be re-deducing at read time something
   the writer had in its hand. */
function _fillDescriptionField(text, source) {
  state.descSource = source || null;
  state.formData.description = text || '';
  _wsPropagateAboutGame(text || '');
  _macFullPropagateDescription(text || '');
  _applePropagateDescription(text || '');
  const descEl = document.getElementById('ob-desc');
  if (descEl) {
    descEl.value = text || '';
    charCount('ob-desc-count', text || '', 4000);
    /* AND THE ARRIVAL SWEEPS GREEN (v6.75)
       `_masCommitGlimmer` is the Mac preview's own confirmation — each letter
       starts green and fades to its colour on a left-to-right stagger — and it
       has never once fired for a field SHIPMATE filled, only for text you typed
       yourself. Which is the wrong way round: a field you type confirms itself,
       because you are looking at the words as they appear, where text that
       arrives from a fetch lands in a box you were not watching. This is the
       stronger of the two cases and it was the unused one.

       IT GOES HERE BECAUSE THIS IS THE ONE DOOR. Both of `selectPicklistItem`'s
       branches fill through this function — Steam when there is a linked page,
       IGDB when there is not — so one call covers every source, and any source
       added later is covered by construction. The alternative is a call beside
       each branch, which is the inventory this file keeps paying for.

       NOT on `_setDescLoading(false)`, which is where it first looks like it
       belongs: that runs on a failed fetch too, and a green sweep across an
       empty box would celebrate nothing having happened. The glimmer's own
       guards do the rest — empty text, reduced motion and a field with no box
       (a hidden sub-tab) all return before anything is drawn. */
    _masCommitGlimmer(descEl);
  }
  _iasTriggerAutoTranslate('description', text || '');
}

function _refreshScreenshotGrid() {
  const grid = document.getElementById('ob-screenshot-grid');
  if (grid) renderScreenshotGridInto(grid);
  // The well is what shows an imported batch now, so a Steam or IGDB fetch
  // has to redraw it or the files arrive invisibly.
  if (typeof renderAssetLibrary === 'function') renderAssetLibrary();
  updateObSectionStates();
}

// The guidance line is the one part of the Assets pane that changes without
// anything being dropped — a Steam scrape fills the library from elsewhere.
// Called from renderAssetLibrary, which is the single repaint every door
// into the pool already goes through.
/* AND AN IDENTICAL REPAINT IS NOT A REPAINT (v6.76). Jaco: *"no veo el glimmer
   verde de la 'Shipmate found…'"*. `outerHTML` replaces the node whatever it is
   being replaced WITH, and this line is repainted by every door into the pool —
   `renderDetails` alone reaches `renderAssetLibrary` twice, and anything that
   touches an asset reaches it again a frame or two later. So a sweep laid down
   on entering the pane was being thrown away by a render that changed nothing,
   with `assetsFoundSwept` already spent: the celebration existed for one frame
   and could never come back.

   The rAF inside `_assetsFoundGlimmer` coalesces repaints INSIDE one tick and
   cannot help across ticks — that is the whole gap this closes. Comparing the
   string is the honest test rather than a second flag: if the sentence has not
   changed there is nothing to draw, and the spans mid-animation are exactly the
   thing worth not destroying. It also removes DOM churn nobody asked for. */
let _assetsGuidanceHtmlLast = null;
function _renderAssetsGuidance() {
  const el = document.getElementById('ob-assets-guidance');
  if (el && typeof _assetsGuidanceHtml === 'function') {
    const html = _assetsGuidanceHtml();
    if (html !== _assetsGuidanceHtmlLast) {
      _assetsGuidanceHtmlLast = html;
      el.outerHTML = html;
    }
  }
  _assetsFoundGlimmer();
}

/* AND THE FOUND LINE SWEEPS GREEN THE FIRST TIME YOU SEE IT (v6.76)
   Jaco: *"cuando entremos en assets, el 'SHIPMATE FOUND X…' puedas animármelo
   con el glimmer verde, para que sea todavía más celebratorio la primera vez
   que entra."*

   **THE KEYFRAMES ALREADY FIT, AND THAT IS WHY THIS IS A CALL RATHER THAN A
   DESIGN.** `charToOwn` runs `#8FF0BF` → `#31DC80` → hold → `inherit`, written
   as "the celebration colour, then the element's own colour". On the Mac
   preview's fields `inherit` is white and the green IS the news; here the line
   is ALREADY `#31DC80`, so the middle stop is where it rests and **the pale
   opening is the whole of the sweep** — a shimmer travelling across green text
   rather than a colour change. One animation, two surfaces, no second dialect.

   **IT PAINTS THE ELEMENT, IT DOES NOT CLONE IT**, which is the opposite of
   `_masCommitGlimmer` and for that function's own stated reason. That one is a
   `position: fixed` overlay because the render which turns an editor back into
   a display element is DEFERRED and can be deferred indefinitely — so it could
   not wait for a node to exist. This line has no editor and no deferral: it is
   a plain div that `_renderAssetsGuidance` has just written, so the spans go
   straight in and the copied metrics — that overlay's one real cost — are not
   paid at all.

   **THE FLANK IS "VISIBLE AND NOT YET CELEBRATED", NOT "PRESENT".**
   `renderDetails` draws all three panes and CSS reveals one, so a Steam scrape
   that lands while you are on Basic Info would otherwise sweep a line nobody
   can see and leave nothing for the moment you arrive — the zero-rect trap the
   description's own glimmer had to be guarded against, one surface over. The
   test is `offsetParent`, which asks the DOM whether the thing is drawable
   rather than asking the router which sub-tab is open: the pane can move, be
   renamed or gain a fourth sibling without this line caring.

   **Keyed on the TEXT, so it fires again when the sentence really changes** —
   scrape three more assets and the new count is a new fact worth a sweep,
   where a bare boolean would celebrate once and then go quiet for the rest of
   the session. Transient by design, like `descSource`: never persisted, so a
   reload gets its one celebration back.

   **AND IT IS DEFERRED A FRAME, WHICH IS NOT AN OPTIMISATION.** Measured,
   entering the sub-tab repaints this line **twice** in one tick — `renderDetails`
   hydrates the pane and the well's own solve repaints it again. Run
   synchronously, the first pass laid the spans down and the second replaced the
   node with fresh `outerHTML`, taking them with it; the flag was set by then, so
   the sweep was created and destroyed inside one frame and nothing was ever on
   screen. **A flag that says "done" after an animation that was thrown away is
   worse than no flag**, because it also spends the one celebration there was.
   One pending flag plus a `requestAnimationFrame` coalesces any number of
   repaints in a tick into one sweep on whichever node survives them — the same
   shape `_smDropwellSolve` uses, and for the same reason. */
let _assetsGlimmerQueued = false;
function _assetsFoundGlimmer() {
  if (_assetsGlimmerQueued) return;
  _assetsGlimmerQueued = true;
  requestAnimationFrame(() => { _assetsGlimmerQueued = false; _assetsFoundGlimmerRun(); });
}
function _assetsFoundGlimmerRun() {
  const el = document.getElementById('ob-assets-guidance');
  if (!el || !el.classList.contains('is-found')) return;
  if (window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) return;
  const text = (el.textContent || '').trim();
  if (!text) return;
  if (state.assetsFoundSwept === text) return;   // already celebrated this one
  if (!el.offsetParent) return;                  // drawn, but on a hidden sub-tab
  state.assetsFoundSwept = text;

  const SWEEP = 280, FADE = 320;
  const chars = Array.from(el.textContent);
  el.textContent = '';
  chars.forEach((ch, i) => {
    const sp = document.createElement('span');
    sp.className = 'flash-char';
    sp.textContent = ch;
    sp.style.animationDelay = Math.round((i / Math.max(1, chars.length - 1)) * SWEEP) + 'ms';
    el.appendChild(sp);
  });
  /* The spans are swapped back for plain text, the same tidy-up the overlay
     does by removing itself — and it is safe at any moment because `charToOwn`
     ends on `inherit`, so the last frame already IS the resting colour. Guarded
     on `isConnected`: a repaint mid-sweep replaces this node wholesale, which
     takes the spans with it and leaves nothing to restore. */
  /* AND A SWEEP THAT DID NOT SURVIVE ITS FIRST FRAME GIVES THE FLAG BACK
     (v6.76). The guard above makes an identical repaint a no-op, but a full
     `renderDetails` rebuilds this pane with innerHTML and takes the spans with
     it whatever they say — and the flag was already set, so the one celebration
     was spent on an animation nobody saw. Checking that the spans are still on
     screen one frame later is the difference between "done" and "drawn": the
     next repaint sweeps instead of going quiet for the rest of the session. */
  requestAnimationFrame(() => {
    if (!el.isConnected || !el.querySelector('.flash-char')) state.assetsFoundSwept = null;
  });
  setTimeout(() => {
    if (el.isConnected && el.querySelector('.flash-char')) el.textContent = chars.join('');
  }, SWEEP + FADE + 80);
}

// Mirrors an auto-import batch (IGDB or Steam — see
// _fillScreenshotGridFromIgdb/_fillScreenshotGridFromSteam below) into the
// Web platform's own independent screenshots copy: same "drop the
// previous auto-populated batch, keep anything with a dataUrl" rule as
// Game Details' own array uses, applied to state.webSite.screenshots
// instead. `entries` is the SAME array (same ids) just pushed onto
// state.uploads.screenshots, so a later per-id removal (removeScreenshot)
// still matches correctly on both sides. See the state.js comment above
// webSite.screenshots.
function _wsSyncAutoScreenshots(entries) {
  if (!state.webSite) state.webSite = {};
  if (!state.webSite.screenshots) state.webSite.screenshots = [];
  state.webSite.screenshots = state.webSite.screenshots.filter(s => s.dataUrl);
  state.webSite.screenshots.push(...entries);
  const wsGrid = document.getElementById('ws-screenshot-grid');
  if (wsGrid) renderWebScreenshotGridInto(wsGrid);
}

// Always clears previously auto-populated screenshots (id starts with
// 'igdb-' or 'steam-') when a new game is selected, then loads the new
// game's screenshots. User-uploaded screenshots (those with a dataUrl) are
// left untouched. IGDB CDN images route through wsrv.nl (via _screenshotSrc
// at render time) to avoid 403s from direct hotlinking.
function _fillScreenshotGridFromIgdb(urls) {
  const entries = (urls || []).map((url, i) => ({
    id:   'igdb-' + i + '-' + Date.now(),
    // Adopted on arrival, so a fetched screenshot is classified and pickable
    // straight away rather than at the next project load. The wsrv.nl proxy
    // still happens at render time, inside _screenshotSrc.
    /* THE SOURCE SAID SO (v7.18). These came out of IGDB's `screenshots`
       field — there is nothing to infer. See smKindIsDeclared (assets.js) for
       why a declared kind outranks the geometry classifier. */
    ref:  smAdopt({ name: `screenshot-${i + 1}.jpg`, url, kind: 'screenshot' }, 'igdb'),
  }));
  // Manual uploads survive a change of linked title; fetched ones do not —
  // and "do not" means removed from the shared asset pool itself, not just
  // unlinked from this array, or they'd linger in the Assets tab's library
  // grid forever (see _smClearAutoScreenshots).
  _smClearAutoScreenshots();
  state.uploads.screenshots = state.uploads.screenshots.filter(smIsOwn);
  state.uploads.screenshots.push(...entries);
  _wsSyncAutoScreenshots(entries);
  _refreshScreenshotGrid();
}

// Same clearing behavior as _fillScreenshotGridFromIgdb, sourced from a
// Steam appdetails 'screenshots' array ({ id, path_thumbnail, path_full }
// objects) instead — up to the first 10. Steam's own CDN images load
// directly with no proxy needed (same reasoning as steamLibraryHeroUrl
// above: plain <img> loading doesn't require CORS headers).
// Takes plain URL strings now. It used to take appdetails' screenshots[]
// objects and reach for .path_full; /game hands back images[] entries whose
// url is already the full-size one, so the caller filters by type and passes
// the urls (see _applySteamAboutData). A string array is also the smaller
// contract — this function never wanted the rest of that object.
function _fillScreenshotGridFromSteam(screenshotUrls) {
  const ts = Date.now();
  const entries = (screenshotUrls || []).slice(0, 10).filter(Boolean).map((url, i) => ({
    id:   'steam-' + i + '-' + ts,
    // Adopted on arrival: a fetched screenshot is as much a project asset as
    // an uploaded one, and the library is where anything pickable lives.
    /* THE SOURCE SAID SO (v7.18), and this is the call the Portal bug ran
       through: `_applySteamAboutData` has ALREADY filtered images[] on
       `type === 'screenshot'` to build this list, and adopting them without
       the word threw that away. Portal's seven legacy assets decode at
       640x360 and came back out of the classifier as Key art. */
    ref:  smAdopt({ name: `screenshot-${i + 1}.jpg`, url, kind: 'screenshot' }, 'steam'),
  }));
  // Manual uploads survive a change of linked title; fetched ones do not —
  // and "do not" means removed from the shared asset pool itself, not just
  // unlinked from this array, or they'd linger in the Assets tab's library
  // grid forever (see _smClearAutoScreenshots).
  _smClearAutoScreenshots();
  state.uploads.screenshots = state.uploads.screenshots.filter(smIsOwn);
  state.uploads.screenshots.push(...entries);
  _wsSyncAutoScreenshots(entries);
  _refreshScreenshotGrid();
}

// Fallback used whenever Steam scraping doesn't produce screenshots for the
// currently-selected title — no Steam link at all, the Steam lookup/fetch
// itself failed, or Steam succeeded but simply has none listed for this
// game (see call sites in selectPicklistItem and _applySteamAboutData
// below). Fetches this one title's screenshots from IGDB directly
// (_igdbFetchScreenshots, claude.js — a separate, single-item query, since
// IGDB_SEARCH_ENDPOINT's own results never carry screenshots; see
// _igdbSearchRaw) and fills the grid with them. Fire-and-forget and
// non-fatal: a failure here just leaves the grid as it already is, same as
// every other Steam/IGDB enrichment call. Guards against a stale/superseded
// title the same way selectPicklistItem's own Steam enrichment calls do.
function _applyIgdbScreenshotFallback(igdbId, expectedTitle) {
  if (!igdbId || typeof _igdbFetchScreenshots !== 'function') return;
  _igdbFetchScreenshots(igdbId).then(urls => {
    if ((state.formData.title || '').trim() !== (expectedTitle || '').trim()) return;
    if (urls && urls.length) _fillScreenshotGridFromIgdb(urls);
  }).catch(err => {
    console.warn('[Picklist] IGDB screenshot fallback failed:', err.message);
  });
}

/* Runs after selectPicklistItem when the picked title has a linked Steam
   page (item.steamAppId). Fetches the title's Steam data (via
   fetchShipmateGame in claude.js, against Shipmate's own /game endpoint —
   this used to call Steam's appdetails through a free CORS proxy, replaced
   in v6.50) and, on success, replaces IGDB as the source of truth for this
   game's:
     - About section Description ← Steam's about_the_game (HTML flattened to
       blank-line-separated paragraphs, same conversion as the Web platform
       Description below — NOT Steam's short_description, which is only a
       one-or-two-sentence marketing blurb far shorter than what belongs in
       a store listing's actual Description field)
     - Web platform Factsheet Developer ← Steam's developers list, joined
     - Web platform Factsheet Publisher ← Steam's publishers list, joined
     - Web platform Factsheet Links "Official Website" ← Steam's website field
     - Web platform Description "About This Game" ← Steam's about_the_game
       (HTML flattened to blank-line-separated paragraphs — see
       _steamHtmlToParagraphLines in claude.js and _pkParagraphs in
       render.js — preserving Steam's own paragraph spacing instead of
       flattening every line break to identical spacing)
     - Assets screenshot grid ← Steam's first 10 screenshots
     - Web platform Factsheet Genres ← Steam's genres list, joined
     - Steam Key Art "Capsule Image" ← Steam's own capsule_image
     - Steam Key Art "Header Image" ← Steam's own header_image
     - Assets "Trailer" section thumbnail ← Steam's own appdetails movies[0]
       (see _steamTrailerFromMovies below) — a clickable preview thumbnail
       that swaps in an inline hls.js player (playSteamTrailer below) on
       click, streaming the trailer directly from Steam's own CDN
   Same stale-title guard as _applySteamHeroBanner/_applySteamCapsuleFromCover:
   if the user has since picked a different title, this silently no-ops.
   If the fetch itself fails (network error, no Steam data for this app id,
   etc.), falls back to filling from IGDB's own summary/screenshots — via
   fallbackItem, the same picklist item passed to selectPicklistItem — so a
   flaky Steam fetch doesn't leave the About section and screenshot grid
   empty; it just quietly degrades to the same result as a title with no
   linked Steam page. (Genres, Capsule Image/Header Image, and the Trailer
   thumbnail have no IGDB-sourced fallback/equivalent today, so they're
   simply left as-is when the Steam fetch fails.) */
/* Steam's appdetails `movies` array holds the store page's trailer/video
   entries — in the same order the store page itself lists them (its first
   entry is the store page's own primary/featured trailer, in practice also
   the one with highlight: true).
   An earlier version of this function assumed a { webm: { 480, max },
   mp4: { 480, max } } shape based on long-standing community documentation
   of this undocumented/unofficial API — but that turned out to be stale.
   Confirmed live against two real store pages (Go Ape Ship!/4037180 and
   Spilled!/2240080, both fetched directly during this project's own bug
   investigation) that today's actual shape is
   { id, name, thumbnail, highlight, dash_av1, dash_h264, hls_h264 } — Steam
   has moved entirely to adaptive streaming, with NO plain progressive
   mp4/webm file at all anymore. That's why the old mp4/webm-only version of
   this function silently matched nothing for every real game — this is the
   fix for that bug.
   hls_h264 (an .m3u8 HLS manifest) is the one used here, since it's what
   the inline player this feeds (playSteamTrailer/hls.js in this file) is
   built to consume; the dash_av1/dash_h264 (.mpd DASH manifests) variants
   are left unused for now. Valve can of course change this shape again with
   no notice, so this still degrades to null (no trailer shown) rather than
   throwing if hls_h264 or thumbnail is ever missing.
   Returns { name, thumbnail, hlsUrl } for the first entry with both a
   thumbnail and an hls_h264 URL, or null otherwise. */
function _steamTrailerFromMovies(movies) {
  if (!movies || !movies.length) return null;
  const movie = movies[0];
  if (!movie || !movie.thumbnail || !movie.hls_h264) return null;
  return { name: movie.name || 'Trailer', thumbnail: movie.thumbnail, hlsUrl: movie.hls_h264 };
}

/* ── App Store Product Page Preview — Steam-sourced Description
   localization ───────────────────────────────────────────────────────
   When a selected title is linked to a Steam store page, Steam's own
   store-page copy is already the source of truth for the PRIMARY
   language's Description (_applySteamAboutData above). If the developer's
   Steam store page has ALSO been localized into one of Shipmate's
   supported languages, that real, developer-written translation is a
   better source for that language's Description than an AI (Claude)
   translation of the primary text — so it's used instead, whenever it's
   available.

   /game accepts a `lang=<language>` query param (fetchShipmateGame,
   claude.js) taking Steam's OWN language codes,
   which don't match Shipmate's ISO-ish codes (OB_LANG_NAMES, render.js) —
   STEAM_LOCALIZATION_LANG_MAP bridges the two. Steam has no store-page
   localization support at all for Malay or Hebrew as of this writing, so
   those two are deliberately left out of the map (not just unmapped by
   accident) — a lookup miss is treated as "Steam can't possibly have
   this", short-circuiting before any network call. */
const STEAM_LOCALIZATION_LANG_MAP = {
  en: 'english', fr: 'french', de: 'german', es: 'spanish', 'es-419': 'latam',
  it: 'italian', pt: 'portuguese', 'pt-BR': 'brazilian', ru: 'russian',
  ja: 'japanese', ko: 'koreana', zh: 'schinese', 'zh-TW': 'tchinese',
  pl: 'polish', nl: 'dutch', tr: 'turkish', sv: 'swedish', nb: 'norwegian',
  da: 'danish', fi: 'finnish', cs: 'czech', hu: 'hungarian', ro: 'romanian',
  uk: 'ukrainian', el: 'greek', th: 'thai', vi: 'vietnamese', id: 'indonesian',
  ar: 'arabic',
};

// Display names Steam's own `supported_languages` field (appdetails) is
// known to use for each of its language codes — used only as a soft,
// best-effort pre-filter (see _steamSupportsLanguageCandidate below), never
// as the actual proof of localization (that always comes from comparing
// real fetched content, in _checkSteamLocalizedDescription).
const STEAM_LANG_DISPLAY_NAMES = {
  english: ['English'], french: ['French'], german: ['German'],
  spanish: ['Spanish - Spain', 'Spanish'], latam: ['Spanish - Latin America', 'Latin American Spanish'],
  // Steam lists European Portuguese as "Portuguese - Portugal" on current
  // store pages; the bare 'Portuguese' here was the older wording and is kept
  // for pages still carrying it.
  italian: ['Italian'], portuguese: ['Portuguese - Portugal', 'Portuguese'],
  brazilian: ['Portuguese - Brazil', 'Brazilian Portuguese'],
  russian: ['Russian'], japanese: ['Japanese'], koreana: ['Korean'],
  schinese: ['Simplified Chinese', 'Chinese - Simplified'],
  tchinese: ['Traditional Chinese', 'Chinese - Traditional'],
  polish: ['Polish'], dutch: ['Dutch'], turkish: ['Turkish'], swedish: ['Swedish'],
  norwegian: ['Norwegian'], danish: ['Danish'], finnish: ['Finnish'], czech: ['Czech'],
  hungarian: ['Hungarian'], romanian: ['Romanian'], ukrainian: ['Ukrainian'],
  greek: ['Greek'], thai: ['Thai'], vietnamese: ['Vietnamese'], indonesian: ['Indonesian'],
  arabic: ['Arabic'],
};

// Steam's supported_languages string is a comma-separated list of display
// names with occasional inline HTML (an asterisk wrapped in <strong> tags
// flags "full audio support"), followed by a "*languages with full audio
// support" footnote sentence appended after the list itself — e.g.
// "English<strong>*</strong>, French, German<br><strong>*</strong>languages
// with full audio support". Strips the tags and footnote, returning the
// plain list of names.
function _steamSupportedLanguageNames(raw) {
  if (!raw) return [];
  const noTags = raw.replace(/<[^>]*>/g, '');
  const beforeFootnote = noTags.split(/\*\s*languages with/i)[0];
  return beforeFootnote.split(',').map(s => s.replace(/\*/g, '').trim()).filter(Boolean);
}

// Best-effort check of whether Steam's own supported_languages listing
// mentions a given Steam language code at all — purely an optimization to
// skip an unnecessary network fetch for a language the game clearly
// doesn't support. Deliberately fails OPEN (returns true, "go ahead and
// check") whenever parsing is inconclusive, since the real answer always
// comes from _checkSteamLocalizedDescription's own content comparison —
// this must never be the thing that wrongly rules out a real localization.
// THE MAPPING LAYER, and it turned out to be a shape adapter rather than a
// translation table. STEAM_LANG_DISPLAY_NAMES is already keyed by Steam API
// language code and holds exactly the English display names /game returns
// ('Spanish - Spain', 'Portuguese - Brazil', 'Simplified Chinese'), so the
// only mismatch was one raw string vs. an array. Both are accepted here: an
// array passes straight through, a string still goes through
// _steamSupportedLanguageNames' tag/footnote stripping — which keeps the old
// appdetails shape working for anything still on it, and means callers don't
// have to care which source their steamLocInfo came from.
//
// The array MUST be the English one from the baseline call. A localized
// response's supportedLanguages (["İngilizce","Fransızca", …]) matches
// nothing here, and because this fails closed on a non-empty list that
// matches nothing, it would veto every language rather than failing open.
/* MATCHED ON THE BASE LANGUAGE, NOT THE EXACT STRING (v6.60), and that was a
   real reported bug rather than tidying.

   The comparison was `n.toLowerCase() === e.toLowerCase()` against a fixed
   table, which made every entry in that table a hard dependency on Steam's
   exact present-day wording — and the wording has moved. Steam now lists
   European Portuguese as "Portuguese - Portugal" where the table said
   "Portuguese", so for a game offering "Portuguese - Brazil" and/or
   "Portuguese - Portugal" this returned FALSE for `pt`. Everything downstream
   agrees with that answer: _checkSteamLocalizedDescription returns before
   issuing a fetch, and _steamMayStillSupply reports nothing is coming — so the
   card got an AI translation instead of Steam's real text AND never showed the
   loading state, which is exactly the pair of symptoms reported against Hades.

   That is also the precise failure this function's own contract says it must
   never produce: "deliberately fails OPEN whenever parsing is inconclusive
   … this must never be the thing that wrongly rules out a real localization".
   Exact equality against a non-empty list fails CLOSED, which contradicted it.

   So the test is now on the base language either side of a regional suffix:
   "portuguese" matches "portuguese - brazil", and "portuguese - brazil"
   matches a bare "portuguese". Both directions, because either side can be the
   more specific one depending on which name Steam happens to print.

   It is deliberately generous, and that costs nothing it did not already risk:
   the worst case is one fetch for a regional variant Steam answers with its
   fallback language, which _checkSteamLocalizedDescription's baseline
   comparison then rejects and the AI translation fills in — the same outcome
   as today, one HTTP call later. The best case is the localization the
   developer actually paid for showing up. */
function _steamLangNameMatches(listed, expected) {
  // Normalised: case, surrounding space, en/em dashes Steam sometimes prints
  // instead of a hyphen, and any run of whitespace around the separator.
  const norm = (v) => String(v).toLowerCase()
    .replace(/[\u2010-\u2015]/g, '-')
    .replace(/\s*-\s*/g, ' - ')
    .replace(/\s+/g, ' ')
    .trim();
  const a = norm(listed), b = norm(expected);
  if (a === b) return true;
  return a.startsWith(b + ' - ') || b.startsWith(a + ' - ');
}

function _steamSupportsLanguageCandidate(steamLang, supportedLanguages) {
  const names = Array.isArray(supportedLanguages)
    ? supportedLanguages.filter(Boolean).map(s => String(s).trim())
    : _steamSupportedLanguageNames(supportedLanguages);
  if (!names.length) return true;
  const expected = STEAM_LANG_DISPLAY_NAMES[steamLang];
  if (!expected) return true;
  return names.some(n => expected.some(e => _steamLangNameMatches(n, e)));
}

// Checks whether the currently-selected Steam-linked game's store page has
// a genuine localized "About This Game" for `lang` (a Shipmate language
// code), and if so, populates that language's Description with Steam's own
// text (same about_the_game field and HTML-to-plain-text conversion as the
// initial Description population — NOT short_description) — taking
// priority over an AI-translated guess. Called whenever a supporting
// language is added (toggleObLang/setObLangPreset/applyObLangPreset) and
// once up front for every already-selected supporting language as soon as
// a Steam-linked title is picked (_applySteamAboutData). A complete no-op
// if the current title isn't Steam-linked, or Steam has no localization
// support for `lang` at all (STEAM_LOCALIZATION_LANG_MAP has no entry for it).
//
// Deliberately NOT called from selectLocPrimary for the demoted outgoing
// primary language: that language's Description there is genuine
// developer-authored content (it was just the primary field's live value),
// not an AI-translated placeholder — overwriting it with Steam's own
// "About This Game" copy would replace real authored text rather than
// backfilling an empty/translated one, unlike every other call site here.
async function _checkSteamLocalizedDescriptionInner(lang) {
  const info = state.steamLocInfo;
  if (!info || !info.appId) return;
  const steamLang = STEAM_LOCALIZATION_LANG_MAP[lang];
  if (!steamLang) return;
  if (!_steamSupportsLanguageCandidate(steamLang, info.supportedLanguages)) return;

  let data = null;
  try {
    // A PROSE-ONLY call. Only `description` is read below — genres,
    // supportedLanguages and releaseDate.date come back translated on this
    // request and must never be taken from it (see fetchShipmateGame).
    data = await fetchShipmateGame(info.appId, steamLang);
  } catch (e) {
    console.warn('[Steam Localized Description]', lang, e.message);
    return;
  }

  // Stale guards — bail if the user switched to a different title, or
  // deselected this language again, while the fetch was in flight.
  if (!state.steamLocInfo || state.steamLocInfo.appId !== info.appId) return;
  if (!(state.formData.localizations || []).includes(lang)) return;

  // Same field and HTML-to-plain-text conversion as the initial Description
  // population in _applySteamAboutData (about_the_game, NOT the much
  // shorter short_description) — kept consistent so this comparison is
  // apples-to-apples against info.baselineDescription, which was cached
  // from that same conversion.
  const localizedDesc = _steamHtmlToParagraphLines(data && data.description || '').trim();
  const baseline      = (info.baselineDescription || '').trim();
  // Steam silently falls back to the store page's default listing language
  // instead of erroring when it has no real translation for the requested
  // language — comparing against the baseline is the only way to tell
  // "genuinely localized" from "silently fell back to English (or
  // whatever the default is)".
  if (!localizedDesc || localizedDesc === baseline) return;

  _iasSetFieldValue('description', lang, localizedDesc);
  if (state.formData.localizedStoreText && state.formData.localizedStoreText[lang]) {
    const entry = state.formData.localizedStoreText[lang];
    // A genuine Steam store-page localization is authoritative over an
    // AI-translated guess of the SAME primary text — descriptionFromSteam
    // flags that so _iasTriggerAutoTranslate's write-time guard won't let
    // an already-in-flight translation clobber it (see that guard for the
    // exact race this closes). This authority is intentionally temporary,
    // not permanent: it only holds for as long as descriptionSourceText
    // (set right below) still matches the CURRENT primary Description. The
    // moment the developer edits the primary Description again,
    // _iasTriggerAutoTranslate sees this language as stale like any other
    // and its translation overrides this Steam-sourced text — Steam only
    // gets to supply a language's *initial* Description.
    entry.descriptionFromSteam  = true;
    // Also refresh the staleness cache to the CURRENT primary Description,
    // so a translate pass already in flight when this write lands (or one
    // that runs before the flag above exists, e.g. this exact call racing
    // the auto-translate kicked off by the same language-add) still sees
    // nothing stale here even before the flag check is consulted.
    entry.descriptionSourceText = state.formData.description || '';
  }
  // Deferred, not direct — this resolves on its own independently-timed
  // network fetch, often seconds after the language-add that kicked it off,
  // by which point the user may well be clicking or scrolling around
  // whichever step modal happens to be open. Same guard every
  // *TriggerAutoTranslate function uses (_deferredRerenderStepModal's own
  // comment, above) — this function and its four siblings below
  // (_checkSteamLocalizedListing/_checkSteamLocalizedAchievements/
  // _checkIosLocalizedAchievements/_checkMacFullLocalizedAchievements) were
  // the gap v5.25's fix missed: all five are fired from the exact same
  // language-add call sites (toggleObLang, addLangFromSearch,
  // _checkSteamLocalizedDescriptionForNewLangs) as the ten *TriggerAutoTranslate
  // functions that fix covered, but weren't themselves *TriggerAutoTranslate
  // functions, so they kept calling reRenderStepModal() directly.
  _locDeferredRerenderStorePage('description', false);
}

// Sibling to _checkSteamLocalizedDescription above — same "genuine Steam
// localization beats an AI-translated guess" idea, extended to Steam's OWN
// Localization Review fields (Title/Short Description/Developer/Publisher/
// About This Game — buildSteamLocalizationReviewSection, render.js) rather
// than the App Store's own Description. Kept as a fully separate function
// with its own fetchShipmateGame(appId, steamLang) call rather than
// folded into _checkSteamLocalizedDescription, even though the two request
// the exact same response for the same appId+lang: keeping them apart means
// this newer, less-tested code path can never risk the already-shipped iOS
// Description-localization behavior — worth one redundant network call per
// language-add event. Same call sites/timing as _checkSteamLocalizedDescription
// (toggleObLang, _checkSteamLocalizedDescriptionForNewLangs,
// _applySteamAboutData's initial already-selected-languages pass).
//
// Each field is checked independently against its own cached baseline —
// state.steamLocInfo's baselineName/baselineDescription/baselineDeveloper/
// baselinePublisher/shortDescription, all cached at Steam-link time by
// _applySteamAboutData — the same "differs from baseline" test
// _checkSteamLocalizedDescription uses to tell a genuine per-language
// translation apart from Steam silently falling back to the store page's
// default listing language. A field whose localized value doesn't differ
// from its baseline (true for Developer/Publisher almost always, and often
// for Title — Steam rarely localizes a game's own name or its makers') is
// simply left alone; no flag, no write.
//
// Title writes through the SHARED App Store storage (_iasSetFieldValue,
// titleFromSteam/titleSourceText on formData.localizedStoreText[lang] —
// mirrors descriptionFromSteam/descriptionSourceText exactly, just for
// Title); Short Description/Developer/Publisher/About This Game write
// through Steam's own independent storage (webSite.localizedStoreText[lang],
// `${field}FromSteam`/`${field}SourceText`). Each flag is later read by
// _steamLocReviewSourceBadge/_locReviewSourceBadge (the 'steam' badge) and
// guarded against being clobbered by an in-flight AI translation inside
// _steamTriggerAutoTranslate's/_iasTriggerAutoTranslate's own write-time
// checks (see those functions for the exact race this closes).
async function _checkSteamLocalizedListingInner(lang) {
  const info = state.steamLocInfo;
  if (!info || !info.appId) return;
  const steamLang = STEAM_LOCALIZATION_LANG_MAP[lang];
  if (!steamLang) return;
  if (!_steamSupportsLanguageCandidate(steamLang, info.supportedLanguages)) return;

  let data = null;
  try {
    // PROSE ONLY — name, summary, description, developers and publishers are
    // the only fields read below. genres/supportedLanguages/releaseDate.date
    // are translated on a lang= request and are never read from one; the
    // baseline call in _applySteamAboutData owns those.
    data = await fetchShipmateGame(info.appId, steamLang);
  } catch (e) {
    console.warn('[Steam Localized Listing]', lang, e.message);
    return;
  }

  // Stale guards — bail if the user switched to a different title, or
  // deselected this language again, while the fetch was in flight.
  if (!state.steamLocInfo || state.steamLocInfo.appId !== info.appId) return;
  if (!(state.formData.localizations || []).includes(lang)) return;

  const fd = state.formData;
  const ws = state.webSite;
  if (!ws) return;

  // Title — shared with the App Store, same storage _iasSetFieldValue
  // writes through for every other Title edit.
  const localizedName = (data.name || '').trim();
  const baselineName  = (info.baselineName || '').trim();
  if (localizedName && localizedName !== baselineName) {
    _iasSetFieldValue('title', lang, localizedName);
    if (fd.localizedStoreText && fd.localizedStoreText[lang]) {
      const entry = fd.localizedStoreText[lang];
      entry.titleFromSteam  = true;
      entry.titleSourceText = fd.title || '';
    }
  }

  if (!ws.localizedStoreText) ws.localizedStoreText = {};
  if (!ws.localizedStoreText[lang]) ws.localizedStoreText[lang] = _steamBlankLocalizedText();
  const wsEntry = ws.localizedStoreText[lang];

  // Short Description — compared against the default-language
  // short_description cached at link time (info.shortDescription), same
  // fallback value Short Description's own primary-language card falls
  // back to (see _steamFieldValue).
  //
  // /api/appdetails's `l=` param isn't reliably honored for
  // short_description on every app — confirmed live that a store page can
  // correctly render a localized short description (via its own
  // og:description/description meta tags) for a language this JSON field
  // comes back empty, or identical to the default-language text, for. When
  // that happens, fall back to scraping that meta tag directly off the
  // store page itself (via a meta-tag parse that no longer exists — see
  // claude.js where the store-page scrape used to be) before giving up on
  // this language's Short Description.
  /* THE STORE-PAGE HTML FALLBACK IS GONE, and it was a workaround for a bug
     this endpoint doesn't have. /api/appdetails didn't reliably honour its
     own `l=` for short_description — a page could render a correctly
     localized og:description while the JSON came back empty or in the
     default language — so this scraped the meta tag off the store page HTML
     to recover it. /game returns genuinely localized prose for a language
     the game supports (verified: ?lang=french gives French summary AND
     description), so there is nothing left to recover, and dropping it also
     drops one of the two remaining proxied calls. */
  const localizedShortDesc = (data.summary || '').trim();
  const baselineShortDesc  = (info.shortDescription || '').trim();
  if (localizedShortDesc && localizedShortDesc !== baselineShortDesc) {
    wsEntry.description           = localizedShortDesc;
    wsEntry.descriptionFromSteam  = true;
    // Fallback-inclusive, NOT raw ws.description — this is the real bug
    // behind Task #26's intermittent "Chinese/Spanish aren't pulled"
    // report. When the primary card relies on the Steam-scrape fallback
    // (ws.description is '', real text comes from steamLocInfo.shortDescription
    // — see _steamFieldValue), _steamTriggerAutoTranslate is triggered with
    // that fallback text as `primaryValue` (_steamPropagateAllFields/
    // toggleObLang already read through _steamFieldValue for this exact
    // reason) — but this write used to cache '' here instead, so its
    // anti-overwrite guard (`entry.descriptionSourceText === text`) could
    // never match a non-empty `text` and never protected this write. The
    // Steam-scrape fetch and the AI translate call race every time a
    // supporting language is added; whichever caches '' here always loses
    // that race regardless of resolution order, silently letting an AI
    // guess clobber the genuine Steam localization moments after it landed.
    // Confirmed live (Claude Browser against the real Steam API + the real
    // Go Ape Ship! listing): 5/5 trials lost the race for Chinese and 4/5
    // for Spanish before this fix; 4/4 held after it.
    wsEntry.descriptionSourceText = _steamFieldValue('description', fd.primaryLanguage || 'en');
  }

  // Developer/Publisher — Steam essentially never localizes these, but
  // checked for full parity with the other 3 fields; compared against the
  // baseline cached at link time rather than the current primary value, so
  // a developer's own manual edit in between doesn't get misread as "Steam
  // disagrees with the primary text" here.
  const localizedDeveloper = (data.developers || []).join(', ').trim();
  const baselineDeveloper  = (info.baselineDeveloper || '').trim();
  if (localizedDeveloper && localizedDeveloper !== baselineDeveloper) {
    wsEntry.developer           = localizedDeveloper;
    wsEntry.developerFromSteam  = true;
    wsEntry.developerSourceText = ws.developer || '';
  }
  const localizedPublisher = (data.publishers || []).join(', ').trim();
  const baselinePublisher  = (info.baselinePublisher || '').trim();
  if (localizedPublisher && localizedPublisher !== baselinePublisher) {
    wsEntry.publisher           = localizedPublisher;
    wsEntry.publisherFromSteam  = true;
    wsEntry.publisherSourceText = ws.publisher || '';
  }

  // About This Game — same about_the_game field/HTML-to-plain-text
  // conversion and baseline comparison _checkSteamLocalizedDescription uses
  // for the App Store's own Description, just written into Steam's own
  // independent About This Game field instead.
  const localizedAboutGame = _steamHtmlToParagraphLines(data.description || '').trim();
  const baselineAboutGame  = (info.baselineDescription || '').trim();
  if (localizedAboutGame && localizedAboutGame !== baselineAboutGame) {
    wsEntry.aboutGame           = localizedAboutGame;
    wsEntry.aboutGameFromSteam  = true;
    wsEntry.aboutGameSourceText = ws.aboutGame || '';
  }

  // Deferred — see _checkSteamLocalizedDescription's own comment above for
  // why this can't be a direct reRenderStepModal() call.
  _locDeferredRerenderStorePage('title', null);
}

// Defense-in-depth backstop for every "*FromSteam" authority flag this
// feature cluster sets — descriptionFromSteam/titleFromSteam on
// state.formData.localizedStoreText (see _checkSteamLocalizedDescription/
// _checkSteamLocalizedListing above), plus description/developer/publisher/
// aboutGame FromSteam on state.webSite.localizedStoreText (_checkSteamLocalizedListing)
// — called whenever a different title is selected from the picklist.
// Normally each flag's authority already expires on its own the instant the
// new game's corresponding primary-language field loads
// (_iasTriggerAutoTranslate's/_steamTriggerAutoTranslate's staleness checks
// no longer match the old game's cached source text), but that natural
// expiry relies on the new primary text actually differing from the old
// one — in the unlikely case where two different games' initial text is
// textually identical for some field, the stale flag would otherwise be
// wrongly treated as still authoritative for the new game's (unrelated)
// Steam page. Clearing everything unconditionally here removes that edge
// case entirely.
function _clearSteamDescriptionAuthority() {
  const lst = state.formData.localizedStoreText;
  if (lst) {
    Object.keys(lst).forEach(lang => {
      delete lst[lang].descriptionFromSteam;
      delete lst[lang].titleFromSteam;
    });
  }
  const wlst = state.webSite && state.webSite.localizedStoreText;
  if (wlst) {
    Object.keys(wlst).forEach(lang => {
      ['description', 'developer', 'publisher', 'aboutGame'].forEach(f => { delete wlst[lang][f + 'FromSteam']; });
    });
  }
}

// Runs _checkSteamLocalizedDescription/_checkSteamLocalizedListing/
// _checkSteamLocalizedAchievements for every language present in
// `afterLangs` but not in `beforeLangs` — used by the bulk language-preset
// paths (setObLangPreset/applyObLangPreset), which set the whole
// localizations array in one shot rather than adding languages one at a
// time like toggleObLang.
function _checkSteamLocalizedDescriptionForNewLangs(beforeLangs, afterLangs) {
  const before = new Set(beforeLangs || []);
  (afterLangs || []).forEach(lang => {
    if (before.has(lang)) return;
    _checkSteamLocalizedDescription(lang);
    _checkSteamLocalizedListing(lang);
    _checkSteamLocalizedAchievements(lang);
    _checkIosLocalizedAchievements(lang);
    _checkMacFullLocalizedAchievements(lang);
  });
}

// Brings Steam's own Localization Review (Short Description/Developer/
// Publisher/About This Game) and Mac App Store's own independent one
// (Description/Release Notes) up to date for every already-selected
// supporting language, once a newly-picked game's primary-language content
// has settled — called from selectPicklistItem's own IGDB-only path and
// from every branch of the async Steam-link resolution that follows it
// (found/not-found/failed), so exactly one of those calls fires per pick.
//
// This exists to close a gap that's easy to miss: _iasPropagateAllFields/
// _masPropagateAllFields/_steamPropagateAllFields (the functions that
// actually run an AI translation of a primary field into every supporting
// language) are normally only called when the supporting-language LIST
// itself changes (toggleObLang/setObLangPreset/applyObLangPreset/
// selectLocPrimary) — nothing calls them when the GAME changes instead,
// even though that's exactly when every one of these fields' primary text
// just changed too. The App Store's own Description/Title are already
// covered elsewhere (_fillDescriptionField's own _iasTriggerAutoTranslate
// call; _iasPropagateTitle in selectPicklistItem) — this covers the rest.
//
// Without this, a supporting language Steam's own store page has no real
// localization for (_checkSteamLocalizedListing/_checkSteamLocalizedDescription
// correctly no-op rather than blank the field in that case — see their own
// comments) is simply never populated for the new game at all: now that
// selectPicklistItem correctly clears the previous game's stale content on
// every pick (see its own comment), a language Steam doesn't cover is left
// blank instead of falling back to a machine translation of the new
// primary text, which is what should happen instead. Each translate call
// below is race-safe against a genuine Steam scrape landing for the same
// language (see their own *FromSteam write-time guards), so calling both
// unconditionally here is safe regardless of which one resolves first.
function _refreshLocalizationForNewGame() {
  // Mac App Store's own Description/Release Notes were reset to null when
  // this game was picked (selectPicklistItem) specifically so they'd
  // reseed fresh here rather than keep showing the previous game's text —
  // a no-op if something already reseeded it in the meantime (e.g. the
  // user opened the Mac App Store step while this was still resolving).
  // Gated on Mac App Store actually being an active platform for this game,
  // matching seedMacAppStoreListing's own "first time the platform is
  // activated" contract (state.js) — reseeding it unconditionally here
  // would spuriously create state.macAppStoreListing (normally lazy, unlike
  // state.webSite below) even for a game that never targets macOS at all.
  if (state.activePlatforms && state.activePlatforms.has('macos')) {
    seedMacAppStoreListing();
    _masPropagateAllFields();
  }
  // Mac App Store Full's own independent Description/Release Notes get the
  // same treatment -- gated on the platform actually being active, same
  // "don't spuriously create the listing" contract as seedMacFullAppStoreListing
  // itself (see its own comment).
  if (state.activePlatforms && state.activePlatforms.has('macos_full')) {
    seedMacFullAppStoreListing();
    _macFullPropagateAllFields();
  }
  _steamPropagateAllFields();
}

async function _applySteamAboutData(appId, expectedTitle, fallbackItem) {
  let data = null;
  let fetchFailed = false;
  try {
    // THE BASELINE CALL, and the only structural source. Pinned to English by
    // fetchShipmateGame itself — genres/supportedLanguages/releaseDate.date
    // all translate on this endpoint, so reading them off anything else would
    // put Turkish genre names in a store listing. See that function's comment.
    data = await fetchShipmateGame(appId);
  } catch (e) {
    console.warn('[Steam About Data] failed to fetch /game for app', appId, e);
    fetchFailed = true;
  }

  // Stale guard — bail if the user has since picked a different title.
  // Note: on fallback we still want to fill in IGDB data for the CURRENT
  // title, so this guard applies to both branches below, not just success.
  if ((state.formData.title || '').trim() !== (expectedTitle || '').trim()) return;

  // The IGDB-fallback branch below still fills in what it can (Description,
  // screenshots), so this isn't a hard failure from the developer's seat —
  // but Developer/Publisher/Genres/Release Date/Key Art/Trailer/localization
  // baseline all come ONLY from Steam and are silently skipped when this
  // fetch fails (proxy/network/rate-limit — see FETCH_TIMEOUT_MS,
  // claude.js). A toast beats leaving those fields quietly blank with
  // nothing to explain why, indistinguishable from "Steam just has nothing
  // for this game".
  if (fetchFailed) {
    bcToast(`Couldn't load Steam store data for "${expectedTitle}" — filled in what IGDB had. Try reselecting the title, or fill in Developer/Publisher/Key Art manually.`);
  }

  if (data) {
    // "About This Game" (data.about_the_game) is Steam's own full-length
    // store-page copy, flattened from HTML to blank-line-separated
    // paragraphs by _steamHtmlToParagraphLines (claude.js) — feeds the About
    // section's own Description field below. It does NOT also get written
    // directly into the Web platform's "About This Game" field (state.
    // webSite.aboutGame) anymore — that field now syncs with (falls back to)
    // Game Details' Description field at render time instead (see
    // buildWebSitePreviewSection, render.js), the same "default + override"
    // treatment "Hook" used to have. Since Game Details' Description is
    // filled from this exact text two lines below, About This Game still
    // ends up showing Steam's about_the_game by default for a Steam-linked
    // title — just through that one indirect path rather than two separate
    // direct writes that could drift out of sync with each other.
    // Still through _steamHtmlToParagraphLines: /game's own `description` is
    // the same store-page HTML, and its server-side flattening is lossier
    // than this one's (bullets glued onto the previous sentence, <i>/<strong>
    // left in). This function handles <li>/</p>/headings properly, so the
    // pre-fill stays readable — see its own comment in claude.js.
    const aboutGameText = data.description ? _steamHtmlToParagraphLines(data.description) : '';

    // Guarded like item.summary in the no-Steam-link branch below — only
    // overwrite a field if Steam actually has content for it, rather than
    // blanking something the developer may have already typed in on the
    // rare page missing one of these fields. Since selectPicklistItem now
    // defers filling Description from IGDB until this function settles (to
    // avoid flashing IGDB's text before Steam's arrives — see
    // hasSteamAppId there), a successful Steam fetch that happens to have
    // no about_the_game text needs its own IGDB fallback here too, or the
    // field would be left blank instead of getting IGDB's summary the way
    // it always did before that deferral.
    /* THE STEAM-FIRST GATE IS ARMED BEFORE THE FIRST WRITE (v6.60).

       This block used to sit ~120 lines further down, after every field this
       function fills. That is a race, and it is the second half of the
       reported "sometimes": _fillDescriptionField immediately below calls
       _iasTriggerAutoTranslate, and _steamMayStillSupply — the gate that holds
       a translation back for a language Steam might genuinely localize —
       answers `false` while state.steamLocInfo is still null. So any language
       already selected when a title was picked had its translation fired off
       before this function had said which languages Steam covers, with no
       loading state for the wait either, because that is read from the same
       gate.

       Nothing here depends on the writes below; `data`, `appId` and
       `aboutGameText` are all in hand. Setting it first means the gate is up
       from the moment the baseline lands, which is the earliest any write can
       happen. */
    state.steamLocInfo = {
      appId,
      // baselineName/baselineDeveloper/baselinePublisher, alongside
      // baselineDescription/shortDescription below, give
      // _checkSteamLocalizedListing (above) a same-language-as-default
      // value to compare each of Steam's own Localization Review fields
      // against, so it can tell a genuine per-language localization apart
      // from Steam silently falling back to this default listing language.
      baselineName:           data.name || '',
      baselineDescription:    aboutGameText,
      baselineDeveloper:      (data.developers || []).join(', '),
      baselinePublisher:      (data.publishers || []).join(', '),
      shortDescription:       data.summary || '',
      /* AN ARRAY OF ENGLISH DISPLAY NAMES, and both halves of that matter.
         appdetails gave one raw HTML-ish string ("English<strong>*</strong>,
         French, …" with a footnote about full audio support) which
         _steamSupportedLanguageNames had to strip and split; /game gives
         ["English","French","Spanish - Spain","Simplified Chinese", …]
         already parsed, so the parser is bypassed — see
         _steamSupportsLanguageCandidate.

         ENGLISH because it came from the baseline call. This exact field is
         one of the three that translate on a lang= request, and a Turkish
         ["İngilizce","Fransızca", …] would match nothing in
         STEAM_LANG_DISPLAY_NAMES and silently veto every language before a
         single localized fetch went out. Never repopulate it from a
         localized response. */
      supportedLanguages:     Array.isArray(data.supportedLanguages) ? data.supportedLanguages : [],
    };

    /* The source is stamped per BRANCH, never once for the function: a Steam
       fetch that comes back without an About This Game section still lands
       here, and the text it fills with is IGDB's. */
    if (aboutGameText) {
      _fillDescriptionField(aboutGameText, 'Steam');
    } else if (fallbackItem && fallbackItem.summary) {
      _fillDescriptionField(fallbackItem.summary, 'IGDB');
    }
    // Social links, straight off this same response — see
    // _applySteamSocialLinks for what this replaced.
    _applySteamSocialLinks(data.links);
    if (data.developers && data.developers.length) state.webSite.developer = data.developers.join(', ');
    // Publisher — same "join Steam's list" treatment as Developer above,
    // just a different appdetails field (a game can, and often does, have
    // different developer(s) and publisher(s)).
    if (data.publishers && data.publishers.length) state.webSite.publisher = data.publishers.join(', ');
    // Official Website — Steam's appdetails 'website' field (the game's own
    // landing page, when the developer has set one on the store page —
    // Steam leaves this blank more often than not, so this often stays
    // whatever the developer already typed). Backs Factsheet > Developer >
    // Links > "Official Website".
    if (data.website) state.webSite.officialWebsite = data.website;
    // Support URL — Steam's appdetails 'support_info' object (shaped like
    // { url, email }), when the developer has filled one in on the store
    // page. Cached on state.steamSupportUrl (see its own comment, state.js)
    // rather than directly on state.macFullAppStoreListing, since that
    // object may not exist yet (Mac App Store Full might not have been
    // activated at all when this Steam fetch runs) — seedMacFullAppStoreListing
    // (app.js) reads this cached value once, the same "auto-fill once,
    // then freely editable" treatment as officialWebsite above, just for
    // Mac App Store Full's own Support URL field instead of the preview
    // website's.
    if (data.supportUrl) state.steamSupportUrl = data.supportUrl;
    // supportEmail is new with this endpoint — appdetails had support_info.email
    // and nothing here ever read it. Cached the same "auto-fill once, then
    // freely editable" way as supportUrl above, for Mac App Store Full's own
    // support contact field to seed from.
    if (data.supportEmail) state.steamSupportEmail = data.supportEmail;
    // Steam's genres are { id, description } objects (e.g. { id: "1",
    // description: "Action" }) — not the community-voted "tags" chips
    // shown on the store page (appdetails has no field for those at all,
    // see this project's Steam-tags research), just the short, fixed,
    // developer-assigned genre list. webSite.genres is free text (see
    // state.js), so this joins the descriptions the same way developers
    // above joins Steam's developers list.
    // Plain strings now (["Action","Adventure","Indie"]) where appdetails gave
    // { id, description } objects — same join, one less hop. English because
    // this is the baseline call; see fetchShipmateGame.
    if (data.genres && data.genres.length) state.webSite.genres = data.genres.filter(Boolean).join(', ');
    // Purchase price. /game gives { currency, value } in MINOR units (1999 =
    // $19.99) rather than appdetails' pre-formatted "$19.99", and omits the
    // object entirely for free-to-play titles while setting isFree — so the
    // two are read together by _shipmateFormatPrice (claude.js), which is
    // also what keeps "free" distinguishable from "not populated". Same
    // "auto-fill once, then freely editable" treatment as developer/publisher/
    // genres above — set here at link time and never re-synced, so a later
    // edit (or the game going on sale) is never silently overwritten.
    const priceText = _shipmateFormatPrice(data);
    if (priceText) state.webSite.price = priceText;
    // Release Date — Steam's own appdetails 'release_date' field, shaped
    // { coming_soon: bool, date: string } (e.g. { coming_soon: false, date:
    // "Feb 18, 2026" }, confirmed live against this project's own captured
    // Go Ape Ship! appdetails response). Unlike Developer/Publisher/Genres
    // above, this ALWAYS sets something whenever Steam returns the field at
    // all, rather than only overwriting on non-empty content — an
    // unannounced/TBD title still gets a release_date object back with an
    // empty `date` string (rather than omitting the field entirely), and by
    // request that case fills in the literal text "Coming soon" instead of
    // being left blank, matching webSite.releaseDate's own render-time
    // fallback for "nothing entered here at all" (see releaseDateValue,
    // render.js). Only skipped when Steam omits release_date entirely,
    // which the "only overwrite with real content" guard elsewhere in this
    // function would also apply to.
    // camelCase on this endpoint ({ comingSoon, date }) where appdetails used
    // release_date/{coming_soon}. `date` is English here because this is the
    // baseline call — it localizes ("17 Eyl 2020") on a lang= request, which
    // is one of the three fields that must never be read off one.
    if (data.releaseDate) {
      const rd = (data.releaseDate.date || '').trim();
      state.webSite.releaseDate = rd || 'Coming soon';
    }
    // Screenshots and Key Art now arrive in ONE images[] array discriminated
    // by `type`, where appdetails had screenshots[] plus capsule_image and
    // header_image as separate top-level fields — _shipmateImages/
    // _shipmateImageUrl (claude.js) do the filtering.
    const shotUrls = _shipmateImages(data, 'screenshot').map(im => im.url);
    _fillScreenshotGridFromSteam(shotUrls);
    // The record has no screenshots for this title — fall back to IGDB's own
    // rather than leaving the grid empty, same fallback used when the fetch
    // fails outright below.
    if (!shotUrls.length && fallbackItem) {
      _applyIgdbScreenshotFallback(fallbackItem.id, expectedTitle);
    }
    // Steam Key Art "Capsule Image"/"Header Image" — capsule_231x87.jpg and
    // header.jpg, handed back already hash-resolved exactly as appdetails
    // did, just under images[].type now. Fetched art joins the library too,
    // so it is classified and pickable from the moment it arrives rather
    // than at the next project load.
    const capsuleUrl = _shipmateImageUrl(data, 'capsule');
    const headerUrl  = _shipmateImageUrl(data, 'header');
    if (capsuleUrl) state.uploads.steamCapsuleImage = smRef(smAdopt({ name:'capsule.jpg', url: capsuleUrl }, 'steam'));
    if (headerUrl)  state.uploads.steamHeaderImage  = smRef(smAdopt({ name:'header.jpg',  url: headerUrl  }, 'steam'));
    // Assets "Trailer" section thumbnail — Steam's own first listed trailer
    // (appdetails' movies[0]), rather than anything IGDB provides.
    const trailer = _steamTrailerFromMovies(data.movies);
    if (trailer) state.uploads.steamTrailer = trailer;

    // Cache this game's default-language ("baseline") About This Game text
    // — the SAME field/conversion just used to populate the Description
    // field above, so a later localized comparison in
    // _checkSteamLocalizedDescription is apples-to-apples — plus the raw
    // supported_languages string, so that function can later (a) tell a
    // genuinely-localized appdetails response apart from Steam silently
    // falling back to this same baseline text, and (b) cheaply pre-filter
    // obviously-unsupported languages without an extra fetch. Reuses this
    // call's own appdetails response rather than issuing a second one —
    // this function already fetches exactly what's needed.
    //
    // shortDescription is Steam's own one-or-two-sentence marketing blurb
    // (data.short_description) — deliberately NOT used for About This Game
    // or Game Details' Description above (both far longer fields; see
    // aboutGameText's own comment) but exactly the right length for the Web
    // platform's "Hook" field, which reads this at render time
    // (buildWebSitePreviewSection, render.js) the same way it used to read
    // Game Details' Description before that role moved to About This Game.
    // Any supported languages already selected before this game finished
    // loading (e.g. left over from a prior title, or set via a language
    // preset that ran before this async fetch resolved) haven't had a
    // chance to be checked against this game's Steam localization yet —
    // check them now rather than only checking languages added afterward.
    (state.formData.localizations || []).forEach(lang => {
      _checkSteamLocalizedDescription(lang);
      _checkSteamLocalizedListing(lang);
      // Achievements' own baseline (state.steamAchievementsBaseline) comes
      // from a separate, independently-timed fetch (_applySteamAchievements)
      // that may not have resolved yet — a no-op here if so, since that
      // function runs this same already-selected-languages pass itself once
      // its own baseline lands.
      _checkSteamLocalizedAchievements(lang);
    });
  } else {
    if (fallbackItem && fallbackItem.summary) _fillDescriptionField(fallbackItem.summary, 'IGDB');
    // Steam scraping failed for this title — fall back to IGDB's own
    // screenshots (fallbackItem.screenshots is always [] now — the picklist
    // search backend doesn't return screenshots; see _igdbSearchRaw,
    // claude.js — so a real single-item IGDB lookup is needed here instead).
    if (fallbackItem) _applyIgdbScreenshotFallback(fallbackItem.id, expectedTitle);
    // No usable Steam data for this title (fetch failed) — clear any stale
    // cache from a previous game so a later language-add doesn't wrongly
    // check this new (non-Steam-backed) title against the OLD game's Steam
    // localization info.
    state.steamLocInfo = null;
  }
  // Description/webSite.developer/publisher/aboutGame all have their final
  // values for this game now (either from Steam above, or IGDB's fallback
  // in the else branch) — bring already-selected supporting languages'
  // Steam/Mac App Store Localization Review cards up to date for whichever
  // of those fields the localizations-forEach loop above (Steam's own
  // scrape) didn't already cover (see _refreshLocalizationForNewGame's own
  // comment).
  _refreshLocalizationForNewGame();
  reRenderStepModal();
}

/* Fills Factsheet > Developer > Links (state.webSite.links) from the picked
   title's social media links.

   NO LONGER A SCRAPE (v6.61). This used to be the one place in the app that
   parsed Steam's store-page HTML: appdetails had no field for social links,
   no documented Steamworks interface exposed them, and /game did not carry
   them either — so it fetched https://store.steampowered.com/app/<id>/ through
   a free third-party CORS proxy and ran a regex over the "Find Community" row.
   That was a second network round trip on an undocumented markup contract
   Valve could change without notice, and it was the last thing keeping the
   store page's HTML in this app at all.

   /game returns `links` now — [{name, url}], exactly the shape the regex used
   to produce — so this is a read off the response _applySteamAboutData already
   has. No extra request, no proxy, no parse. Confirmed live against Hades
   (appid 1145360): Facebook, X, YouTube.

   TAKEN FROM THE BASELINE RESPONSE ONLY, deliberately. `links` is absent from
   some localized responses, so reading it off a lang= call could blank a list
   the baseline had filled — the same reason genres/supportedLanguages/
   releaseDate.date are baseline-only (see fetchShipmateGame, claude.js).

   Everything the old version guarded against still holds. Only overwrites once
   Steam actually has links, matching the "only overwrite a field if Steam has
   content for it" rule Developer/Publisher/Genres follow, so a title with no
   socials configured never wipes out links the developer added by hand. When
   it does apply it REPLACES the whole list rather than merging — Steam is the
   source of truth once a title is linked. The stale-title guard is its
   caller's now (_applySteamAboutData checks before any of its writes), which
   is stricter than this function having its own: there is no longer a separate
   fetch that could resolve against a title the developer has since changed. */
function _applySteamSocialLinks(links) {
  if (!Array.isArray(links)) return;
  const clean = links
    .filter(l => l && String(l.name || '').trim() && String(l.url || '').trim())
    .map(l => ({ id: generateId('link'), name: String(l.name).trim(), url: String(l.url).trim() }));
  if (!clean.length) return;
  if (!state.webSite) state.webSite = {};
  state.webSite.links = clean;
}

/* Pre-populates Mac App Store's Game Center > Achievements section
   (state.macGameCenterAchievements — see its own comment, state.js) from
   /game's own `achievements` array (fetchShipmateGame / _shipmateAchievements,
   claude.js) the moment a Steam-linked title is picked from the IGDB
   picklist. This used to scrape Steam's public global achievement stats page;
   /game replaced it in v6.50 and carries a stable `identifier` and a stated
   `hidden` that the scrape never had. Follows the same fire-and-forget,
   stale-title-guarded pattern as _applySteamAboutData/_applySteamHeroBanner/
   _applySteamSocialLinks above — but, per product decision, does NOT follow
   their "never overwrite existing content" convention: selectPicklistItem
   already wipes state.macGameCenterAchievements unconditionally the moment
   a new title is picked (a new game means a new — or absent — achievement
   set, full stop), and this function's only job is to repopulate it from
   the new title's own Steam data, if any exists. So there's no "developer
   already has achievements, don't clobber them" guard here to no-op
   silently or need a toast for — an earlier version had exactly that guard,
   which turned out to be the cause of a real bug report ("achievements
   aren't scraping"): a single leftover manually-added achievement from
   testing the Game Center UI silently blocked every future Steam import
   with zero explanation, even though the rest of the Steam data (Capsule/
   Header art, About text) filled in fine. Each imported achievement is
   still tagged `fromSteam: true` for potential future bulk-refresh UI,
   though nothing currently reads that flag. "Hidden" is inferred from the
   achievement having no visible description on Steam's page — Steam blanks
   the description for hidden achievements, which is the only signal this
   public page gives us. Rows start collapsed since an imported achievement
   already has a Reference Name, Display Name, and Earned Description filled
   in — no more work needed unless the developer wants to review it. */
async function _applySteamAchievements(appId, expectedTitle) {
  let parsed = null;
  try {
    // From /game's own achievements array now, not a scrape of
    // steamcommunity.com/stats/<appid>/achievements — same fields, plus a
    // stated `hidden` and a stable `identifier` (see _shipmateAchievements,
    // claude.js). The one thing the scrape had that this doesn't is the
    // global unlock percentage, which nothing in this app ever read.
    const game = await fetchShipmateGame(appId);
    parsed = _shipmateAchievements(game);
  } catch (e) {
    console.warn('[Steam Achievements] failed to fetch achievements for app', appId, e);
    if ((state.formData.title || '').trim() === (expectedTitle || '').trim()) {
      bcToast(`Couldn't load Steam's achievements for "${expectedTitle}" — add them manually under Game Center if needed.`);
    }
    return;
  }

  // Stale guard — bail if the user has since picked a different title.
  if ((state.formData.title || '').trim() !== (expectedTitle || '').trim()) return;
  if (!parsed || !parsed.length) return;

  // Cache this fetch's default-language ("baseline") name/description for
  // every achievement, keyed by its position in Steam's own listing — the
  // same "genuinely localized vs. Steam silently fell back to the default
  // language" comparison _checkSteamLocalizedDescription/_checkSteamLocalizedListing
  // already use for the store listing, extended here to achievements (see
  // _checkSteamLocalizedAchievements below). Kept as its own independent
  // state field rather than folded into state.steamLocInfo (populated by a
  // separate, differently-timed fetch in _applySteamAboutData) so neither
  // cache has to guess whether the other has finished loading yet.
  state.steamAchievementsBaseline = {
    appId,
    // identifier rides along so the localized comparison can pair by key
    // rather than by array position — see _checkSteamLocalizedAchievements.
    achievements: parsed.map(p => ({
      identifier:  p.identifier || '',
      name:        p.name,
      description: p.description || '',
    })),
  };

  state.macGameCenterAchievements = parsed.map((p, idx) => ({
    id: generateId('ach'),
    refName: p.name,
    pointValue: '',
    hidden: p.hidden,
    achievableMultipleTimes: false,
    collapsed: true,
    saved: true,
    fromSteam: true,
    // Position in Steam's own achievement listing at import time — stable
    // even after the developer drags achievements into a different order
    // (macGcAchievementDrop) — so _checkSteamLocalizedAchievements can still
    // match this achievement back up against a freshly-fetched localized
    // listing (which Steam always returns in this same, order-independent-
    // of-language order) purely by position, without needing a shared name
    // key that a developer edit could invalidate.
    steamIndex: idx,
    steamKey: p.identifier || '',
    displayName: p.name,
    earnedDescription: p.description || '',
    /* PRE-EARNED STARTS AS A COPY OF EARNED (v6.56), by request. Steam has
       one description per achievement and no notion of a before/after pair,
       so this field used to import blank — leaving every scraped achievement
       with a hole the developer had to fill in by hand, usually by retyping
       the sentence directly above it.

       A COPY, NOT A LINK. Nothing keeps the two in step afterwards: they are
       separate fields on the record from this moment on, and editing either
       one leaves the other exactly as it is. The only thing that reads the
       two together again is _steamAchPreEarnedMirrors (below), and only to
       decide whether Steam's own LOCALIZED description should seed this
       field's translations the same way — which it stops doing the moment
       the developer makes them differ. */
    preEarnedDescription: p.description || '',
    image: p.iconUrl ? { name: 'Imported from Steam', dataUrl: p.iconUrl } : null,
  }));
  // App Store (ios)'s own Game Center gets the SAME Steam import, at the
  // same time, for full feature parity with Mac App Store's — a separate
  // array with its own ids (generateId('ach') called fresh per platform)
  // so editing/reordering/localizing one achievement list never touches the
  // other, even though both started from identical Steam data just now.
  state.iosGameCenterAchievements = parsed.map((p, idx) => ({
    id: generateId('ach'),
    refName: p.name,
    pointValue: '',
    hidden: p.hidden,
    achievableMultipleTimes: false,
    collapsed: true,
    saved: true,
    fromSteam: true,
    steamIndex: idx,
    steamKey: p.identifier || '',
    displayName: p.name,
    earnedDescription: p.description || '',
    // A copy of Earned at import, never linked to it afterwards — see Mac App
    // Store's own copy of this line above for the whole rule.
    preEarnedDescription: p.description || '',
    image: p.iconUrl ? { name: 'Imported from Steam', dataUrl: p.iconUrl } : null,
  }));
  // Mac App Store Full's own Game Center gets the SAME Steam import too,
  // same reasoning as App Store (ios)'s own copy directly above — its own
  // separate array/ids, full feature parity with Mac App Store's Game
  // Center.
  state.macFullGameCenterAchievements = parsed.map((p, idx) => ({
    id: generateId('ach'),
    refName: p.name,
    pointValue: '',
    hidden: p.hidden,
    achievableMultipleTimes: false,
    collapsed: true,
    saved: true,
    fromSteam: true,
    steamIndex: idx,
    steamKey: p.identifier || '',
    displayName: p.name,
    earnedDescription: p.description || '',
    // A copy of Earned at import, never linked to it afterwards — see Mac App
    // Store's own copy of this line above for the whole rule.
    preEarnedDescription: p.description || '',
    image: p.iconUrl ? { name: 'Imported from Steam', dataUrl: p.iconUrl } : null,
  }));
  reRenderStepModal();
  updateIOSCard('macos');
  updateIOSCard('ios');
  updateIOSCard('macos_full');

  // Kick off an AI-translated fallback for every newly-imported
  // achievement's three fields — the Steam-import counterpart to
  // saveMacGcAchievement's own propagation call (see that function's
  // comment for the full bug this closes). Achievements imported here are
  // created already collapsed, bypassing saveMacGcAchievement entirely, so
  // without this call a supporting language Steam doesn't genuinely
  // localize (_checkSteamLocalizedAchievements below silently skips writing
  // anything for it) would otherwise stay blank forever in Achievement
  // Localizations — AI translation is the same fallback Localization
  // Review already relies on for every other Mac App Store field.
  // _masAchLocTriggerAutoTranslate's own write-time guard
  // (entry[field+'FromSteam'] check) protects a genuine Steam localization
  // — whether it arrives concurrently below or was already cached from a
  // prior import of this same title — from being clobbered by this
  // fallback, regardless of which of the two calls happens to resolve
  // first. preEarnedDescription has no Steam source at all, so it's always
  // eligible for this fallback (or stays blank if the developer hasn't
  // typed one yet — _masAchLocTriggerAutoTranslate no-ops on empty text).
  state.macGameCenterAchievements.forEach(a => {
    ACHIEVEMENT_LOC_TRANSLATABLE_FIELDS.forEach(field => _masAchLocTriggerAutoTranslate(a.id, field, a[field] || ''));
  });
  // Same fallback, same reasoning, for App Store (ios)'s own newly-imported
  // achievements — _iasAchLocTriggerAutoTranslate's own write-time guard.
  state.iosGameCenterAchievements.forEach(a => {
    ACHIEVEMENT_LOC_TRANSLATABLE_FIELDS.forEach(field => _iasAchLocTriggerAutoTranslate(a.id, field, a[field] || ''));
  });
  // Same fallback, same reasoning, for Mac App Store Full's own newly-
  // imported achievements — _macFullAchLocTriggerAutoTranslate's own write-
  // time guard.
  state.macFullGameCenterAchievements.forEach(a => {
    ACHIEVEMENT_LOC_TRANSLATABLE_FIELDS.forEach(field => _macFullAchLocTriggerAutoTranslate(a.id, field, a[field] || ''));
  });

  // Bring every already-selected supporting language's Achievement
  // Localizations up to date with this game's own Steam data, same as
  // _applySteamAboutData's own already-selected-languages pass for the
  // store listing — this fetch's baseline just became available, so
  // languages added before it resolved haven't had a chance to check yet.
  (state.formData.localizations || []).forEach(lang => {
    _checkSteamLocalizedAchievements(lang);
    _checkIosLocalizedAchievements(lang);
    _checkMacFullLocalizedAchievements(lang);
  });
}

