/* ══════════════════════════════════════════════════════
   SCREENSHOT STEP — adding a screenshot from the editor
   ══════════════════════════════════════════════════════
   `togglePlatformScreenshot` and `removePlatformScreenshot` went with the grid
   they served. Selection was that step's whole model — a checkbox per upload —
   and the editor has no such control: what a listing HOLDS is `order` minus
   `removed`, and pressing a thumbnail selects it for EDITING rather than for
   inclusion. Deleted rather than left dormant, the dev bar's own argument.

   This one survives because adding is still adding. Three things it gained:
   it clears the id out of `removed` (a file dropped in is an inclusion, and it
   would otherwise land straight back in the bin it had never been in), it
   appends to `order` so the new shot lands at the END where a new one belongs,
   and it opens it in the stage — you added it to look at it. */
function handlePlatformScreenshotFiles(pid, files) {
  if (!files || !files.length) return;
  const ps = _shotEdPs(pid);
  const list = Array.from(files).filter(f => f.type.startsWith('image/'));
  if (!list.length) return;
  let pending = list.length, lastId = null;
  list.forEach(file => {
    const reader = new FileReader();
    reader.onload = ev => {
      const id = 'pshot-' + pid + '-' + Date.now() + '-' + Math.random().toString(36).slice(2, 7);
      ps.custom = ps.custom || [];
      ps.custom.push({ id, name: file.name, dataUrl: ev.target.result });
      ps.removed = (ps.removed || []).filter(x => x !== id);
      /* Only meaningful once `order` is real — while it is empty the pool's own
         sequence already puts a new upload last, and writing a one-id order
         here would claim the developer had arranged the listing. */
      if (ps.order.length) ps.order.push(id);
      lastId = id;
      if (--pending === 0) {
        reRenderStepModalScreenshots(pid, lastId);
        renderDashboard();
      }
    };
    reader.onerror = () => { if (--pending === 0) reRenderStepModalScreenshots(pid, lastId); };
    reader.readAsDataURL(file);
  });
}

/* ============================================================================
   THE ASSET LIBRARY — Shipmate's side
   ============================================================================
   assets.js holds the pool, the classifier and the store table. This is the
   part that has to know about Shipmate: the picker grid, the Assets tab
   panel, and the coverage read-out.
   ========================================================================== */

/* ── THE PICKER ────────────────────────────────────────────────────────────
   Opened by any uploader that used to open a file dialog. `kinds` is what
   belongs in this slot — the header wants landscape art, the corner wants a
   mark — and everything else is behind "Show all" rather than hidden,
   because a logotype the classifier called art-port must still be findable.

   Returns a REF, so choosing an image the project already has costs nothing
   and creates no second copy. */
let _smPick = null;

function smPickAsset(kinds, done) {
  _smPick = { kinds: kinds && kinds.length ? kinds : null, done, all: false };
  _smRenderPicker();
}

function smPickerClose() {
  _smPick = null;
  const el = document.getElementById('sm-picker');
  if (el) el.remove();
  document.body.classList.remove('sm-picker-open');
}

function smPickerAll() { if (_smPick) { _smPick.all = true; _smRenderPicker(); } }

/* Upload from inside the picker: the file joins the library and is chosen in
   one gesture, which is what "Upload new…" has to mean or it is just a file
   dialog with extra steps. */
function smPickerUpload() {
  const inp = document.createElement('input');
  inp.type = 'file'; inp.accept = 'image/*';
  inp.style.cssText = 'position:fixed;left:-9999px;width:1px;height:1px;opacity:0';
  document.body.appendChild(inp);
  const cleanup = () => { if (inp.parentNode) inp.parentNode.removeChild(inp); };
  inp.addEventListener('change', () => {
    const f = inp.files && inp.files[0];
    cleanup();
    if (!f) return;
    smAddFile(f, id => { if (id) smPickerChoose(id); });
  });
  inp.addEventListener('cancel', cleanup);
  setTimeout(cleanup, 5 * 60 * 1000);
  inp.click();
}

function smPickerChoose(id) {
  const cb = _smPick && _smPick.done;
  smPickerClose();
  if (cb) cb(smRef(id));
}

function _smRenderPicker() {
  if (!_smPick) return;
  let host = document.getElementById('sm-picker');
  if (!host) {
    host = document.createElement('div');
    host.id = 'sm-picker';
    document.body.appendChild(host);
    document.body.classList.add('sm-picker-open');
    // Clicking the backdrop is the same as pressing Escape: a picker you
    // cannot dismiss without choosing something is a trap.
    host.addEventListener('click', e => { if (e.target === host) smPickerClose(); });
  }
  const pool = (state.assets || []).filter(a => a.kind !== 'video');
  const want = _smPick.kinds;
  const shown = (_smPick.all || !want) ? pool : pool.filter(a => want.includes(a.kind));
  const hidden = pool.length - shown.length;

  host.innerHTML = `
    <div class="sm-picker-box" role="dialog" aria-label="Choose an image">
      <div class="sm-picker-head">
        <b>Choose an image</b>
        ${want ? `<span class="sm-picker-sub">${want.map(k => escHtml(SM_KIND_SHORT[k] || k)).join(' · ')}</span>` : ''}
        <button class="sm-picker-x" onclick="smPickerClose()" aria-label="Close">×</button>
      </div>
      <div class="sm-picker-grid">
        ${/* NO FAKE THUMBNAIL HERE. Giving this a .sm-tile-img of its own was
              the wrong idea and it showed: that box is 84px tall while the row
              is 141, so the upload tile ended up with a rounded rectangle
              inside it that lined up with nothing. It is not an asset, so it
              does not get an asset's anatomy — it is one square the height of
              the row, with the + and its label centred in it. */''}
        <button class="sm-tile sm-tile-new" onclick="smPickerUpload()">
          <span class="sm-tile-plus">+</span>
          <span class="sm-tile-name">Upload new…</span>
        </button>
        ${shown.map(a => `
          <button class="sm-tile" onclick="smPickerChoose('${a.id}')" title="${escHtml(a.name)}">
            ${/* Video is in the pool now, so it can reach this grid — and a
                  <img> pointed at a video blob draws nothing at all. */''}
            ${/* --ar as a NUMBER as well as the ratio, because the width has
                  to be clamped against the tile and CSS cannot divide two
                  numbers out of an aspect-ratio. See .sm-tile-img. */''}
            <span class="sm-tile-img" style="--ar:${(a.w || 16) / (a.h || 9)}">${a.kind === 'video'
              ? `<video src="${escHtml(a.src)}#t=0.1" muted playsinline preload="metadata"></video>`
              : `<img src="${escHtml(a.src)}" alt="">`}</span>
            <span class="sm-tile-meta">
              <span class="sm-tile-name">${escHtml(a.name)}</span>
              <span class="sm-tile-dim">${a.w || '?'}×${a.h || '?'}</span>
            </span>
          </button>`).join('')}
      </div>
      ${!shown.length ? `<p class="sm-picker-empty">Nothing here yet — upload one.</p>` : ''}
      ${hidden > 0 ? `<button class="sm-picker-more" onclick="smPickerAll()">
          Show ${hidden} other asset${hidden === 1 ? '' : 's'}</button>` : ''}
    </div>`;
}

if (typeof document !== 'undefined' && !smPickAsset._esc) {
  smPickAsset._esc = true;
  document.addEventListener('keydown', e => {
    if (e.key === 'Escape' && _smPick) { e.preventDefault(); e.stopPropagation(); smPickerClose(); }
  }, true);
}

/* ── THE LIBRARY PANEL, on the Assets tab ─────────────────────────────────
   Everything the project has, grouped by what it is, with the label editable
   in place. Plus the two things the classification is FOR: what each store
   still needs, and the smallest set of masters that would cover it. */
function renderAssetLibrary() {
  /* The project chip in the header can be showing an icon that came from this
     pool (see renderProjectBar), so a change here can change it too. */
  if (typeof renderProjectBar === 'function') renderProjectBar();
  const el = document.getElementById('sm-library');
  if (el) el.innerHTML = _smLibraryHTML();
  const cov = document.getElementById('sm-coverage');
  if (cov) cov.innerHTML = _smCoverageHTML();
  /* The line above the well counts the same pool this list draws, so it is
     repainted HERE rather than at each of the nine call sites that change the
     library — an inventory of consequences goes stale the first time a tenth
     door starts writing to the pool. It no-ops on the Website builder, which
     renders its own copy of #sm-library and has no guidance line. */
  _renderAssetsGuidance();
  _smDropwellFit();
}

/* ── THE DROP WELL GIVES ROOM BACK WHEN THE LIBRARY WRAPS ─────────────────
   Jaco: *"solo cambiamos el pocillo si añado 2 líneas de assets, porque si no,
   se mantiene en su tamaño."* The Assets card was asked to top out at 576 and
   the well is the only number left to spend — but spending it unconditionally
   would shrink an EMPTY tab's well for a row that is not there. So the second
   line of the library buys its own space out of the box directly above it, and
   one line leaves the well at the 175 it was given for its own sake.

   **IT IS MEASURED, BECAUSE CSS CANNOT COUNT WRAPPED FLEX LINES.** `:has()`
   can ask what exists and not how it landed: whether `.sm-wells` wraps depends
   on the WIDTH and on how wide each group happens to be — a Screenshot group
   with five thumbs is ~480 and a lone Icon is ~89 — so the number of GROUPS
   does not predict the number of LINES either. Counting distinct `offsetTop`s
   is asking the layout the only question that has a true answer. They are
   siblings, so they share an offsetParent and the comparison needs no origin.

   **AND IT CANNOT FEED BACK ON ITSELF, which is what makes the observer safe.**
   What the class changes is the well's HEIGHT, and the well is a sibling ABOVE
   the library; wrapping is decided by WIDTH alone, so nothing this writes can
   change what it just measured. The one real loop is the observer's own: a
   `ResizeObserver` fires once on `observe()`, so re-arming inside its callback
   would call itself forever — hence the node guard. Re-arming at all is the
   `_smModalFades` contract: `#sm-library` is rebuilt with innerHTML, so the
   node being watched is replaced out from under it.

   The observer is what covers a WINDOW RESIZE, which is the case a render hook
   alone would miss entirely: nothing re-renders, the row rewraps, and the card
   would keep a height solved for the other count. */
let _smWellsRO = null;
let _smWellsNode = null;
let _smFitPending = false;

function _smDropwellFit() {
  const dz = document.getElementById('ob-screenshot-dropzone');
  const wells = document.querySelector('#sm-library .sm-wells');

  if (dz) {
    /* NO LINE COUNTING ANY MORE (v6.74). This used to count the library's
       wrapped flex lines and switch `is-tight` at two, because the library sat
       BELOW the well and its second row was what pushed the card over. It sits
       INSIDE the well now, so the pane's height stops depending on how many
       rows the folder makes and there is nothing left to condition on — the
       well is one number, always. The counting, the class and its rule went
       together rather than being left switched off.

       THE SOLVE STILL CANNOT FEED BACK ON ITSELF, and the reason CHANGED with
       the markup, so it is worth restating rather than inheriting: it used to
       be that the well was a sibling ABOVE the library and wrapping is decided
       by width. Now the library is the well's own child — and what the solve
       writes is still the well's HEIGHT, while `.sm-wells` wraps against its
       WIDTH, which is the well's content box and is untouched by any of this.
       The observer therefore cannot be re-triggered by the thing it triggers. */

    /* THE SOLVE WAITS A FRAME, AND THE FIRST VERSION DID NOT — that is the
       whole of why it silently never wrote. `renderAssetLibrary` runs inside
       the render that built this pane, and at that moment the measurement it
       needs is not available yet: the solve took its early out and nothing
       ever came back, because the ResizeObserver only fires when `.sm-wells`
       changes and that had already happened. Measured, calling the same
       function by hand one beat later wrote 145.81 and landed the card on
       577.99 — right logic, wrong moment.

       One pending flag, so a render plus an observer fire in the same tick
       solve once. It cannot recurse: what the solve writes is the WELL's
       height, and nothing it reads is a function of that. */
    if (!_smFitPending) {
      _smFitPending = true;
      requestAnimationFrame(() => {
        _smFitPending = false;
        const el = document.getElementById('ob-screenshot-dropzone');
        if (el) _smDropwellSolve(el);
      });
    }
  }

  /* Only when the NODE changed — see above. A repeat on the same element is a
     no-op rather than a re-observe, or the callback re-triggers itself. */
  if (wells !== _smWellsNode) {
    if (_smWellsRO) _smWellsRO.disconnect();
    _smWellsNode = wells;
    _smWellsRO = null;
    if (wells && typeof ResizeObserver === 'function') {
      _smWellsRO = new ResizeObserver(() => _smDropwellFit());
      _smWellsRO.observe(wells);
    }
  }
}

/* ── THE WELL'S HEIGHT IS SOLVED AGAINST BASIC INFO, NEVER TYPED ──────────
   Jaco: *"quiero que me claves la altura con respecto a la card de basic info
   en el caso de doble fila, para que sea perfecto."* 576 was only ever a
   STAND-IN for that card — measured, Basic Info is 578 and the 144 landed
   Assets on 576.19, so the two were 1.8 apart and the number he actually
   wanted was never the one he could name.

   **AND IN v6.74 IT STOPPED BEING CONDITIONAL, WHICH IS A SIMPLIFICATION THIS
   FUNCTION GETS FOR FREE.** The library moved inside the well, so the pane no
   longer grows with the folder and there is no "double row" case to solve for:
   ONE height, always, and it is still this measurement rather than the 334 in
   the CSS. The `tight` argument and the early `removeProperty` went with the
   class — everything below is unchanged, because the arithmetic never cared
   which state asked for it.

   **Same shape as `_sizeLangSearchList`, one pane over**, and for the same
   reason that function gives: 578 is what Basic Info happens to be today and
   is a function of `--gi-desc-h`, the title row and the platform grid — the
   kind of literal this file has watched go stale three times.
   `_gdPaneHeight('gamedetails')` reads the real pane instead.

   **BOTH READINGS ARE PANE TO PANE**, so the sub-tab rail, the Prev/Next row
   and the panel's padding cancel: match the panes and the CARDS match, with no
   arithmetic about the 115 of chrome anywhere in here. A `--gi-drop-h` of 334
   stays in the CSS as the value this solves to today; the inline property is
   what makes it exact.

   **THE CORRECTION IS A DELTA, WHICH IS WHY IT CANNOT OSCILLATE.** It measures
   the overshoot with the well at its CURRENT height and takes that off the
   well, so one pass converges by construction; measuring again returns 0 and
   the sub-pixel guard then writes nothing. And the `ResizeObserver` watches
   `.sm-wells`, whose box does not change when the well above it does — so the
   thing that triggers this cannot be moved by it.

   **THE FLOOR IS MEASURED, NOT PICKED.** `min-height` below the content is a
   no-op, so a well asked for less than its three lines simply stops shrinking
   and the card overshoots — visible and correct, but the number written should
   not be a fiction. It reads the natural height with the floor removed for one
   frame, the way `_sizeLangSearchList` measures its room, and clamps there.

   Skipped entirely while the pane is hidden: `getBoundingClientRect` on a
   `display: none` pane is 0, and a delta against 0 would write nonsense. The
   next render on the way into Assets does it. */
function _smDropwellSolve(dz) {
  /* THE SOLVED VALUE LIVES ON THE ROOT, NOT ON THE WELL — and the first
     version put it on the well, which is why it kept measuring right and
     landing back at 144. `renderDetails` rebuilds the pane with innerHTML, so
     **the dropzone is a different node after every render** (verified:
     `dz === previous` is false), and an inline property written on the old one
     goes out with it. On the root it survives the render, and a freshly built
     well inherits the solved height on its first paint rather than flashing
     the CSS default and easing down to it.

     Same class of mistake as the renamed selector two sections up: the code
     was correct about the NUMBER and wrong about WHERE it was kept. */
  const root = document.documentElement;

  const pane = dz.closest('.gd-pane');
  if (!pane || !pane.getBoundingClientRect().height) return;   // hidden: not now
  if (typeof _gdPaneHeight !== 'function') return;

  const target = _gdPaneHeight('gamedetails');
  if (!target) return;

  const cur = dz.getBoundingClientRect().height;
  const delta = pane.getBoundingClientRect().height - target;

  /* THE CHEAPEST PROBE IS THE ONE THAT DOES NOT RUN (v6.76). Jaco: *"cuando
     entro en assets, veo el dropwell redibujarse."*

     Everything below takes the well OUT OF FLOW for a frame to read its floor,
     and the long note above is the history of making that invisible. It is
     invisible and it is still not free: it forces two extra layouts on the pane
     on EVERY repaint of the library, and this function runs on every one of
     them — entering the pane alone reaches it twice.

     And on all but the first it has nothing to do. The solved value lives on
     the ROOT, so it survives the render that rebuilt the well: arriving in
     Assets a second time the card already matches Basic Info and `delta` is
     zero. **A measurement taken to decide a number that cannot move is the
     whole of the redraw.** So the exit moves ABOVE the probe — the guard that
     was at the bottom only ever saved the write.

     `now` has to exist for this to be safe: with nothing solved yet a zero
     delta is a coincidence (the CSS 334 happening to fit), not an answer, and
     the floor still has to be read once. */
  const solved = parseFloat(root.style.getPropertyValue('--gi-drop-h'));
  if (solved && Math.abs(delta) < 0.5) return;

  /* The floor: what the three lines need on their own.

     **THE TRANSITION HAS TO BE SWITCHED OFF FOR THIS READ, and leaving it on
     is what made the whole solve write the wrong number.** `.asset-dropzone`
     carries `transition: all 0.2s`, so dropping `min-height` to 0 does not
     resize the box — it STARTS AN ANIMATION, and the rect read on the next
     line is the animation's first frame, i.e. the height it already had.
     Measured: the floor came back **175**, so `Math.max(floor, …)` clamped the
     answer to exactly the value it was trying to move away from, the solve
     "converged" on 175 and the card sat 29px over Basic Info with a root
     variable that looked like it was working.

     Third time this file has been bitten by reading a transitioned property in
     the turn that set it (`.prv-box`'s hover, the card's own height). The rule:
     if you are going to measure a property you just wrote, take the transition
     off first — and put it back, or the well stops easing for good.

     **AND THE PROBE IS MEASURED OUT OF FLOW, WHICH IS THE HALF THAT MAKES IT
     INVISIBLE (v6.75).** Jaco: *"al clicar Assets, veo cómo se redimensiona la
     card en real time en vez de estar ya cargada en su dimensión
     correspondiente."* Sampled every frame across a real tab switch, the card
     went **578 → 451.8 → 578 over ~260ms**: it COLLAPSED and eased back up.

     451.8 was this probe. Dropping the well to its content for one frame is
     invisible on the WELL — that transition is off and the restore is flushed —
     but `.sec-panel` carries `transition: all`, so the CARD saw a 126px change,
     started its own ease and was still easing long after the well had snapped
     back. The probe was correct and its BLAST RADIUS was not.

     **Freezing the card's transition too was the obvious fix and did not work**,
     which is worth keeping: with `transition: none` on the panel the collapse
     merely became instant, and restoring the transition let it ease back up
     from 451.8 anyway — measured, still twelve dipped frames. You cannot fix a
     layout change by hiding its animation; the ancestor must never see it.

     So the well is taken OUT OF FLOW for the read — `position: absolute` with
     its width pinned to the px it already had, so wrapping is identical and
     nothing above it can move. That is `_gdPaneHeight`'s own mechanism, one
     element down, and this file's standing answer to "measure something without
     showing the measurement". `visibility: hidden` because an absolutely
     positioned box still paints.

     **AND THE RESTORE HAS TO BE FLUSHED BEFORE THE TRANSITION COMES BACK, which
     is the third and actual cause.** Measured frame by frame, `--gi-drop-h` was
     `333.81px` the whole way through and the WELL still read 207.6 — its own
     content height — for six frames before easing up to 333.8 over ~250ms. So
     nothing was wrong with the number; the well was ANIMATING out of the probe.

     The old sequence restored `min-height` and `transition` together and only
     then flushed, so at the moment the browser next computed style the element
     had `transition: all .2s` AND a height that had just changed from 207.6 —
     which is a transition trigger, textbook. The probe was invisible and its
     EXIT was not.

     Restore the geometry, flush while the transition is still off, and only
     then give it back. Three steps that have to stay in that order. */
  const prevCss = dz.getAttribute('style') || '';
  const w = dz.getBoundingClientRect().width;
  dz.style.cssText = prevCss +
    ';transition:none;position:absolute;visibility:hidden;min-height:0;' +
    'width:' + w + 'px;box-sizing:border-box;';
  const floor = dz.getBoundingClientRect().height;
  dz.style.cssText = prevCss + ';transition:none;';   // back in flow, still frozen
  void dz.offsetHeight;                               // …and the browser agrees
  if (prevCss) dz.setAttribute('style', prevCss); else dz.removeAttribute('style');

  const want = Math.max(floor, cur - delta);
  if (Math.abs(want - (solved || 0)) < 0.5) return;   // already solved — write nothing

  /* AND THE WRITE ITSELF IS NOT EASED (v6.76), which is the other half of the
     redraw. The probe was made invisible three times over and the ANSWER was
     left to animate: the well carries `transition: all .2s` and the card
     `transition: all`, so the first solve of a session — the CSS 334 moving to
     the measured height — was 200ms of a box growing under the line that has
     just been told to celebrate. The sweep and the resize ran in the same
     window, which is why one of them was not being seen.

     The same three steps the probe's exit uses, on the two elements that can
     see this change: freeze, write, flush while still frozen, then give the
     transition back. By the time it comes back the geometry has settled, so
     there is nothing left to trigger. `.sec-panel` is named as well as the well
     because it is the box whose ease is the visible one — freezing only the
     child leaves the parent animating to the same number. */
  const panel = dz.closest('.sec-panel');
  const dzCss = dz.getAttribute('style') || '';
  const pnCss = panel ? panel.getAttribute('style') || '' : '';
  dz.style.cssText = dzCss + ';transition:none;';
  if (panel) panel.style.cssText = pnCss + ';transition:none;';
  root.style.setProperty('--gi-drop-h', want.toFixed(2) + 'px');
  void dz.offsetHeight;
  if (dzCss) dz.setAttribute('style', dzCss); else dz.removeAttribute('style');
  if (panel) { if (pnCss) panel.setAttribute('style', pnCss); else panel.removeAttribute('style'); }
}

/* THE WELL'S CONTENTS, IN THE SHAPE OF THE NAV PROTOTYPE.

   Two things that version got right and a card grid does not.

   THUMBNAILS KEEP THEIR OWN PROPORTIONS, matched on HEIGHT rather than boxed
   into a uniform tile. That is not only prettier: the shape IS the evidence.
   A row where the screenshots are wide, the icon is square and the logotype
   is a long thin sliver shows the developer what the classifier saw, so a
   file in the wrong group is visible as a wrong shape before anybody reads a
   label.

   AND THE GROUPS FLOW INLINE rather than stacking. Five screenshots, an icon
   and two pieces of key art fit on one line, so the whole folder is one
   glance instead of a scroll — which is the entire promise of dropping a
   folder in and being told what is in it. */
/* THE SCRAPED TRAILER IS JUST A VIDEO (v6.53)

   It used to get its own block under the dropzone — a big thumbnail with
   "🎬 Launch Trailer (from Steam)" written beside it — which made the one
   asset Shipmate found for you look like a different class of thing from the
   ones you dropped in yourself. By request it now sits in the Video well with
   everything else, at the same 50px the rest of the library uses and with no
   caption at all.

   It cannot be a real pool record: smAdd stores a directly-playable `src`, and
   Steam hands out an HLS manifest plus a poster image, not a file. So this is
   a synthetic entry rendered from state.uploads.steamTrailer — same .sm-thumb
   markup, same hold-to-remove gesture, its own click target (the poster is an
   <img>, and playback needs hls.js — see smZoomSteamTrailer). */
const SM_STEAM_TRAILER_ID = '__steam-trailer';

/* ONE WELL PER ROW, IN THE ORDER A DEVELOPER WOULD LIST THEM (v7.20, by
   request: "each section should begin on a new row").

   THIS REPLACES `SM_WELL_LAST`, AND THAT RULE IS NOT BEING SWITCHED OFF, IT IS
   BEING RETIRED. v6.75 sorted the unbounded groups (Screenshot, Other) last so
   the small ones could pack onto line 1 and the wide one took a line of its
   own — a careful answer to a real measurement (key art 214 + portrait 30 +
   screenshot 660 + video 75 in a 763px row, missing by two pixels). Every word
   of that reasoning was about how a WRAPPING row lands. `.sm-wells` is a
   column now, so there is no line to pack, nothing to miss by two pixels, and
   no economy left for that rule to buy. Leaving it in place would be a
   statement about a layout that no longer exists.

   THE ORDER IS THE ASKED-FOR ONE and is now simply written down: Key art,
   Logotype, Icon, Screenshot, Video. `art-port` rides with `art-land` because
   the display merges the two into one "Key art" well (see byKind below), and
   is listed so the order still holds if that merge is ever undone.

   ANYTHING NOT NAMED STILL APPEARS, appended in `SM_KINDS`' own order — the
   one property worth keeping from what this replaces. A kind added to the
   model and forgotten here shows up at the end rather than vanishing. */
const SM_WELL_ORDER = ['art-land', 'art-port', 'logo', 'icon', 'screenshot', 'video', 'other'];

/* "USE THIS" GOES UNDER THE TILE, NOT OVER IT (v7.10). Jaco, on the first
   version: *"muchas cosas en tan pequeño, quizás me lo imaginaba DEBAJO de
   cada icono, NO DENTRO."*

   It was drawn inside the thumbnail on the argument that an absolutely
   positioned strip costs no height, which is the rule the × and the play badge
   are written under — and it is the wrong rule for this one. Those two are
   MARKS: a glyph in a corner of a picture. This is a sentence, and a sentence
   laid over 50px of someone's artwork is two things fighting for the same
   square, which is exactly what the screenshot shows.

   THE ROW ALIGNS ON ITS BOTTOM EDGE (`.sm-well-row` is `align-items:
   flex-end`), so hanging a label under ONE tile lifts that tile above its
   neighbours. Both get the label and the one that is already the icon gets it
   INVISIBLE — the same trick the privacy table's Show/Hide toggle uses, where
   both strings sit in the box so the width cannot change with the state. Here
   it is the height, and reserving it needs no measurement and no second
   number to keep in sync with the font.

   AND IT ONLY WRAPS WHEN THERE IS A CHOICE TO MAKE. One icon in the group is
   the icon by default; offering to use the thing you are already using is a
   control that can do nothing. With a single icon the tile renders exactly as
   it did before this existed. */
/* The empty Icon tile. RED because that is what was asked for, and it is worth
   saying that it argues with this app's own colour table: green is done, amber
   is *this needs you*, red is WRONG — and a missing icon is the middle one.
   The case for red anyway is that this is the only required asset the library
   can be silent about, and it is silent by construction (see `needsIcon`). If
   it ever reads as an error rather than as a gap, `--alert-*` → the ambers is
   the one-line change.

   It opens the well's own file input rather than a second uploader: the well
   already accepts images and classifies them, so a square PNG dropped here
   becomes an icon by the same route as any other file. `stopPropagation` is
   NOT needed — `#sm-library` already stops the well's own click, which is why
   this has to reach the input by name. */
function _smIconMissingHtml() {
  /* `hideGlobalTip()` FIRST, and it is the thumbnail ×'s own lesson arriving on
     a second control. Jaco: *"si subo un archivo desde el icon rojo, al
     subirlo, se queda pendiente un tooltip."* Pressing this opens the OS file
     dialog, so the pointer leaves for somewhere the page cannot see; picking a
     file then repaints the library and this button stops existing, so the
     `mouseout` that would have dismissed its bubble never fires and the hint
     is stranded over a tile that is no longer there. Anything that removes its
     own anchor has to take the tooltip down by hand. */
  return `<button type="button" class="sm-thumb sm-thumb-missing"
                  onclick="window.hideGlobalTip?.(); document.getElementById('ob-screenshot-input')?.click()"
                  data-tip="Upload an app icon">Icon</button>`;
}

/* WHICH ONE IS OURS, AND HOW TO CHANGE IT (v7.15 extends this to video).

   ICONS HAD THIS AND VIDEOS DID NOT, which was fine while a project had one
   trailer and silently wrong the moment it had two: every surface took the
   first video it found and the developer had no way to say otherwise. Video
   now answers to the same slot model (`smAppTrailer`, assets.js), so one
   wrapper serves both rather than a second one growing beside it.

   THE BORDER IS NEW AND IS FOR BOTH. "Use this" only ever appeared on the
   tiles that were NOT selected — it is the action, and the chosen one has no
   action to offer — so with two icons the current one was identified by the
   absence of a button, which is not identification at all. A ring states it.
   It is on the tile in every case, including the single-asset case where no
   button is drawn: a project with exactly one trailer still benefits from
   seeing that it is the one being used.

   THE BUTTON STILL NEEDS TWO, because a choice between one thing is not a
   choice. `>= 2` on the group, counted as displayed. */
function _smPickWrap(a, list, thumbHtml) {
  const isIcon  = a.kind === 'icon';
  const isVideo = a.kind === 'video';
  if (!isIcon && !isVideo) return thumbHtml;

  const id   = a.steamTrailer ? SM_STEAM_TRAILER_REF : a.id;
  const mine = isIcon ? _smIsAppIcon(a)
                      : (typeof smIsAppTrailer === 'function' && smIsAppTrailer(id));
  const use  = isIcon ? `smUseAsAppIcon('${a.id}')` : `smUseAsTrailer('${id}')`;
  const wrapped = `<div class="sm-pick-tile${mine ? ' is-current' : ''}">${thumbHtml}</div>`;

  const group = list.filter(x => x.kind === a.kind).length;
  if (group < 2) return wrapped;

  return `<div class="sm-pick">${wrapped}
    ${mine
      ? `<span class="sm-pick-use is-off" aria-hidden="true">Use this</span>`
      : `<button type="button" class="sm-pick-use"
                 onclick="${use}">Use this</button>`}
  </div>`;
}

/* The video half of `smUseAsAppIcon`, and the same three lines: write the
   slot, close whatever is open over it, repaint. The id may be the synthetic
   Steam one, which is why this takes an id rather than a pool record. */
function smUseAsTrailer(id) {
  if (!id) return;
  state.uploads = state.uploads || {};
  state.uploads.appTrailer = { ref: id };
  smZoomClose();
  if (typeof renderDetails === 'function') renderDetails();
  else if (typeof renderAssetLibrary === 'function') renderAssetLibrary();
  if (typeof renderDashboard === 'function') renderDashboard();
}

/* PLAYING THE TRAILER FROM ANYWHERE. The store previews' carousel needs the
   same thing the Assets well does — the lightbox — and the two sources reach
   it by two different doors: a pool video has a file, so `smZoom` plays it;
   the Steam one is an HLS manifest and has its own opener. One function, so
   the preview never has to know which kind it is looking at. */
function smPlayAppTrailer() {
  const tr = (typeof smAppTrailer === 'function') ? smAppTrailer() : null;
  if (!tr) return;
  if (tr.isSteam) { if (typeof smZoomSteamTrailer === 'function') smZoomSteamTrailer(); return; }
  if (typeof smZoom === 'function') smZoom(tr.id);
}

function _smLibraryHTML() {
  const pool = state.assets || [];
  const steamTrailer = (state.uploads && state.uploads.steamTrailer) || null;
  const hasSteamTrailer = !!(steamTrailer && steamTrailer.thumbnail);
  /* Nothing at all draws nothing. The dropzone directly above already says
     what to do, and a paragraph under it repeating that is the interface
     talking to itself. */
  if (!pool.length && !hasSteamTrailer) return '';
  const byKind = {};
  SM_KINDS.forEach(k => { byKind[k] = pool.filter(a => a.kind === k); });
  /* PORTRAIT ART IS KEY ART (v7.09). Jaco: *"si portrait art ocupa mucho (el
     texto), quizás puedes unirlo como parte de key art."* Its own group cost a
     whole label row — "Portrait art" is the longest short name in the table —
     to separate two things a developer thinks of as one: the art for this
     game, in the shapes the stores ask for. The ORIENTATION is still on each
     file (a.kind is untouched, so `_shotEdRatio`, the coverage line and every
     slot picker read exactly what they read before) and it is still visible at
     a glance, because a portrait thumbnail is visibly portrait. This merges
     the DISPLAY only, which is why it happens here and not in SM_KINDS. */
  byKind['art-land'] = byKind['art-land'].concat(byKind['art-port']);
  byKind['art-port'] = [];
  if (hasSteamTrailer) {
    byKind.video = byKind.video.concat([{
      id: SM_STEAM_TRAILER_ID, kind: 'video', steamTrailer: true,
      name: steamTrailer.name || 'Trailer',
      src: steamTrailer.thumbnail, w: 16, h: 9,
    }]);
  }
  const order = SM_WELL_ORDER.concat(SM_KINDS.filter(k => !SM_WELL_ORDER.includes(k)));
  /* AN ICON NOBODY HAS IS STILL A ROW (v7.10). Jaco: *"si no hay nada
     iconizable después del scrapeo, podrías poner un thumbnail vacío de ICON,
     en rojo, y tocando ahí también te lleva al uploader?"*

     A store page with no icon is the one gap in this library that the library
     itself cannot show, because a group with nothing in it does not exist —
     so the absence was invisible in exactly the place the developer goes to
     check what they have. It draws an empty tile in Icon's own position now,
     which is where the eye would look for one.

     IT CANNOT APPEAR ON AN EMPTY PROJECT, and that falls out rather than being
     tested for: this whole function returns '' while the pool is empty, so the
     placeholder is only ever reachable once something else has landed. Which
     is precisely "después del scrapeo" — a brand-new form is still an
     invitation, not a complaint.

     `smAppIcon()` rather than a scan of the pool, so an icon held only in the
     uploader's slot counts: the question is "does this game have an icon",
     and that function is the one answer to it. */
  const needsIcon = !(typeof smAppIcon === 'function' ? smAppIcon() : pool.some(a => a.kind === 'icon'));
  const groups = order.map(k => [k, byKind[k] || []])
                      .filter(([k, l]) => l.length || (k === 'icon' && needsIcon));
  return `<div class="sm-wells">${groups.map(([k, list]) => `
    <div class="sm-well">
      ${/* THE COUNT IS IN PARENTHESES, NOT AFTER A MIDDOT (v6.74). Jaco: *"en
            vez de un punto separando la descripción (screenshots · 2) que esté
            justo después entre paréntesis."* The middot is a SEPARATOR — it
            holds two things apart and says they are peers, which is what made
            `SCREENSHOTS · 2` read as a list of two facts rather than as one
            label carrying its own count. Brackets say the number belongs to
            the word, and they cost no space to say it.

            The privacy table made this exact move for the same reason (see
            "AND THE COUNT CAME BACK AGAINST THE NAME, IN PARENTHESES" in
            CLAUDE.md), so this is the app agreeing with itself rather than a
            second idea: one plain space, because the brackets carry their own
            side bearings and a wider gap re-opens the hole the middot left.

            Still only past one — a group of one screenshot saying "(1)" is a
            count with nothing to count against. */''}
      <div class="sm-well-h">${escHtml(SM_KIND_SHORT[k] || k)}${
        list.length > 1 ? ` <span>(${list.length})</span>` : ''}</div>
      <div class="sm-well-row">
        ${!list.length ? _smIconMissingHtml() : ''}
        ${list.map(a => _smPickWrap(a, list, `
          ${/* A THUMBNAIL AT 90px CANNOT BE JUDGED, which is the whole reason
               it opens. The grid answers "did my files land and does the tool
               know what they are"; whether the logotype has the halo baked in
               is a question you can only answer at full size. */''}
          ${/* AN ICON THUMB IS SQUARE, WHATEVER THE NUMBERS SAY (v7.09). Jaco:
                *"el thumbnail de icono debe ser cuadrado, que no tenga esos
                bordes transparentes a los lados."* The box takes the file's own
                ratio, and `a.w`/`a.h` are 0 until smMeasure's async callback
                lands (or for good, if that read failed) — so the 16/9 fallback
                drew a genuinely square icon letterboxed, with the checkerboard
                showing through either side and reading as transparency the file
                does not have. An icon IS square by definition, in every
                SM_REQS row that names one, so for this kind the square is not a
                fallback, it is the answer. */''}
          <div class="sm-thumb${a.kindBy === 'user' ? ' is-user' : ''}"
               style="aspect-ratio:${a.kind === 'icon' ? '1/1' : `${a.w || 16}/${a.h || 9}`}"
               onclick="${a.steamTrailer ? 'smZoomSteamTrailer()' : `smZoom('${a.id}')`}" role="button" tabindex="0"
               onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();${a.steamTrailer ? 'smZoomSteamTrailer()' : `smZoom('${a.id}')`}}"
               title="${a.steamTrailer ? escHtml(a.name) : `${escHtml(a.name)} · ${a.w || '?'}×${a.h || '?'}${a.alpha ? ' · transparent' : ''}`}">
            ${/* A VIDEO CANNOT BE AN <img>. preload="metadata" is what gets a
                  first frame without pulling the whole file, and #t=0.1 asks
                  for a frame a tenth of a second in — the frame at exactly 0
                  is black in a great many trailers. muted + playsinline so no
                  browser decides to autoplay it with sound on a phone. */''}
            ${/* The scraped trailer has a poster frame from Steam rather than a
                  file to pull a frame out of, so it draws that — with the same
                  play badge the rest of the app puts on a Steam trailer, since
                  a still with nothing on it is indistinguishable from a
                  screenshot. */''}
            ${a.steamTrailer
              ? `<img src="${escHtml(a.src)}" alt="${escHtml(a.name)}"><span class="steam-trailer-play-badge">▶</span>`
              : a.kind === 'video'
                ? `<video src="${escHtml(a.src)}#t=0.1" muted playsinline preload="metadata"></video>`
                : `<img src="${escHtml(a.src)}" alt="${escHtml(a.name)}">`}
            ${/* HOLD, DON'T CLICK. These are the developer's own files, often
                 the only copy to hand, and a 20px × in the corner of a
                 thumbnail is exactly the target a stray click finds. There is
                 no undo behind it — smRemove drops the record and every slot
                 referencing it — so the gesture is made deliberately hard to
                 do by accident instead. The bar IS the confirmation dialogue,
                 and it costs a second and a half rather than a round trip. */''}
            ${/* THE APP'S BUBBLE, NOT THE BROWSER'S. This carried a bare
                  `title`, which sits for about a second and then draws in the
                  SYSTEM's style — and it is the one control here whose whole
                  problem is that nobody can guess the gesture, so it was also
                  the slowest hint in the library. `data-tip` is the trigger
                  (see initGlobalTooltip): the ATTRIBUTE is the tooltip and the
                  `.tooltip-anchor` class is only layout, which this 20px
                  absolutely-positioned button must not take.

                  DELETE, not remove, and both strings say it. `smRemove` drops
                  the record and every slot referencing it with no undo behind
                  it — which is the whole reason the gesture is a hold — so the
                  quieter verb was the one place this control understated what
                  it does. The `aria-label` keeps the file's name because the
                  accessible name has to say WHICH thumbnail; the bubble does
                  not, since it is drawn on the picture. */''}
            <button class="sm-thumb-x" aria-label="Hold to delete ${escHtml(a.name)}"
                    data-tip="Hold to delete" data-tip-tone="danger"
                    onclick="event.stopPropagation()"
                    onpointerdown="smHoldStart(event, '${a.id}')"
                    onpointerup="smHoldCancel()" onpointerleave="smHoldCancel()"
                    onpointercancel="smHoldCancel()" onblur="smHoldCancel()">×</button>
            <span class="sm-thumb-burn" aria-hidden="true"></span>
          </div>`)).join('')}
      </div>
    </div>`).join('')}</div>`;
}

/* ── HOLD TO REMOVE ───────────────────────────────────────────────────────
   The bar is CSS — a transform the browser runs on the compositor — and the
   deletion is one timer. No rAF loop, because a progress bar that a script
   redraws every frame is a script that can stutter; this one cannot, and it
   also cannot drift out of step with the timer, since both are started by the
   same event and cancelled by the same call.

   ARMED STATE LIVES IN A CLASS, NOT IN STATE. A gesture in progress is not
   data — abandon it and there is nothing to clean up, and no render can
   catch it half-finished. Same reasoning as the drag handlers above. */
let _smHold = null;

function smHoldStart(ev, id) {
  ev.preventDefault();          // no text selection, no drag ghost
  ev.stopPropagation();         // and no zoom: the × is not the picture
  const thumb = ev.currentTarget.closest('.sm-thumb');
  if (!thumb) return;
  smHoldCancel();
  thumb.classList.add('is-arming');

  /* THE HINT BECOMES A REPORT WHILE THE BAR RUNS (v6.81). Jaco: *"se podría
     actualizar el tooltip cuando estoy borrando a Deleting..."* — and the
     reason it is right is the one this control was built on: the × is the only
     thing on screen that says what the gesture IS, so during the gesture it
     should say what is HAPPENING. "Hold to delete" is an instruction, and an
     instruction you are already following is the shape this file keeps
     refusing (the locked Submit row printing a gesture for a shut door, one
     face over).

     It is written onto the BUTTON's own `data-tip` rather than pushed into the
     bubble, so there is still exactly one place the hint lives: an ordinary
     hover a second later reads the same attribute and gets the same answer.
     The ellipsis is the app's own — SUBMITTING…, CANCELING SUBMISSION — a
     single glyph, and the word matches the `aria-label`'s verb rather than the
     quieter "remove" this control gave up in v6.68. */
  const btn = ev.currentTarget;
  const tipWas = btn.dataset.tip;
  btn.dataset.tip = 'Deleting…';
  if (typeof smTipRefresh === 'function') smTipRefresh(btn);

  _smHold = { thumb, btn, tipWas, t: setTimeout(() => {
    _smHold = null;
    thumb.classList.remove('is-arming');
    /* AND THE BUBBLE GOES WITH THE BUTTON. `renderAssetLibrary` replaces this
       node, so `mouseout` never fires on it — without this, "Deleting…" is
       left floating over a thumbnail that no longer exists until the pointer
       happens to cross another anchor. The one case where a hover tooltip has
       to be taken down by something other than the pointer leaving. */
    if (typeof hideGlobalTip === 'function') hideGlobalTip();
    // The scraped trailer is not a pool record (see _smLibraryHTML) — removing
    // it means dropping the scrape, not calling smRemove with an id smGet
    // would never find.
    if (id === SM_STEAM_TRAILER_ID) { if (state.uploads) state.uploads.steamTrailer = null; }
    else smRemove(id);
    renderAssetLibrary();
    // The trailer counts toward the Shippy Checklist's "Add a trailer" item
    // (v6.51), and that lives outside this panel.
    if (typeof renderDashboard === 'function') renderDashboard();
  }, 1500) };
}

/* Called from pointerup, pointerleave, pointercancel AND blur — letting go,
   sliding off, the browser taking the pointer away, or the window losing
   focus mid-press all mean the same thing: they did not go through with it. */
function smHoldCancel() {
  if (!_smHold) return;
  clearTimeout(_smHold.t);
  _smHold.thumb.classList.remove('is-arming');
  /* Put the instruction back, and redraw it if the pointer is still there —
     letting go is an undo, so the control has to return to saying what it
     would do rather than what it was doing. Restored from what was CAPTURED
     rather than re-typed, so the string exists once (in `_smLibraryHTML`) and
     a future change to it cannot leave this function printing the old one. */
  if (_smHold.btn) {
    _smHold.btn.dataset.tip = _smHold.tipWas;
    if (typeof smTipRefresh === 'function') smTipRefresh(_smHold.btn);
  }
  _smHold = null;
}

/* ── FULL-SIZE PREVIEW ────────────────────────────────────────────────────
   Built and thrown away rather than kept hidden in the markup, because the
   asset library is rebuilt wholesale by renderAssetLibrary and a node parked
   inside it would go with it. On <body>, so no ancestor's overflow or stacking
   context can clip it — the library lives several nested panels deep. */
/* CHOOSING THE ICON, WHERE YOU ARE ALREADY JUDGING IT (v7.09).
   Jaco: *"sigo quedándome con ganas de poder elegir el icono, de alguna manera
   no intrusiva."*

   Two candidates now land in the library and one is assigned on arrival, which
   answers "is there an icon" and leaves "is it the right one" with nowhere to
   go. Every place that question could be asked in the WELL costs something at
   rest — a second mark on every icon thumbnail, or a row of controls under a
   group, on a surface whose whole argument is that it is files rather than a
   form. That is the shape this feature has already been corrected out of
   twice.

   THE ZOOM COSTS NOTHING AT REST, and it is the right moment rather than
   merely a free one. This lightbox exists because *"a thumbnail at 50px cannot
   be judged"* — its own words — and which of two icons is yours is precisely a
   judgement you cannot make at 50px. So the caption that already names the
   file, its size and its kind gains one more fact: whether it is the icon, or
   a button to make it so.

   ANY 'icon' IN THE POOL, not just the two built ones, which closes a gap that
   predates them: `smAppIcon()`'s second door takes the FIRST icon-kind asset
   in the pool, so a developer who dropped three square files had the array's
   order choose for them with no way to say otherwise. Now there is one.

   It writes the SLOT — `uploads.appIcon`, the door that means "chosen for this
   job" — so the answer survives anything later landing in the pool beside it. */
function _smIsAppIcon(a) {
  if (!a || a.kind !== 'icon') return false;
  /* BY ID, NOT BY SRC (v7.15), and v7.14 is what made that necessary rather
     than merely tidier. This compared `smAppIconSrc()` against `a.src` — and
     that function now returns the CROPPED BAKE when the App Icon editor has
     made one, which equals no asset's own src. So the moment a developer
     cropped their icon, the library stopped being able to say which file it
     was: no ring, and "Use this" offered on the icon already in use.

     The src comparison also could not tell two identical files apart. `smAdd`
     dedupes by src so the pool cannot normally hold both, but identity by
     content was always the weaker claim. `smAppIconId` is the same answer
     `smAppIconSrc` looks the crop up under, so the two cannot disagree.

     The src fallback stays for the pre-pool upload shape, which has no id. */
  const id = (typeof smAppIconId === 'function') ? smAppIconId() : null;
  if (id) return id === a.id;
  const cur = (typeof smAppIconSrc === 'function') ? smAppIconSrc() : '';
  return !!cur && cur === a.src;
}

/* THE PACK YOU ARE INSIDE, in the order the library drew it (v7.11). Jaco:
   *"quiero que me dejes navegar con las flechas si estoy dentro de un mismo
   pack de thumbnails, porque así es más cómodo."*

   "Pack" is the GROUP as displayed, which is not quite the same as the kind:
   `_smLibraryHTML` merges portrait art into Key art, so the two read as one row
   and arrowing through them has to agree with that or the keys would skip past
   something plainly sitting in the same run. Everything else is its own kind.

   Read off the pool in pool order, which IS the display order — the library
   filters that same array rather than sorting it, so this cannot drift from
   what is on screen without the library drifting too. */
function _smZoomPack(a) {
  const pool = (typeof state !== 'undefined' && state.assets) || [];
  const grp = k => (k === 'art-port' ? 'art-land' : k);
  return pool.filter(x => grp(x.kind) === grp(a.kind));
}
/* AND THE CONTROL IS BACK HERE TOO, WHICH REVERSES MY OWN ARGUMENT (v7.11).
   Jaco: *"me has quitado el 'use this icon' de la full screen preview, y me
   gustaba."*

   It was removed when `Use this` moved under the tile, on the rule this file
   states repeatedly: two controls in one role is one too many. That rule is
   about a control DUPLICATED for no reason, and these two are not that. The
   tile is for switching between candidates you can already tell apart at 42px;
   the lightbox is the only place you can make the choice when you CANNOT —
   which is the entire reason it exists ("a thumbnail at 42px cannot be
   judged"). Taking the action away from the one surface where the decision is
   actually informed was applying the rule past what it is for.

   So: the state when it IS the icon, the action when it is not. */
function _smIconPickHtml(a) {
  if (!a || a.kind !== 'icon') return '';
  if (_smIsAppIcon(a)) return ` · <span class="sm-zoom-iscur">Current app icon</span>`;
  return ` · <button type="button" class="sm-zoom-use" onclick="smUseAsAppIcon('${a.id}')">Use this icon</button>`;
}

/* WHAT THE KEYS DO, SAID WHERE THE KEYS ARE. Jaco: *"y que en algún sitio ponga
   'press esc to exit' o algo así."* Escape has closed this since it was built
   and nothing ever said so — a shortcut nobody is told about is a shortcut for
   whoever wrote it.

   AND ESCAPE IS THE ONLY ONE IT NAMES. Jaco: *"quítame el 'browse' y las
   flechas, debería ser un extra."* The arrows still work; they are simply not
   advertised, which is the difference between a legend and an inventory. Esc
   earns the line because it is the way OUT — someone who does not know it is
   stuck with the mouse — where the arrows are a convenience for a second
   look, and nothing is lost by the person who never finds them. */
function _smZoomHintHtml() {
  return `<div class="sm-zoom-hint">Esc to close</div>`;
}

/* `renderDetails` rather than a surgical repaint: the icon reaches the project
   chip, five store previews, the guide's checklist and the Assets coverage
   line, and an inventory of those is what this file keeps being bitten by. */
function smUseAsAppIcon(id) {
  const a = (typeof smGet === 'function') && smGet(id);
  if (!a) return;
  state.uploads = state.uploads || {};
  state.uploads.appIcon = smRef(id);
  smZoomClose();
  if (typeof renderDetails === 'function') renderDetails();
  else if (typeof renderAssetLibrary === 'function') renderAssetLibrary();
}

/* The picture, its caption and the legend — one function, because the open and
   the swap below have to produce the same thing and two copies of this would
   be two chances to differ. */
function _smZoomFigureHtml(a) {
  return `<figure>
       ${a.kind === 'video'
         ? `<video src="${escHtml(a.src)}" controls autoplay muted playsinline></video>`
         : `<img src="${escHtml(a.src)}" alt="${escHtml(a.name)}">`}
       <figcaption>${escHtml(a.name)} · ${a.w || '?'}×${a.h || '?'}${
         a.alpha ? ' · transparent' : ''} · ${escHtml(SM_KIND_SHORT[a.kind] || a.kind)}${
         _smIconPickHtml(a)}</figcaption>
       ${_smZoomHintHtml()}
     </figure>`;
}

function smZoom(id) {
  const a = (typeof smGet === 'function') && smGet(id);
  if (!a) return;

  /* BROWSING SWAPS THE FIGURE; IT DOES NOT REBUILD THE WINDOW (v7.12). Jaco:
     *"cada vez que browseo, hay un flashazo en el que se ve el fondo de la
     página, no debería."*

     Arrowing called this function, and this function opened by CLOSING first —
     so every step removed the backdrop from the document and appended a new
     one, and between those two the page underneath was on screen. One frame,
     and a black overlay is exactly the thing whose absence for one frame
     reads as a flash. `sm-lb-in` made it worse by fading the replacement in
     over 140ms, so the flash was really a dip.

     With the box already up, only the figure is replaced. The backdrop, its
     click handler and the Escape listener are never touched, which is also why
     this cannot leak a listener per step. Nothing is animated because nothing
     arrived: the window did not open, its contents changed. */
  /* `_smZoomId` IS PART OF THE TEST, not decoration. `smZoomSteamTrailer` draws
     into this same `#sm-lightbox` and is the one caller that mounts hls.js —
     swapping a figure into ITS box would drop the player on the floor still
     fetching segments, which is the leak `smZoomClose` exists to prevent. That
     function never sets `_smZoomId`, so a null one means the window on screen
     is not ours to swap and the full path runs, teardown included. */
  const open = _smZoomId && document.getElementById('sm-lightbox');
  if (open) {
    open.innerHTML = _smZoomFigureHtml(a);
    _smZoomId = id;
    return;
  }

  smZoomClose();
  const box = document.createElement('div');
  box.id = 'sm-lightbox';
  box.innerHTML = _smZoomFigureHtml(a);
  /* Anywhere but the picture itself closes it. Testing for the IMG rather than
     for the backdrop means the caption and the margin around the image close
     it too, which is what "click outside" means to the hand. */
  box.addEventListener('click', e => {
    /* VIDEO counts as the picture too, or the play button would dismiss the
       thing you just opened. */
    if (e.target.tagName !== 'IMG' && e.target.tagName !== 'VIDEO') smZoomClose();
  });
  document.body.appendChild(box);
  _smZoomId = id;
  /* CAPTURE PHASE, and it stops the event dead. Escape is spoken for twice
     over on this screen — the step modal closes on it, and so does the
     full-page website preview — and closing the modal behind the lightbox
     when someone meant to dismiss the lightbox would throw away the panel
     they were working in. The topmost thing gets the key. */
  document.addEventListener('keydown', _smZoomKey, true);
}

/* Remembered rather than re-derived from the DOM: the lightbox draws the image
   and the caption, not the id, and asking the markup which asset it is showing
   would be parsing our own output back. */
let _smZoomId = null;
function _smZoomKey(e) {
  if (e.key === 'Escape') {
    e.preventDefault();
    e.stopImmediatePropagation();
    smZoomClose();
    return;
  }
  if (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight') return;
  const a = (typeof smGet === 'function') && _smZoomId && smGet(_smZoomId);
  if (!a) return;
  const pack = _smZoomPack(a);
  if (pack.length < 2) return;
  e.preventDefault();
  e.stopImmediatePropagation();
  /* WRAPS, because a pack is a ring rather than a document: with four
     screenshots open, arrowing off the end and stopping dead reads as the key
     having broken rather than as the end of anything. */
  const i = pack.findIndex(x => x.id === a.id);
  const n = (i + (e.key === 'ArrowRight' ? 1 : -1) + pack.length) % pack.length;
  smZoom(pack[n].id);
}

/* The scraped trailer opens the same lightbox an uploaded video does. It can't
   go through smZoom, which needs a pool record with a directly-playable src:
   Steam publishes an adaptive-streaming manifest, so the <video> here is fed
   the same way playSteamTrailer feeds the inline player — natively on Safari,
   through hls.js elsewhere, and a link-out when neither is available. */
function smZoomSteamTrailer() {
  const t = (state.uploads && state.uploads.steamTrailer) || null;
  if (!t || !t.hlsUrl) return;
  smZoomClose();
  const box = document.createElement('div');
  box.id = 'sm-lightbox';
  box.innerHTML =
    `<figure>
       <video controls autoplay playsinline></video>
       <figcaption>${escHtml(t.name || 'Trailer')} · ${escHtml(SM_KIND_SHORT.video || 'Video')}</figcaption>
     </figure>`;
  const video = box.querySelector('video');
  if (video.canPlayType('application/vnd.apple.mpegurl')) {
    video.src = t.hlsUrl;
  } else if (window.Hls && window.Hls.isSupported()) {
    const hls = new window.Hls();
    hls.loadSource(t.hlsUrl);
    hls.attachMedia(video);
    // Torn down by smZoomClose — an abandoned hls.js instance keeps fetching
    // segments long after its <video> has left the document.
    _smZoomHls = hls;
  } else {
    const link = document.createElement('a');
    link.href = t.hlsUrl; link.target = '_blank'; link.rel = 'noopener';
    link.className = 'steam-trailer-fallback-link';
    link.textContent = 'This browser can\u2019t play the trailer inline \u2014 open it on Steam\u2019s CDN instead';
    video.replaceWith(link);
  }
  box.addEventListener('click', e => {
    if (e.target.tagName !== 'IMG' && e.target.tagName !== 'VIDEO' && e.target.tagName !== 'A') smZoomClose();
  });
  document.body.appendChild(box);
  document.addEventListener('keydown', _smZoomKey, true);
}

let _smZoomHls = null;

function smZoomClose() {
  _smZoomId = null;
  if (_smZoomHls) { try { _smZoomHls.destroy(); } catch (_) {} _smZoomHls = null; }
  document.removeEventListener('keydown', _smZoomKey, true);
  const box = document.getElementById('sm-lightbox');
  if (box) box.remove();
}

const _SM_GRADE = { exact:'Exact', square:'Square', crop:'Crop', ratio:'Ratio' };

function _smCoverageHTML() {
  const pids = [...(state.activePlatforms || [])];
  if (!pids.length) return `<p class="sm-lib-empty">Pick your platforms to see what each store needs.</p>`;

  /* THE ANSWER TO "WHAT DO I ACTUALLY NEED TO MAKE". Every requirement in
     the table reduces to one of five source kinds, so the answer is five
     files — each at the largest size any store asks of it, because a master
     can be cropped down and must never be scaled up. */
  const set  = smSourceSet(pids);
  const miss = smMissingSources(pids);
  const cov  = smCoverage(pids);

  const masters = `
    <div class="sm-cov-set">
      <div class="sm-cov-h">The smallest set that covers everything</div>
      <p class="sm-cov-p">${set.length} master${set.length === 1 ? '' : 's'} at these sizes
         cover every slot across your platforms. Anything larger crops down; nothing is ever scaled up.</p>
      <div class="sm-cov-masters">
        ${set.map(sv => {
          const have = (state.assets || []).some(a => a.kind === sv.kind);
          return `<div class="sm-master${have ? ' has' : ''}">
            <span class="sm-master-k">${escHtml(SM_KIND_SHORT[sv.kind] || sv.kind)}</span>
            <span class="sm-master-d">${sv.w}×${sv.h}${sv.alpha ? ' · transparent PNG' : ''}</span>
            <span class="sm-master-s">${have ? '✓ have it' : 'missing'}</span>
          </div>`;
        }).join('')}
      </div>
      ${miss.length ? `<p class="sm-cov-todo">Still to make:
        ${miss.map(m => `<b>${escHtml(SM_KIND_SHORT[m.kind])} ${m.w}×${m.h}</b>`).join(', ')}.</p>` : ''}
      ${/* SCREENSHOTS ARE NOT IN THAT SET, and saying so is more useful than
           quietly leaving them out. Every other slot is artwork that crops
           down from one master; a screenshot is a capture of the game at a
           device's resolution, and cropping an iPhone capture into an iPad
           one throws away the interface an iPad would have shown. The stores
           know it — that is why they mark these must-upload. */''}
      ${(() => {
        const shots = smShotNeeds(pids);
        if (!shots.length) return '';
        return `<div class="sm-cov-shots">
          <div class="sm-cov-h2">Plus screenshots, captured from the game</div>
          <p class="sm-cov-p">These cannot come from your key art — each is a capture at
             that device's own resolution.</p>
          <div class="sm-cov-masters">
            ${shots.map(sv => `<div class="sm-master">
              <span class="sm-master-k">${sv.count > 1 ? sv.count + '×' : ''} ${sv.w > sv.h ? 'Landscape' : 'Portrait'}</span>
              <span class="sm-master-d">${sv.w}×${sv.h}${sv.min ? ' or larger' : ''}</span>
              <span class="sm-master-s">${sv.pids.map(p =>
                escHtml((typeof PLATFORMS !== 'undefined' && PLATFORMS[p] && PLATFORMS[p].label) || p)).join(', ')}</span>
            </div>`).join('')}
          </div>
        </div>`;
      })()}
    </div>`;

  const perStore = cov.map(c => {
    const label = (typeof PLATFORMS !== 'undefined' && PLATFORMS[c.pid] && PLATFORMS[c.pid].label) || c.pid;
    /* Nintendo is deliberately absent from the table rather than guessed at:
       it is the one platform where a developer has no public doc to check us
       against, so a wrong number there is the most expensive thing this panel
       could print. */
    if (c.noSpec) return `<div class="sm-cov-store">
      <div class="sm-cov-store-h">${escHtml(label)}</div>
      <p class="sm-cov-nospec">${escHtml(c.noSpec)}</p></div>`;
    return `<div class="sm-cov-store">
      <div class="sm-cov-store-h">${escHtml(label)}
        <span class="sm-cov-score${c.done === c.total ? ' full' : ''}">${c.done}/${c.total}</span></div>
      <div class="sm-cov-rows">
        ${c.rows.map(x => `
          <div class="sm-cov-row${x.grade ? ' ok' : ''}${x.r.opt ? ' opt' : ''}">
            <span class="sm-cov-n">${escHtml(x.r.n)}${x.r.opt ? ' <i>optional</i>' : ''}</span>
            <span class="sm-cov-d">${x.r.w}×${x.r.h}${x.r.min ? '+' : ''}</span>
            <span class="sm-cov-g">${x.grade ? escHtml(_SM_GRADE[x.grade] || x.grade)
              : '<em>' + escHtml(SM_KIND_SHORT[x.need] || x.need) + ' needed</em>'}</span>
          </div>${x.r.note ? `<div class="sm-cov-note">${escHtml(x.r.note)}</div>` : ''}`).join('')}
      </div>
      ${/* Where the numbers came from. A spec measured off a live storefront
           is a different kind of fact from one a store published, and
           flattening the two would be the dishonest part. */''}
      <p class="sm-cov-conf">${escHtml(SM_CONF_LABEL[(c.rows[0] || {}).r
        ? c.rows[0].r.conf : 'official'] || '')}</p>
    </div>`;
  }).join('');

  return masters + `<div class="sm-cov-stores">${perStore}</div>`;
}
